// Submit Request struct
#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct SubmitRequest {
    pub chain: String, // "sui" | "evm" | "solana"
    pub sender: String,
    #[serde(default)]
    pub nonce: Option<u64>,
    pub ptb: PtbJson,
    #[serde(default)]
    pub signature: Option<String>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct SubmitResponse {
    pub success: bool,
    pub message: String,
    pub data: Option<serde_json::Value>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct SubmitBatchRequest {
    pub requests: Vec<SubmitRequest>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct SubmitBatchItemResponse {
    pub index: usize,
    pub status: u16,
    pub success: bool,
    pub replayed: bool,
    pub message: String,
    pub data: Option<serde_json::Value>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct SubmitBatchResponse {
    pub success: bool,
    pub message: String,
    pub data: Vec<SubmitBatchItemResponse>,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
enum ExecutionBackendKind {
    Sui,
    Riscv,
}

impl ExecutionBackendKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Sui => "sui",
            Self::Riscv => "riscv",
        }
    }
}

impl std::fmt::Display for ExecutionBackendKind {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.as_str())
    }
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct IntentCompileErrorInfo {
    pub code: String,
    pub message: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub detail: Option<serde_json::Value>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(tag = "op", rename_all = "snake_case")]
pub enum RiscvProgramInstruction {
    ResolveObject {
        object_id: String,
    },
    PureInput {
        input_index: usize,
        bytes_len: usize,
        bytes_hash: String,
    },
    MoveCall {
        package: String,
        module: String,
        function: String,
        type_arguments: Vec<String>,
        arguments_len: usize,
    },
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct RiscvProgramArtifact {
    pub version: u32,
    pub entry: String,
    pub artifact_id: String,
    pub program_hash: String,
    pub ptb_hash: String,
    pub instructions: Vec<RiscvProgramInstruction>,
    #[serde(default)]
    pub notes: Vec<String>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum IntentPayload {
    SuiMoveCall(SuiMoveCallIntent),
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct SuiMoveCallIntent {
    pub package: String,
    pub module: String,
    pub function: String,
    #[serde(default, rename = "typeArguments")]
    pub type_arguments: Vec<String>,
    #[serde(default)]
    pub inputs: Vec<PtbInput>,
    #[serde(default)]
    pub arguments: Vec<ArgumentJson>,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct IntentCompileRequest {
    #[serde(default)]
    pub chain: Option<String>,
    pub sender: String,
    #[serde(default)]
    pub nonce: Option<u64>,
    pub intent: IntentPayload,
}

#[derive(Debug, Serialize, Deserialize, Clone)]
pub struct IntentCompileData {
    pub chain: String,
    pub backend: String,
    pub sender: String,
    pub nonce: u64,
    pub ptb: PtbJson,
    pub submit: SubmitRequest,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub artifact: Option<RiscvProgramArtifact>,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct IntentCompileResponse {
    pub success: bool,
    pub message: String,
    pub data: Option<IntentCompileData>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<IntentCompileErrorInfo>,
}

