#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OpsRuntimeRolloutActionAdapterKind {
    Deploy,
    Traffic,
}

impl OpsRuntimeRolloutActionAdapterKind {
    fn as_str(self) -> &'static str {
        match self {
            Self::Deploy => "deploy",
            Self::Traffic => "traffic",
        }
    }

    fn webhook_url<'a>(self, config: &'a DubheChannelConfig) -> Option<&'a str> {
        match self {
            Self::Deploy => config
                .ops_runtime_rollout_deploy_action_webhook_url
                .as_deref(),
            Self::Traffic => config
                .ops_runtime_rollout_traffic_action_webhook_url
                .as_deref(),
        }
    }

    fn bearer_token<'a>(self, config: &'a DubheChannelConfig) -> Option<&'a str> {
        match self {
            Self::Deploy => config
                .ops_runtime_rollout_deploy_action_webhook_bearer_token
                .as_deref(),
            Self::Traffic => config
                .ops_runtime_rollout_traffic_action_webhook_bearer_token
                .as_deref(),
        }
    }

    fn hmac_secret<'a>(self, config: &'a DubheChannelConfig) -> Option<&'a str> {
        match self {
            Self::Deploy => config
                .ops_runtime_rollout_deploy_action_webhook_hmac_secret
                .as_deref(),
            Self::Traffic => config
                .ops_runtime_rollout_traffic_action_webhook_hmac_secret
                .as_deref(),
        }
    }

    fn callback_token_secret<'a>(self, config: &'a DubheChannelConfig) -> Option<&'a str> {
        match self {
            Self::Deploy => config
                .ops_runtime_rollout_deploy_action_callback_token_secret
                .as_deref(),
            Self::Traffic => config
                .ops_runtime_rollout_traffic_action_callback_token_secret
                .as_deref(),
        }
    }
}

