#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeadLetterReplaySource {
    Manual,
    Auto,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeadLetterAutoReplayBackoffClass {
    PolicyBlocked,
    CooldownBlocked,
    LeaseConflict,
    Failed,
}

impl DeadLetterAutoReplayBackoffClass {
    fn as_str(self) -> &'static str {
        match self {
            Self::PolicyBlocked => "policy_blocked",
            Self::CooldownBlocked => "cooldown_blocked",
            Self::LeaseConflict => "lease_conflict",
            Self::Failed => "failed",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DeadLetterReplayInternalErrorClass {
    ReplayStatusRead,
    ReplayHandoffRead,
    EscalationAckRead,
    EscalationNotificationRead,
    ReplayHistoryRead,
}

impl DeadLetterReplayInternalErrorClass {
    fn as_str(self) -> &'static str {
        match self {
            Self::ReplayStatusRead => "replay_status_read_failed",
            Self::ReplayHandoffRead => "replay_handoff_read_failed",
            Self::EscalationAckRead => "escalation_ack_read_failed",
            Self::EscalationNotificationRead => "escalation_notification_read_failed",
            Self::ReplayHistoryRead => "replay_history_read_failed",
        }
    }
}

impl DeadLetterReplaySource {
    fn as_str(self) -> &'static str {
        match self {
            Self::Manual => "manual",
            Self::Auto => "auto",
        }
    }

    fn default_operator(self) -> &'static str {
        match self {
            Self::Manual => "ops",
            Self::Auto => "system:auto-replay",
        }
    }

    fn default_reason(self) -> &'static str {
        match self {
            Self::Manual => "manual dead-letter replay",
            Self::Auto => "automatic dead-letter replay",
        }
    }
}

