#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
enum SubmitMaterializationFailureClass {
    Unknown,
    ScopeSnapshotQuery,
    RuntimeSnapshot,
    ScopeRuntimeEvent,
    RuntimePublish,
}

impl Default for SubmitMaterializationFailureClass {
    fn default() -> Self {
        Self::Unknown
    }
}

impl SubmitMaterializationFailureClass {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Unknown => "unknown",
            Self::ScopeSnapshotQuery => "scope_snapshot_query_failed",
            Self::RuntimeSnapshot => "runtime_snapshot_failed",
            Self::ScopeRuntimeEvent => "scope_runtime_event_failed",
            Self::RuntimePublish => "runtime_publish_failed",
        }
    }
}

