    async fn push_dead_letter_replay_history(
        &self,
        entry: &DeadLetterReplayHistoryEntry,
        keep_limit: usize,
    ) -> Result<()> {
        if keep_limit == 0 {
            return Ok(());
        }

        let key = self.replay_history_key();
        let payload = serde_json::to_string(entry)?;
        let mut connection = self.connection.clone();
        let _: () = redis::pipe()
            .cmd("LPUSH")
            .arg(&key)
            .arg(payload)
            .ignore()
            .cmd("LTRIM")
            .arg(&key)
            .arg(0)
            .arg((keep_limit as isize) - 1)
            .ignore()
            .query_async(&mut connection)
            .await?;
        Ok(())
    }

    async fn peek_dead_letter_replay_history(
        &self,
        limit: usize,
    ) -> Result<Vec<DeadLetterReplayHistoryEntry>> {
        if limit == 0 {
            return Ok(Vec::new());
        }

        let key = self.replay_history_key();
        let mut connection = self.connection.clone();
        let values: Vec<String> = connection.lrange(&key, 0, (limit as isize) - 1).await?;
        values
            .into_iter()
            .map(|value| serde_json::from_str(&value).map_err(Into::into))
            .collect()
    }

