    async fn push_ops_runtime_rollout_receipt_history(
        &self,
        entry: &OpsRuntimeRolloutReceiptHistoryEntry,
        keep_limit: usize,
    ) -> Result<()> {
        if keep_limit == 0 {
            return Ok(());
        }

        let key = self.ops_runtime_rollout_receipt_history_key();
        let payload = serde_json::to_string(entry)?;
        let mut connection = self.connection.clone();
        let _: () = redis::pipe()
            .cmd("LPUSH")
            .arg(&key)
            .arg(payload)
            .ignore()
            .cmd("LTRIM")
            .arg(&key)
            .arg(0)
            .arg((keep_limit as isize) - 1)
            .ignore()
            .query_async(&mut connection)
            .await?;
        Ok(())
    }

    async fn peek_ops_runtime_rollout_receipt_history(
        &self,
        limit: usize,
    ) -> Result<Vec<OpsRuntimeRolloutReceiptHistoryEntry>> {
        if limit == 0 {
            return Ok(Vec::new());
        }

        let key = self.ops_runtime_rollout_receipt_history_key();
        let mut connection = self.connection.clone();
        let values: Vec<String> = connection.lrange(&key, 0, (limit as isize) - 1).await?;
        values
            .into_iter()
            .map(|value| serde_json::from_str(&value).map_err(Into::into))
            .collect()
    }

