    async fn admit_ops_runtime_topic_publish_window(
        &self,
        scoped_topic: &str,
        now_ms: u64,
        window_ms: u64,
        publish_limit_per_window: u64,
    ) -> Result<ClusterTopicPublishWindowState> {
        let key = self.ops_runtime_topic_publish_window_key(scoped_topic);
        let retention_ms = window_ms.saturating_mul(3).max(window_ms).max(1_000);
        let script = Script::new(
            r#"
            local raw = redis.call("GET", KEYS[1])
            local state = nil
            if raw then
              state = cjson.decode(raw)
            else
              state = {
                window_started_at_ms = tonumber(ARGV[1]),
                publish_count = 0,
                rejected_publishes = 0
              }
            end

            local now_ms = tonumber(ARGV[1])
            local window_ms = tonumber(ARGV[2])
            local publish_limit = tonumber(ARGV[3])
            local started = tonumber(state["window_started_at_ms"] or "0")
            if started == 0 or (window_ms > 0 and (now_ms - started) >= window_ms) then
              state["window_started_at_ms"] = now_ms
              state["publish_count"] = 0
              state["rejected_publishes"] = 0
            end

            local admitted = 1
            local publish_count = tonumber(state["publish_count"] or "0")
            if publish_limit > 0 and publish_count >= publish_limit then
              state["rejected_publishes"] = tonumber(state["rejected_publishes"] or "0") + 1
              admitted = 0
            else
              state["publish_count"] = publish_count + 1
            end

            redis.call("SET", KEYS[1], cjson.encode(state), "PX", tonumber(ARGV[4]))
            return {
              admitted,
              tonumber(state["window_started_at_ms"] or "0"),
              tonumber(state["publish_count"] or "0"),
              tonumber(state["rejected_publishes"] or "0")
            }
            "#,
        );
        let mut connection = self.connection.clone();
        let result: Vec<i64> = script
            .key(key)
            .arg(now_ms as i64)
            .arg(window_ms as i64)
            .arg(publish_limit_per_window as i64)
            .arg(retention_ms as i64)
            .invoke_async(&mut connection)
            .await?;
        if result.len() != 4 {
            return Err(anyhow!(
                "unexpected redis topic publish window response len={}",
                result.len()
            ));
        }

        let window_started_at_ms = result[1].max(0) as u64;
        Ok(ClusterTopicPublishWindowState {
            admitted: result[0] != 0,
            window_started_at_ms,
            remaining_window_ms: topic_window_remaining_ms(window_started_at_ms, now_ms, window_ms),
            publish_count: result[2].max(0) as u64,
            rejected_publishes: result[3].max(0) as u64,
        })
    }

