async fn handle_metrics<DB>(state: &AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    refresh_submit_materialization_outbox_size(state).await;
    refresh_submit_materialization_dead_letter_size(state).await;
    refresh_submit_chain_commit_outbox_size(state).await;
    refresh_submit_chain_commit_dead_letter_size(state).await;
    let outbox_size = state
        .metrics
        .submit_materialization_outbox_size
        .load(Ordering::Relaxed);
    let dead_letter_size = state
        .metrics
        .submit_materialization_dead_letter_size
        .load(Ordering::Relaxed);
    let ready_evaluation = evaluate_ready_state(state, outbox_size, dead_letter_size).await;
    update_ready_metrics(&state.metrics, &ready_evaluation);
    let ready_slo = observe_ready_slo_snapshot(state, ready_evaluation.ready).await;
    let _ = current_ops_write_gate_state(state).await;
    let _ = current_ops_realtime_gate_state(state).await;
    let _ = current_ops_runtime_profile_state(state).await;
    let _ = current_ops_runtime_rollout_state(state).await;
    let _ = current_ops_runtime_drill_state(state).await;
    let _ = current_ops_runtime_rollout_receipt_state(state).await;
    let _ = current_ops_runtime_rollout_traffic_receipt_state(state).await;
    if let Ok(snapshot) = build_dead_letter_ops_snapshot(state).await {
        let feed = build_ops_alert_feed(state, ready_evaluation.clone(), &ready_slo, &snapshot);
        update_ops_alert_metrics(&state.metrics, feed.alerts.as_slice());
    }
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "text/plain; version=0.0.4")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(state.metrics.render(state.config.hosted_mode)))
        .unwrap()
}

async fn handle_ops_alerts<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let snapshot = match build_dead_letter_ops_snapshot(&state).await {
        Ok(snapshot) => snapshot,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let ready_evaluation =
        evaluate_ready_state(&state, snapshot.outbox_size, snapshot.dead_letter_size).await;
    update_ready_metrics(&state.metrics, &ready_evaluation);
    let ready_slo = observe_ready_slo_snapshot(&state, ready_evaluation.ready).await;
    let feed = build_ops_alert_feed(&state, ready_evaluation, &ready_slo, &snapshot);
    update_ops_alert_metrics(&state.metrics, feed.alerts.as_slice());
    let write_gate_state =
        current_ops_write_gate_state(&state)
            .await
            .unwrap_or(OpsWriteGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let realtime_gate_state =
        current_ops_realtime_gate_state(&state)
            .await
            .unwrap_or(OpsRealtimeGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let runtime_drill_state = current_ops_runtime_drill_state(&state)
        .await
        .unwrap_or_default();
    let runtime_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let runtime_profile_matches_effective = ops_runtime_profile_matches_effective(
        &runtime_profile_state,
        &write_gate_state,
        &realtime_gate_state,
        &runtime_drill_state,
    );
    let runtime_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let runtime_rollout_matches_target_profile =
        runtime_profile_state.profile == runtime_rollout_state.target_profile;
    let runtime_rollout_target_matches_effective = ops_runtime_profile_matches_effective(
        &OpsRuntimeProfileState {
            profile: runtime_rollout_state.target_profile.clone(),
            operator: runtime_rollout_state.operator.clone(),
            reason: runtime_rollout_state.reason.clone(),
            request_id: runtime_rollout_state.request_id.clone(),
            updated_at_ms: runtime_rollout_state.updated_at_ms,
        },
        &write_gate_state,
        &realtime_gate_state,
        &runtime_drill_state,
    );
    let dispatch_state = current_ops_alert_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_alert_delivery_pending(&state)
        .await
        .unwrap_or_default();
    let critical_alerts = feed
        .alerts
        .iter()
        .filter(|alert| {
            alert
                .get("severity")
                .and_then(|value| value.as_str())
                .map(|severity| severity_rank(severity) >= severity_rank("critical"))
                .unwrap_or(false)
        })
        .count() as u64;

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "generated_at_ms": feed.generated_at_ms,
                "ready": feed.ready_evaluation.ready,
                "summary": {
                    "active_alerts": feed.alerts.len(),
                    "critical_alerts": critical_alerts,
                    "highest_severity": feed.highest_severity,
                    "fingerprint": feed.fingerprint,
                },
                "ready_slo": ready_slo_snapshot_to_json(&ready_slo),
                "runtime": {
                    "rollout": {
                        "active": runtime_rollout_state.active,
                        "phase": runtime_rollout_state.phase,
                        "severity": ops_runtime_rollout_severity(&runtime_rollout_state.phase),
                        "target_profile": runtime_rollout_state.target_profile,
                        "baseline_profile": runtime_rollout_state.baseline_profile,
                        "operator": runtime_rollout_state.operator,
                        "reason": runtime_rollout_state.reason,
                        "request_id": runtime_rollout_state.request_id,
                        "updated_at_ms": runtime_rollout_state.updated_at_ms,
                        "matches_target_profile": runtime_rollout_matches_target_profile,
                        "target_matches_effective": runtime_rollout_target_matches_effective,
                        "history_limit": state.config.ops_runtime_rollout_history_limit,
                    },
                    "profile": {
                        "profile": runtime_profile_state.profile,
                        "active": ops_runtime_profile_is_active(&runtime_profile_state.profile),
                        "severity": ops_runtime_profile_severity(&runtime_profile_state.profile),
                        "operator": runtime_profile_state.operator,
                        "reason": runtime_profile_state.reason,
                        "request_id": runtime_profile_state.request_id,
                        "updated_at_ms": runtime_profile_state.updated_at_ms,
                        "matches_effective": runtime_profile_matches_effective,
                    },
                    "write_gate": {
                        "enabled": write_gate_state.enabled,
                        "operator": write_gate_state.operator,
                        "reason": write_gate_state.reason,
                        "request_id": write_gate_state.request_id,
                        "updated_at_ms": write_gate_state.updated_at_ms,
                    },
                    "realtime_gate": {
                        "enabled": realtime_gate_state.enabled,
                        "operator": realtime_gate_state.operator,
                        "reason": realtime_gate_state.reason,
                        "request_id": realtime_gate_state.request_id,
                        "updated_at_ms": realtime_gate_state.updated_at_ms,
                    },
                    "drill": {
                        "enabled": runtime_drill_state.enabled,
                        "kind": runtime_drill_state.kind,
                        "operator": runtime_drill_state.operator,
                        "reason": runtime_drill_state.reason,
                        "request_id": runtime_drill_state.request_id,
                        "updated_at_ms": runtime_drill_state.updated_at_ms,
                        "degrades_ready": ops_runtime_drill_kind_degrades_ready(&runtime_drill_state.kind),
                    }
                },
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_alert_webhook_url.is_some(),
                    state.config.ops_alert_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
                "objectives": feed.objectives,
                "alerts": feed.alerts,
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_alerts_dispatch<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let dispatch_request = if body_bytes.is_empty() {
        OpsAlertDispatchRequest::default()
    } else {
        match serde_json::from_slice::<OpsAlertDispatchRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({ "error": format!("invalid alert dispatch request: {}", error) })
                            .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    match dispatch_ops_alert_feed(&state, dispatch_request.force.unwrap_or(false)).await {
        Ok((feed, skipped)) => {
            let pending_delivery = current_ops_alert_delivery_pending(&state)
                .await
                .unwrap_or_default();
            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "ok": true,
                        "request_id": request_id,
                        "skipped": skipped,
                        "webhook_url": state.config.ops_alert_webhook_url.clone(),
                        "delivery_pending": pending_delivery.is_some(),
                        "summary": {
                            "active_alerts": feed.alerts.len(),
                            "highest_severity": feed.highest_severity,
                            "fingerprint": feed.fingerprint,
                        },
                    })
                    .to_string(),
                ))
                .unwrap()
        }
        Err(error) => Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap(),
    }
}

