async fn handle_ops_runtime_topics<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let topics = snapshot_realtime_topics(&state).await;
    let _ = sync_local_realtime_topic_presence(&state).await;
    let cluster_topics = aggregate_realtime_topic_presence(&state, &topics)
        .await
        .unwrap_or_default();
    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "realtime_topics": realtime_topics_json(&state.config, &state.metrics, &topics),
                "cluster_realtime_topics": aggregate_realtime_topics_json(
                    &state.config,
                    &cluster_topics,
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_profile<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    if req.method() == hyper::Method::GET {
        let profile_state = match current_ops_runtime_profile_state(&state).await {
            Ok(profile_state) => profile_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
        let write_gate_state =
            current_ops_write_gate_state(&state)
                .await
                .unwrap_or(OpsWriteGateState {
                    enabled: true,
                    operator: "system:default".to_string(),
                    reason: None,
                    request_id: "default".to_string(),
                    updated_at_ms: 0,
                });
        let realtime_gate_state =
            current_ops_realtime_gate_state(&state)
                .await
                .unwrap_or(OpsRealtimeGateState {
                    enabled: true,
                    operator: "system:default".to_string(),
                    reason: None,
                    request_id: "default".to_string(),
                    updated_at_ms: 0,
                });
        let runtime_drill_state = current_ops_runtime_drill_state(&state)
            .await
            .unwrap_or_default();
        let matches_effective = ops_runtime_profile_matches_effective(
            &profile_state,
            &write_gate_state,
            &realtime_gate_state,
            &runtime_drill_state,
        );

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "runtime_profile": {
                        "profile": profile_state.profile,
                        "active": ops_runtime_profile_is_active(&profile_state.profile),
                        "severity": ops_runtime_profile_severity(&profile_state.profile),
                        "operator": profile_state.operator,
                        "reason": profile_state.reason,
                        "request_id": profile_state.request_id,
                        "updated_at_ms": profile_state.updated_at_ms,
                        "matches_effective": matches_effective,
                        "effective": {
                            "write_gate_enabled": write_gate_state.enabled,
                            "realtime_gate_enabled": realtime_gate_state.enabled,
                            "runtime_drill_enabled": runtime_drill_state.enabled,
                            "runtime_drill_kind": runtime_drill_state.kind,
                        },
                        "history_limit": state.config.ops_runtime_profile_history_limit,
                    }
                })
                .to_string(),
            ))
            .unwrap();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let profile_request = match serde_json::from_slice::<OpsRuntimeProfileRequest>(&body_bytes) {
        Ok(payload) => payload,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("invalid runtime profile request: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let profile = match normalize_ops_runtime_profile(profile_request.profile) {
        Ok(profile) => profile,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let profile_state = OpsRuntimeProfileState {
        profile,
        operator: normalized_optional_string(profile_request.operator)
            .unwrap_or_else(|| "ops".to_string()),
        reason: normalized_optional_string(profile_request.reason),
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    let (expected_write_gate, expected_realtime_gate, expected_runtime_drill) =
        build_runtime_profile_effective_states(&profile_state);

    match apply_ops_runtime_profile_with_audit(&state, profile_state.clone(), "manual").await {
        Ok(history_entry) => Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "ok": true,
                    "runtime_profile": {
                        "profile": profile_state.profile,
                        "active": ops_runtime_profile_is_active(&profile_state.profile),
                        "severity": ops_runtime_profile_severity(&profile_state.profile),
                        "operator": profile_state.operator,
                        "reason": profile_state.reason,
                        "request_id": profile_state.request_id,
                        "updated_at_ms": profile_state.updated_at_ms,
                        "matches_effective": true,
                        "effective": {
                            "write_gate_enabled": expected_write_gate.enabled,
                            "realtime_gate_enabled": expected_realtime_gate.enabled,
                            "runtime_drill_enabled": expected_runtime_drill.enabled,
                            "runtime_drill_kind": expected_runtime_drill.kind,
                        },
                    },
                    "history_entry": history_entry,
                })
                .to_string(),
            ))
            .unwrap(),
        Err(error) => Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap(),
    }
}

