async fn handle_ops_runtime_profile_rollback<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let rollback_request = if body_bytes.is_empty() {
        OpsRuntimeProfileRollbackRequest::default()
    } else {
        match serde_json::from_slice::<OpsRuntimeProfileRollbackRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({ "error": format!("invalid runtime profile rollback request: {}", error) })
                            .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    let history_limit = state.config.ops_runtime_profile_history_limit.max(1);
    let history = match current_ops_runtime_profile_history(&state, history_limit).await {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let target_entry = if let Some(target_request_id) = rollback_request.request_id.as_deref() {
        history
            .iter()
            .find(|entry| entry.request_id == target_request_id)
            .cloned()
    } else {
        let steps_back = rollback_request.steps_back.unwrap_or(1);
        history.get(steps_back).cloned()
    };
    let Some(target_entry) = target_entry else {
        return ops_conflict_response("runtime profile rollback target unavailable".to_string());
    };
    let current_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let rollback_state = OpsRuntimeProfileState {
        profile: target_entry.profile.clone(),
        operator: normalized_optional_string(rollback_request.operator)
            .unwrap_or_else(|| "ops:rollback".to_string()),
        reason: normalized_optional_string(rollback_request.reason).or_else(|| {
            Some(format!(
                "rollback to request_id={} profile={}",
                target_entry.request_id, target_entry.profile
            ))
        }),
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    let (expected_write_gate, expected_realtime_gate, expected_runtime_drill) =
        build_runtime_profile_effective_states(&rollback_state);

    match apply_ops_runtime_profile_with_audit(&state, rollback_state.clone(), "rollback").await {
        Ok(history_entry) => Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "ok": true,
                    "rollback": {
                        "from_profile": current_profile_state.profile,
                        "to_profile": rollback_state.profile,
                        "target_history_request_id": target_entry.request_id,
                        "target_history_source": target_entry.source,
                        "history_entry": history_entry,
                    },
                    "runtime_profile": {
                        "profile": rollback_state.profile,
                        "active": ops_runtime_profile_is_active(&rollback_state.profile),
                        "severity": ops_runtime_profile_severity(&rollback_state.profile),
                        "operator": rollback_state.operator,
                        "reason": rollback_state.reason,
                        "request_id": rollback_state.request_id,
                        "updated_at_ms": rollback_state.updated_at_ms,
                        "matches_effective": true,
                        "effective": {
                            "write_gate_enabled": expected_write_gate.enabled,
                            "realtime_gate_enabled": expected_realtime_gate.enabled,
                            "runtime_drill_enabled": expected_runtime_drill.enabled,
                            "runtime_drill_kind": expected_runtime_drill.kind,
                        },
                    }
                })
                .to_string(),
            ))
            .unwrap(),
        Err(error) => Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap(),
    }
}

