fn runtime_rollout_stage_completion_to_json(
    evaluation: &RuntimeRolloutStageCompletionEvaluation,
) -> serde_json::Value {
    json!({
        "summary": {
            "current_phase": evaluation.current_phase,
            "next_phase": evaluation.next_phase,
            "can_transition": evaluation.can_transition,
            "recommended_action": evaluation.recommended_action,
            "blocked_reasons": evaluation.blocked_reasons,
        },
        "phase_dwell": evaluation.phase_dwell.as_ref().map_or_else(
            || json!({ "active": false }),
            |phase_dwell| {
                json!({
                    "active": true,
                    "phase": phase_dwell.phase,
                    "required_ms": phase_dwell.required_ms,
                    "elapsed_ms": phase_dwell.elapsed_ms,
                    "remaining_ms": phase_dwell.remaining_ms,
                    "started_at_ms": phase_dwell.started_at_ms,
                    "satisfied": phase_dwell.satisfied,
                })
            }
        ),
        "checks": evaluation.checks,
    })
}

fn rollout_controller_state_to_json(
    controller_state: &OpsRuntimeRolloutControllerState,
    interval_ms: u64,
) -> serde_json::Value {
    json!({
        "enabled": interval_ms > 0,
        "interval_ms": interval_ms,
        "last_request_id": controller_state.last_request_id,
        "last_decision_at_ms": controller_state.last_decision_at_ms,
        "last_decision": controller_state.last_decision,
        "rollout_request_id": controller_state.rollout_request_id,
        "current_phase": controller_state.current_phase,
        "next_phase": controller_state.next_phase,
        "recommended_action": controller_state.recommended_action,
        "blocked_reasons": controller_state.blocked_reasons,
        "ready_slo_severity": controller_state.ready_slo_severity,
        "ready_slo_policy_action": controller_state.ready_slo_policy_action,
        "last_error": controller_state.last_error,
        "triggered": controller_state.triggered,
    })
}

