fn rollout_dispatch_result_to_json(
    dispatch_result: Option<&Result<(OpsRuntimeRolloutDeliveryFeed, bool), String>>,
) -> serde_json::Value {
    match dispatch_result {
        Some(Ok((feed, skipped))) => json!({
            "attempted": true,
            "skipped": skipped,
            "source": feed.source,
            "fingerprint": feed.fingerprint,
            "generated_at_ms": feed.generated_at_ms,
        }),
        Some(Err(error)) => json!({
            "attempted": true,
            "error": error,
        }),
        None => json!({
            "attempted": false,
            "reason": "webhook_not_configured",
        }),
    }
}

fn rollout_action_dispatch_result_to_json(
    dispatch_result: Option<&Result<(OpsRuntimeRolloutActionFeed, bool), String>>,
) -> serde_json::Value {
    match dispatch_result {
        Some(Ok((feed, skipped))) => json!({
            "attempted": true,
            "skipped": skipped,
            "adapter": feed.adapter.as_str(),
            "source": feed.source,
            "fingerprint": feed.fingerprint,
            "generated_at_ms": feed.generated_at_ms,
        }),
        Some(Err(error)) => json!({
            "attempted": true,
            "error": error,
        }),
        None => json!({
            "attempted": false,
            "reason": "webhook_not_configured",
        }),
    }
}

fn select_ops_runtime_rollout_rollback_target(
    history: &[OpsRuntimeRolloutHistoryEntry],
    request_id: Option<&str>,
    steps_back: usize,
) -> Option<OpsRuntimeRolloutHistoryEntry> {
    if let Some(target_request_id) = request_id {
        history
            .iter()
            .find(|entry| entry.request_id == target_request_id)
            .cloned()
    } else {
        history.get(steps_back).cloned()
    }
}

fn is_failed_receipt_for_current_rollout(
    receipt_state: Option<&OpsRuntimeRolloutReceiptState>,
    rollout_state: &OpsRuntimeRolloutState,
) -> bool {
    receipt_state
        .map(|receipt| {
            receipt.rollout_request_id == rollout_state.request_id && receipt.status == "failed"
        })
        .unwrap_or(false)
}

fn is_failed_traffic_receipt_for_current_rollout(
    traffic_receipt_state: Option<&OpsRuntimeRolloutTrafficReceiptState>,
    rollout_state: &OpsRuntimeRolloutState,
) -> bool {
    traffic_receipt_state
        .map(|receipt| {
            receipt.rollout_request_id == rollout_state.request_id && receipt.status == "failed"
        })
        .unwrap_or(false)
}

fn is_timed_out_receipt_for_current_rollout(
    receipt_state: Option<&OpsRuntimeRolloutReceiptState>,
    rollout_state: &OpsRuntimeRolloutState,
    timeout_ms: u64,
    now_ms: u64,
) -> bool {
    receipt_state
        .map(|receipt| {
            receipt.rollout_request_id == rollout_state.request_id
                && rollout_execution_receipt_timed_out(
                    receipt.status.as_str(),
                    receipt.updated_at_ms,
                    timeout_ms,
                    now_ms,
                )
        })
        .unwrap_or(false)
}

fn is_timed_out_traffic_receipt_for_current_rollout(
    traffic_receipt_state: Option<&OpsRuntimeRolloutTrafficReceiptState>,
    rollout_state: &OpsRuntimeRolloutState,
    timeout_ms: u64,
    now_ms: u64,
) -> bool {
    traffic_receipt_state
        .map(|receipt| {
            receipt.rollout_request_id == rollout_state.request_id
                && rollout_execution_receipt_timed_out(
                    receipt.status.as_str(),
                    receipt.updated_at_ms,
                    timeout_ms,
                    now_ms,
                )
        })
        .unwrap_or(false)
}

async fn handle_ops_runtime_rollout_rollback<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let rollback_request = if body_bytes.is_empty() {
        OpsRuntimeRolloutRollbackRequest::default()
    } else {
        match serde_json::from_slice::<OpsRuntimeRolloutRollbackRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({ "error": format!("invalid runtime rollout rollback request: {}", error) })
                            .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    let history_limit = state.config.ops_runtime_rollout_history_limit.max(1);
    let history = match current_ops_runtime_rollout_history(&state, history_limit).await {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let target_entry = select_ops_runtime_rollout_rollback_target(
        &history,
        rollback_request.request_id.as_deref(),
        rollback_request.steps_back.unwrap_or(1),
    );
    let Some(target_entry) = target_entry else {
        return ops_conflict_response("runtime rollout rollback target unavailable".to_string());
    };

    let apply_target_profile = rollback_request.apply_target_profile.unwrap_or(false);
    if apply_target_profile {
        let target_profile_state = OpsRuntimeProfileState {
            profile: target_entry.target_profile.clone(),
            operator: normalized_optional_string(rollback_request.operator.clone())
                .unwrap_or_else(|| "ops:rollout-rollback".to_string()),
            reason: normalized_optional_string(rollback_request.reason.clone()).or_else(|| {
                Some(format!(
                    "rollout rollback to request_id={} target_profile={}",
                    target_entry.request_id, target_entry.target_profile
                ))
            }),
            request_id: request_id.clone(),
            updated_at_ms: now_ts_ms(),
        };
        if let Err(error) =
            apply_ops_runtime_profile_with_audit(&state, target_profile_state, "rollout_rollback")
                .await
        {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    }

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let rollout_state = OpsRuntimeRolloutState {
        active: target_entry.active,
        phase: target_entry.phase.clone(),
        target_profile: target_entry.target_profile.clone(),
        baseline_profile: target_entry.baseline_profile.clone(),
        operator: normalized_optional_string(rollback_request.operator)
            .unwrap_or_else(|| "ops:rollout-rollback".to_string()),
        reason: normalized_optional_string(rollback_request.reason).or_else(|| {
            Some(format!(
                "rollback to request_id={} phase={} target_profile={}",
                target_entry.request_id, target_entry.phase, target_entry.target_profile
            ))
        }),
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = match update_ops_runtime_rollout_with_audit(
        &state,
        rollout_state.clone(),
        apply_target_profile,
        "rollback",
    )
    .await
    {
        Ok(entry) => entry,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let rollout_dispatch = if state.config.ops_runtime_rollout_webhook_url.is_some() {
        Some(
            dispatch_ops_runtime_rollout_feed(
                &state,
                false,
                Some("rollback"),
                Some(&history_entry),
            )
            .await,
        )
    } else {
        None
    };
    let deploy_action_dispatch = if state
        .config
        .ops_runtime_rollout_deploy_action_webhook_url
        .is_some()
    {
        Some(
            dispatch_ops_runtime_rollout_action_feed(
                &state,
                OpsRuntimeRolloutActionAdapterKind::Deploy,
                true,
                Some("rollback"),
                Some(&history_entry),
            )
            .await,
        )
    } else {
        None
    };

    let updated_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let write_gate_state =
        current_ops_write_gate_state(&state)
            .await
            .unwrap_or(OpsWriteGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let realtime_gate_state =
        current_ops_realtime_gate_state(&state)
            .await
            .unwrap_or(OpsRealtimeGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let runtime_drill_state = current_ops_runtime_drill_state(&state)
        .await
        .unwrap_or_default();
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();
    let deploy_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let deploy_action_pending = current_ops_runtime_rollout_action_delivery_pending(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let matches_target_profile = updated_profile_state.profile == rollout_state.target_profile;
    let target_matches_effective = ops_runtime_profile_matches_effective(
        &OpsRuntimeProfileState {
            profile: rollout_state.target_profile.clone(),
            operator: rollout_state.operator.clone(),
            reason: rollout_state.reason.clone(),
            request_id: rollout_state.request_id.clone(),
            updated_at_ms: rollout_state.updated_at_ms,
        },
        &write_gate_state,
        &realtime_gate_state,
        &runtime_drill_state,
    );

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "rollback": {
                    "from_active": current_rollout_state.active,
                    "from_phase": current_rollout_state.phase,
                    "to_active": rollout_state.active,
                    "to_phase": rollout_state.phase,
                    "target_history_request_id": target_entry.request_id,
                    "target_history_source": target_entry.source,
                    "history_entry": history_entry,
                },
                "runtime_rollout": runtime_rollout_state_to_json(
                    &rollout_state,
                    matches_target_profile,
                    target_matches_effective,
                    state.config.ops_runtime_rollout_history_limit,
                ),
                "dispatch": rollout_dispatch_result_to_json(rollout_dispatch.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
                "deploy_action_dispatch": rollout_action_dispatch_result_to_json(
                    deploy_action_dispatch.as_ref(),
                ),
                "deploy_action_delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_deploy_action_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_adapter_interval_ms,
                    &deploy_action_dispatch_state,
                    deploy_action_pending.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout_auto_rollback<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    state
        .metrics
        .ops_runtime_rollout_auto_rollback_requests_total
        .fetch_add(1, Ordering::Relaxed);

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let auto_rollback_request = if body_bytes.is_empty() {
        OpsRuntimeRolloutAutoRollbackRequest::default()
    } else {
        match serde_json::from_slice::<OpsRuntimeRolloutAutoRollbackRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!(
                                "invalid runtime rollout auto rollback request: {}",
                                error
                            )
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    if !current_rollout_state.active {
        state
            .metrics
            .ops_runtime_rollout_auto_rollback_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(
            "runtime rollout auto rollback requires an active rollout".to_string(),
        );
    }

    let receipt_state = match current_ops_runtime_rollout_receipt_state(&state).await {
        Ok(receipt_state) => receipt_state,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let traffic_receipt_state =
        match current_ops_runtime_rollout_traffic_receipt_state(&state).await {
            Ok(traffic_receipt_state) => traffic_receipt_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
    let force = auto_rollback_request.force.unwrap_or(false);
    let receipt_failed =
        is_failed_receipt_for_current_rollout(receipt_state.as_ref(), &current_rollout_state);
    let traffic_receipt_failed = is_failed_traffic_receipt_for_current_rollout(
        traffic_receipt_state.as_ref(),
        &current_rollout_state,
    );
    let ready_slo_critical_requested = auto_rollback_request.ready_slo_critical.unwrap_or(false);
    let ready_slo_critical = if ready_slo_critical_requested {
        match current_ready_slo_severity(&state).await {
            Ok((_ready_evaluation, _ready_slo, severity)) => severity == Some("critical"),
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        }
    } else {
        false
    };
    if !receipt_failed && !traffic_receipt_failed && !ready_slo_critical && !force {
        state
            .metrics
            .ops_runtime_rollout_auto_rollback_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        let rollback_requirement_error = if ready_slo_critical_requested {
            format!(
                "runtime rollout auto rollback requires failed receipt, failed traffic receipt, or critical ready slo for current rollout request_id={}",
                current_rollout_state.request_id
            )
        } else {
            format!(
                "runtime rollout auto rollback requires failed receipt or failed traffic receipt for current rollout request_id={}",
                current_rollout_state.request_id
            )
        };
        return Response::builder()
            .status(StatusCode::CONFLICT)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": rollback_requirement_error,
                    "force_hint": true,
                    "ready_slo_critical_requested": ready_slo_critical_requested,
                    "ready_slo_critical": ready_slo_critical,
                    "runtime_rollout": {
                        "active": current_rollout_state.active,
                        "phase": current_rollout_state.phase,
                        "request_id": current_rollout_state.request_id,
                    },
                    "receipt": receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |receipt_state| {
                            rollout_receipt_state_to_json(
                                receipt_state,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                    "traffic_receipt": traffic_receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |traffic_receipt_state| {
                            rollout_traffic_receipt_state_to_json(
                                traffic_receipt_state,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config
                                    .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }

    let history_limit = state.config.ops_runtime_rollout_history_limit.max(1);
    let history = match current_ops_runtime_rollout_history(&state, history_limit).await {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let target_entry = select_ops_runtime_rollout_rollback_target(
        &history,
        auto_rollback_request.request_id.as_deref(),
        auto_rollback_request.steps_back.unwrap_or(1),
    );
    let Some(target_entry) = target_entry else {
        state
            .metrics
            .ops_runtime_rollout_auto_rollback_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(
            "runtime rollout auto rollback target unavailable".to_string(),
        );
    };

    let apply_target_profile = auto_rollback_request.apply_target_profile.unwrap_or(true);
    let operator = normalized_optional_string(auto_rollback_request.operator)
        .unwrap_or_else(|| "ops:auto-rollback".to_string());
    let reason = normalized_optional_string(auto_rollback_request.reason).or_else(|| {
        Some(format!(
            "auto rollback after {} for rollout_request_id={} to request_id={} target_profile={}",
            if receipt_failed {
                "failed receipt"
            } else if traffic_receipt_failed {
                "failed traffic receipt"
            } else if ready_slo_critical {
                "critical ready slo"
            } else {
                "manual trigger"
            },
            current_rollout_state.request_id,
            target_entry.request_id,
            target_entry.target_profile
        ))
    });
    if apply_target_profile {
        let target_profile_state = OpsRuntimeProfileState {
            profile: target_entry.target_profile.clone(),
            operator: operator.clone(),
            reason: reason.clone(),
            request_id: request_id.clone(),
            updated_at_ms: now_ts_ms(),
        };
        if let Err(error) =
            apply_ops_runtime_profile_with_audit(&state, target_profile_state, "auto_rollback")
                .await
        {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    }

    let rollback_state = OpsRuntimeRolloutState {
        active: target_entry.active,
        phase: target_entry.phase.clone(),
        target_profile: target_entry.target_profile.clone(),
        baseline_profile: target_entry.baseline_profile.clone(),
        operator,
        reason,
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = match update_ops_runtime_rollout_with_audit(
        &state,
        rollback_state.clone(),
        apply_target_profile,
        "auto_rollback",
    )
    .await
    {
        Ok(entry) => entry,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    state
        .metrics
        .ops_runtime_rollout_auto_rollback_triggered_total
        .fetch_add(1, Ordering::Relaxed);

    let dispatch_result = if auto_rollback_request.dispatch_webhook.unwrap_or(true)
        && state.config.ops_runtime_rollout_webhook_url.is_some()
    {
        Some(
            dispatch_ops_runtime_rollout_feed(
                &state,
                true,
                Some("auto_rollback"),
                Some(&history_entry),
            )
            .await,
        )
    } else {
        None
    };
    let deploy_action_dispatch = if auto_rollback_request.dispatch_webhook.unwrap_or(true)
        && state
            .config
            .ops_runtime_rollout_deploy_action_webhook_url
            .is_some()
    {
        Some(
            dispatch_ops_runtime_rollout_action_feed(
                &state,
                OpsRuntimeRolloutActionAdapterKind::Deploy,
                true,
                Some("auto_rollback"),
                Some(&history_entry),
            )
            .await,
        )
    } else {
        None
    };

    let updated_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let write_gate_state =
        current_ops_write_gate_state(&state)
            .await
            .unwrap_or(OpsWriteGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let realtime_gate_state =
        current_ops_realtime_gate_state(&state)
            .await
            .unwrap_or(OpsRealtimeGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let runtime_drill_state = current_ops_runtime_drill_state(&state)
        .await
        .unwrap_or_default();
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();
    let deploy_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let deploy_action_pending = current_ops_runtime_rollout_action_delivery_pending(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let latest_receipt_state = current_ops_runtime_rollout_receipt_state(&state)
        .await
        .unwrap_or_default();
    let latest_traffic_receipt_state = current_ops_runtime_rollout_traffic_receipt_state(&state)
        .await
        .unwrap_or_default();
    let matches_target_profile = updated_profile_state.profile == rollback_state.target_profile;
    let target_matches_effective = ops_runtime_profile_matches_effective(
        &OpsRuntimeProfileState {
            profile: rollback_state.target_profile.clone(),
            operator: rollback_state.operator.clone(),
            reason: rollback_state.reason.clone(),
            request_id: rollback_state.request_id.clone(),
            updated_at_ms: rollback_state.updated_at_ms,
        },
        &write_gate_state,
        &realtime_gate_state,
        &runtime_drill_state,
    );

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "auto_rollback": {
                    "forced": force,
                    "receipt_failed": receipt_failed,
                    "traffic_receipt_failed": traffic_receipt_failed,
                    "ready_slo_critical": ready_slo_critical,
                    "from_request_id": current_rollout_state.request_id,
                    "from_phase": current_rollout_state.phase,
                    "to_request_id": rollback_state.request_id,
                    "to_phase": rollback_state.phase,
                    "target_history_request_id": target_entry.request_id,
                    "target_history_source": target_entry.source,
                    "applied_target_profile": apply_target_profile,
                    "history_entry": history_entry,
                },
                "runtime_rollout": runtime_rollout_state_to_json(
                    &rollback_state,
                    matches_target_profile,
                    target_matches_effective,
                    state.config.ops_runtime_rollout_history_limit,
                ),
                "receipt": latest_receipt_state.as_ref().map_or_else(
                    || json!({ "active": false }),
                    |receipt_state| {
                        rollout_receipt_state_to_json(
                            receipt_state,
                            Some(rollback_state.request_id.as_str()),
                            state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                        )
                    }
                ),
                "traffic_receipt": latest_traffic_receipt_state.as_ref().map_or_else(
                    || json!({ "active": false }),
                    |traffic_receipt_state| {
                        rollout_traffic_receipt_state_to_json(
                            traffic_receipt_state,
                            Some(rollback_state.request_id.as_str()),
                            state.config
                                .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                        )
                    }
                ),
                "dispatch": rollout_dispatch_result_to_json(dispatch_result.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
                "deploy_action_dispatch": rollout_action_dispatch_result_to_json(
                    deploy_action_dispatch.as_ref(),
                ),
                "deploy_action_delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_deploy_action_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_adapter_interval_ms,
                    &deploy_action_dispatch_state,
                    deploy_action_pending.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout_checklist<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let rollout_state = match current_ops_runtime_rollout_state(&state).await {
        Ok(rollout_state) => rollout_state,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let evaluation = match evaluate_runtime_rollout_checklist(&state, rollout_state).await {
        Ok(evaluation) => evaluation,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            runtime_rollout_checklist_to_json(
                &evaluation,
                state.config.ops_runtime_rollout_history_limit,
            )
            .to_string(),
        ))
        .unwrap()
}

