async fn handle_ops_runtime_rollout_action_redispatch_adapter<DB>(
    req: Request<Body>,
    state: AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let redispatch_request = if body_bytes.is_empty() {
        OpsRuntimeRolloutActionRedispatchRequest::default()
    } else {
        match serde_json::from_slice::<OpsRuntimeRolloutActionRedispatchRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!(
                                "invalid runtime rollout {} action redispatch request: {}",
                                adapter.as_str(),
                                error
                            )
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    let source = normalized_optional_string(redispatch_request.source)
        .unwrap_or_else(|| "manual_redispatch".to_string());
    let reason = normalized_optional_string(redispatch_request.reason);
    match redispatch_ops_runtime_rollout_action_feed(
        &state,
        adapter,
        &request_id,
        &source,
        reason.as_deref(),
    )
    .await
    {
        Ok((feed, action_status)) => {
            let dispatch_state = current_ops_runtime_rollout_action_dispatch_state(&state, adapter)
                .await
                .unwrap_or_default();
            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "ok": true,
                        "request_id": request_id,
                        "adapter": adapter.as_str(),
                        "source": source,
                        "reason": reason,
                        "summary": {
                            "phase": feed.rollout_state.phase,
                            "target_profile": feed.rollout_state.target_profile,
                            "recommended_action": feed.checklist.recommended_action,
                            "can_proceed": feed.checklist.can_proceed,
                            "fingerprint": feed.fingerprint,
                        },
                        "ack_policy": {
                            "timeout_ms": state.config.ops_runtime_rollout_action_ack_timeout_ms,
                            "waiting_for_ack": action_status.waiting_for_ack,
                            "ack_timed_out": action_status.ack_timed_out,
                            "dispatched_current_action": action_status.dispatched_current_action,
                            "delivery_pending_current_action": action_status.delivery_pending_for_current_action,
                        },
                        "redispatch": rollout_action_redispatch_to_json(
                            &dispatch_state,
                            &action_status,
                        ),
                    })
                    .to_string(),
                ))
                .unwrap()
        }
        Err(error) => Response::builder()
            .status(StatusCode::CONFLICT)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap(),
    }
}

