async fn handle_ops_runtime_rollout_action_ack_adapter<DB>(
    req: Request<Body>,
    state: AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let current_feed =
        match build_ops_runtime_rollout_action_feed(&state, adapter, None, None).await {
            Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
            _ => None,
        };
    let action_status = match build_ops_runtime_rollout_action_status_snapshot(
        &state,
        adapter,
        current_feed.as_ref(),
    )
    .await
    {
        Ok(snapshot) => snapshot,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    if req.method() == hyper::Method::GET {
        if state.config.ops_admin_token.is_none() {
            return ops_admin_not_found_response();
        }
        if !is_ops_admin_authorized(&req, &state) {
            return ops_admin_unauthorized_response();
        }
        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "adapter": adapter.as_str(),
                    "configured": action_status.configured,
                    "action_available": action_status.action_available,
                    "current_fingerprint": action_status.current_fingerprint,
                    "ack": action_status.ack_state.as_ref().map_or_else(
                        || json!({
                            "active": false,
                            "waiting_for_ack": action_status.waiting_for_ack,
                            "ack_timed_out": action_status.ack_timed_out,
                            "dispatched_current_action": action_status.dispatched_current_action,
                            "delivery_pending_current_action": action_status.delivery_pending_for_current_action,
                        }),
                        |ack_state| {
                            rollout_action_ack_state_to_json(
                                ack_state,
                                action_status.current_fingerprint.as_deref(),
                                current_feed
                                    .as_ref()
                                    .map(|feed| feed.rollout_state.request_id.as_str()),
                            )
                        }
                    ),
                    "ack_policy": {
                        "timeout_ms": state.config.ops_runtime_rollout_action_ack_timeout_ms,
                        "waiting_for_ack": action_status.waiting_for_ack,
                        "ack_timed_out": action_status.ack_timed_out,
                        "dispatched_current_action": action_status.dispatched_current_action,
                        "delivery_pending_current_action": action_status.delivery_pending_for_current_action,
                    },
                    "execution": action_status.execution_state.as_ref().map_or_else(
                        || json!({
                            "active": false,
                            "execution_active": action_status.execution_active,
                            "execution_timed_out": action_status.execution_timed_out,
                            "pending_timeout_ms": action_status.execution_timeout_ms,
                        }),
                        |execution_state| {
                            rollout_action_execution_state_to_json(
                                execution_state,
                                action_status.current_fingerprint.as_deref(),
                                current_feed
                                    .as_ref()
                                    .map(|feed| feed.rollout_state.request_id.as_str()),
                                action_status.execution_timeout_ms,
                            )
                        }
                    ),
                    "execution_policy": {
                        "pending_timeout_ms": action_status.execution_timeout_ms,
                        "execution_active": action_status.execution_active,
                        "execution_timed_out": action_status.execution_timed_out,
                    },
                    "redispatch": rollout_action_redispatch_to_json(
                        &current_ops_runtime_rollout_action_dispatch_state(&state, adapter)
                            .await
                            .unwrap_or_default(),
                        &action_status,
                    ),
                    "redispatch_policy": {
                        "max_attempts": state.config.ops_runtime_rollout_action_ack_redispatch_max_attempts,
                        "eligible": action_status.redispatch_eligible,
                        "exhausted": action_status.redispatch_exhausted,
                        "remaining_attempts": action_status.redispatch_remaining_attempts,
                        "backoff_initial_ms": state.config.ops_runtime_rollout_action_redispatch_retry_initial_ms,
                        "backoff_max_ms": state.config.ops_runtime_rollout_action_redispatch_retry_max_ms,
                        "backoff_active": action_status.redispatch_backoff_active,
                        "next_eligible_at_ms": action_status.redispatch_next_eligible_at_ms,
                        "remaining_backoff_ms": action_status.redispatch_remaining_backoff_ms,
                    },
                })
                .to_string(),
            ))
            .unwrap();
    }

    if !is_ops_admin_authorized(&req, &state)
        && !is_runtime_rollout_action_callback_authorized(
            &req,
            &state,
            adapter,
            current_feed.as_ref(),
        )
        .await
    {
        return ops_action_callback_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let ack_request = match serde_json::from_slice::<OpsRuntimeRolloutActionAckRequest>(&body_bytes)
    {
        Ok(payload) => payload,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": format!(
                            "invalid runtime rollout {} action ack request: {}",
                            adapter.as_str(),
                            error
                        )
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    };
    let Some(feed) = current_feed else {
        return ops_conflict_response(format!(
            "runtime rollout {} action ack requires a current actionable command",
            adapter.as_str()
        ));
    };
    if action_status.delivery_pending_for_current_action {
        return ops_conflict_response(format!(
            "runtime rollout {} action ack unavailable while delivery is pending",
            adapter.as_str()
        ));
    }

    let status = match normalize_ops_runtime_rollout_action_ack_status(ack_request.status) {
        Ok(status) => status,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let fingerprint = ack_request
        .fingerprint
        .unwrap_or_else(|| feed.fingerprint.clone());
    if fingerprint != feed.fingerprint {
        return ops_conflict_response(format!(
            "runtime rollout {} action ack fingerprint does not match current action",
            adapter.as_str()
        ));
    }
    let rollout_request_id = ack_request
        .rollout_request_id
        .unwrap_or_else(|| feed.rollout_state.request_id.clone());
    if rollout_request_id != feed.rollout_state.request_id {
        return ops_conflict_response(format!(
            "runtime rollout {} action ack rollout_request_id does not match current action",
            adapter.as_str()
        ));
    }

    let ack_state = OpsRuntimeRolloutActionAckState {
        ack_request_id: request_id,
        adapter: adapter.as_str().to_string(),
        rollout_request_id,
        fingerprint,
        status,
        actor: normalized_optional_string(ack_request.actor)
            .unwrap_or_else(|| format!("external:{}-adapter", adapter.as_str())),
        note: normalized_optional_string(ack_request.note),
        external_ref: normalized_optional_string(ack_request.external_ref),
        updated_at_ms: now_ts_ms(),
    };
    if let Some(current_ack_state) = action_status.ack_state.as_ref() {
        if rollout_action_ack_state_is_idempotent_replay(current_ack_state, &ack_state) {
            record_ops_runtime_rollout_action_ack_idempotent_replay(&state.metrics, adapter);
            return Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "ok": true,
                        "idempotent_replay": true,
                        "adapter": adapter.as_str(),
                        "ack": rollout_action_ack_state_to_json(
                            current_ack_state,
                            Some(feed.fingerprint.as_str()),
                            Some(feed.rollout_state.request_id.as_str()),
                        ),
                        "ack_policy": {
                            "timeout_ms": state.config.ops_runtime_rollout_action_ack_timeout_ms,
                            "waiting_for_ack": action_status.waiting_for_ack,
                            "ack_timed_out": action_status.ack_timed_out,
                            "dispatched_current_action": action_status.dispatched_current_action,
                            "delivery_pending_current_action": action_status.delivery_pending_for_current_action,
                        },
                        "execution": action_status.execution_state.as_ref().map_or_else(
                            || json!({ "active": false }),
                            |execution_state| {
                                rollout_action_execution_state_to_json(
                                    execution_state,
                                    Some(feed.fingerprint.as_str()),
                                    Some(feed.rollout_state.request_id.as_str()),
                                    action_status.execution_timeout_ms,
                                )
                            }
                        ),
                        "redispatch": rollout_action_redispatch_to_json(
                            &current_ops_runtime_rollout_action_dispatch_state(&state, adapter)
                                .await
                                .unwrap_or_default(),
                            &action_status,
                        ),
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    }
    if let Err(error) = validate_rollout_action_ack_state_transition(
        adapter,
        action_status.ack_state.as_ref(),
        &ack_state,
    ) {
        return ops_conflict_response(error);
    }
    if ack_state.status == "accepted" {
        if let Some(execution_state) = action_status.execution_state.as_ref() {
            if action_status.execution_active && execution_state.actor != ack_state.actor {
                match adapter {
                    OpsRuntimeRolloutActionAdapterKind::Deploy => state
                        .metrics
                        .ops_runtime_rollout_deploy_action_execution_conflicts_total
                        .fetch_add(1, Ordering::Relaxed),
                    OpsRuntimeRolloutActionAdapterKind::Traffic => state
                        .metrics
                        .ops_runtime_rollout_traffic_action_execution_conflicts_total
                        .fetch_add(1, Ordering::Relaxed),
                };
                return ops_conflict_response(format!(
                    "runtime rollout {} action execution already owned by actor={} for the current action",
                    adapter.as_str(),
                    execution_state.actor
                ));
            }
        }
    }
    if let Err(error) =
        update_ops_runtime_rollout_action_ack_state(&state, adapter, ack_state.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    record_ops_runtime_rollout_action_ack(&state.metrics, adapter, ack_state.status.as_str());
    if ack_state.status == "accepted" {
        let current_execution_state =
            current_ops_runtime_rollout_action_execution_state(&state, adapter)
                .await
                .unwrap_or(None);
        let claimed_at_ms = current_execution_state
            .as_ref()
            .filter(|execution_state| {
                rollout_action_execution_matches_current_action(
                    execution_state,
                    adapter,
                    Some(feed.fingerprint.as_str()),
                    Some(feed.rollout_state.request_id.as_str()),
                ) && execution_state.actor == ack_state.actor
            })
            .map(|execution_state| execution_state.claimed_at_ms)
            .unwrap_or(ack_state.updated_at_ms);
        let execution_state = OpsRuntimeRolloutActionExecutionState {
            execution_request_id: ack_state.ack_request_id.clone(),
            adapter: adapter.as_str().to_string(),
            rollout_request_id: ack_state.rollout_request_id.clone(),
            fingerprint: ack_state.fingerprint.clone(),
            actor: ack_state.actor.clone(),
            note: ack_state.note.clone(),
            external_ref: ack_state.external_ref.clone(),
            source: "action_ack".to_string(),
            claimed_at_ms,
            updated_at_ms: ack_state.updated_at_ms,
            last_status: Some(ack_state.status.clone()),
        };
        if let Err(error) =
            update_ops_runtime_rollout_action_execution_state(&state, adapter, execution_state)
                .await
        {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    } else {
        let current_execution_state =
            current_ops_runtime_rollout_action_execution_state(&state, adapter)
                .await
                .unwrap_or(None);
        if current_execution_state
            .as_ref()
            .map(|execution_state| {
                rollout_action_execution_matches_current_action(
                    execution_state,
                    adapter,
                    Some(feed.fingerprint.as_str()),
                    Some(feed.rollout_state.request_id.as_str()),
                )
            })
            .unwrap_or(false)
        {
            if let Err(error) =
                clear_ops_runtime_rollout_action_execution_state(&state, adapter).await
            {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        }
    }

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "idempotent_replay": false,
                "adapter": adapter.as_str(),
                "ack": rollout_action_ack_state_to_json(
                    &ack_state,
                    Some(feed.fingerprint.as_str()),
                    Some(feed.rollout_state.request_id.as_str()),
                ),
                "ack_policy": {
                    "timeout_ms": state.config.ops_runtime_rollout_action_ack_timeout_ms,
                    "waiting_for_ack": false,
                    "ack_timed_out": false,
                    "dispatched_current_action": true,
                    "delivery_pending_current_action": false,
                },
                "execution": build_ops_runtime_rollout_action_status_snapshot(
                    &state,
                    adapter,
                    Some(&feed),
                )
                .await
                .ok()
                .and_then(|snapshot| snapshot.execution_state.map(|execution_state| {
                    rollout_action_execution_state_to_json(
                        &execution_state,
                        Some(feed.fingerprint.as_str()),
                        Some(feed.rollout_state.request_id.as_str()),
                        snapshot.execution_timeout_ms,
                    )
                }))
                .unwrap_or_else(|| json!({ "active": false })),
                "redispatch": rollout_action_redispatch_to_json(
                    &current_ops_runtime_rollout_action_dispatch_state(&state, adapter)
                        .await
                        .unwrap_or_default(),
                    &build_ops_runtime_rollout_action_status_snapshot(
                        &state,
                        adapter,
                        Some(&feed),
                    )
                    .await
                    .unwrap_or(OpsRuntimeRolloutActionStatusSnapshot {
                        configured: adapter.webhook_url(&state.config).is_some(),
                        action_available: true,
                        current_fingerprint: Some(feed.fingerprint.clone()),
                        dispatched_current_action: true,
                        delivery_pending_for_current_action: false,
                        ack_state: Some(ack_state.clone()),
                        execution_state: current_ops_runtime_rollout_action_execution_state(
                            &state,
                            adapter,
                        )
                        .await
                        .unwrap_or(None),
                        ack_timed_out: false,
                        waiting_for_ack: false,
                        execution_active: ack_state.status == "accepted",
                        execution_timed_out: false,
                        execution_timeout_ms: ops_runtime_rollout_action_execution_timeout_ms(
                            &state.config,
                            adapter,
                        ),
                        redispatch_attempts: 0,
                        redispatch_max_attempts: state
                            .config
                            .ops_runtime_rollout_action_ack_redispatch_max_attempts,
                        redispatch_remaining_attempts: state
                            .config
                            .ops_runtime_rollout_action_ack_redispatch_max_attempts,
                        redispatch_eligible: false,
                        redispatch_exhausted: false,
                        redispatch_backoff_active: false,
                        redispatch_next_eligible_at_ms: None,
                        redispatch_remaining_backoff_ms: 0,
                    }),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

