async fn handle_ops_runtime_rollout_approval<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if req.method() == hyper::Method::GET {
        if state.config.ops_admin_token.is_none() {
            return ops_admin_not_found_response();
        }
        if !is_ops_admin_authorized(&req, &state) {
            return ops_admin_unauthorized_response();
        }
        let current_rollout_state = current_ops_runtime_rollout_state(&state)
            .await
            .unwrap_or_default();
        let approval_state = match current_ops_runtime_rollout_approval_state(&state).await {
            Ok(approval_state) => approval_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "approval": approval_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |approval_state| {
                            rollout_approval_state_to_json(
                                approval_state,
                                Some(current_rollout_state.request_id.as_str()),
                            )
                        }
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }

    let current_feed = match build_ops_runtime_rollout_action_feed(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
        None,
        None,
    )
    .await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    if !is_ops_admin_authorized(&req, &state)
        && !is_runtime_rollout_action_callback_authorized(
            &req,
            &state,
            OpsRuntimeRolloutActionAdapterKind::Traffic,
            current_feed.as_ref(),
        )
        .await
    {
        return ops_action_callback_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let approval_request =
        match serde_json::from_slice::<OpsRuntimeRolloutApprovalRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!("invalid runtime rollout approval request: {}", error)
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        };
    let status = match normalize_ops_runtime_rollout_approval_status(approval_request.status) {
        Ok(status) => status,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let history = match current_ops_runtime_rollout_history(
        &state,
        state.config.ops_runtime_rollout_history_limit.max(1),
    )
    .await
    {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let target_rollout = if let Some(target_request_id) =
        normalized_optional_string(approval_request.rollout_request_id.clone())
    {
        if current_rollout_state.request_id == target_request_id {
            Some(current_rollout_state.request_id.clone())
        } else {
            history
                .iter()
                .find(|entry| entry.request_id == target_request_id)
                .map(|entry| entry.request_id.clone())
        }
    } else if current_rollout_state.request_id != "default"
        || current_rollout_state.updated_at_ms > 0
    {
        Some(current_rollout_state.request_id.clone())
    } else {
        None
    };

    let Some(target_rollout_request_id) = target_rollout else {
        return ops_conflict_response(
            "runtime rollout approval requires a current rollout or known rollout_request_id"
                .to_string(),
        );
    };

    let actor = normalized_optional_string(approval_request.actor)
        .unwrap_or_else(|| "ops:rollout-approval".to_string());
    let note = normalized_optional_string(approval_request.note);
    let external_ref = normalized_optional_string(approval_request.external_ref);
    let approval_state = OpsRuntimeRolloutApprovalState {
        approval_request_id: request_id.clone(),
        rollout_request_id: target_rollout_request_id.clone(),
        status: status.clone(),
        actor,
        note,
        external_ref,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = OpsRuntimeRolloutApprovalHistoryEntry {
        approval_request_id: approval_state.approval_request_id.clone(),
        rollout_request_id: approval_state.rollout_request_id.clone(),
        status: approval_state.status.clone(),
        actor: approval_state.actor.clone(),
        note: approval_state.note.clone(),
        external_ref: approval_state.external_ref.clone(),
        updated_at_ms: approval_state.updated_at_ms,
    };

    if let Err(error) =
        update_ops_runtime_rollout_approval_state(&state, approval_state.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) =
        record_ops_runtime_rollout_approval_history(&state, history_entry.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }

    let dispatch_webhook = approval_request.dispatch_webhook.unwrap_or(true);
    let dispatch_result =
        if dispatch_webhook && state.config.ops_runtime_rollout_webhook_url.is_some() {
            Some(dispatch_ops_runtime_rollout_feed(&state, true, Some("approval"), None).await)
        } else {
            None
        };
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "approval": rollout_approval_state_to_json(
                    &approval_state,
                    Some(current_rollout_state.request_id.as_str()),
                ),
                "history_entry": history_entry,
                "dispatch": rollout_dispatch_result_to_json(dispatch_result.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

