async fn handle_ops_runtime_rollout_traffic<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if req.method() == hyper::Method::GET {
        if state.config.ops_admin_token.is_none() {
            return ops_admin_not_found_response();
        }
        if !is_ops_admin_authorized(&req, &state) {
            return ops_admin_unauthorized_response();
        }
        let current_rollout_state = current_ops_runtime_rollout_state(&state)
            .await
            .unwrap_or_default();
        let traffic_state = match current_ops_runtime_rollout_traffic_state(&state).await {
            Ok(traffic_state) => traffic_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "traffic": traffic_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |traffic_state| {
                            rollout_traffic_state_to_json(
                                traffic_state,
                                Some(current_rollout_state.request_id.as_str()),
                            )
                        }
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }

    let current_feed = match build_ops_runtime_rollout_action_feed(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
        None,
        None,
    )
    .await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    if !is_ops_admin_authorized(&req, &state)
        && !is_runtime_rollout_action_callback_authorized(
            &req,
            &state,
            OpsRuntimeRolloutActionAdapterKind::Deploy,
            current_feed.as_ref(),
        )
        .await
    {
        return ops_action_callback_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let traffic_request =
        match serde_json::from_slice::<OpsRuntimeRolloutTrafficRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!("invalid runtime rollout traffic request: {}", error)
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        };
    let stage = match normalize_ops_runtime_rollout_traffic_stage(traffic_request.stage) {
        Ok(stage) => stage,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    if (traffic_request.canary_percent as u16 + traffic_request.stable_percent as u16) != 100 {
        return Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": format!(
                        "invalid runtime rollout traffic split: canary_percent={} stable_percent={} must sum to 100",
                        traffic_request.canary_percent, traffic_request.stable_percent
                    )
                })
                .to_string(),
            ))
            .unwrap();
    }

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let history = match current_ops_runtime_rollout_history(
        &state,
        state.config.ops_runtime_rollout_history_limit.max(1),
    )
    .await
    {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let target_rollout = if let Some(target_request_id) =
        normalized_optional_string(traffic_request.rollout_request_id.clone())
    {
        if current_rollout_state.request_id == target_request_id {
            Some(current_rollout_state.request_id.clone())
        } else {
            history
                .iter()
                .find(|entry| entry.request_id == target_request_id)
                .map(|entry| entry.request_id.clone())
        }
    } else if current_rollout_state.request_id != "default"
        || current_rollout_state.updated_at_ms > 0
    {
        Some(current_rollout_state.request_id.clone())
    } else {
        None
    };

    let Some(target_rollout_request_id) = target_rollout else {
        return ops_conflict_response(
            "runtime rollout traffic requires a current rollout or known rollout_request_id"
                .to_string(),
        );
    };

    let actor = normalized_optional_string(traffic_request.actor)
        .unwrap_or_else(|| "ops:rollout-traffic".to_string());
    let note = normalized_optional_string(traffic_request.note);
    let external_ref = normalized_optional_string(traffic_request.external_ref);
    let traffic_state = OpsRuntimeRolloutTrafficState {
        traffic_request_id: request_id.clone(),
        rollout_request_id: target_rollout_request_id.clone(),
        stage,
        canary_percent: traffic_request.canary_percent,
        stable_percent: traffic_request.stable_percent,
        actor,
        note,
        external_ref,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = OpsRuntimeRolloutTrafficHistoryEntry {
        traffic_request_id: traffic_state.traffic_request_id.clone(),
        rollout_request_id: traffic_state.rollout_request_id.clone(),
        stage: traffic_state.stage.clone(),
        canary_percent: traffic_state.canary_percent,
        stable_percent: traffic_state.stable_percent,
        actor: traffic_state.actor.clone(),
        note: traffic_state.note.clone(),
        external_ref: traffic_state.external_ref.clone(),
        updated_at_ms: traffic_state.updated_at_ms,
    };

    if let Err(error) =
        update_ops_runtime_rollout_traffic_state(&state, traffic_state.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) =
        record_ops_runtime_rollout_traffic_history(&state, history_entry.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }

    let dispatch_webhook = traffic_request.dispatch_webhook.unwrap_or(true);
    let dispatch_result =
        if dispatch_webhook && state.config.ops_runtime_rollout_webhook_url.is_some() {
            Some(dispatch_ops_runtime_rollout_feed(&state, true, Some("traffic"), None).await)
        } else {
            None
        };
    let traffic_action_dispatch = if dispatch_webhook
        && state
            .config
            .ops_runtime_rollout_traffic_action_webhook_url
            .is_some()
    {
        Some(
            dispatch_ops_runtime_rollout_action_feed(
                &state,
                OpsRuntimeRolloutActionAdapterKind::Traffic,
                true,
                Some("traffic"),
                None,
            )
            .await,
        )
    } else {
        None
    };
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();
    let traffic_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
    )
    .await
    .unwrap_or_default();
    let traffic_action_pending = current_ops_runtime_rollout_action_delivery_pending(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
    )
    .await
    .unwrap_or_default();

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "traffic": rollout_traffic_state_to_json(
                    &traffic_state,
                    Some(current_rollout_state.request_id.as_str()),
                ),
                "history_entry": history_entry,
                "dispatch": rollout_dispatch_result_to_json(dispatch_result.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
                "traffic_action_dispatch": rollout_action_dispatch_result_to_json(
                    traffic_action_dispatch.as_ref(),
                ),
                "traffic_action_delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_traffic_action_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_adapter_interval_ms,
                    &traffic_action_dispatch_state,
                    traffic_action_pending.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout_traffic_receipt_history<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let limit = query_param_usize(&req, "limit")
        .unwrap_or(20)
        .clamp(1, state.config.ops_runtime_rollout_history_limit.max(1));
    let history = match current_ops_runtime_rollout_traffic_receipt_history(&state, limit).await {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "limit": limit,
                "count": history.len(),
                "history_limit": state.config.ops_runtime_rollout_history_limit,
                "history": history,
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout_traffic_receipt<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if req.method() == hyper::Method::GET {
        if state.config.ops_admin_token.is_none() {
            return ops_admin_not_found_response();
        }
        if !is_ops_admin_authorized(&req, &state) {
            return ops_admin_unauthorized_response();
        }
        let current_rollout_state = current_ops_runtime_rollout_state(&state)
            .await
            .unwrap_or_default();
        let traffic_receipt_state =
            match current_ops_runtime_rollout_traffic_receipt_state(&state).await {
                Ok(traffic_receipt_state) => traffic_receipt_state,
                Err(error) => {
                    return Response::builder()
                        .status(StatusCode::INTERNAL_SERVER_ERROR)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(json!({ "error": error }).to_string()))
                        .unwrap();
                }
            };
        let execution_state = current_ops_runtime_rollout_action_execution_state(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Traffic,
        )
        .await
        .unwrap_or(None);

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "traffic_receipt": traffic_receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |traffic_receipt_state| {
                            rollout_traffic_receipt_state_to_json(
                                traffic_receipt_state,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config
                                    .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                    "execution": execution_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |execution_state| {
                            rollout_action_execution_state_to_json(
                                execution_state,
                                None,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config
                                    .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }

    let current_feed = match build_ops_runtime_rollout_action_feed(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
        None,
        None,
    )
    .await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    if !is_ops_admin_authorized(&req, &state)
        && !is_runtime_rollout_action_callback_authorized(
            &req,
            &state,
            OpsRuntimeRolloutActionAdapterKind::Traffic,
            current_feed.as_ref(),
        )
        .await
    {
        return ops_action_callback_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let traffic_receipt_request =
        match serde_json::from_slice::<OpsRuntimeRolloutTrafficReceiptRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!(
                                "invalid runtime rollout traffic receipt request: {}",
                                error
                            )
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        };
    let status = match normalize_ops_runtime_rollout_traffic_receipt_status(
        traffic_receipt_request.status,
    ) {
        Ok(status) => status,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let history = match current_ops_runtime_rollout_history(
        &state,
        state.config.ops_runtime_rollout_history_limit.max(1),
    )
    .await
    {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let target_rollout = if let Some(target_request_id) =
        normalized_optional_string(traffic_receipt_request.rollout_request_id.clone())
    {
        if current_rollout_state.request_id == target_request_id {
            Some((
                current_rollout_state.request_id.clone(),
                current_rollout_state.phase.clone(),
                current_rollout_state.target_profile.clone(),
            ))
        } else {
            history
                .iter()
                .find(|entry| entry.request_id == target_request_id)
                .map(|entry| {
                    (
                        entry.request_id.clone(),
                        entry.phase.clone(),
                        entry.target_profile.clone(),
                    )
                })
        }
    } else if current_rollout_state.request_id != "default"
        || current_rollout_state.updated_at_ms > 0
    {
        Some((
            current_rollout_state.request_id.clone(),
            current_rollout_state.phase.clone(),
            current_rollout_state.target_profile.clone(),
        ))
    } else {
        None
    };

    let Some((target_rollout_request_id, target_phase, target_profile)) = target_rollout else {
        return ops_conflict_response(
            "runtime rollout traffic receipt requires a current rollout or known rollout_request_id"
                .to_string(),
        );
    };

    let actor = normalized_optional_string(traffic_receipt_request.actor)
        .unwrap_or_else(|| "ops:rollout-traffic-receipt".to_string());
    let stage = normalized_optional_string(traffic_receipt_request.stage)
        .unwrap_or_else(|| target_phase.clone());
    let note = normalized_optional_string(traffic_receipt_request.note);
    let external_ref = normalized_optional_string(traffic_receipt_request.external_ref);
    let execution_request_id =
        normalized_optional_string(traffic_receipt_request.execution_request_id);
    let current_execution_state = match current_ops_runtime_rollout_action_execution_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
    )
    .await
    {
        Ok(execution_state) => execution_state,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let current_traffic_receipt_state =
        match current_ops_runtime_rollout_traffic_receipt_state(&state).await {
            Ok(receipt_state) => receipt_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
    if let Err(error) = validate_rollout_action_receipt_execution_target(
        current_execution_state.as_ref(),
        OpsRuntimeRolloutActionAdapterKind::Traffic,
        &target_rollout_request_id,
        &actor,
        execution_request_id.as_deref(),
    ) {
        state
            .metrics
            .ops_runtime_rollout_traffic_action_execution_conflicts_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(error);
    }
    if let Err(error) = current_traffic_receipt_state
        .as_ref()
        .map_or(Ok(()), |receipt_state| {
            validate_rollout_execution_receipt_state_transition(
                "traffic receipt",
                &receipt_state.rollout_request_id,
                receipt_state.execution_request_id.as_deref(),
                &receipt_state.status,
                &target_rollout_request_id,
                execution_request_id.as_deref(),
                &status,
            )
        })
    {
        state
            .metrics
            .ops_runtime_rollout_traffic_action_execution_conflicts_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(error);
    }
    let traffic_receipt_state = OpsRuntimeRolloutTrafficReceiptState {
        traffic_receipt_request_id: request_id.clone(),
        rollout_request_id: target_rollout_request_id.clone(),
        execution_request_id: execution_request_id.clone(),
        status: status.clone(),
        stage,
        phase: target_phase.clone(),
        target_profile: target_profile.clone(),
        actor,
        note,
        external_ref,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = OpsRuntimeRolloutTrafficReceiptHistoryEntry {
        traffic_receipt_request_id: traffic_receipt_state.traffic_receipt_request_id.clone(),
        rollout_request_id: traffic_receipt_state.rollout_request_id.clone(),
        execution_request_id: traffic_receipt_state.execution_request_id.clone(),
        status: traffic_receipt_state.status.clone(),
        stage: traffic_receipt_state.stage.clone(),
        phase: traffic_receipt_state.phase.clone(),
        target_profile: traffic_receipt_state.target_profile.clone(),
        actor: traffic_receipt_state.actor.clone(),
        note: traffic_receipt_state.note.clone(),
        external_ref: traffic_receipt_state.external_ref.clone(),
        updated_at_ms: traffic_receipt_state.updated_at_ms,
    };
    if let Some(current_receipt_state) = current_traffic_receipt_state.as_ref() {
        if rollout_traffic_receipt_state_is_idempotent_replay(
            current_receipt_state,
            &traffic_receipt_state,
        ) {
            record_ops_runtime_rollout_traffic_receipt_idempotent_replay(&state.metrics);
            let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
                .await
                .unwrap_or_default();
            let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
                .await
                .unwrap_or_default();
            return Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "ok": true,
                        "idempotent_replay": true,
                        "traffic_receipt": rollout_traffic_receipt_state_to_json(
                            current_receipt_state,
                            Some(current_rollout_state.request_id.as_str()),
                            state.config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                        ),
                        "execution": current_execution_state.as_ref().map_or_else(
                            || json!({ "active": false }),
                            |execution_state| {
                                rollout_action_execution_state_to_json(
                                    execution_state,
                                    None,
                                    Some(current_rollout_state.request_id.as_str()),
                                    state.config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                                )
                            }
                        ),
                        "history_entry": serde_json::Value::Null,
                        "dispatch": rollout_dispatch_result_to_json(None),
                        "delivery": ops_delivery_state_to_json(
                            state.config.ops_runtime_rollout_webhook_url.is_some(),
                            state.config.ops_runtime_rollout_webhook_interval_ms,
                            &dispatch_state,
                            pending_delivery.as_ref(),
                        ),
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    }

    if let Err(error) =
        update_ops_runtime_rollout_traffic_receipt_state(&state, traffic_receipt_state.clone())
            .await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) =
        record_ops_runtime_rollout_traffic_receipt_history(&state, history_entry.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) = reconcile_ops_runtime_rollout_action_execution_from_receipt(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
        &traffic_receipt_state.rollout_request_id,
        traffic_receipt_state.execution_request_id.clone(),
        &traffic_receipt_state.actor,
        traffic_receipt_state.note.clone(),
        traffic_receipt_state.external_ref.clone(),
        &traffic_receipt_state.status,
        traffic_receipt_state.updated_at_ms,
    )
    .await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }

    let dispatch_webhook = traffic_receipt_request.dispatch_webhook.unwrap_or(true);
    let dispatch_result = if dispatch_webhook
        && state.config.ops_runtime_rollout_webhook_url.is_some()
    {
        Some(dispatch_ops_runtime_rollout_feed(&state, true, Some("traffic_receipt"), None).await)
    } else {
        None
    };
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "idempotent_replay": false,
                "traffic_receipt": rollout_traffic_receipt_state_to_json(
                    &traffic_receipt_state,
                    Some(current_rollout_state.request_id.as_str()),
                    state.config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                ),
                "execution": current_ops_runtime_rollout_action_execution_state(
                    &state,
                    OpsRuntimeRolloutActionAdapterKind::Traffic,
                )
                .await
                .ok()
                .flatten()
                .map(|execution_state| {
                    rollout_action_execution_state_to_json(
                        &execution_state,
                        None,
                        Some(current_rollout_state.request_id.as_str()),
                        state.config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                    )
                })
                .unwrap_or_else(|| json!({ "active": false })),
                "history_entry": history_entry,
                "dispatch": rollout_dispatch_result_to_json(dispatch_result.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout_receipt<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if req.method() == hyper::Method::GET {
        if state.config.ops_admin_token.is_none() {
            return ops_admin_not_found_response();
        }
        if !is_ops_admin_authorized(&req, &state) {
            return ops_admin_unauthorized_response();
        }
        let current_rollout_state = current_ops_runtime_rollout_state(&state)
            .await
            .unwrap_or_default();
        let receipt_state = match current_ops_runtime_rollout_receipt_state(&state).await {
            Ok(receipt_state) => receipt_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
        let execution_state = current_ops_runtime_rollout_action_execution_state(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Deploy,
        )
        .await
        .unwrap_or(None);

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "receipt": receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |receipt_state| {
                            rollout_receipt_state_to_json(
                                receipt_state,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                    "execution": execution_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |execution_state| {
                            rollout_action_execution_state_to_json(
                                execution_state,
                                None,
                                Some(current_rollout_state.request_id.as_str()),
                                state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }

    let current_feed = match build_ops_runtime_rollout_action_feed(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
        None,
        None,
    )
    .await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    if !is_ops_admin_authorized(&req, &state)
        && !is_runtime_rollout_action_callback_authorized(
            &req,
            &state,
            OpsRuntimeRolloutActionAdapterKind::Deploy,
            current_feed.as_ref(),
        )
        .await
    {
        return ops_action_callback_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let receipt_request =
        match serde_json::from_slice::<OpsRuntimeRolloutReceiptRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({
                            "error": format!("invalid runtime rollout receipt request: {}", error)
                        })
                        .to_string(),
                    ))
                    .unwrap();
            }
        };
    let status = match normalize_ops_runtime_rollout_receipt_status(receipt_request.status) {
        Ok(status) => status,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let history = match current_ops_runtime_rollout_history(
        &state,
        state.config.ops_runtime_rollout_history_limit.max(1),
    )
    .await
    {
        Ok(history) => history,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    let target_rollout = if let Some(target_request_id) =
        normalized_optional_string(receipt_request.rollout_request_id.clone())
    {
        if current_rollout_state.request_id == target_request_id {
            Some((
                current_rollout_state.request_id.clone(),
                current_rollout_state.phase.clone(),
                current_rollout_state.target_profile.clone(),
            ))
        } else {
            history
                .iter()
                .find(|entry| entry.request_id == target_request_id)
                .map(|entry| {
                    (
                        entry.request_id.clone(),
                        entry.phase.clone(),
                        entry.target_profile.clone(),
                    )
                })
        }
    } else if current_rollout_state.request_id != "default"
        || current_rollout_state.updated_at_ms > 0
    {
        Some((
            current_rollout_state.request_id.clone(),
            current_rollout_state.phase.clone(),
            current_rollout_state.target_profile.clone(),
        ))
    } else {
        None
    };

    let Some((target_rollout_request_id, target_phase, target_profile)) = target_rollout else {
        return ops_conflict_response(
            "runtime rollout receipt requires a current rollout or known rollout_request_id"
                .to_string(),
        );
    };

    let actor = normalized_optional_string(receipt_request.actor)
        .unwrap_or_else(|| "ops:rollout-receipt".to_string());
    let stage =
        normalized_optional_string(receipt_request.stage).unwrap_or_else(|| target_phase.clone());
    let note = normalized_optional_string(receipt_request.note);
    let external_ref = normalized_optional_string(receipt_request.external_ref);
    let execution_request_id = normalized_optional_string(receipt_request.execution_request_id);
    let current_execution_state = match current_ops_runtime_rollout_action_execution_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    {
        Ok(execution_state) => execution_state,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let current_receipt_state = match current_ops_runtime_rollout_receipt_state(&state).await {
        Ok(receipt_state) => receipt_state,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    if let Err(error) = validate_rollout_action_receipt_execution_target(
        current_execution_state.as_ref(),
        OpsRuntimeRolloutActionAdapterKind::Deploy,
        &target_rollout_request_id,
        &actor,
        execution_request_id.as_deref(),
    ) {
        state
            .metrics
            .ops_runtime_rollout_deploy_action_execution_conflicts_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(error);
    }
    if let Err(error) = current_receipt_state
        .as_ref()
        .map_or(Ok(()), |receipt_state| {
            validate_rollout_execution_receipt_state_transition(
                "receipt",
                &receipt_state.rollout_request_id,
                receipt_state.execution_request_id.as_deref(),
                &receipt_state.status,
                &target_rollout_request_id,
                execution_request_id.as_deref(),
                &status,
            )
        })
    {
        state
            .metrics
            .ops_runtime_rollout_deploy_action_execution_conflicts_total
            .fetch_add(1, Ordering::Relaxed);
        return ops_conflict_response(error);
    }
    let receipt_state = OpsRuntimeRolloutReceiptState {
        receipt_request_id: request_id.clone(),
        rollout_request_id: target_rollout_request_id.clone(),
        execution_request_id: execution_request_id.clone(),
        status: status.clone(),
        stage,
        phase: target_phase.clone(),
        target_profile: target_profile.clone(),
        actor,
        note,
        external_ref,
        updated_at_ms: now_ts_ms(),
    };
    let history_entry = OpsRuntimeRolloutReceiptHistoryEntry {
        receipt_request_id: receipt_state.receipt_request_id.clone(),
        rollout_request_id: receipt_state.rollout_request_id.clone(),
        execution_request_id: receipt_state.execution_request_id.clone(),
        status: receipt_state.status.clone(),
        stage: receipt_state.stage.clone(),
        phase: receipt_state.phase.clone(),
        target_profile: receipt_state.target_profile.clone(),
        actor: receipt_state.actor.clone(),
        note: receipt_state.note.clone(),
        external_ref: receipt_state.external_ref.clone(),
        updated_at_ms: receipt_state.updated_at_ms,
    };
    if let Some(current_receipt_state) = current_receipt_state.as_ref() {
        if rollout_receipt_state_is_idempotent_replay(current_receipt_state, &receipt_state) {
            record_ops_runtime_rollout_receipt_idempotent_replay(&state.metrics);
            let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
                .await
                .unwrap_or_default();
            let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
                .await
                .unwrap_or_default();
            return Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "ok": true,
                        "idempotent_replay": true,
                        "receipt": rollout_receipt_state_to_json(
                            current_receipt_state,
                            Some(current_rollout_state.request_id.as_str()),
                            state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                        ),
                        "execution": current_execution_state.as_ref().map_or_else(
                            || json!({ "active": false }),
                            |execution_state| {
                                rollout_action_execution_state_to_json(
                                    execution_state,
                                    None,
                                    Some(current_rollout_state.request_id.as_str()),
                                    state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                                )
                            }
                        ),
                        "history_entry": serde_json::Value::Null,
                        "dispatch": rollout_dispatch_result_to_json(None),
                        "delivery": ops_delivery_state_to_json(
                            state.config.ops_runtime_rollout_webhook_url.is_some(),
                            state.config.ops_runtime_rollout_webhook_interval_ms,
                            &dispatch_state,
                            pending_delivery.as_ref(),
                        ),
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    }

    if let Err(error) =
        update_ops_runtime_rollout_receipt_state(&state, receipt_state.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) =
        record_ops_runtime_rollout_receipt_history(&state, history_entry.clone()).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }
    if let Err(error) = reconcile_ops_runtime_rollout_action_execution_from_receipt(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
        &receipt_state.rollout_request_id,
        receipt_state.execution_request_id.clone(),
        &receipt_state.actor,
        receipt_state.note.clone(),
        receipt_state.external_ref.clone(),
        &receipt_state.status,
        receipt_state.updated_at_ms,
    )
    .await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }

    let dispatch_webhook = receipt_request.dispatch_webhook.unwrap_or(true);
    let dispatch_result =
        if dispatch_webhook && state.config.ops_runtime_rollout_webhook_url.is_some() {
            Some(dispatch_ops_runtime_rollout_feed(&state, true, Some("receipt"), None).await)
        } else {
            None
        };
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "idempotent_replay": false,
                "receipt": rollout_receipt_state_to_json(
                    &receipt_state,
                    Some(current_rollout_state.request_id.as_str()),
                    state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                ),
                "execution": current_ops_runtime_rollout_action_execution_state(
                    &state,
                    OpsRuntimeRolloutActionAdapterKind::Deploy,
                )
                .await
                .ok()
                .flatten()
                .map(|execution_state| {
                    rollout_action_execution_state_to_json(
                        &execution_state,
                        None,
                        Some(current_rollout_state.request_id.as_str()),
                        state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                    )
                })
                .unwrap_or_else(|| json!({ "active": false })),
                "history_entry": history_entry,
                "dispatch": rollout_dispatch_result_to_json(dispatch_result.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_rollout<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    if req.method() == hyper::Method::GET {
        let rollout_state = match current_ops_runtime_rollout_state(&state).await {
            Ok(rollout_state) => rollout_state,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
        let runtime_profile_state = current_ops_runtime_profile_state(&state)
            .await
            .unwrap_or_default();
        let write_gate_state =
            current_ops_write_gate_state(&state)
                .await
                .unwrap_or(OpsWriteGateState {
                    enabled: true,
                    operator: "system:default".to_string(),
                    reason: None,
                    request_id: "default".to_string(),
                    updated_at_ms: 0,
                });
        let realtime_gate_state =
            current_ops_realtime_gate_state(&state)
                .await
                .unwrap_or(OpsRealtimeGateState {
                    enabled: true,
                    operator: "system:default".to_string(),
                    reason: None,
                    request_id: "default".to_string(),
                    updated_at_ms: 0,
                });
        let runtime_drill_state = current_ops_runtime_drill_state(&state)
            .await
            .unwrap_or_default();
        let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
            .await
            .unwrap_or_default();
        let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
            .await
            .unwrap_or_default();
        let deploy_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Deploy,
        )
        .await
        .unwrap_or_default();
        let deploy_action_pending = current_ops_runtime_rollout_action_delivery_pending(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Deploy,
        )
        .await
        .unwrap_or_default();
        let traffic_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Traffic,
        )
        .await
        .unwrap_or_default();
        let traffic_action_pending = current_ops_runtime_rollout_action_delivery_pending(
            &state,
            OpsRuntimeRolloutActionAdapterKind::Traffic,
        )
        .await
        .unwrap_or_default();
        let receipt_state = current_ops_runtime_rollout_receipt_state(&state)
            .await
            .unwrap_or_default();
        let approval_state = current_ops_runtime_rollout_approval_state(&state)
            .await
            .unwrap_or_default();
        let traffic_state = current_ops_runtime_rollout_traffic_state(&state)
            .await
            .unwrap_or_default();
        let traffic_receipt_state = current_ops_runtime_rollout_traffic_receipt_state(&state)
            .await
            .unwrap_or_default();
        let matches_target_profile = runtime_profile_state.profile == rollout_state.target_profile;
        let target_matches_effective = ops_runtime_profile_matches_effective(
            &OpsRuntimeProfileState {
                profile: rollout_state.target_profile.clone(),
                operator: rollout_state.operator.clone(),
                reason: rollout_state.reason.clone(),
                request_id: rollout_state.request_id.clone(),
                updated_at_ms: rollout_state.updated_at_ms,
            },
            &write_gate_state,
            &realtime_gate_state,
            &runtime_drill_state,
        );

        return Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "runtime_rollout": runtime_rollout_state_to_json(
                        &rollout_state,
                        matches_target_profile,
                        target_matches_effective,
                        state.config.ops_runtime_rollout_history_limit,
                    ),
                    "delivery": ops_delivery_state_to_json(
                        state.config.ops_runtime_rollout_webhook_url.is_some(),
                        state.config.ops_runtime_rollout_webhook_interval_ms,
                        &dispatch_state,
                        pending_delivery.as_ref(),
                    ),
                    "deploy_action_delivery": ops_delivery_state_to_json(
                        state.config.ops_runtime_rollout_deploy_action_webhook_url.is_some(),
                        state.config.ops_runtime_rollout_adapter_interval_ms,
                        &deploy_action_dispatch_state,
                        deploy_action_pending.as_ref(),
                    ),
                    "traffic_action_delivery": ops_delivery_state_to_json(
                        state.config.ops_runtime_rollout_traffic_action_webhook_url.is_some(),
                        state.config.ops_runtime_rollout_adapter_interval_ms,
                        &traffic_action_dispatch_state,
                        traffic_action_pending.as_ref(),
                    ),
                    "receipt": receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |receipt_state| {
                            rollout_receipt_state_to_json(
                                receipt_state,
                                Some(rollout_state.request_id.as_str()),
                                state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                    "approval": approval_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |approval_state| {
                            rollout_approval_state_to_json(
                                approval_state,
                                Some(rollout_state.request_id.as_str()),
                            )
                        }
                    ),
                    "traffic": traffic_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |traffic_state| {
                            rollout_traffic_state_to_json(
                                traffic_state,
                                Some(rollout_state.request_id.as_str()),
                            )
                        }
                    ),
                    "traffic_receipt": traffic_receipt_state.as_ref().map_or_else(
                        || json!({ "active": false }),
                        |traffic_receipt_state| {
                            rollout_traffic_receipt_state_to_json(
                                traffic_receipt_state,
                                Some(rollout_state.request_id.as_str()),
                                state.config
                                    .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                            )
                        }
                    ),
                    "receipt_policy": {
                        "external_pending_timeout_ms": state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                        "traffic_pending_timeout_ms": state.config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                    },
                })
                .to_string(),
            ))
            .unwrap();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let rollout_request = match serde_json::from_slice::<OpsRuntimeRolloutRequest>(&body_bytes) {
        Ok(payload) => payload,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("invalid runtime rollout request: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let force = rollout_request.force.unwrap_or(false);
    let operator = normalized_optional_string(rollout_request.operator.clone())
        .unwrap_or_else(|| "ops:rollout".to_string());
    let reason = normalized_optional_string(rollout_request.reason.clone());
    let current_rollout_state = current_ops_runtime_rollout_state(&state)
        .await
        .unwrap_or_default();
    let current_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let phase =
        match normalize_ops_runtime_rollout_phase(rollout_request.phase, rollout_request.active) {
            Ok(phase) => phase,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
    let target_profile = match rollout_request.target_profile {
        Some(profile) => match normalize_ops_runtime_profile(profile) {
            Ok(profile) => profile,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        },
        None => current_profile_state.profile.clone(),
    };
    let apply_target_profile = rollout_request.apply_target_profile.unwrap_or(false);
    if apply_target_profile {
        let target_profile_state = OpsRuntimeProfileState {
            profile: target_profile.clone(),
            operator: operator.clone(),
            reason: reason.clone().or_else(|| {
                Some(format!(
                    "rollout phase={} target_profile={}",
                    phase, target_profile
                ))
            }),
            request_id: request_id.clone(),
            updated_at_ms: now_ts_ms(),
        };
        if let Err(error) =
            apply_ops_runtime_profile_with_audit(&state, target_profile_state, "rollout").await
        {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    }

    let rollout_state = OpsRuntimeRolloutState {
        active: rollout_request.active,
        phase,
        target_profile: target_profile.clone(),
        baseline_profile: current_profile_state.profile.clone(),
        operator,
        reason,
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    let transition_allowed = ops_runtime_rollout_transition_allowed(
        &current_rollout_state.phase,
        current_rollout_state.active,
        &rollout_state.phase,
        rollout_state.active,
    );
    if !transition_allowed && !force {
        return Response::builder()
            .status(StatusCode::CONFLICT)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": format!(
                        "runtime rollout transition blocked: current_phase={} next_phase={}",
                        current_rollout_state.phase,
                        rollout_state.phase
                    ),
                    "current_runtime_rollout": {
                        "active": current_rollout_state.active,
                        "phase": current_rollout_state.phase,
                    },
                    "requested_runtime_rollout": {
                        "active": rollout_state.active,
                        "phase": rollout_state.phase,
                    },
                    "force_hint": true,
                })
                .to_string(),
            ))
            .unwrap();
    }
    let guardrail_evaluation =
        match evaluate_runtime_rollout_checklist(&state, rollout_state.clone()).await {
            Ok(evaluation) => evaluation,
            Err(error) => {
                return Response::builder()
                    .status(StatusCode::INTERNAL_SERVER_ERROR)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(json!({ "error": error }).to_string()))
                    .unwrap();
            }
        };
    let enforce_guardrails =
        rollout_state.active && matches!(rollout_state.phase.as_str(), "promote" | "rollback");
    if enforce_guardrails && !guardrail_evaluation.can_proceed && !force {
        return Response::builder()
            .status(StatusCode::CONFLICT)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": format!(
                        "runtime rollout guardrail blocked: phase={} recommended_action={}",
                        rollout_state.phase,
                        guardrail_evaluation.recommended_action
                    ),
                    "force_hint": true,
                    "rollout_checklist": runtime_rollout_checklist_to_json(
                        &guardrail_evaluation,
                        state.config.ops_runtime_rollout_history_limit,
                    ),
                })
                .to_string(),
            ))
            .unwrap();
    }
    let history_entry = match update_ops_runtime_rollout_with_audit(
        &state,
        rollout_state.clone(),
        apply_target_profile,
        "manual",
    )
    .await
    {
        Ok(entry) => entry,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let rollout_dispatch = if state.config.ops_runtime_rollout_webhook_url.is_some() {
        Some(
            dispatch_ops_runtime_rollout_feed(&state, force, Some("manual"), Some(&history_entry))
                .await,
        )
    } else {
        None
    };
    let deploy_action_dispatch = if state
        .config
        .ops_runtime_rollout_deploy_action_webhook_url
        .is_some()
    {
        Some(
            dispatch_ops_runtime_rollout_action_feed(
                &state,
                OpsRuntimeRolloutActionAdapterKind::Deploy,
                true,
                Some("manual"),
                Some(&history_entry),
            )
            .await,
        )
    } else {
        None
    };
    let updated_profile_state = current_ops_runtime_profile_state(&state)
        .await
        .unwrap_or_default();
    let write_gate_state =
        current_ops_write_gate_state(&state)
            .await
            .unwrap_or(OpsWriteGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let realtime_gate_state =
        current_ops_realtime_gate_state(&state)
            .await
            .unwrap_or(OpsRealtimeGateState {
                enabled: true,
                operator: "system:default".to_string(),
                reason: None,
                request_id: "default".to_string(),
                updated_at_ms: 0,
            });
    let runtime_drill_state = current_ops_runtime_drill_state(&state)
        .await
        .unwrap_or_default();
    let dispatch_state = current_ops_runtime_rollout_dispatch_state(&state)
        .await
        .unwrap_or_default();
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(&state)
        .await
        .unwrap_or_default();
    let deploy_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let deploy_action_pending = current_ops_runtime_rollout_action_delivery_pending(
        &state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await
    .unwrap_or_default();
    let matches_target_profile = updated_profile_state.profile == rollout_state.target_profile;
    let target_matches_effective = ops_runtime_profile_matches_effective(
        &OpsRuntimeProfileState {
            profile: rollout_state.target_profile.clone(),
            operator: rollout_state.operator.clone(),
            reason: rollout_state.reason.clone(),
            request_id: rollout_state.request_id.clone(),
            updated_at_ms: rollout_state.updated_at_ms,
        },
        &write_gate_state,
        &realtime_gate_state,
        &runtime_drill_state,
    );

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "ok": true,
                "runtime_rollout": runtime_rollout_state_to_json(
                    &rollout_state,
                    matches_target_profile,
                    target_matches_effective,
                    state.config.ops_runtime_rollout_history_limit,
                ),
                "history_entry": history_entry,
                "guardrail": {
                    "enforced": enforce_guardrails,
                    "forced": force,
                    "can_proceed": guardrail_evaluation.can_proceed,
                    "recommended_action": guardrail_evaluation.recommended_action,
                },
                "dispatch": rollout_dispatch_result_to_json(rollout_dispatch.as_ref()),
                "delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_webhook_interval_ms,
                    &dispatch_state,
                    pending_delivery.as_ref(),
                ),
                "deploy_action_dispatch": rollout_action_dispatch_result_to_json(
                    deploy_action_dispatch.as_ref(),
                ),
                "deploy_action_delivery": ops_delivery_state_to_json(
                    state.config.ops_runtime_rollout_deploy_action_webhook_url.is_some(),
                    state.config.ops_runtime_rollout_adapter_interval_ms,
                    &deploy_action_dispatch_state,
                    deploy_action_pending.as_ref(),
                ),
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_ops_runtime_drill<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    if req.method() == hyper::Method::GET {
        return match current_ops_runtime_drill_state(&state).await {
            Ok(drill_state) => Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "runtime_drill": {
                            "enabled": drill_state.enabled,
                            "kind": drill_state.kind,
                            "operator": drill_state.operator,
                            "reason": drill_state.reason,
                            "request_id": drill_state.request_id,
                            "updated_at_ms": drill_state.updated_at_ms,
                            "degrades_ready": ops_runtime_drill_kind_degrades_ready(&drill_state.kind),
                        }
                    })
                    .to_string(),
                ))
                .unwrap(),
            Err(error) => Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap(),
        };
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let drill_request = match serde_json::from_slice::<OpsRuntimeDrillRequest>(&body_bytes) {
        Ok(payload) => payload,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("invalid runtime drill request: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };
    let kind = match normalize_ops_runtime_drill_kind(drill_request.kind, drill_request.enabled) {
        Ok(kind) => kind,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };
    let drill_state = OpsRuntimeDrillState {
        enabled: drill_request.enabled,
        kind,
        operator: normalized_optional_string(drill_request.operator)
            .unwrap_or_else(|| "ops".to_string()),
        reason: normalized_optional_string(drill_request.reason),
        request_id,
        updated_at_ms: now_ts_ms(),
    };
    match update_ops_runtime_drill_state(&state, drill_state.clone()).await {
        Ok(()) => Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "ok": true,
                    "runtime_drill": {
                        "enabled": drill_state.enabled,
                        "kind": drill_state.kind,
                        "operator": drill_state.operator,
                        "reason": drill_state.reason,
                        "request_id": drill_state.request_id,
                        "updated_at_ms": drill_state.updated_at_ms,
                        "degrades_ready": ops_runtime_drill_kind_degrades_ready(&drill_state.kind),
                    }
                })
                .to_string(),
            ))
            .unwrap(),
        Err(error) => Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap(),
    }
}

