async fn realtime_gate_disconnect_state(
    submit_coordinator: Option<&Arc<RedisSubmitCoordinator>>,
    local_gate_state: &Arc<RwLock<Option<OpsRealtimeGateState>>>,
    metrics: &Arc<AppMetrics>,
) -> Option<OpsRealtimeGateState> {
    let gate_state = if let Some(coordinator) = submit_coordinator {
        coordinator
            .inspect_ops_realtime_gate_state()
            .await
            .ok()
            .flatten()
    } else {
        local_gate_state.read().await.clone()
    }
    .unwrap_or(OpsRealtimeGateState {
        enabled: true,
        operator: "system:default".to_string(),
        reason: None,
        request_id: "default".to_string(),
        updated_at_ms: 0,
    });

    metrics
        .ops_realtime_gate_enabled
        .store(u64::from(gate_state.enabled), Ordering::Relaxed);
    (!gate_state.enabled).then_some(gate_state)
}

async fn snapshot_sse_connections<DB>(state: &AppState<DB>) -> SseConnectionSnapshot
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let connection_state = state.sse_connection_state.read().await;
    SseConnectionSnapshot {
        total_active: connection_state.total_active,
        tenant_slots: connection_state.by_tenant.len(),
        client_slots: connection_state.by_client.len(),
        connections_by_tenant: connection_state.by_tenant.clone(),
        connections_by_client: connection_state.by_client.clone(),
    }
}

fn realtime_connection_presence_stale_after_ms() -> u64 {
    SSE_GATE_POLL_INTERVAL_MS.saturating_mul(5).max(5_000)
}

fn lagged_messages_from_channel_error(error: &dubhe_channel_core::ChannelError) -> Option<u64> {
    if error.code != "lagged" {
        return None;
    }
    error
        .message
        .strip_prefix("lagged by ")
        .and_then(|rest| rest.strip_suffix(" messages"))
        .and_then(|value| value.parse::<u64>().ok())
        .or(Some(1))
}

fn optional_non_zero_u64(value: u64) -> Option<u64> {
    (value > 0).then_some(value)
}

fn timestamp_is_recent(timestamp: Option<u64>, now_ms: u64, window_ms: u64) -> bool {
    timestamp
        .map(|timestamp| now_ms.saturating_sub(timestamp) <= window_ms)
        .unwrap_or(false)
}

fn local_realtime_connection_presence_entry(
    instance_id: &str,
    snapshot: &SseConnectionSnapshot,
    metrics: &Arc<AppMetrics>,
    now_ms: u64,
) -> RealtimeConnectionPresenceEntry {
    RealtimeConnectionPresenceEntry {
        instance_id: instance_id.to_string(),
        updated_at_ms: now_ms,
        total_active: snapshot.total_active,
        tenant_slots: snapshot.tenant_slots,
        client_slots: snapshot.client_slots,
        connections_by_tenant: snapshot.connections_by_tenant.clone(),
        connections_by_client: snapshot.connections_by_client.clone(),
        idle_disconnects_total: metrics.sse_idle_disconnects_total.load(Ordering::Relaxed),
        gate_disconnects_total: metrics.sse_gate_disconnects_total.load(Ordering::Relaxed),
        lagged_messages_total: metrics.sse_lagged_messages_total.load(Ordering::Relaxed),
        slow_consumer_disconnects_total: metrics
            .sse_slow_consumer_disconnects_total
            .load(Ordering::Relaxed),
        last_idle_disconnect_at_ms: metrics
            .sse_last_idle_disconnect_at_ms
            .load(Ordering::Relaxed),
        last_gate_disconnect_at_ms: metrics
            .sse_last_gate_disconnect_at_ms
            .load(Ordering::Relaxed),
        last_lagged_message_at_ms: metrics
            .sse_last_lagged_message_at_ms
            .load(Ordering::Relaxed),
        last_slow_consumer_disconnect_at_ms: metrics
            .sse_last_slow_consumer_disconnect_at_ms
            .load(Ordering::Relaxed),
    }
}

fn aggregate_realtime_connection_presence_entries(
    mut entries: Vec<RealtimeConnectionPresenceEntry>,
    local_entry: RealtimeConnectionPresenceEntry,
    now_ms: u64,
) -> RealtimeConnectionPresenceAggregate {
    entries.retain(|entry| entry.instance_id != local_entry.instance_id);
    entries.push(local_entry);
    entries.sort_by(|left, right| left.instance_id.cmp(&right.instance_id));

    let stale_after_ms = realtime_connection_presence_stale_after_ms();
    let mut aggregate = RealtimeConnectionPresenceAggregate::default();
    for entry in entries {
        if now_ms.saturating_sub(entry.updated_at_ms) > stale_after_ms {
            aggregate.stale_instances.push(entry);
            continue;
        }
        aggregate.aggregate_active_connections = aggregate
            .aggregate_active_connections
            .saturating_add(entry.total_active);
        aggregate.aggregate_tenant_slots = aggregate
            .aggregate_tenant_slots
            .saturating_add(entry.tenant_slots as u64);
        aggregate.aggregate_client_slots = aggregate
            .aggregate_client_slots
            .saturating_add(entry.client_slots as u64);
        for (tenant_key, active_connections) in &entry.connections_by_tenant {
            *aggregate
                .aggregate_connections_by_tenant
                .entry(tenant_key.clone())
                .or_insert(0) += *active_connections;
        }
        for (client_key, active_connections) in &entry.connections_by_client {
            *aggregate
                .aggregate_connections_by_client
                .entry(client_key.clone())
                .or_insert(0) += *active_connections;
        }
        aggregate.aggregate_idle_disconnects_total = aggregate
            .aggregate_idle_disconnects_total
            .saturating_add(entry.idle_disconnects_total);
        aggregate.aggregate_gate_disconnects_total = aggregate
            .aggregate_gate_disconnects_total
            .saturating_add(entry.gate_disconnects_total);
        aggregate.aggregate_lagged_messages_total = aggregate
            .aggregate_lagged_messages_total
            .saturating_add(entry.lagged_messages_total);
        aggregate.aggregate_slow_consumer_disconnects_total = aggregate
            .aggregate_slow_consumer_disconnects_total
            .saturating_add(entry.slow_consumer_disconnects_total);
        aggregate.aggregate_last_idle_disconnect_at_ms = aggregate
            .aggregate_last_idle_disconnect_at_ms
            .max(entry.last_idle_disconnect_at_ms);
        aggregate.aggregate_last_gate_disconnect_at_ms = aggregate
            .aggregate_last_gate_disconnect_at_ms
            .max(entry.last_gate_disconnect_at_ms);
        aggregate.aggregate_last_lagged_message_at_ms = aggregate
            .aggregate_last_lagged_message_at_ms
            .max(entry.last_lagged_message_at_ms);
        aggregate.aggregate_last_slow_consumer_disconnect_at_ms = aggregate
            .aggregate_last_slow_consumer_disconnect_at_ms
            .max(entry.last_slow_consumer_disconnect_at_ms);
        aggregate.instances.push(entry);
    }

    aggregate.instances.sort_by(|left, right| {
        right
            .total_active
            .cmp(&left.total_active)
            .then_with(|| right.updated_at_ms.cmp(&left.updated_at_ms))
            .then_with(|| left.instance_id.cmp(&right.instance_id))
    });
    aggregate.stale_instances.sort_by(|left, right| {
        right
            .updated_at_ms
            .cmp(&left.updated_at_ms)
            .then_with(|| left.instance_id.cmp(&right.instance_id))
    });
    aggregate
}

fn realtime_connection_presence_active_instances_for_tenant(
    aggregate: &RealtimeConnectionPresenceAggregate,
    tenant_key: &str,
) -> usize {
    aggregate
        .instances
        .iter()
        .filter(|entry| {
            entry
                .connections_by_tenant
                .get(tenant_key)
                .copied()
                .unwrap_or(0)
                > 0
        })
        .count()
}

fn realtime_connection_presence_active_instances_for_client(
    aggregate: &RealtimeConnectionPresenceAggregate,
    client_key: &str,
) -> usize {
    aggregate
        .instances
        .iter()
        .filter(|entry| {
            entry
                .connections_by_client
                .get(client_key)
                .copied()
                .unwrap_or(0)
                > 0
        })
        .count()
}

async fn sync_local_realtime_connection_presence<DB>(
    state: &AppState<DB>,
) -> Result<RealtimeConnectionPresenceEntry, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let snapshot = snapshot_sse_connections(state).await;
    let entry = local_realtime_connection_presence_entry(
        &state.runtime_instance_id,
        &snapshot,
        &state.metrics,
        now_ts_ms(),
    );
    if let Some(coordinator) = state.submit_coordinator.as_ref() {
        coordinator
            .store_ops_realtime_connection_presence(&entry)
            .await
            .map_err(|error| error.to_string())?;
    }
    Ok(entry)
}

async fn current_realtime_consumer_pressure_snapshot<DB>(
    state: &AppState<DB>,
) -> RealtimeConsumerPressureSnapshot
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let local_snapshot = snapshot_sse_connections(state).await;
    let local_entry = local_realtime_connection_presence_entry(
        &state.runtime_instance_id,
        &local_snapshot,
        &state.metrics,
        now_ts_ms(),
    );

    if state.submit_coordinator.is_some() {
        if let Ok(aggregate) = aggregate_realtime_connection_presence(state, &local_snapshot).await
        {
            return RealtimeConsumerPressureSnapshot {
                scope: "cluster",
                active_instances: aggregate.instances.len(),
                lagged_messages_total: aggregate.aggregate_lagged_messages_total,
                slow_consumer_disconnects_total: aggregate
                    .aggregate_slow_consumer_disconnects_total,
                last_lagged_message_at_ms: optional_non_zero_u64(
                    aggregate.aggregate_last_lagged_message_at_ms,
                ),
                last_slow_consumer_disconnect_at_ms: optional_non_zero_u64(
                    aggregate.aggregate_last_slow_consumer_disconnect_at_ms,
                ),
            };
        }
    }

    RealtimeConsumerPressureSnapshot {
        scope: "local",
        active_instances: 1,
        lagged_messages_total: local_entry.lagged_messages_total,
        slow_consumer_disconnects_total: local_entry.slow_consumer_disconnects_total,
        last_lagged_message_at_ms: optional_non_zero_u64(local_entry.last_lagged_message_at_ms),
        last_slow_consumer_disconnect_at_ms: optional_non_zero_u64(
            local_entry.last_slow_consumer_disconnect_at_ms,
        ),
    }
}

async fn aggregate_realtime_connection_presence<DB>(
    state: &AppState<DB>,
    local_snapshot: &SseConnectionSnapshot,
) -> Result<RealtimeConnectionPresenceAggregate, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let now_ms = now_ts_ms();
    let local_entry = local_realtime_connection_presence_entry(
        &state.runtime_instance_id,
        local_snapshot,
        &state.metrics,
        now_ms,
    );
    if let Some(coordinator) = state.submit_coordinator.as_ref() {
        let entries = coordinator
            .inspect_ops_realtime_connection_presence()
            .await
            .map_err(|error| error.to_string())?;
        return Ok(aggregate_realtime_connection_presence_entries(
            entries,
            local_entry,
            now_ms,
        ));
    }
    Ok(aggregate_realtime_connection_presence_entries(
        Vec::new(),
        local_entry,
        now_ms,
    ))
}

fn local_realtime_topic_presence_entry(
    instance_id: &str,
    topics: &[TopicActivitySnapshot],
    now_ms: u64,
) -> RealtimeTopicPresenceEntry {
    RealtimeTopicPresenceEntry {
        instance_id: instance_id.to_string(),
        updated_at_ms: now_ms,
        topics: topics.to_vec(),
    }
}

fn aggregate_realtime_topic_presence_entries(
    mut entries: Vec<RealtimeTopicPresenceEntry>,
    local_entry: RealtimeTopicPresenceEntry,
    now_ms: u64,
    config: &DubheChannelConfig,
) -> RealtimeTopicPresenceAggregate {
    entries.retain(|entry| entry.instance_id != local_entry.instance_id);
    entries.push(local_entry);
    entries.sort_by(|left, right| left.instance_id.cmp(&right.instance_id));

    let stale_after_ms = realtime_connection_presence_stale_after_ms();
    let mut aggregate = RealtimeTopicPresenceAggregate::default();
    let mut by_scoped_topic: BTreeMap<String, AggregatedTopicActivitySnapshot> = BTreeMap::new();

    for entry in entries {
        if now_ms.saturating_sub(entry.updated_at_ms) > stale_after_ms {
            aggregate.stale_instances.push(entry);
            continue;
        }
        for topic in &entry.topics {
            let aggregate_entry = by_scoped_topic
                .entry(topic.scoped_topic.clone())
                .or_insert_with(|| AggregatedTopicActivitySnapshot {
                    tenant_namespace: topic.tenant_namespace.clone(),
                    scoped_topic: topic.scoped_topic.clone(),
                    public_topic: topic.public_topic.clone(),
                    window_started_at_ms: topic.window_started_at_ms,
                    window_age_ms: topic.window_age_ms,
                    remaining_window_ms: topic.remaining_window_ms,
                    last_publish_at_ms: topic.last_publish_at_ms,
                    last_delivery_at_ms: topic.last_delivery_at_ms,
                    publish_count: 0,
                    delivery_count: 0,
                    rejected_publishes: 0,
                    hotspot_active: false,
                    instances_reporting: 0,
                });
            aggregate_entry.window_started_at_ms = aggregate_entry
                .window_started_at_ms
                .min(topic.window_started_at_ms);
            aggregate_entry.last_publish_at_ms = aggregate_entry
                .last_publish_at_ms
                .max(topic.last_publish_at_ms);
            aggregate_entry.last_delivery_at_ms = aggregate_entry
                .last_delivery_at_ms
                .max(topic.last_delivery_at_ms);
            aggregate_entry.publish_count = aggregate_entry
                .publish_count
                .saturating_add(topic.publish_count);
            aggregate_entry.delivery_count = aggregate_entry
                .delivery_count
                .saturating_add(topic.delivery_count);
            aggregate_entry.rejected_publishes = aggregate_entry
                .rejected_publishes
                .saturating_add(topic.rejected_publishes);
            aggregate_entry.hotspot_active = aggregate_entry.hotspot_active || topic.hotspot_active;
            aggregate_entry.instances_reporting =
                aggregate_entry.instances_reporting.saturating_add(1);
        }
        aggregate.instances.push(entry);
    }

    let window_ms = config.ops_runtime_topic_window_ms;
    aggregate.aggregate_topics = by_scoped_topic
        .into_values()
        .map(|mut topic| {
            topic.window_age_ms = now_ms.saturating_sub(topic.window_started_at_ms);
            topic.remaining_window_ms =
                topic_window_remaining_ms(topic.window_started_at_ms, now_ms, window_ms);
            if !topic.hotspot_active && config.ops_runtime_topic_publish_limit_per_window > 0 {
                topic.hotspot_active = topic.publish_count
                    >= config.ops_runtime_topic_publish_limit_per_window
                    || topic.delivery_count >= config.ops_runtime_topic_publish_limit_per_window;
            }
            topic
        })
        .collect::<Vec<_>>();
    aggregate.aggregate_topics.sort_by(|left, right| {
        right
            .rejected_publishes
            .cmp(&left.rejected_publishes)
            .then_with(|| {
                right
                    .publish_count
                    .max(right.delivery_count)
                    .cmp(&left.publish_count.max(left.delivery_count))
            })
            .then_with(|| {
                right
                    .last_publish_at_ms
                    .max(right.last_delivery_at_ms)
                    .cmp(&left.last_publish_at_ms.max(left.last_delivery_at_ms))
            })
            .then_with(|| left.scoped_topic.cmp(&right.scoped_topic))
    });
    aggregate
        .aggregate_topics
        .truncate(config.ops_runtime_topic_status_limit);
    aggregate.instances.sort_by(|left, right| {
        right
            .topics
            .len()
            .cmp(&left.topics.len())
            .then_with(|| right.updated_at_ms.cmp(&left.updated_at_ms))
            .then_with(|| left.instance_id.cmp(&right.instance_id))
    });
    aggregate.stale_instances.sort_by(|left, right| {
        right
            .updated_at_ms
            .cmp(&left.updated_at_ms)
            .then_with(|| left.instance_id.cmp(&right.instance_id))
    });
    aggregate
}

