async fn aggregate_realtime_topic_presence<DB>(
    state: &AppState<DB>,
    local_topics: &[TopicActivitySnapshot],
) -> Result<RealtimeTopicPresenceAggregate, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let now_ms = now_ts_ms();
    let local_entry =
        local_realtime_topic_presence_entry(&state.runtime_instance_id, local_topics, now_ms);
    if let Some(coordinator) = state.submit_coordinator.as_ref() {
        let entries = coordinator
            .inspect_ops_runtime_topics_presence()
            .await
            .map_err(|error| error.to_string())?;
        return Ok(aggregate_realtime_topic_presence_entries(
            entries,
            local_entry,
            now_ms,
            &state.config,
        ));
    }
    Ok(aggregate_realtime_topic_presence_entries(
        Vec::new(),
        local_entry,
        now_ms,
        &state.config,
    ))
}

fn realtime_gate_live_enforcement_json(
    gate_enabled: bool,
    snapshot: &SseConnectionSnapshot,
    metrics: &Arc<AppMetrics>,
) -> serde_json::Value {
    let drain_state = if gate_enabled {
        "open"
    } else if snapshot.total_active == 0 {
        "drained"
    } else {
        "draining"
    };
    json!({
        "poll_interval_ms": SSE_GATE_POLL_INTERVAL_MS,
        "local_active_connections": snapshot.total_active,
        "local_tenant_slots": snapshot.tenant_slots,
        "local_client_slots": snapshot.client_slots,
        "drain_complete": gate_enabled || snapshot.total_active == 0,
        "drain_state": drain_state,
        "gate_disconnects_total": metrics.sse_gate_disconnects_total.load(Ordering::Relaxed),
    })
}

fn realtime_gate_cluster_enforcement_json(
    gate_enabled: bool,
    aggregate: &RealtimeConnectionPresenceAggregate,
    global_limit: u64,
    per_tenant_limit: u64,
    per_client_limit: u64,
    metrics: &Arc<AppMetrics>,
) -> serde_json::Value {
    let drain_state = if gate_enabled {
        "open"
    } else if aggregate.aggregate_active_connections == 0 {
        "drained"
    } else {
        "draining"
    };
    let mut tenant_connections = aggregate
        .aggregate_connections_by_tenant
        .iter()
        .map(|(tenant, active_connections)| {
            let active_instances =
                realtime_connection_presence_active_instances_for_tenant(aggregate, tenant);
            json!({
                "tenant": tenant,
                "active_connections": active_connections,
                "active_instances": active_instances,
                "remaining_connections": if per_tenant_limit == 0 {
                    serde_json::Value::Null
                } else {
                    json!(per_tenant_limit.saturating_sub(*active_connections))
                },
                "limit_reached": per_tenant_limit > 0 && *active_connections >= per_tenant_limit,
            })
        })
        .collect::<Vec<_>>();
    tenant_connections.sort_by(|left, right| {
        right["active_connections"]
            .as_u64()
            .cmp(&left["active_connections"].as_u64())
            .then_with(|| {
                right["active_instances"]
                    .as_u64()
                    .cmp(&left["active_instances"].as_u64())
            })
            .then_with(|| left["tenant"].as_str().cmp(&right["tenant"].as_str()))
    });
    let tenants_at_limit = tenant_connections
        .iter()
        .filter(|entry| entry["limit_reached"].as_bool().unwrap_or(false))
        .count();
    let mut client_connections = aggregate
        .aggregate_connections_by_client
        .iter()
        .map(|(client, active_connections)| {
            let active_instances =
                realtime_connection_presence_active_instances_for_client(aggregate, client);
            json!({
                "client": client,
                "active_connections": active_connections,
                "active_instances": active_instances,
                "remaining_connections": if per_client_limit == 0 {
                    serde_json::Value::Null
                } else {
                    json!(per_client_limit.saturating_sub(*active_connections))
                },
                "limit_reached": per_client_limit > 0 && *active_connections >= per_client_limit,
            })
        })
        .collect::<Vec<_>>();
    client_connections.sort_by(|left, right| {
        right["active_connections"]
            .as_u64()
            .cmp(&left["active_connections"].as_u64())
            .then_with(|| {
                right["active_instances"]
                    .as_u64()
                    .cmp(&left["active_instances"].as_u64())
            })
            .then_with(|| left["client"].as_str().cmp(&right["client"].as_str()))
    });
    let clients_at_limit = client_connections
        .iter()
        .filter(|entry| entry["limit_reached"].as_bool().unwrap_or(false))
        .count();
    json!({
        "poll_interval_ms": SSE_GATE_POLL_INTERVAL_MS,
        "stale_after_ms": realtime_connection_presence_stale_after_ms(),
        "active_instances": aggregate.instances.len(),
        "stale_instances": aggregate.stale_instances.len(),
        "aggregate_active_connections": aggregate.aggregate_active_connections,
        "aggregate_tenant_slots": aggregate.aggregate_tenant_slots,
        "aggregate_client_slots": aggregate.aggregate_client_slots,
        "admission_scope": "cluster",
        "global_connection_limit": global_limit,
        "remaining_global_connections": if global_limit == 0 {
            serde_json::Value::Null
        } else {
            json!(global_limit.saturating_sub(aggregate.aggregate_active_connections))
        },
        "global_limit_reached": global_limit > 0 && aggregate.aggregate_active_connections >= global_limit,
        "per_tenant_connection_limit": per_tenant_limit,
        "tenants_at_limit": tenants_at_limit,
        "tenant_connections": tenant_connections,
        "per_client_connection_limit": per_client_limit,
        "clients_at_limit": clients_at_limit,
        "client_connections": client_connections,
        "drain_complete": gate_enabled || aggregate.aggregate_active_connections == 0,
        "drain_state": drain_state,
        "idle_disconnects_total": aggregate.aggregate_idle_disconnects_total,
        "gate_disconnects_total": aggregate.aggregate_gate_disconnects_total,
        "lagged_messages_total": aggregate.aggregate_lagged_messages_total,
        "slow_consumer_disconnects_total": aggregate.aggregate_slow_consumer_disconnects_total,
        "last_idle_disconnect_at_ms": optional_non_zero_u64(aggregate.aggregate_last_idle_disconnect_at_ms),
        "last_gate_disconnect_at_ms": optional_non_zero_u64(aggregate.aggregate_last_gate_disconnect_at_ms),
        "last_lagged_message_at_ms": optional_non_zero_u64(aggregate.aggregate_last_lagged_message_at_ms),
        "last_slow_consumer_disconnect_at_ms": optional_non_zero_u64(aggregate.aggregate_last_slow_consumer_disconnect_at_ms),
        "local_idle_disconnects_total": metrics.sse_idle_disconnects_total.load(Ordering::Relaxed),
        "local_gate_disconnects_total": metrics.sse_gate_disconnects_total.load(Ordering::Relaxed),
        "local_lagged_messages_total": metrics.sse_lagged_messages_total.load(Ordering::Relaxed),
        "local_slow_consumer_disconnects_total": metrics.sse_slow_consumer_disconnects_total.load(Ordering::Relaxed),
        "local_last_idle_disconnect_at_ms": optional_non_zero_u64(metrics.sse_last_idle_disconnect_at_ms.load(Ordering::Relaxed)),
        "local_last_gate_disconnect_at_ms": optional_non_zero_u64(metrics.sse_last_gate_disconnect_at_ms.load(Ordering::Relaxed)),
        "local_last_lagged_message_at_ms": optional_non_zero_u64(metrics.sse_last_lagged_message_at_ms.load(Ordering::Relaxed)),
        "local_last_slow_consumer_disconnect_at_ms": optional_non_zero_u64(metrics.sse_last_slow_consumer_disconnect_at_ms.load(Ordering::Relaxed)),
        "instances": aggregate.instances.iter().map(|entry| {
            json!({
                "instance_id": entry.instance_id,
                "updated_at_ms": entry.updated_at_ms,
                "active_connections": entry.total_active,
                "tenant_slots": entry.tenant_slots,
                "client_slots": entry.client_slots,
                "tenant_connections": entry.connections_by_tenant,
                "client_connections": entry.connections_by_client,
                "idle_disconnects_total": entry.idle_disconnects_total,
                "gate_disconnects_total": entry.gate_disconnects_total,
                "lagged_messages_total": entry.lagged_messages_total,
                "slow_consumer_disconnects_total": entry.slow_consumer_disconnects_total,
                "last_idle_disconnect_at_ms": optional_non_zero_u64(entry.last_idle_disconnect_at_ms),
                "last_gate_disconnect_at_ms": optional_non_zero_u64(entry.last_gate_disconnect_at_ms),
                "last_lagged_message_at_ms": optional_non_zero_u64(entry.last_lagged_message_at_ms),
                "last_slow_consumer_disconnect_at_ms": optional_non_zero_u64(entry.last_slow_consumer_disconnect_at_ms),
            })
        }).collect::<Vec<_>>(),
        "stale_instance_entries": aggregate.stale_instances.iter().map(|entry| {
            json!({
                "instance_id": entry.instance_id,
                "updated_at_ms": entry.updated_at_ms,
                "active_connections": entry.total_active,
                "tenant_slots": entry.tenant_slots,
                "client_slots": entry.client_slots,
                "tenant_connections": entry.connections_by_tenant,
                "client_connections": entry.connections_by_client,
                "idle_disconnects_total": entry.idle_disconnects_total,
                "gate_disconnects_total": entry.gate_disconnects_total,
                "lagged_messages_total": entry.lagged_messages_total,
                "slow_consumer_disconnects_total": entry.slow_consumer_disconnects_total,
                "last_idle_disconnect_at_ms": optional_non_zero_u64(entry.last_idle_disconnect_at_ms),
                "last_gate_disconnect_at_ms": optional_non_zero_u64(entry.last_gate_disconnect_at_ms),
                "last_lagged_message_at_ms": optional_non_zero_u64(entry.last_lagged_message_at_ms),
                "last_slow_consumer_disconnect_at_ms": optional_non_zero_u64(entry.last_slow_consumer_disconnect_at_ms),
            })
        }).collect::<Vec<_>>(),
    })
}

fn normalize_ops_runtime_profile(profile: String) -> Result<String, String> {
    match profile.trim() {
        "normal" => Ok("normal".to_string()),
        "readonly" => Ok("readonly".to_string()),
        "drain" => Ok("drain".to_string()),
        "maintenance" => Ok("maintenance".to_string()),
        other => Err(format!(
            "invalid runtime profile: {} (supported: normal, readonly, drain, maintenance)",
            other
        )),
    }
}

fn ops_runtime_profile_is_active(profile: &str) -> bool {
    profile != "normal"
}

fn ops_runtime_profile_severity(profile: &str) -> &'static str {
    match profile {
        "readonly" => "medium",
        "drain" | "maintenance" => "high",
        _ => "none",
    }
}

fn build_runtime_profile_effective_states(
    profile_state: &OpsRuntimeProfileState,
) -> (
    OpsWriteGateState,
    OpsRealtimeGateState,
    OpsRuntimeDrillState,
) {
    let (write_enabled, realtime_enabled, drill_enabled, drill_kind) =
        match profile_state.profile.as_str() {
            "readonly" => (false, true, false, "none"),
            "drain" => (false, false, false, "none"),
            "maintenance" => (false, false, true, "ready_degraded"),
            _ => (true, true, false, "none"),
        };
    (
        OpsWriteGateState {
            enabled: write_enabled,
            operator: profile_state.operator.clone(),
            reason: profile_state.reason.clone(),
            request_id: profile_state.request_id.clone(),
            updated_at_ms: profile_state.updated_at_ms,
        },
        OpsRealtimeGateState {
            enabled: realtime_enabled,
            operator: profile_state.operator.clone(),
            reason: profile_state.reason.clone(),
            request_id: profile_state.request_id.clone(),
            updated_at_ms: profile_state.updated_at_ms,
        },
        OpsRuntimeDrillState {
            enabled: drill_enabled,
            kind: drill_kind.to_string(),
            operator: profile_state.operator.clone(),
            reason: profile_state.reason.clone(),
            request_id: profile_state.request_id.clone(),
            updated_at_ms: profile_state.updated_at_ms,
        },
    )
}

fn ops_runtime_profile_matches_effective(
    profile_state: &OpsRuntimeProfileState,
    write_gate_state: &OpsWriteGateState,
    realtime_gate_state: &OpsRealtimeGateState,
    runtime_drill_state: &OpsRuntimeDrillState,
) -> bool {
    let (expected_write, expected_realtime, expected_drill) =
        build_runtime_profile_effective_states(profile_state);
    write_gate_state.enabled == expected_write.enabled
        && realtime_gate_state.enabled == expected_realtime.enabled
        && runtime_drill_state.enabled == expected_drill.enabled
        && runtime_drill_state.kind == expected_drill.kind
}

fn normalize_ops_runtime_rollout_phase(
    phase: Option<String>,
    active: bool,
) -> Result<String, String> {
    if !active {
        return Ok("idle".to_string());
    }

    match normalized_optional_string(phase)
        .unwrap_or_else(|| "canary".to_string())
        .as_str()
    {
        "prepare" => Ok("prepare".to_string()),
        "canary" => Ok("canary".to_string()),
        "promote" => Ok("promote".to_string()),
        "rollback" => Ok("rollback".to_string()),
        "hold" => Ok("hold".to_string()),
        other => Err(format!(
            "invalid runtime rollout phase: {} (supported: prepare, canary, promote, rollback, hold)",
            other
        )),
    }
}

fn ops_runtime_rollout_severity(phase: &str) -> &'static str {
    match phase {
        "rollback" => "high",
        "canary" | "hold" => "medium",
        "prepare" | "promote" => "low",
        _ => "none",
    }
}

fn ops_runtime_rollout_next_phase_hint(phase: &str) -> Option<&'static str> {
    match phase {
        "prepare" => Some("canary"),
        "canary" => Some("promote"),
        "promote" => Some("complete"),
        "rollback" => Some("complete"),
        _ => None,
    }
}

fn runtime_rollout_phase_min_dwell_ms(config: &DubheChannelConfig, phase: &str) -> u64 {
    match phase {
        "prepare" => config.ops_runtime_rollout_prepare_min_dwell_ms,
        "canary" => config.ops_runtime_rollout_canary_min_dwell_ms,
        "promote" => config.ops_runtime_rollout_promote_min_dwell_ms,
        "rollback" => config.ops_runtime_rollout_rollback_min_dwell_ms,
        _ => 0,
    }
}

fn runtime_rollout_phase_dwell_snapshot(
    config: &DubheChannelConfig,
    rollout_state: &OpsRuntimeRolloutState,
    now_ms: u64,
) -> Option<RuntimeRolloutPhaseDwellSnapshot> {
    if !rollout_state.active {
        return None;
    }

    let required_ms = runtime_rollout_phase_min_dwell_ms(config, rollout_state.phase.as_str());
    if required_ms == 0 {
        return None;
    }

    let started_at_ms = rollout_state.updated_at_ms;
    let elapsed_ms = if started_at_ms == 0 {
        0
    } else {
        now_ms.saturating_sub(started_at_ms)
    };
    let remaining_ms = required_ms.saturating_sub(elapsed_ms);

    Some(RuntimeRolloutPhaseDwellSnapshot {
        phase: rollout_state.phase.clone(),
        required_ms,
        elapsed_ms,
        remaining_ms,
        started_at_ms,
        satisfied: remaining_ms == 0,
    })
}

fn ops_runtime_rollout_transition_allowed(
    current_phase: &str,
    current_active: bool,
    next_phase: &str,
    next_active: bool,
) -> bool {
    if !next_active {
        return next_phase == "idle";
    }

    let current_phase = if current_active {
        current_phase
    } else {
        "idle"
    };
    match current_phase {
        "idle" => matches!(next_phase, "prepare" | "canary" | "hold"),
        "prepare" => matches!(
            next_phase,
            "prepare" | "canary" | "hold" | "rollback" | "idle"
        ),
        "canary" => matches!(
            next_phase,
            "canary" | "promote" | "hold" | "rollback" | "idle"
        ),
        "promote" => matches!(next_phase, "promote" | "hold" | "rollback" | "idle"),
        "rollback" => matches!(next_phase, "rollback" | "hold" | "idle"),
        "hold" => matches!(
            next_phase,
            "prepare" | "canary" | "promote" | "rollback" | "hold" | "idle"
        ),
        _ => false,
    }
}

async fn current_ops_runtime_profile_state<DB>(
    state: &AppState<DB>,
) -> Result<OpsRuntimeProfileState, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let profile_state = if let Some(coordinator) = &state.submit_coordinator {
        coordinator
            .inspect_ops_runtime_profile_state()
            .await
            .map_err(|error| error.to_string())?
    } else {
        state.ops_runtime_profile_state.read().await.clone()
    }
    .unwrap_or_default();

    state.metrics.ops_runtime_profile_active.store(
        u64::from(ops_runtime_profile_is_active(&profile_state.profile)),
        Ordering::Relaxed,
    );
    Ok(profile_state)
}

