async fn current_ops_runtime_rollout_history<DB>(
    state: &AppState<DB>,
    limit: usize,
) -> Result<Vec<OpsRuntimeRolloutHistoryEntry>, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if let Some(coordinator) = &state.submit_coordinator {
        return coordinator
            .peek_ops_runtime_rollout_history(limit)
            .await
            .map_err(|error| error.to_string());
    }

    Ok(state
        .ops_runtime_rollout_history
        .read()
        .await
        .iter()
        .take(limit)
        .cloned()
        .collect())
}

async fn record_ops_runtime_rollout_history<DB>(
    state: &AppState<DB>,
    entry: OpsRuntimeRolloutHistoryEntry,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    {
        let mut history = state.ops_runtime_rollout_history.write().await;
        history.push_front(entry.clone());
        let keep_limit = state.config.ops_runtime_rollout_history_limit;
        while history.len() > keep_limit {
            history.pop_back();
        }
    }

    if let Some(coordinator) = &state.submit_coordinator {
        coordinator
            .push_ops_runtime_rollout_history(
                &entry,
                state.config.ops_runtime_rollout_history_limit,
            )
            .await
            .map_err(|error| error.to_string())?;
    }

    Ok(())
}

