fn normalize_ops_runtime_drill_kind(kind: Option<String>, enabled: bool) -> Result<String, String> {
    if !enabled {
        return Ok("none".to_string());
    }

    match normalized_optional_string(kind)
        .unwrap_or_else(|| "ready_degraded".to_string())
        .as_str()
    {
        "ready_degraded" => Ok("ready_degraded".to_string()),
        "alert_only" => Ok("alert_only".to_string()),
        other => Err(format!(
            "invalid runtime drill kind: {} (supported: ready_degraded, alert_only)",
            other
        )),
    }
}

fn ops_runtime_drill_kind_degrades_ready(kind: &str) -> bool {
    matches!(kind, "ready_degraded")
}

fn ops_runtime_drill_severity(kind: &str) -> &'static str {
    if ops_runtime_drill_kind_degrades_ready(kind) {
        "high"
    } else {
        "medium"
    }
}

