async fn apply_ops_runtime_profile<DB>(
    state: &AppState<DB>,
    profile_state: OpsRuntimeProfileState,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let (write_gate_state, realtime_gate_state, runtime_drill_state) =
        build_runtime_profile_effective_states(&profile_state);
    update_ops_write_gate_state(state, write_gate_state).await?;
    update_ops_realtime_gate_state(state, realtime_gate_state).await?;
    update_ops_runtime_drill_state(state, runtime_drill_state).await?;
    update_ops_runtime_profile_state(state, profile_state).await
}

async fn apply_ops_runtime_profile_with_audit<DB>(
    state: &AppState<DB>,
    profile_state: OpsRuntimeProfileState,
    source: &str,
) -> Result<OpsRuntimeProfileHistoryEntry, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let previous_profile = current_ops_runtime_profile_state(state)
        .await
        .ok()
        .map(|state| state.profile);
    apply_ops_runtime_profile(state, profile_state.clone()).await?;
    let entry = OpsRuntimeProfileHistoryEntry {
        request_id: profile_state.request_id.clone(),
        profile: profile_state.profile.clone(),
        previous_profile,
        operator: profile_state.operator.clone(),
        reason: profile_state.reason.clone(),
        updated_at_ms: profile_state.updated_at_ms,
        source: source.to_string(),
    };
    record_ops_runtime_profile_history(state, entry.clone()).await?;
    Ok(entry)
}

async fn update_ops_runtime_rollout_with_audit<DB>(
    state: &AppState<DB>,
    rollout_state: OpsRuntimeRolloutState,
    apply_target_profile: bool,
    source: &str,
) -> Result<OpsRuntimeRolloutHistoryEntry, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let previous_phase = current_ops_runtime_rollout_state(state)
        .await
        .ok()
        .and_then(|state| {
            if state.active {
                Some(state.phase)
            } else {
                None
            }
        });
    update_ops_runtime_rollout_state(state, rollout_state.clone()).await?;
    let entry = OpsRuntimeRolloutHistoryEntry {
        request_id: rollout_state.request_id.clone(),
        active: rollout_state.active,
        phase: rollout_state.phase.clone(),
        target_profile: rollout_state.target_profile.clone(),
        baseline_profile: rollout_state.baseline_profile.clone(),
        previous_phase,
        operator: rollout_state.operator.clone(),
        reason: rollout_state.reason.clone(),
        updated_at_ms: rollout_state.updated_at_ms,
        apply_target_profile,
        source: source.to_string(),
    };
    record_ops_runtime_rollout_history(state, entry.clone()).await?;
    Ok(entry)
}

