fn current_action_redispatch_attempts(
    dispatch_state: &OpsAlertDispatchState,
    current_fingerprint: Option<&str>,
) -> u64 {
    match (
        dispatch_state.last_redispatch_fingerprint.as_deref(),
        current_fingerprint,
    ) {
        (Some(last_fingerprint), Some(current_fingerprint))
            if last_fingerprint == current_fingerprint =>
        {
            dispatch_state.last_redispatch_attempts
        }
        _ => 0,
    }
}

fn current_action_redispatch_attempts_by_updated_at(
    dispatch_state: &OpsAlertDispatchState,
    current_updated_at_ms: u64,
) -> u64 {
    dispatch_state
        .last_redispatch_at_ms
        .filter(|last_redispatch_at_ms| *last_redispatch_at_ms >= current_updated_at_ms)
        .map(|_| dispatch_state.last_redispatch_attempts)
        .unwrap_or(0)
}

fn update_action_redispatch_state(
    dispatch_state: &mut OpsAlertDispatchState,
    request_id: &str,
    source: &str,
    reason: Option<&str>,
    fingerprint: &str,
    now_ms: u64,
) {
    let next_attempt = if dispatch_state.last_redispatch_fingerprint.as_deref() == Some(fingerprint)
    {
        dispatch_state.last_redispatch_attempts.saturating_add(1)
    } else {
        1
    };
    dispatch_state.last_redispatch_request_id = Some(request_id.to_string());
    dispatch_state.last_redispatch_at_ms = Some(now_ms);
    dispatch_state.last_redispatch_source = Some(source.to_string());
    dispatch_state.last_redispatch_reason = reason.map(str::to_string);
    dispatch_state.last_redispatch_fingerprint = Some(fingerprint.to_string());
    dispatch_state.last_redispatch_attempts = next_attempt;
}

