fn ops_runtime_rollout_action_execution_timeout_ms(
    config: &DubheChannelConfig,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> u64 {
    match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => {
            config.ops_runtime_rollout_receipt_pending_timeout_ms
        }
        OpsRuntimeRolloutActionAdapterKind::Traffic => {
            config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms
        }
    }
}

fn rollout_action_execution_matches_current_action(
    execution_state: &OpsRuntimeRolloutActionExecutionState,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    current_fingerprint: Option<&str>,
    current_rollout_request_id: Option<&str>,
) -> bool {
    let matches_current_rollout = current_rollout_request_id
        .map(|request_id| request_id == execution_state.rollout_request_id)
        .unwrap_or(false);
    let matches_current_action = current_fingerprint
        .map(|fingerprint| fingerprint == execution_state.fingerprint)
        .unwrap_or(matches_current_rollout)
        || matches_current_rollout;
    execution_state.adapter == adapter.as_str() && matches_current_rollout && matches_current_action
}

fn rollout_action_execution_timed_out(
    execution_state: &OpsRuntimeRolloutActionExecutionState,
    timeout_ms: u64,
    now_ms: u64,
) -> bool {
    timeout_ms > 0 && now_ms.saturating_sub(execution_state.updated_at_ms) >= timeout_ms
}

fn rollout_action_ack_matches_current_action(
    ack_state: &OpsRuntimeRolloutActionAckState,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    current_fingerprint: Option<&str>,
    current_rollout_request_id: Option<&str>,
    min_updated_at_ms: Option<u64>,
) -> bool {
    let matches_current_rollout = current_rollout_request_id
        .map(|request_id| request_id == ack_state.rollout_request_id)
        .unwrap_or(false);
    let matches_current_action = current_fingerprint
        .map(|fingerprint| fingerprint == ack_state.fingerprint)
        .unwrap_or(matches_current_rollout)
        || matches_current_rollout;
    let fresh_enough = min_updated_at_ms
        .map(|min_updated_at_ms| ack_state.updated_at_ms >= min_updated_at_ms)
        .unwrap_or(true);
    ack_state.adapter == adapter.as_str()
        && matches_current_rollout
        && matches_current_action
        && fresh_enough
}

fn rollout_action_redispatch_timeout_reason(
    ack_timed_out: bool,
    execution_timed_out: bool,
) -> Option<&'static str> {
    if execution_timed_out {
        Some("action_execution_timeout")
    } else if ack_timed_out {
        Some("action_ack_timeout")
    } else {
        None
    }
}

fn validate_rollout_action_receipt_execution_target(
    execution_state: Option<&OpsRuntimeRolloutActionExecutionState>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    rollout_request_id: &str,
    actor: &str,
    execution_request_id: Option<&str>,
) -> Result<(), String> {
    let Some(execution_state) = execution_state else {
        return Ok(());
    };
    if execution_state.adapter != adapter.as_str()
        || execution_state.rollout_request_id != rollout_request_id
    {
        return Ok(());
    }
    if let Some(execution_request_id) = execution_request_id {
        if execution_request_id != execution_state.execution_request_id {
            return Err(format!(
                "runtime rollout {} receipt targets stale execution_request_id={} (current={})",
                adapter.as_str(),
                execution_request_id,
                execution_state.execution_request_id
            ));
        }
        return Ok(());
    }
    if execution_state.actor != actor {
        return Err(format!(
            "runtime rollout {} receipt actor={} does not match current execution owner={}",
            adapter.as_str(),
            actor,
            execution_state.actor
        ));
    }
    Ok(())
}

async fn current_ops_runtime_rollout_action_execution_state<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> Result<Option<OpsRuntimeRolloutActionExecutionState>, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if let Some(coordinator) = &state.submit_coordinator {
        let value = match adapter {
            OpsRuntimeRolloutActionAdapterKind::Deploy => {
                coordinator
                    .inspect_ops_runtime_rollout_deploy_action_execution_state()
                    .await
            }
            OpsRuntimeRolloutActionAdapterKind::Traffic => {
                coordinator
                    .inspect_ops_runtime_rollout_traffic_action_execution_state()
                    .await
            }
        }
        .map_err(|error| error.to_string())?;
        return Ok(value);
    }

    Ok(match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => state
            .ops_runtime_rollout_deploy_action_execution_state
            .read()
            .await
            .clone(),
        OpsRuntimeRolloutActionAdapterKind::Traffic => state
            .ops_runtime_rollout_traffic_action_execution_state
            .read()
            .await
            .clone(),
    })
}

async fn update_ops_runtime_rollout_action_execution_state<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    execution_state: OpsRuntimeRolloutActionExecutionState,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => {
            *state
                .ops_runtime_rollout_deploy_action_execution_state
                .write()
                .await = Some(execution_state.clone());
        }
        OpsRuntimeRolloutActionAdapterKind::Traffic => {
            *state
                .ops_runtime_rollout_traffic_action_execution_state
                .write()
                .await = Some(execution_state.clone());
        }
    }

    if let Some(coordinator) = &state.submit_coordinator {
        match adapter {
            OpsRuntimeRolloutActionAdapterKind::Deploy => coordinator
                .store_ops_runtime_rollout_deploy_action_execution_state(&execution_state)
                .await
                .map_err(|error| error.to_string())?,
            OpsRuntimeRolloutActionAdapterKind::Traffic => coordinator
                .store_ops_runtime_rollout_traffic_action_execution_state(&execution_state)
                .await
                .map_err(|error| error.to_string())?,
        }
    }

    Ok(())
}

