async fn reconcile_ops_runtime_rollout_action_execution_from_receipt<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    rollout_request_id: &str,
    execution_request_id: Option<String>,
    actor: &str,
    note: Option<String>,
    external_ref: Option<String>,
    status: &str,
    updated_at_ms: u64,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let existing_execution =
        current_ops_runtime_rollout_action_execution_state(state, adapter).await?;
    if rollout_execution_receipt_pending(status) {
        let ack_state = current_ops_runtime_rollout_action_ack_state(state, adapter).await?;
        let fingerprint = existing_execution
            .as_ref()
            .filter(|entry| {
                entry.adapter == adapter.as_str() && entry.rollout_request_id == rollout_request_id
            })
            .map(|entry| entry.fingerprint.clone())
            .or_else(|| {
                ack_state
                    .as_ref()
                    .filter(|entry| {
                        entry.adapter == adapter.as_str()
                            && entry.rollout_request_id == rollout_request_id
                    })
                    .map(|entry| entry.fingerprint.clone())
            })
            .unwrap_or_else(|| rollout_request_id.to_string());
        let claimed_at_ms = existing_execution
            .as_ref()
            .filter(|entry| {
                entry.adapter == adapter.as_str()
                    && entry.rollout_request_id == rollout_request_id
                    && entry.actor == actor
            })
            .map(|entry| entry.claimed_at_ms)
            .unwrap_or(updated_at_ms);
        let execution_request_id = execution_request_id
            .or_else(|| {
                existing_execution
                    .as_ref()
                    .filter(|entry| {
                        entry.adapter == adapter.as_str()
                            && entry.rollout_request_id == rollout_request_id
                            && entry.actor == actor
                    })
                    .map(|entry| entry.execution_request_id.clone())
            })
            .unwrap_or_else(|| {
                format!(
                    "runtime-rollout-{}-execution-{}",
                    adapter.as_str(),
                    updated_at_ms
                )
            });
        let execution_state = OpsRuntimeRolloutActionExecutionState {
            execution_request_id,
            adapter: adapter.as_str().to_string(),
            rollout_request_id: rollout_request_id.to_string(),
            fingerprint,
            actor: actor.to_string(),
            note,
            external_ref,
            source: "receipt".to_string(),
            claimed_at_ms,
            updated_at_ms,
            last_status: Some(status.to_string()),
        };
        update_ops_runtime_rollout_action_execution_state(state, adapter, execution_state).await?;
    } else if existing_execution
        .as_ref()
        .map(|entry| {
            entry.adapter == adapter.as_str() && entry.rollout_request_id == rollout_request_id
        })
        .unwrap_or(false)
    {
        clear_ops_runtime_rollout_action_execution_state(state, adapter).await?;
    }
    Ok(())
}

