async fn build_ops_runtime_rollout_action_status_snapshot<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    feed: Option<&OpsRuntimeRolloutActionFeed>,
) -> Result<OpsRuntimeRolloutActionStatusSnapshot, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let dispatch_state = current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
    let pending_delivery =
        current_ops_runtime_rollout_action_delivery_pending(state, adapter).await?;
    let ack_state = current_ops_runtime_rollout_action_ack_state(state, adapter).await?;
    let execution_state =
        current_ops_runtime_rollout_action_execution_state(state, adapter).await?;
    let configured = adapter.webhook_url(&state.config).is_some();
    let current_fingerprint = feed.map(|feed| feed.fingerprint.clone());
    let current_rollout_request_id = feed.map(|feed| feed.rollout_state.request_id.as_str());
    let action_available = current_fingerprint.is_some();
    let dispatched_current_action = current_fingerprint
        .as_ref()
        .and_then(|fingerprint| {
            dispatch_state
                .last_fingerprint
                .as_ref()
                .map(|last_fingerprint| last_fingerprint == fingerprint)
        })
        .unwrap_or(false)
        && dispatch_state.last_success_at_ms.is_some();
    let current_action_dispatched_at_ms = if dispatched_current_action {
        dispatch_state.last_success_at_ms
    } else {
        None
    };
    let delivery_pending_for_current_action = current_fingerprint
        .as_ref()
        .and_then(|fingerprint| {
            pending_delivery
                .as_ref()
                .map(|pending| pending.fingerprint == *fingerprint)
        })
        .unwrap_or(false);
    let ack_matches_current_action = current_fingerprint
        .as_ref()
        .zip(current_rollout_request_id)
        .and_then(|(fingerprint, rollout_request_id)| {
            ack_state.as_ref().map(|ack_state| {
                rollout_action_ack_matches_current_action(
                    ack_state,
                    adapter,
                    Some(fingerprint.as_str()),
                    Some(rollout_request_id),
                    current_action_dispatched_at_ms,
                )
            })
        })
        .unwrap_or(false);
    let waiting_for_ack = current_fingerprint.is_some()
        && dispatched_current_action
        && !delivery_pending_for_current_action
        && !ack_matches_current_action;
    let ack_timed_out = waiting_for_ack
        && state.config.ops_runtime_rollout_action_ack_timeout_ms > 0
        && dispatch_state
            .last_success_at_ms
            .map(|last_success_at_ms| {
                now_ts_ms().saturating_sub(last_success_at_ms)
                    >= state.config.ops_runtime_rollout_action_ack_timeout_ms
            })
            .unwrap_or(false);
    let execution_timeout_ms =
        ops_runtime_rollout_action_execution_timeout_ms(&state.config, adapter);
    let execution_matches_current_action = execution_state
        .as_ref()
        .map(|execution_state| {
            rollout_action_execution_matches_current_action(
                execution_state,
                adapter,
                current_fingerprint.as_deref(),
                current_rollout_request_id,
            )
        })
        .unwrap_or(false);
    let now_ms = now_ts_ms();
    let execution_timed_out = execution_matches_current_action
        && execution_state
            .as_ref()
            .map(|execution_state| {
                rollout_action_execution_timed_out(execution_state, execution_timeout_ms, now_ms)
            })
            .unwrap_or(false);
    let execution_active = execution_matches_current_action && !execution_timed_out;
    let redispatch_attempts =
        current_action_redispatch_attempts(&dispatch_state, current_fingerprint.as_deref());
    let redispatch_max_attempts = state
        .config
        .ops_runtime_rollout_action_ack_redispatch_max_attempts;
    let redispatch_remaining_attempts = redispatch_max_attempts.saturating_sub(redispatch_attempts);
    let redispatch_exhausted =
        redispatch_max_attempts > 0 && redispatch_attempts >= redispatch_max_attempts;
    let redispatch_timeout_active =
        rollout_action_redispatch_timeout_reason(ack_timed_out, execution_timed_out).is_some();
    let redispatch_next_eligible_at_ms = if redispatch_timeout_active && redispatch_attempts > 0 {
        dispatch_state
            .last_redispatch_at_ms
            .map(|last_redispatch_at_ms| {
                last_redispatch_at_ms.saturating_add(
                    ops_runtime_rollout_action_redispatch_backoff_ms(
                        &state.config,
                        redispatch_attempts,
                    ),
                )
            })
    } else {
        None
    };
    let redispatch_remaining_backoff_ms = redispatch_next_eligible_at_ms
        .map(|next_eligible_at_ms| next_eligible_at_ms.saturating_sub(now_ms))
        .unwrap_or(0);
    let redispatch_backoff_active = !redispatch_exhausted && redispatch_remaining_backoff_ms > 0;
    let redispatch_eligible = configured
        && action_available
        && redispatch_timeout_active
        && redispatch_max_attempts > 0
        && !redispatch_exhausted
        && !delivery_pending_for_current_action
        && !redispatch_backoff_active;

    Ok(OpsRuntimeRolloutActionStatusSnapshot {
        configured,
        action_available,
        current_fingerprint,
        dispatched_current_action,
        delivery_pending_for_current_action,
        ack_state,
        execution_state,
        ack_timed_out,
        waiting_for_ack,
        execution_active,
        execution_timed_out,
        execution_timeout_ms,
        redispatch_attempts,
        redispatch_max_attempts,
        redispatch_remaining_attempts,
        redispatch_eligible,
        redispatch_exhausted,
        redispatch_backoff_active,
        redispatch_next_eligible_at_ms,
        redispatch_remaining_backoff_ms,
    })
}

fn runtime_rollout_action_redispatch_block_reason(
    action_status: &OpsRuntimeRolloutActionStatusSnapshot,
) -> Option<&'static str> {
    if !action_status.configured {
        Some("runtime rollout action webhook is not configured")
    } else if !action_status.action_available {
        Some("runtime rollout action redispatch requires a current actionable command")
    } else if action_status.delivery_pending_for_current_action {
        Some("runtime rollout action redispatch unavailable while delivery is pending")
    } else if !action_status.waiting_for_ack && !action_status.execution_timed_out {
        Some("runtime rollout action redispatch requires an outstanding ack wait or execution timeout")
    } else if rollout_action_redispatch_timeout_reason(
        action_status.ack_timed_out,
        action_status.execution_timed_out,
    )
    .is_none()
    {
        Some("runtime rollout action redispatch requires ack timeout or execution timeout")
    } else if action_status.redispatch_backoff_active {
        Some("runtime rollout action redispatch backoff is active")
    } else if action_status.redispatch_max_attempts == 0 {
        Some("runtime rollout action redispatch is disabled")
    } else if action_status.redispatch_exhausted {
        Some("runtime rollout action redispatch attempts exhausted")
    } else {
        None
    }
}

async fn redispatch_ops_runtime_rollout_action_feed<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    request_id: &str,
    source: &str,
    reason: Option<&str>,
) -> Result<
    (
        OpsRuntimeRolloutActionFeed,
        OpsRuntimeRolloutActionStatusSnapshot,
    ),
    String,
>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let current_feed = match build_ops_runtime_rollout_action_feed(state, adapter, None, None).await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    let action_status =
        build_ops_runtime_rollout_action_status_snapshot(state, adapter, current_feed.as_ref())
            .await?;
    if let Some(error) = runtime_rollout_action_redispatch_block_reason(&action_status) {
        record_ops_runtime_rollout_action_redispatch_blocked(&state.metrics, adapter);
        return Err(error.to_string());
    }
    let Some(_) = current_feed else {
        record_ops_runtime_rollout_action_redispatch_blocked(&state.metrics, adapter);
        return Err(
            "runtime rollout action redispatch requires a current actionable command".to_string(),
        );
    };
    let _lease = acquire_ops_runtime_rollout_action_redispatch_lease(state, adapter, request_id)
        .await
        .map_err(|error| {
            record_ops_runtime_rollout_action_redispatch_blocked(&state.metrics, adapter);
            format!(
                "runtime rollout {} action redispatch lease busy: {}",
                adapter.as_str(),
                error
            )
        })?;
    let current_feed = match build_ops_runtime_rollout_action_feed(state, adapter, None, None).await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    let action_status =
        build_ops_runtime_rollout_action_status_snapshot(state, adapter, current_feed.as_ref())
            .await?;
    if let Some(error) = runtime_rollout_action_redispatch_block_reason(&action_status) {
        record_ops_runtime_rollout_action_redispatch_blocked(&state.metrics, adapter);
        return Err(error.to_string());
    }
    let Some(_) = current_feed else {
        record_ops_runtime_rollout_action_redispatch_blocked(&state.metrics, adapter);
        return Err(
            "runtime rollout action redispatch requires a current actionable command".to_string(),
        );
    };

    let (feed, _skipped) =
        dispatch_ops_runtime_rollout_action_feed(state, adapter, true, Some(source), None).await?;
    let mut dispatch_state =
        current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
    update_action_redispatch_state(
        &mut dispatch_state,
        request_id,
        source,
        reason,
        &feed.fingerprint,
        now_ts_ms(),
    );
    update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
    record_ops_runtime_rollout_action_redispatch_triggered(&state.metrics, adapter);

    let action_status =
        build_ops_runtime_rollout_action_status_snapshot(state, adapter, Some(&feed)).await?;
    Ok((feed, action_status))
}

async fn process_ops_runtime_rollout_action_auto_redispatch_once<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> Result<bool, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let current_feed = match build_ops_runtime_rollout_action_feed(state, adapter, None, None).await
    {
        Ok(feed) if validate_ops_runtime_rollout_action_feed(&feed).is_ok() => Some(feed),
        _ => None,
    };
    let action_status =
        build_ops_runtime_rollout_action_status_snapshot(state, adapter, current_feed.as_ref())
            .await?;
    if !action_status.redispatch_eligible {
        return Ok(false);
    }

    let request_id = format!(
        "rollout-adapter-auto-redispatch-{}-{}",
        adapter.as_str(),
        now_ts_ms()
    );
    let reason = rollout_action_redispatch_timeout_reason(
        action_status.ack_timed_out,
        action_status.execution_timed_out,
    )
    .unwrap_or("action_ack_timeout");
    redispatch_ops_runtime_rollout_action_feed(
        state,
        adapter,
        &request_id,
        "adapter_auto_redispatch",
        Some(reason),
    )
    .await?;
    Ok(true)
}

fn normalize_ops_runtime_rollout_receipt_status(status: String) -> Result<String, String> {
    match status.trim() {
        "acknowledged" => Ok("acknowledged".to_string()),
        "in_progress" => Ok("in_progress".to_string()),
        "applied" => Ok("applied".to_string()),
        "completed" => Ok("completed".to_string()),
        "failed" => Ok("failed".to_string()),
        "rolled_back" => Ok("rolled_back".to_string()),
        other => Err(format!(
            "invalid runtime rollout receipt status: {} (supported: acknowledged, in_progress, applied, completed, failed, rolled_back)",
            other
        )),
    }
}

fn normalize_ops_runtime_rollout_approval_status(status: String) -> Result<String, String> {
    match status.trim() {
        "pending" => Ok("pending".to_string()),
        "approved" => Ok("approved".to_string()),
        "rejected" => Ok("rejected".to_string()),
        other => Err(format!(
            "invalid runtime rollout approval status: {} (supported: pending, approved, rejected)",
            other
        )),
    }
}

fn normalize_ops_runtime_rollout_traffic_stage(stage: String) -> Result<String, String> {
    match stage.trim() {
        "baseline" => Ok("baseline".to_string()),
        "canary" => Ok("canary".to_string()),
        "promote" => Ok("promote".to_string()),
        "rollback" => Ok("rollback".to_string()),
        other => Err(format!(
            "invalid runtime rollout traffic stage: {} (supported: baseline, canary, promote, rollback)",
            other
        )),
    }
}

fn normalize_ops_runtime_rollout_traffic_receipt_status(status: String) -> Result<String, String> {
    match status.trim() {
        "acknowledged" => Ok("acknowledged".to_string()),
        "in_progress" => Ok("in_progress".to_string()),
        "applied" => Ok("applied".to_string()),
        "completed" => Ok("completed".to_string()),
        "failed" => Ok("failed".to_string()),
        "rolled_back" => Ok("rolled_back".to_string()),
        other => Err(format!(
            "invalid runtime rollout traffic receipt status: {} (supported: acknowledged, in_progress, applied, completed, failed, rolled_back)",
            other
        )),
    }
}

async fn current_ops_runtime_rollout_receipt_state<DB>(
    state: &AppState<DB>,
) -> Result<Option<OpsRuntimeRolloutReceiptState>, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let now_ms = now_ts_ms();
    let receipt_state = if let Some(coordinator) = &state.submit_coordinator {
        coordinator
            .inspect_ops_runtime_rollout_receipt_state()
            .await
            .map_err(|error| error.to_string())?
    } else {
        state.ops_runtime_rollout_receipt_state.read().await.clone()
    };

    state
        .metrics
        .ops_runtime_rollout_receipt_failed_active
        .store(
            u64::from(
                receipt_state
                    .as_ref()
                    .map(|receipt| receipt.status == "failed")
                    .unwrap_or(false),
            ),
            Ordering::Relaxed,
        );
    state
        .metrics
        .ops_runtime_rollout_receipt_timeout_active
        .store(
            u64::from(
                receipt_state
                    .as_ref()
                    .map(|receipt| {
                        rollout_execution_receipt_timed_out(
                            receipt.status.as_str(),
                            receipt.updated_at_ms,
                            state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
                            now_ms,
                        )
                    })
                    .unwrap_or(false),
            ),
            Ordering::Relaxed,
        );
    Ok(receipt_state)
}

