fn summarize_dead_letter_error_classes(
    entries: &[SubmitMaterializationOutboxEntry],
) -> DeadLetterErrorClassSummary {
    if entries.is_empty() {
        return DeadLetterErrorClassSummary::default();
    }

    let mut counts = BTreeMap::new();
    for entry in entries {
        *counts
            .entry(entry.last_error_class.as_str().to_string())
            .or_insert(0_u64) += 1;
    }

    let dominant = counts
        .iter()
        .max_by(|(left_class, left_count), (right_class, right_count)| {
            left_count
                .cmp(right_count)
                .then_with(|| right_class.cmp(left_class))
        })
        .map(|(class, count)| (class.clone(), *count));
    let dominant_class = dominant.as_ref().map(|(class, _)| class.clone());
    let dominant_count = dominant.map(|(_, count)| count).unwrap_or(0);
    let alert_active = dominant_class
        .as_deref()
        .map(|class| class != SubmitMaterializationFailureClass::Unknown.as_str())
        .unwrap_or(false);

    DeadLetterErrorClassSummary {
        sample_size: entries.len(),
        counts,
        dominant_class,
        dominant_count,
        alert_active,
    }
}

async fn current_dead_letter_error_class_summary<DB>(
    state: &AppState<DB>,
    dead_letter_size: u64,
) -> Result<DeadLetterErrorClassSummary, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let sample_limit = (dead_letter_size as usize).min(DEAD_LETTER_ERROR_CLASS_SAMPLE_LIMIT);
    if sample_limit == 0 {
        return Ok(DeadLetterErrorClassSummary::default());
    }

    let entries = current_dead_letter_entries(state, sample_limit).await?;
    Ok(summarize_dead_letter_error_classes(entries.as_slice()))
}

async fn build_dead_letter_ops_snapshot<DB>(
    state: &AppState<DB>,
) -> Result<DeadLetterOpsSnapshot, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    refresh_submit_materialization_outbox_size(state).await;
    refresh_submit_materialization_dead_letter_size(state).await;

    let replay_owner = current_dead_letter_replay_owner(state).await?;
    let replay_status = current_dead_letter_replay_status(state).await?;
    let auto_replay_state = current_dead_letter_auto_replay_state(state).await?;
    let replay_handoff = current_dead_letter_replay_handoff(state).await?;
    let replay_escalation_ack = current_dead_letter_replay_escalation_ack(state).await?;
    let replay_escalation_notification =
        current_dead_letter_replay_escalation_notification(state).await?;
    let runbook_history_limit = state
        .config
        .submit_materialization_dead_letter_replay_history_limit
        .min(DEAD_LETTER_RUNBOOK_HISTORY_SAMPLE_LIMIT)
        .max(1);
    let replay_history = current_dead_letter_replay_history(state, runbook_history_limit).await?;
    let now_ms = now_ts_ms();
    let outbox_size = state
        .metrics
        .submit_materialization_outbox_size
        .load(Ordering::Relaxed);
    let dead_letter_size = state
        .metrics
        .submit_materialization_dead_letter_size
        .load(Ordering::Relaxed);
    let dead_letter_error_summary =
        current_dead_letter_error_class_summary(state, dead_letter_size).await?;
    let cooldown_until_ms =
        current_dead_letter_replay_cooldown_until(replay_status.as_ref(), &state.config);
    let cooldown_active = cooldown_until_ms
        .map(|until_ms| now_ms < until_ms)
        .unwrap_or(false);
    let mut runbook_summary = build_dead_letter_runbook_summary(
        &state.config,
        now_ms,
        outbox_size,
        dead_letter_size,
        Some(&dead_letter_error_summary),
        replay_owner.is_some(),
        cooldown_active,
        replay_handoff.as_ref(),
        replay_status.as_ref(),
        replay_history.as_slice(),
    );
    let runbook_fingerprint = runbook_summary
        .get("fingerprint")
        .and_then(|value| value.as_str())
        .unwrap_or_default()
        .to_string();
    let escalation_acknowledged = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
        && replay_escalation_ack
            .as_ref()
            .map(|ack| ack.runbook_fingerprint == runbook_fingerprint)
            .unwrap_or(false);
    let escalation_notified = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
        && replay_escalation_notification
            .as_ref()
            .map(|notification| notification.runbook_fingerprint == runbook_fingerprint)
            .unwrap_or(false);
    let replay_policy_block_reason = dead_letter_replay_policy_block_reason(
        &runbook_summary,
        escalation_acknowledged,
        escalation_notified,
    );
    if let Some(runbook) = runbook_summary.as_object_mut() {
        runbook.insert(
            "escalation_acknowledged".to_string(),
            serde_json::Value::Bool(escalation_acknowledged),
        );
        runbook.insert(
            "notification_sent".to_string(),
            serde_json::Value::Bool(escalation_notified),
        );
        runbook.insert(
            "notification_required".to_string(),
            serde_json::Value::Bool(
                runbook
                    .get("escalate")
                    .and_then(|value| value.as_bool())
                    .unwrap_or(false)
                    && !escalation_notified,
            ),
        );
        runbook.insert(
            "replay_blocked".to_string(),
            serde_json::Value::Bool(replay_policy_block_reason.is_some()),
        );
        runbook.insert(
            "replay_block_reason".to_string(),
            replay_policy_block_reason.map_or(serde_json::Value::Null, |reason| {
                serde_json::Value::String(reason.to_string())
            }),
        );
    }

    Ok(DeadLetterOpsSnapshot {
        outbox_size,
        dead_letter_size,
        dead_letter_error_summary,
        replay_owner,
        replay_status,
        auto_replay_state,
        replay_handoff,
        replay_escalation_ack,
        replay_escalation_notification,
        cooldown_until_ms,
        cooldown_active,
        runbook_history_limit,
        runbook_summary,
        escalation_acknowledged,
        escalation_notified,
        replay_policy_block_reason,
    })
}

async fn current_dead_letter_replay_history<DB>(
    state: &AppState<DB>,
    limit: usize,
) -> Result<Vec<DeadLetterReplayHistoryEntry>, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if let Some(coordinator) = &state.submit_coordinator {
        return coordinator
            .peek_dead_letter_replay_history(limit)
            .await
            .map_err(|error| error.to_string());
    }

    Ok(state
        .submit_materialization_dead_letter_replay_history
        .read()
        .await
        .iter()
        .take(limit)
        .cloned()
        .collect())
}

async fn record_dead_letter_replay_history<DB>(
    state: &AppState<DB>,
    entry: DeadLetterReplayHistoryEntry,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    {
        let mut history = state
            .submit_materialization_dead_letter_replay_history
            .write()
            .await;
        history.push_front(entry.clone());
        let keep_limit = state
            .config
            .submit_materialization_dead_letter_replay_history_limit;
        while history.len() > keep_limit {
            history.pop_back();
        }
    }

    if let Some(coordinator) = &state.submit_coordinator {
        coordinator
            .push_dead_letter_replay_history(
                &entry,
                state
                    .config
                    .submit_materialization_dead_letter_replay_history_limit,
            )
            .await
            .map_err(|error| error.to_string())?;
    }

    Ok(())
}

