async fn update_dead_letter_replay_handoff<DB>(
    state: &AppState<DB>,
    handoff: Option<DeadLetterHandoffState>,
) -> Result<(), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    *state
        .submit_materialization_dead_letter_replay_handoff
        .write()
        .await = handoff.clone();

    if let Some(coordinator) = &state.submit_coordinator {
        match handoff {
            Some(handoff) => coordinator
                .store_dead_letter_replay_handoff(&handoff)
                .await
                .map_err(|error| error.to_string())?,
            None => coordinator
                .clear_dead_letter_replay_handoff()
                .await
                .map_err(|error| error.to_string())?,
        }
    }

    Ok(())
}

