fn normalized_optional_string(value: Option<String>) -> Option<String> {
    value.and_then(|value| {
        let trimmed = value.trim();
        if trimmed.is_empty() {
            None
        } else {
            Some(trimmed.to_string())
        }
    })
}

fn current_dead_letter_replay_cooldown_until(
    status: Option<&DeadLetterReplayStatus>,
    config: &DubheChannelConfig,
) -> Option<u64> {
    if config.submit_materialization_dead_letter_replay_cooldown_ms == 0 {
        return None;
    }

    let finished_at_ms = status?.last_finished_at_ms?;
    Some(
        finished_at_ms.saturating_add(config.submit_materialization_dead_letter_replay_cooldown_ms),
    )
}

fn build_dead_letter_runbook_fingerprint(
    outbox_size: u64,
    dead_letter_size: u64,
    severity: &str,
    recommended_action: &str,
    reasons: &[String],
    consecutive_failures: u64,
    handoff_stale: bool,
) -> String {
    let payload = json!({
        "outbox_size": outbox_size,
        "dead_letter_size": dead_letter_size,
        "severity": severity,
        "recommended_action": recommended_action,
        "reasons": reasons,
        "consecutive_failures": consecutive_failures,
        "handoff_stale": handoff_stale,
    })
    .to_string();
    let mut hasher = Sha256::new();
    hasher.update(payload.as_bytes());
    format!("{:x}", hasher.finalize())
}

fn dead_letter_replay_policy_block_reason(
    runbook_summary: &serde_json::Value,
    escalation_acknowledged: bool,
    escalation_notified: bool,
) -> Option<&'static str> {
    let recommended_action = runbook_summary
        .get("recommended_action")
        .and_then(|value| value.as_str())
        .unwrap_or("none");
    let escalate = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);

    if recommended_action == "claim_handoff" {
        Some("handoff_claim_required")
    } else if escalate && !escalation_notified {
        Some("escalation_notification_required")
    } else if recommended_action == "pause_and_investigate" && !escalation_acknowledged {
        Some("investigation_ack_required")
    } else if recommended_action == "escalate_stale_handoff" && !escalation_acknowledged {
        Some("escalation_ack_required")
    } else {
        None
    }
}

fn dead_letter_replay_failure_streak(
    replay_history: &[DeadLetterReplayHistoryEntry],
    replay_status: Option<&DeadLetterReplayStatus>,
) -> u64 {
    if !replay_history.is_empty() {
        return replay_history
            .iter()
            .take_while(|entry| entry.result == "failed")
            .count() as u64;
    }

    if matches!(
        replay_status.and_then(|status| status.last_result.as_deref()),
        Some("failed")
    ) {
        1
    } else {
        0
    }
}

fn build_dead_letter_runbook_summary(
    config: &DubheChannelConfig,
    now_ms: u64,
    outbox_size: u64,
    dead_letter_size: u64,
    dead_letter_error_summary: Option<&DeadLetterErrorClassSummary>,
    replay_active: bool,
    cooldown_active: bool,
    replay_handoff: Option<&DeadLetterHandoffState>,
    replay_status: Option<&DeadLetterReplayStatus>,
    replay_history: &[DeadLetterReplayHistoryEntry],
) -> serde_json::Value {
    let dead_letter_threshold_breached = config.submit_materialization_ready_max_dead_letter_size
        > 0
        && dead_letter_size >= config.submit_materialization_ready_max_dead_letter_size;
    let outbox_threshold_breached = config.submit_materialization_ready_max_outbox_size > 0
        && outbox_size >= config.submit_materialization_ready_max_outbox_size;
    let handoff_age_ms = replay_handoff.map(|handoff| now_ms.saturating_sub(handoff.updated_at_ms));
    let handoff_stale = dead_letter_size > 0
        && !replay_active
        && config.submit_materialization_dead_letter_handoff_stale_ms > 0
        && handoff_age_ms
            .map(|age_ms| age_ms >= config.submit_materialization_dead_letter_handoff_stale_ms)
            .unwrap_or(false);
    let consecutive_failures = dead_letter_replay_failure_streak(replay_history, replay_status);
    let failure_streak_threshold =
        config.submit_materialization_dead_letter_replay_failure_streak_threshold;
    let failure_streak_threshold_breached = dead_letter_size > 0
        && failure_streak_threshold > 0
        && consecutive_failures >= failure_streak_threshold;
    let last_failed = matches!(
        replay_status.and_then(|status| status.last_result.as_deref()),
        Some("failed")
    );
    let last_internal_error = replay_status
        .and_then(|status| status.last_error_class.as_deref())
        .is_some();
    let dominant_dead_letter_error_class =
        dead_letter_error_summary.and_then(|summary| summary.dominant_class.as_deref());
    let dominant_dead_letter_error_count = dead_letter_error_summary
        .map(|summary| summary.dominant_count)
        .unwrap_or(0);
    let dead_letter_error_class_alert_active = dead_letter_error_summary
        .map(|summary| summary.alert_active)
        .unwrap_or(false);

    let mut reasons = Vec::new();
    if dead_letter_size > 0 {
        reasons.push("dead_letter_backlog_present".to_string());
    }
    if replay_handoff.is_none() && dead_letter_size > 0 {
        reasons.push("no_active_handoff".to_string());
    }
    if cooldown_active && dead_letter_size > 0 {
        reasons.push("replay_cooldown_active".to_string());
    }
    if replay_active {
        reasons.push("replay_currently_running".to_string());
    }
    if last_failed {
        reasons.push("last_replay_failed".to_string());
    }
    if last_internal_error {
        reasons.push("last_replay_internal_error".to_string());
    }
    if let Some(class) = dominant_dead_letter_error_class {
        if class != SubmitMaterializationFailureClass::Unknown.as_str() {
            reasons.push(format!("dominant_dead_letter_error_class={}", class));
        }
    }
    if handoff_stale {
        reasons.push("handoff_stale".to_string());
    }
    if failure_streak_threshold_breached {
        reasons.push("replay_failure_streak_threshold_breached".to_string());
    }
    if dead_letter_threshold_breached {
        reasons.push("dead_letter_alert_threshold_breached".to_string());
    }
    if outbox_threshold_breached {
        reasons.push("outbox_alert_threshold_breached".to_string());
    }

    let severity = if dead_letter_threshold_breached
        || failure_streak_threshold_breached
        || (dead_letter_size > 0 && last_failed && handoff_stale)
    {
        "critical"
    } else if handoff_stale || (dead_letter_size > 0 && replay_handoff.is_none()) {
        "high"
    } else if dead_letter_size > 0 || outbox_threshold_breached {
        "medium"
    } else if outbox_size > 0 {
        "low"
    } else {
        "none"
    };

    let recommended_action = if replay_active {
        "wait_for_active_replay"
    } else if dead_letter_size == 0 && outbox_size == 0 {
        "none"
    } else if failure_streak_threshold_breached {
        "pause_and_investigate"
    } else if handoff_stale {
        "escalate_stale_handoff"
    } else if dead_letter_size > 0 && replay_handoff.is_none() {
        "claim_handoff"
    } else if dead_letter_size > 0 && cooldown_active {
        "wait_or_force_replay"
    } else if dead_letter_size > 0 {
        "run_replay"
    } else {
        "monitor_recovery_worker"
    };
    let fingerprint = build_dead_letter_runbook_fingerprint(
        outbox_size,
        dead_letter_size,
        severity,
        recommended_action,
        &reasons,
        consecutive_failures,
        handoff_stale,
    );

    json!({
        "claimed": replay_handoff.is_some(),
        "cooldown_force_required": cooldown_active,
        "severity": severity,
        "recommended_action": recommended_action,
        "escalate": severity == "critical" || handoff_stale,
        "reasons": reasons,
        "fingerprint": fingerprint,
        "handoff_stale": handoff_stale,
        "handoff_age_ms": handoff_age_ms,
        "consecutive_failures": consecutive_failures,
        "failure_streak_threshold": failure_streak_threshold,
        "dead_letter_error_class_alert_active": dead_letter_error_class_alert_active,
        "dead_letter_error_class_sample_size": dead_letter_error_summary
            .map(|summary| summary.sample_size)
            .unwrap_or(0),
        "dominant_dead_letter_error_class": dominant_dead_letter_error_class,
        "dominant_dead_letter_error_count": dominant_dead_letter_error_count,
        "investigation_hint": dominant_dead_letter_error_class
            .and_then(submit_materialization_failure_investigation_hint),
    })
}

fn push_ops_alert(
    alerts: &mut Vec<serde_json::Value>,
    key: &'static str,
    severity: &str,
    summary: String,
    labels: BTreeMap<String, String>,
    annotations: BTreeMap<String, String>,
) {
    let fingerprint = build_ops_alert_fingerprint(key, severity, &labels, &annotations);
    alerts.push(json!({
        "key": key,
        "severity": severity,
        "summary": summary,
        "fingerprint": fingerprint,
        "labels": labels,
        "annotations": annotations,
    }));
}

fn build_ops_alerts<DB>(
    state: &AppState<DB>,
    ready_evaluation: &ReadyEvaluation,
    ready_slo: &ReadySloSnapshot,
    snapshot: &DeadLetterOpsSnapshot,
) -> Vec<serde_json::Value>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut alerts = Vec::new();
    let runtime_backend = if state.config.redis_url.is_some() && state.config.nats_url.is_some() {
        "redis+nats"
    } else {
        "in-memory"
    };
    let runbook_severity = snapshot
        .runbook_summary
        .get("severity")
        .and_then(|value| value.as_str())
        .unwrap_or("high");
    let recommended_action = snapshot
        .runbook_summary
        .get("recommended_action")
        .and_then(|value| value.as_str())
        .unwrap_or("none");
    let investigation_hint = snapshot
        .runbook_summary
        .get("investigation_hint")
        .and_then(|value| value.as_str());

    if let Some(severity) = ready_slo_alert_severity(&state.config, ready_slo) {
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "readiness".to_string()),
            ("alert_type".to_string(), "ready_slo_burn_rate".to_string()),
            ("target_bps".to_string(), ready_slo.target_bps.to_string()),
        ]);
        let annotations = BTreeMap::from([
            (
                "short_window_burn_rate_milli".to_string(),
                ready_slo.short_window.burn_rate_milli.to_string(),
            ),
            (
                "short_window_availability_bps".to_string(),
                ready_slo.short_window.availability_bps.to_string(),
            ),
            (
                "long_window_burn_rate_milli".to_string(),
                ready_slo.long_window.burn_rate_milli.to_string(),
            ),
            (
                "long_window_availability_bps".to_string(),
                ready_slo.long_window.availability_bps.to_string(),
            ),
        ]);
        push_ops_alert(
            &mut alerts,
            "channel_ready_slo_burn_rate",
            severity,
            format!(
                "channel ready SLO burn rate exceeded thresholds: short={} long={} target_bps={}",
                ready_slo.short_window.burn_rate_milli,
                ready_slo.long_window.burn_rate_milli,
                ready_slo.target_bps
            ),
            labels,
            annotations,
        );
    }

    if ready_evaluation.runtime_drill_active {
        let kind = ready_evaluation
            .runtime_drill_kind
            .as_deref()
            .unwrap_or("unknown");
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "runtime".to_string()),
            ("alert_type".to_string(), "runtime_drill".to_string()),
            ("kind".to_string(), kind.to_string()),
            (
                "operator".to_string(),
                ready_evaluation
                    .runtime_drill_operator
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
        ]);
        let mut annotations = BTreeMap::from([(
            "degrades_ready".to_string(),
            ready_evaluation.runtime_drill_degrades_ready.to_string(),
        )]);
        if let Some(reason) = ready_evaluation.runtime_drill_reason.clone() {
            annotations.insert("reason".to_string(), reason);
        }
        push_ops_alert(
            &mut alerts,
            "runtime_drill_active",
            ops_runtime_drill_severity(kind),
            format!("runtime drill is active: kind={}", kind),
            labels,
            annotations,
        );
    }

    if ready_evaluation.runtime_profile_active {
        let profile = ready_evaluation
            .runtime_profile_name
            .as_deref()
            .unwrap_or("unknown");
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "runtime".to_string()),
            ("alert_type".to_string(), "runtime_profile".to_string()),
            ("profile".to_string(), profile.to_string()),
            (
                "operator".to_string(),
                ready_evaluation
                    .runtime_profile_operator
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
        ]);
        let mut annotations = BTreeMap::new();
        if let Some(reason) = ready_evaluation.runtime_profile_reason.clone() {
            annotations.insert("reason".to_string(), reason);
        }
        push_ops_alert(
            &mut alerts,
            "runtime_profile_active",
            ops_runtime_profile_severity(profile),
            format!("runtime profile is active: profile={}", profile),
            labels,
            annotations,
        );
    }

    if ready_evaluation.runtime_rollout_active {
        let phase = ready_evaluation
            .runtime_rollout_phase
            .as_deref()
            .unwrap_or("unknown");
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "runtime".to_string()),
            ("alert_type".to_string(), "runtime_rollout".to_string()),
            ("phase".to_string(), phase.to_string()),
            (
                "target_profile".to_string(),
                ready_evaluation
                    .runtime_rollout_target_profile
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
            (
                "operator".to_string(),
                ready_evaluation
                    .runtime_rollout_operator
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
        ]);
        let mut annotations = BTreeMap::from([
            (
                "matches_target_profile".to_string(),
                ready_evaluation
                    .runtime_rollout_matches_target_profile
                    .to_string(),
            ),
            (
                "target_matches_effective".to_string(),
                ready_evaluation
                    .runtime_rollout_target_matches_effective
                    .to_string(),
            ),
        ]);
        if let Some(reason) = ready_evaluation.runtime_rollout_reason.clone() {
            annotations.insert("reason".to_string(), reason);
        }
        push_ops_alert(
            &mut alerts,
            "runtime_rollout_active",
            ops_runtime_rollout_severity(phase),
            format!("runtime rollout is active: phase={}", phase),
            labels,
            annotations,
        );
    }

    if ready_evaluation.realtime_gate_disabled {
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "realtime".to_string()),
            (
                "alert_type".to_string(),
                "realtime_gate_disabled".to_string(),
            ),
            (
                "operator".to_string(),
                ready_evaluation
                    .realtime_gate_operator
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
        ]);
        let mut annotations = BTreeMap::new();
        if let Some(reason) = ready_evaluation.realtime_gate_reason.clone() {
            annotations.insert("reason".to_string(), reason);
        }
        push_ops_alert(
            &mut alerts,
            "runtime_realtime_gate_disabled",
            "high",
            "runtime realtime gate is disabled; new subscriptions are blocked".to_string(),
            labels,
            annotations,
        );
    }

    if ready_evaluation.realtime_consumer_pressure_active {
        let mut labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "realtime".to_string()),
            ("alert_type".to_string(), "consumer_pressure".to_string()),
            (
                "scope".to_string(),
                ready_evaluation
                    .realtime_consumer_pressure_scope
                    .clone()
                    .unwrap_or_else(|| "local".to_string()),
            ),
        ]);
        labels.insert(
            "recent_lagged_messages".to_string(),
            ready_evaluation.realtime_recent_lagged_messages.to_string(),
        );
        labels.insert(
            "recent_slow_consumer_disconnects".to_string(),
            ready_evaluation
                .realtime_recent_slow_consumer_disconnects
                .to_string(),
        );
        let mut annotations = BTreeMap::from([
            (
                "window_ms".to_string(),
                REALTIME_CONSUMER_PRESSURE_WINDOW_MS.to_string(),
            ),
            (
                "lagged_messages_total".to_string(),
                ready_evaluation.realtime_lagged_messages_total.to_string(),
            ),
            (
                "slow_consumer_disconnects_total".to_string(),
                ready_evaluation
                    .realtime_slow_consumer_disconnects_total
                    .to_string(),
            ),
            (
                "active_instances".to_string(),
                ready_evaluation
                    .realtime_consumer_pressure_active_instances
                    .to_string(),
            ),
        ]);
        if let Some(last_lagged_message_at_ms) = ready_evaluation.realtime_last_lagged_message_at_ms
        {
            annotations.insert(
                "last_lagged_message_at_ms".to_string(),
                last_lagged_message_at_ms.to_string(),
            );
        }
        if let Some(last_slow_consumer_disconnect_at_ms) =
            ready_evaluation.realtime_last_slow_consumer_disconnect_at_ms
        {
            annotations.insert(
                "last_slow_consumer_disconnect_at_ms".to_string(),
                last_slow_consumer_disconnect_at_ms.to_string(),
            );
        }
        push_ops_alert(
            &mut alerts,
            "channel_realtime_consumer_pressure",
            ready_evaluation
                .realtime_consumer_pressure_severity
                .as_deref()
                .unwrap_or("medium"),
            if ready_evaluation.realtime_recent_slow_consumer_disconnects {
                "recent realtime slow-consumer disconnect activity detected".to_string()
            } else {
                "recent realtime lagged-message pressure detected".to_string()
            },
            labels,
            annotations,
        );
    }

    if ready_evaluation.write_gate_disabled {
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            ("component".to_string(), "runtime".to_string()),
            ("alert_type".to_string(), "write_gate_disabled".to_string()),
            (
                "operator".to_string(),
                ready_evaluation
                    .write_gate_operator
                    .clone()
                    .unwrap_or_else(|| "unknown".to_string()),
            ),
        ]);
        let mut annotations = BTreeMap::new();
        if let Some(reason) = ready_evaluation.write_gate_reason.clone() {
            annotations.insert("reason".to_string(), reason);
        }
        push_ops_alert(
            &mut alerts,
            "runtime_write_gate_disabled",
            "high",
            "runtime write gate is disabled; write traffic is blocked".to_string(),
            labels,
            annotations,
        );
    }

    if ready_evaluation.outbox_alert_active {
        let mut labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            (
                "component".to_string(),
                "submit_materialization".to_string(),
            ),
            ("alert_type".to_string(), "outbox_backlog".to_string()),
            ("runtime_backend".to_string(), runtime_backend.to_string()),
        ]);
        labels.insert(
            "threshold".to_string(),
            state
                .config
                .submit_materialization_ready_max_outbox_size
                .to_string(),
        );
        let annotations = BTreeMap::from([
            ("outbox_size".to_string(), snapshot.outbox_size.to_string()),
            (
                "recommended_action".to_string(),
                "drain_outbox_and_check_recovery_worker".to_string(),
            ),
        ]);
        push_ops_alert(
            &mut alerts,
            "submit_materialization_outbox_backlog",
            "high",
            format!(
                "submit materialization outbox backlog exceeded threshold: size={} threshold={}",
                snapshot.outbox_size, state.config.submit_materialization_ready_max_outbox_size
            ),
            labels,
            annotations,
        );
    }

    if ready_evaluation.dead_letter_alert_active {
        let mut labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            (
                "component".to_string(),
                "submit_materialization".to_string(),
            ),
            ("alert_type".to_string(), "dead_letter_backlog".to_string()),
            ("runtime_backend".to_string(), runtime_backend.to_string()),
        ]);
        labels.insert(
            "threshold".to_string(),
            state
                .config
                .submit_materialization_ready_max_dead_letter_size
                .to_string(),
        );
        let annotations = BTreeMap::from([
            (
                "dead_letter_size".to_string(),
                snapshot.dead_letter_size.to_string(),
            ),
            (
                "recommended_action".to_string(),
                recommended_action.to_string(),
            ),
        ]);
        push_ops_alert(
            &mut alerts,
            "submit_materialization_dead_letter_backlog",
            runbook_severity,
            format!(
                "submit materialization dead-letter backlog exceeded threshold: size={} threshold={}",
                snapshot.dead_letter_size,
                state.config.submit_materialization_ready_max_dead_letter_size
            ),
            labels,
            annotations,
        );
    }

    if ready_evaluation.dead_letter_error_class_alert_active {
        let dominant_error_class = ready_evaluation
            .dead_letter_dominant_error_class
            .as_deref()
            .unwrap_or("unknown");
        let mut labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            (
                "component".to_string(),
                "submit_materialization".to_string(),
            ),
            (
                "alert_type".to_string(),
                "dead_letter_error_class".to_string(),
            ),
            (
                "dominant_error_class".to_string(),
                dominant_error_class.to_string(),
            ),
        ]);
        if let Some(hint) = investigation_hint {
            labels.insert("investigation_hint".to_string(), hint.to_string());
        }
        let mut annotations = BTreeMap::from([
            (
                "sample_size".to_string(),
                snapshot.dead_letter_error_summary.sample_size.to_string(),
            ),
            (
                "dominant_count".to_string(),
                snapshot
                    .dead_letter_error_summary
                    .dominant_count
                    .to_string(),
            ),
            (
                "recommended_action".to_string(),
                recommended_action.to_string(),
            ),
        ]);
        if let Some(hint) = investigation_hint {
            annotations.insert("investigation_hint".to_string(), hint.to_string());
        }
        push_ops_alert(
            &mut alerts,
            "submit_materialization_dead_letter_dominant_error_class",
            runbook_severity,
            format!(
                "submit materialization dominant dead-letter failure class is {} (sample_count={} sample_size={})",
                dominant_error_class,
                snapshot.dead_letter_error_summary.dominant_count,
                snapshot.dead_letter_error_summary.sample_size
            ),
            labels,
            annotations,
        );
    }

    if ready_evaluation.dead_letter_replay_internal_alert_active {
        let replay_error_class = snapshot
            .replay_status
            .as_ref()
            .and_then(|status| status.last_error_class.as_deref())
            .unwrap_or("replay_status_unavailable");
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            (
                "component".to_string(),
                "submit_materialization".to_string(),
            ),
            (
                "alert_type".to_string(),
                "dead_letter_replay_internal".to_string(),
            ),
            ("error_class".to_string(), replay_error_class.to_string()),
        ]);
        let annotations = BTreeMap::from([
            (
                "recommended_action".to_string(),
                recommended_action.to_string(),
            ),
            (
                "dead_letter_size".to_string(),
                snapshot.dead_letter_size.to_string(),
            ),
        ]);
        push_ops_alert(
            &mut alerts,
            "submit_materialization_dead_letter_replay_internal",
            "critical",
            format!(
                "submit materialization dead-letter replay internal dependency failure is active: error_class={}",
                replay_error_class
            ),
            labels,
            annotations,
        );
    }

    if snapshot
        .runbook_summary
        .get("notification_required")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
    {
        let labels = BTreeMap::from([
            ("service".to_string(), "dubhe-channel".to_string()),
            (
                "component".to_string(),
                "submit_materialization".to_string(),
            ),
            ("alert_type".to_string(), "escalation_required".to_string()),
            ("severity".to_string(), runbook_severity.to_string()),
        ]);
        let mut annotations = BTreeMap::from([
            (
                "recommended_action".to_string(),
                recommended_action.to_string(),
            ),
            (
                "runbook_fingerprint".to_string(),
                snapshot
                    .runbook_summary
                    .get("fingerprint")
                    .and_then(|value| value.as_str())
                    .unwrap_or_default()
                    .to_string(),
            ),
        ]);
        if let Some(reason) = snapshot.replay_policy_block_reason {
            annotations.insert("replay_block_reason".to_string(), reason.to_string());
        }
        push_ops_alert(
            &mut alerts,
            "submit_materialization_dead_letter_escalation_required",
            runbook_severity,
            "submit materialization incident requires escalation notification".to_string(),
            labels,
            annotations,
        );
    }

    alerts
}

fn build_ops_objectives(
    config: &DubheChannelConfig,
    ready_evaluation: &ReadyEvaluation,
    ready_slo: &ReadySloSnapshot,
    snapshot: &DeadLetterOpsSnapshot,
) -> Vec<serde_json::Value> {
    let channel_ready_reason = if ready_evaluation.reasons.is_empty() {
        serde_json::Value::Null
    } else {
        serde_json::Value::String(ready_evaluation.reasons.join("; "))
    };
    let materialization_degraded = snapshot.outbox_size > 0
        || snapshot.dead_letter_size > 0
        || ready_evaluation.dead_letter_error_class_alert_active
        || ready_evaluation.dead_letter_replay_internal_alert_active;
    let materialization_reason = if !materialization_degraded {
        serde_json::Value::Null
    } else {
        serde_json::Value::String(
            snapshot
                .runbook_summary
                .get("recommended_action")
                .and_then(|value| value.as_str())
                .unwrap_or("monitor_recovery_worker")
                .to_string(),
        )
    };
    let ready_slo_severity = ready_slo_alert_severity(config, ready_slo);
    let ready_slo_reason = ready_slo_severity.map_or(serde_json::Value::Null, |_| {
        serde_json::Value::String(format!(
            "short_burn_rate_milli={} long_burn_rate_milli={}",
            ready_slo.short_window.burn_rate_milli, ready_slo.long_window.burn_rate_milli
        ))
    });
    let runtime_drill_reason = if ready_evaluation.runtime_drill_active {
        serde_json::Value::String(
            ready_evaluation
                .runtime_drill_kind
                .clone()
                .unwrap_or_else(|| "unknown".to_string()),
        )
    } else {
        serde_json::Value::Null
    };
    let runtime_profile_reason = if ready_evaluation.runtime_profile_active {
        serde_json::Value::String(
            ready_evaluation
                .runtime_profile_name
                .clone()
                .unwrap_or_else(|| "unknown".to_string()),
        )
    } else {
        serde_json::Value::Null
    };
    let runtime_rollout_reason = if ready_evaluation.runtime_rollout_active {
        serde_json::Value::String(format!(
            "phase={} target_profile={} matches_target_profile={} target_matches_effective={}",
            ready_evaluation
                .runtime_rollout_phase
                .as_deref()
                .unwrap_or("unknown"),
            ready_evaluation
                .runtime_rollout_target_profile
                .as_deref()
                .unwrap_or("unknown"),
            ready_evaluation.runtime_rollout_matches_target_profile,
            ready_evaluation.runtime_rollout_target_matches_effective,
        ))
    } else {
        serde_json::Value::Null
    };
    let realtime_consumer_pressure_reason = if ready_evaluation.realtime_consumer_pressure_active {
        serde_json::Value::String(format!(
            "scope={} active_instances={} last_lagged_message_at_ms={} last_slow_consumer_disconnect_at_ms={}",
            ready_evaluation
                .realtime_consumer_pressure_scope
                .as_deref()
                .unwrap_or("local"),
            ready_evaluation.realtime_consumer_pressure_active_instances,
            ready_evaluation
                .realtime_last_lagged_message_at_ms
                .map(|value| value.to_string())
                .unwrap_or_else(|| "none".to_string()),
            ready_evaluation
                .realtime_last_slow_consumer_disconnect_at_ms
                .map(|value| value.to_string())
                .unwrap_or_else(|| "none".to_string()),
        ))
    } else {
        serde_json::Value::Null
    };

    vec![
        json!({
            "key": "channel_ready",
            "status": if ready_evaluation.ready { "healthy" } else { "degraded" },
            "severity": if ready_evaluation.ready { "none" } else { "critical" },
            "reason": channel_ready_reason,
        }),
        json!({
            "key": "ops_runtime_drill",
            "status": if ready_evaluation.runtime_drill_active { "degraded" } else { "healthy" },
            "severity": if ready_evaluation.runtime_drill_active {
                ops_runtime_drill_severity(
                    ready_evaluation
                        .runtime_drill_kind
                        .as_deref()
                        .unwrap_or("unknown")
                )
            } else {
                "none"
            },
            "reason": runtime_drill_reason,
        }),
        json!({
            "key": "ops_runtime_profile",
            "status": if ready_evaluation.runtime_profile_active { "degraded" } else { "healthy" },
            "severity": if ready_evaluation.runtime_profile_active {
                ops_runtime_profile_severity(
                    ready_evaluation
                        .runtime_profile_name
                        .as_deref()
                        .unwrap_or("unknown")
                )
            } else {
                "none"
            },
            "reason": runtime_profile_reason,
        }),
        json!({
            "key": "ops_runtime_rollout",
            "status": if ready_evaluation.runtime_rollout_active { "degraded" } else { "healthy" },
            "severity": if ready_evaluation.runtime_rollout_active {
                ops_runtime_rollout_severity(
                    ready_evaluation
                        .runtime_rollout_phase
                        .as_deref()
                        .unwrap_or("unknown")
                )
            } else {
                "none"
            },
            "reason": runtime_rollout_reason,
        }),
        json!({
            "key": "channel_realtime_path",
            "status": if ready_evaluation.realtime_gate_disabled { "degraded" } else { "healthy" },
            "severity": if ready_evaluation.realtime_gate_disabled { "high" } else { "none" },
            "reason": if ready_evaluation.realtime_gate_disabled {
                serde_json::Value::String("realtime_gate_disabled".to_string())
            } else {
                serde_json::Value::Null
            },
        }),
        json!({
            "key": "channel_realtime_consumers",
            "status": if ready_evaluation.realtime_consumer_pressure_active { "degraded" } else { "healthy" },
            "severity": ready_evaluation.realtime_consumer_pressure_severity.as_deref().unwrap_or("none"),
            "reason": realtime_consumer_pressure_reason,
        }),
        json!({
            "key": "channel_write_path",
            "status": if ready_evaluation.write_gate_disabled { "degraded" } else { "healthy" },
            "severity": if ready_evaluation.write_gate_disabled { "high" } else { "none" },
            "reason": if ready_evaluation.write_gate_disabled {
                serde_json::Value::String("write_gate_disabled".to_string())
            } else {
                serde_json::Value::Null
            },
        }),
        json!({
            "key": "submit_materialization_recovery",
            "status": if materialization_degraded { "degraded" } else { "healthy" },
            "severity": snapshot.runbook_summary.get("severity").and_then(|value| value.as_str()).unwrap_or("none"),
            "reason": materialization_reason,
        }),
        json!({
            "key": "channel_ready_slo",
            "status": if ready_slo_severity.is_some() { "degraded" } else { "healthy" },
            "severity": ready_slo_severity.unwrap_or("none"),
            "reason": ready_slo_reason,
        }),
    ]
}

fn build_ops_alert_feed<DB>(
    state: &AppState<DB>,
    ready_evaluation: ReadyEvaluation,
    ready_slo: &ReadySloSnapshot,
    snapshot: &DeadLetterOpsSnapshot,
) -> OpsAlertFeed
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let alerts = build_ops_alerts(state, &ready_evaluation, ready_slo, snapshot);
    let objectives = build_ops_objectives(&state.config, &ready_evaluation, ready_slo, snapshot);
    let highest_severity = alerts
        .iter()
        .filter_map(|alert| alert.get("severity").and_then(|value| value.as_str()))
        .max_by_key(|severity| severity_rank(severity))
        .unwrap_or("none")
        .to_string();
    let generated_at_ms = now_ts_ms();
    let fingerprint_payload = json!({
        "ready": ready_evaluation.ready,
        "objectives": objectives.clone(),
        "alerts": alerts.clone(),
    })
    .to_string();
    let mut hasher = Sha256::new();
    hasher.update(fingerprint_payload.as_bytes());
    let fingerprint = format!("{:x}", hasher.finalize());

    OpsAlertFeed {
        generated_at_ms,
        ready_evaluation,
        objectives,
        alerts,
        highest_severity,
        fingerprint,
    }
}

fn update_ops_alert_metrics(metrics: &AppMetrics, alerts: &[serde_json::Value]) {
    metrics
        .ops_active_alerts_total
        .store(alerts.len() as u64, Ordering::Relaxed);
    metrics.ops_critical_alerts_total.store(
        alerts
            .iter()
            .filter(|alert| {
                alert
                    .get("severity")
                    .and_then(|value| value.as_str())
                    .map(|severity| severity_rank(severity) >= severity_rank("critical"))
                    .unwrap_or(false)
            })
            .count() as u64,
        Ordering::Relaxed,
    );
    metrics.ops_ready_slo_warning_alert_active.store(
        u64::from(alerts.iter().any(|alert| {
            alert["key"] == "channel_ready_slo_burn_rate" && alert["severity"] == "high"
        })),
        Ordering::Relaxed,
    );
    metrics.ops_ready_slo_critical_alert_active.store(
        u64::from(alerts.iter().any(|alert| {
            alert["key"] == "channel_ready_slo_burn_rate" && alert["severity"] == "critical"
        })),
        Ordering::Relaxed,
    );
}

fn ops_alert_delivery_backoff_ms(config: &DubheChannelConfig, attempts: u64) -> u64 {
    let initial = config.ops_alert_delivery_retry_initial_ms.max(1);
    let max_backoff = config.ops_alert_delivery_retry_max_ms.max(initial);
    let exponent = attempts.saturating_sub(1).min(16);
    initial.saturating_mul(1_u64 << exponent).min(max_backoff)
}

fn ops_runtime_rollout_delivery_backoff_ms(config: &DubheChannelConfig, attempts: u64) -> u64 {
    let initial = config.ops_runtime_rollout_delivery_retry_initial_ms.max(1);
    let max_backoff = config
        .ops_runtime_rollout_delivery_retry_max_ms
        .max(initial);
    let exponent = attempts.saturating_sub(1).min(16);
    initial.saturating_mul(1_u64 << exponent).min(max_backoff)
}

fn ops_runtime_rollout_action_redispatch_backoff_ms(
    config: &DubheChannelConfig,
    attempts: u64,
) -> u64 {
    let initial = config
        .ops_runtime_rollout_action_redispatch_retry_initial_ms
        .max(1);
    let max_backoff = config
        .ops_runtime_rollout_action_redispatch_retry_max_ms
        .max(initial);
    let exponent = attempts.saturating_sub(1).min(16);
    initial.saturating_mul(1_u64 << exponent).min(max_backoff)
}

fn build_ops_alert_delivery_payload(feed: &OpsAlertFeed) -> serde_json::Value {
    let critical_alerts = feed
        .alerts
        .iter()
        .filter(|alert| {
            alert
                .get("severity")
                .and_then(|value| value.as_str())
                .map(|severity| severity_rank(severity) >= severity_rank("critical"))
                .unwrap_or(false)
        })
        .count();
    json!({
        "generated_at_ms": feed.generated_at_ms,
        "ready": feed.ready_evaluation.ready,
        "summary": {
            "active_alerts": feed.alerts.len(),
            "critical_alerts": critical_alerts,
            "highest_severity": feed.highest_severity,
            "fingerprint": feed.fingerprint,
        },
        "objectives": feed.objectives,
        "alerts": feed.alerts,
    })
}

fn build_ops_runtime_rollout_delivery_payload(
    feed: &OpsRuntimeRolloutDeliveryFeed,
    receipt_state: Option<&OpsRuntimeRolloutReceiptState>,
    history_limit: usize,
    config: &DubheChannelConfig,
) -> serde_json::Value {
    json!({
        "event_type": "runtime_rollout",
        "generated_at_ms": feed.generated_at_ms,
        "source": feed.source,
        "summary": {
            "active": feed.rollout_state.active,
            "phase": feed.rollout_state.phase,
            "severity": ops_runtime_rollout_severity(&feed.rollout_state.phase),
            "target_profile": feed.rollout_state.target_profile,
            "recommended_action": feed.checklist.recommended_action,
            "can_proceed": feed.checklist.can_proceed,
            "next_suggested_phase": feed.checklist.next_suggested_phase,
            "blocked_reasons": feed.checklist.blocked_reasons,
            "fingerprint": feed.fingerprint,
        },
        "runtime_rollout": runtime_rollout_state_to_json(
            &feed.rollout_state,
            feed.checklist.matches_target_profile,
            feed.checklist.target_matches_effective,
            history_limit,
        ),
        "receipt": receipt_state.map_or_else(
            || json!({ "active": false }),
            |receipt_state| {
                rollout_receipt_state_to_json(
                    receipt_state,
                    Some(feed.rollout_state.request_id.as_str()),
                    config.ops_runtime_rollout_receipt_pending_timeout_ms,
                )
            }
        ),
        "approval": feed.checklist.approval_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |approval_state| {
                rollout_approval_state_to_json(
                    approval_state,
                    Some(feed.rollout_state.request_id.as_str()),
                )
            }
        ),
        "traffic": feed.checklist.traffic_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |traffic_state| {
                rollout_traffic_state_to_json(
                    traffic_state,
                    Some(feed.rollout_state.request_id.as_str()),
                )
            }
        ),
        "traffic_receipt": feed.checklist.traffic_receipt_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |traffic_receipt_state| {
                rollout_traffic_receipt_state_to_json(
                    traffic_receipt_state,
                    Some(feed.rollout_state.request_id.as_str()),
                    config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                )
            }
        ),
        "rollout_checklist": runtime_rollout_checklist_to_json(&feed.checklist, history_limit),
        "history_entry": feed.history_entry,
    })
}

fn build_ops_runtime_rollout_action_payload(
    feed: &OpsRuntimeRolloutActionFeed,
    history_limit: usize,
    config: &DubheChannelConfig,
    dispatch_state: &OpsAlertDispatchState,
    action_status: &OpsRuntimeRolloutActionStatusSnapshot,
) -> serde_json::Value {
    let known_rollout =
        feed.rollout_state.updated_at_ms > 0 || feed.rollout_state.request_id != "default";
    let action = match feed.adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => json!({
            "kind": "deploy",
            "available": known_rollout,
            "active": feed.rollout_state.active,
            "request_id": feed.rollout_state.request_id,
            "rollout_request_id": feed.rollout_state.request_id,
            "phase": feed.rollout_state.phase,
            "target_profile": feed.rollout_state.target_profile,
            "baseline_profile": feed.rollout_state.baseline_profile,
            "operator": feed.rollout_state.operator,
            "reason": feed.rollout_state.reason,
            "apply_target_profile": feed
                .history_entry
                .as_ref()
                .map(|entry| entry.apply_target_profile)
                .unwrap_or(false),
            "recommended_action": feed.checklist.recommended_action,
            "can_proceed": feed.checklist.can_proceed,
            "next_suggested_phase": feed.checklist.next_suggested_phase,
            "matches_target_profile": feed.checklist.matches_target_profile,
            "target_matches_effective": feed.checklist.target_matches_effective,
        }),
        OpsRuntimeRolloutActionAdapterKind::Traffic => {
            let traffic_state = feed.checklist.traffic_state.as_ref();
            let matches_current_rollout = traffic_state
                .map(|traffic_state| {
                    traffic_state.rollout_request_id == feed.rollout_state.request_id
                })
                .unwrap_or(false);
            json!({
                "kind": "traffic",
                "available": traffic_state.is_some() && matches_current_rollout,
                "active": traffic_state.is_some() && matches_current_rollout,
                "rollout_request_id": feed.rollout_state.request_id,
                "phase": feed.rollout_state.phase,
                "target_profile": feed.rollout_state.target_profile,
                "traffic_request_id": traffic_state.map(|traffic_state| traffic_state.traffic_request_id.clone()),
                "stage": traffic_state.map(|traffic_state| traffic_state.stage.clone()),
                "canary_percent": traffic_state.map(|traffic_state| traffic_state.canary_percent),
                "stable_percent": traffic_state.map(|traffic_state| traffic_state.stable_percent),
                "actor": traffic_state.map(|traffic_state| traffic_state.actor.clone()),
                "note": traffic_state.and_then(|traffic_state| traffic_state.note.clone()),
                "external_ref": traffic_state.and_then(|traffic_state| traffic_state.external_ref.clone()),
                "matches_current_rollout": matches_current_rollout,
                "recommended_action": feed.checklist.recommended_action,
                "can_proceed": feed.checklist.can_proceed,
            })
        }
    };

    let current_rollout_request_id = Some(feed.rollout_state.request_id.as_str());
    let current_fingerprint = action_status.current_fingerprint.as_deref();
    let callback_token = runtime_rollout_action_callback_token_for_feed(config, feed);
    let current_action_dispatched_at_ms = if action_status.dispatched_current_action {
        dispatch_state.last_success_at_ms
    } else {
        None
    };
    let ack_matches_current_action = action_status
        .ack_state
        .as_ref()
        .map(|ack_state| {
            rollout_action_ack_matches_current_action(
                ack_state,
                feed.adapter,
                current_fingerprint,
                current_rollout_request_id,
                current_action_dispatched_at_ms,
            )
        })
        .unwrap_or(false);
    let execution_matches_current_action = action_status
        .execution_state
        .as_ref()
        .map(|execution_state| {
            rollout_action_execution_matches_current_action(
                execution_state,
                feed.adapter,
                current_fingerprint,
                current_rollout_request_id,
            )
        })
        .unwrap_or(false);
    let current_ack = action_status
        .ack_state
        .as_ref()
        .filter(|_| ack_matches_current_action)
        .map_or_else(
            || json!({ "active": false }),
            |ack_state| {
                rollout_action_ack_state_to_json(
                    ack_state,
                    current_fingerprint,
                    current_rollout_request_id,
                )
            },
        );
    let current_execution = action_status
        .execution_state
        .as_ref()
        .filter(|_| execution_matches_current_action)
        .map_or_else(
            || json!({ "active": false }),
            |execution_state| {
                rollout_action_execution_state_to_json(
                    execution_state,
                    current_fingerprint,
                    current_rollout_request_id,
                    action_status.execution_timeout_ms,
                )
            },
        );
    let source_is_redispatch = feed.source.contains("redispatch");
    let takeover_reason = if action_status.execution_timed_out {
        Some("action_execution_timeout")
    } else if action_status.ack_timed_out {
        Some("action_ack_timeout")
    } else if execution_matches_current_action {
        Some("execution_owner_present")
    } else if source_is_redispatch || action_status.redispatch_attempts > 0 {
        Some("redispatch_retry")
    } else {
        None
    };
    let takeover_expected = takeover_reason.is_some();

    json!({
        "event_type": "runtime_rollout_action",
        "adapter": feed.adapter.as_str(),
        "generated_at_ms": feed.generated_at_ms,
        "source": feed.source,
        "summary": {
            "adapter": feed.adapter.as_str(),
            "phase": feed.rollout_state.phase,
            "target_profile": feed.rollout_state.target_profile,
            "recommended_action": feed.checklist.recommended_action,
            "can_proceed": feed.checklist.can_proceed,
            "fingerprint": feed.fingerprint,
        },
        "callbacks": {
            "ack_path": ops_runtime_rollout_action_ack_path(feed.adapter),
            "receipt_path": ops_runtime_rollout_action_receipt_path(feed.adapter),
            "admin_token_header": OPS_ADMIN_TOKEN_HEADER,
            "request_id_header": REQUEST_ID_HEADER,
            "callback_token_header": OPS_ACTION_CALLBACK_TOKEN_HEADER,
            "callback_token": callback_token,
            "ack_timeout_ms": config.ops_runtime_rollout_action_ack_timeout_ms,
            "execution_timeout_ms": action_status.execution_timeout_ms,
        },
        "execution_contract": {
            "active": true,
            "receiver_must_ack_before_execution": true,
            "receipt_required": true,
            "receipt_requires_execution_request_id": true,
            "receipt_rejects_stale_execution_request_id": true,
            "ack_timeout_ms": config.ops_runtime_rollout_action_ack_timeout_ms,
            "execution_timeout_ms": action_status.execution_timeout_ms,
            "current_ack": current_ack,
            "current_execution": current_execution,
            "takeover": {
                "expected": takeover_expected,
                "source_is_redispatch": source_is_redispatch,
                "reason": takeover_reason,
                "redispatch_attempts": action_status.redispatch_attempts,
                "redispatch_remaining_attempts": action_status.redispatch_remaining_attempts,
                "last_request_id": dispatch_state.last_redispatch_request_id,
                "last_source": dispatch_state.last_redispatch_source,
                "last_reason": dispatch_state.last_redispatch_reason,
                "last_redispatch_at_ms": dispatch_state.last_redispatch_at_ms,
            },
        },
        "action": action,
        "runtime_rollout": runtime_rollout_state_to_json(
            &feed.rollout_state,
            feed.checklist.matches_target_profile,
            feed.checklist.target_matches_effective,
            history_limit,
        ),
        "receipt": feed.checklist.receipt_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |receipt_state| {
                rollout_receipt_state_to_json(
                    receipt_state,
                    Some(feed.rollout_state.request_id.as_str()),
                    config.ops_runtime_rollout_receipt_pending_timeout_ms,
                )
            }
        ),
        "approval": feed.checklist.approval_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |approval_state| {
                rollout_approval_state_to_json(
                    approval_state,
                    Some(feed.rollout_state.request_id.as_str()),
                )
            }
        ),
        "traffic": feed.checklist.traffic_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |traffic_state| {
                rollout_traffic_state_to_json(
                    traffic_state,
                    Some(feed.rollout_state.request_id.as_str()),
                )
            }
        ),
        "traffic_receipt": feed.checklist.traffic_receipt_state.as_ref().map_or_else(
            || json!({ "active": false }),
            |traffic_receipt_state| {
                rollout_traffic_receipt_state_to_json(
                    traffic_receipt_state,
                    Some(feed.rollout_state.request_id.as_str()),
                    config.ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
                )
            }
        ),
        "rollout_checklist": runtime_rollout_checklist_to_json(&feed.checklist, history_limit),
        "history_entry": feed.history_entry,
    })
}

async fn build_ops_runtime_rollout_delivery_feed<DB>(
    state: &AppState<DB>,
    source: Option<&str>,
    history_entry: Option<&OpsRuntimeRolloutHistoryEntry>,
) -> Result<OpsRuntimeRolloutDeliveryFeed, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let rollout_state = current_ops_runtime_rollout_state(state).await?;
    let checklist = Box::pin(evaluate_runtime_rollout_checklist(
        state,
        rollout_state.clone(),
    ))
    .await?;
    let receipt_state = current_ops_runtime_rollout_receipt_state(state).await?;
    let history_entry = match history_entry.cloned() {
        Some(entry) => Some(entry),
        None => current_ops_runtime_rollout_history(state, 1)
            .await?
            .into_iter()
            .next(),
    };
    let generated_at_ms = now_ts_ms();
    let source = source
        .map(str::to_string)
        .or_else(|| history_entry.as_ref().map(|entry| entry.source.clone()))
        .unwrap_or_else(|| "dispatch".to_string());
    let fingerprint_payload = json!({
        "source": source,
        "runtime_rollout": runtime_rollout_state_to_json(
            &rollout_state,
            checklist.matches_target_profile,
            checklist.target_matches_effective,
            state.config.ops_runtime_rollout_history_limit,
        ),
        "recommended_action": checklist.recommended_action,
        "next_suggested_phase": checklist.next_suggested_phase,
        "blocked_reasons": checklist.blocked_reasons,
        "history_entry": history_entry,
        "receipt": receipt_state,
        "approval": checklist.approval_state.clone(),
        "traffic": checklist.traffic_state.clone(),
        "traffic_receipt": checklist.traffic_receipt_state.clone(),
    })
    .to_string();
    let mut hasher = Sha256::new();
    hasher.update(fingerprint_payload.as_bytes());
    let fingerprint = format!("{:x}", hasher.finalize());

    Ok(OpsRuntimeRolloutDeliveryFeed {
        generated_at_ms,
        source,
        rollout_state,
        checklist,
        history_entry,
        fingerprint,
    })
}

async fn build_ops_runtime_rollout_action_feed<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    source: Option<&str>,
    history_entry: Option<&OpsRuntimeRolloutHistoryEntry>,
) -> Result<OpsRuntimeRolloutActionFeed, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let rollout_state = current_ops_runtime_rollout_state(state).await?;
    let checklist = Box::pin(evaluate_runtime_rollout_checklist(
        state,
        rollout_state.clone(),
    ))
    .await?;
    let history_entry = match history_entry.cloned() {
        Some(entry) => Some(entry),
        None => current_ops_runtime_rollout_history(state, 1)
            .await?
            .into_iter()
            .next(),
    };
    let generated_at_ms = now_ts_ms();
    let source = source
        .map(str::to_string)
        .or_else(|| history_entry.as_ref().map(|entry| entry.source.clone()))
        .unwrap_or_else(|| "dispatch".to_string());
    let fingerprint_payload = match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => json!({
            "adapter": adapter.as_str(),
            "rollout_request_id": rollout_state.request_id,
            "phase": rollout_state.phase,
            "target_profile": rollout_state.target_profile,
            "baseline_profile": rollout_state.baseline_profile,
            "apply_target_profile": history_entry
                .as_ref()
                .map(|entry| entry.apply_target_profile)
                .unwrap_or(false),
        })
        .to_string(),
        OpsRuntimeRolloutActionAdapterKind::Traffic => {
            let traffic_state = checklist.traffic_state.as_ref();
            json!({
                "adapter": adapter.as_str(),
                "rollout_request_id": rollout_state.request_id,
                "phase": rollout_state.phase,
                "traffic_request_id": traffic_state.map(|traffic_state| traffic_state.traffic_request_id.clone()),
                "stage": traffic_state.map(|traffic_state| traffic_state.stage.clone()),
                "canary_percent": traffic_state.map(|traffic_state| traffic_state.canary_percent),
                "stable_percent": traffic_state.map(|traffic_state| traffic_state.stable_percent),
            })
            .to_string()
        }
    };
    let mut hasher = Sha256::new();
    hasher.update(fingerprint_payload.as_bytes());
    let fingerprint = format!("{:x}", hasher.finalize());

    Ok(OpsRuntimeRolloutActionFeed {
        generated_at_ms,
        adapter,
        source,
        rollout_state,
        checklist,
        history_entry,
        fingerprint,
    })
}

fn validate_ops_runtime_rollout_action_feed(
    feed: &OpsRuntimeRolloutActionFeed,
) -> Result<(), String> {
    let known_rollout =
        feed.rollout_state.updated_at_ms > 0 || feed.rollout_state.request_id != "default";
    match feed.adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => {
            if !known_rollout {
                Err("runtime rollout deploy action requires existing rollout state".to_string())
            } else {
                Ok(())
            }
        }
        OpsRuntimeRolloutActionAdapterKind::Traffic => match feed.checklist.traffic_state.as_ref() {
            Some(traffic_state)
                if traffic_state.rollout_request_id == feed.rollout_state.request_id =>
            {
                Ok(())
            }
            Some(_) => Err(
                "runtime rollout traffic action requires traffic state matching current rollout"
                    .to_string(),
            ),
            None => {
                Err("runtime rollout traffic action requires recorded traffic state".to_string())
            }
        },
    }
}

fn ops_runtime_rollout_action_ack_path(
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> &'static str {
    match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_ACK_PATH,
        OpsRuntimeRolloutActionAdapterKind::Traffic => OPS_RUNTIME_ROLLOUT_TRAFFIC_ACTION_ACK_PATH,
    }
}

fn ops_runtime_rollout_action_receipt_path(
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> &'static str {
    match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => OPS_RUNTIME_ROLLOUT_RECEIPT_PATH,
        OpsRuntimeRolloutActionAdapterKind::Traffic => OPS_RUNTIME_ROLLOUT_TRAFFIC_RECEIPT_PATH,
    }
}

fn normalize_ops_runtime_rollout_action_ack_status(status: String) -> Result<String, String> {
    match status.trim().to_ascii_lowercase().as_str() {
        "accepted" => Ok("accepted".to_string()),
        "rejected" => Ok("rejected".to_string()),
        _ => Err("action ack status must be one of: accepted, rejected".to_string()),
    }
}

fn validate_rollout_action_ack_state_transition(
    adapter: OpsRuntimeRolloutActionAdapterKind,
    current_ack_state: Option<&OpsRuntimeRolloutActionAckState>,
    next_ack_state: &OpsRuntimeRolloutActionAckState,
) -> Result<(), String> {
    let Some(current_ack_state) = current_ack_state else {
        return Ok(());
    };
    if current_ack_state.rollout_request_id != next_ack_state.rollout_request_id
        || current_ack_state.fingerprint != next_ack_state.fingerprint
    {
        return Ok(());
    }
    if current_ack_state.status != next_ack_state.status {
        return Err(format!(
            "runtime rollout {} action ack cannot change status from {} to {} for the current action",
            adapter.as_str(),
            current_ack_state.status,
            next_ack_state.status,
        ));
    }
    Ok(())
}

fn rollout_optional_string_matches(current: &Option<String>, next: &Option<String>) -> bool {
    current.as_deref() == next.as_deref()
}

fn rollout_action_ack_state_is_idempotent_replay(
    current_ack_state: &OpsRuntimeRolloutActionAckState,
    next_ack_state: &OpsRuntimeRolloutActionAckState,
) -> bool {
    current_ack_state.adapter == next_ack_state.adapter
        && current_ack_state.rollout_request_id == next_ack_state.rollout_request_id
        && current_ack_state.fingerprint == next_ack_state.fingerprint
        && current_ack_state.status == next_ack_state.status
        && current_ack_state.actor == next_ack_state.actor
        && rollout_optional_string_matches(&current_ack_state.note, &next_ack_state.note)
        && rollout_optional_string_matches(
            &current_ack_state.external_ref,
            &next_ack_state.external_ref,
        )
}

fn rollout_execution_receipt_status_transition_allowed(current: &str, next: &str) -> bool {
    match current {
        "acknowledged" => matches!(
            next,
            "acknowledged" | "in_progress" | "applied" | "completed" | "failed" | "rolled_back"
        ),
        "in_progress" => matches!(
            next,
            "in_progress" | "applied" | "completed" | "failed" | "rolled_back"
        ),
        "applied" => matches!(next, "applied" | "completed" | "failed" | "rolled_back"),
        "failed" => matches!(next, "failed" | "rolled_back"),
        "completed" => next == "completed",
        "rolled_back" => next == "rolled_back",
        _ => false,
    }
}

fn rollout_execution_receipt_targets_same_execution(
    current_rollout_request_id: &str,
    current_execution_request_id: Option<&str>,
    next_rollout_request_id: &str,
    next_execution_request_id: Option<&str>,
) -> bool {
    if current_rollout_request_id != next_rollout_request_id {
        return false;
    }
    match (current_execution_request_id, next_execution_request_id) {
        (Some(current_execution_request_id), Some(next_execution_request_id)) => {
            current_execution_request_id == next_execution_request_id
        }
        _ => true,
    }
}

fn validate_rollout_execution_receipt_state_transition(
    label: &str,
    current_rollout_request_id: &str,
    current_execution_request_id: Option<&str>,
    current_status: &str,
    next_rollout_request_id: &str,
    next_execution_request_id: Option<&str>,
    next_status: &str,
) -> Result<(), String> {
    if !rollout_execution_receipt_targets_same_execution(
        current_rollout_request_id,
        current_execution_request_id,
        next_rollout_request_id,
        next_execution_request_id,
    ) {
        return Ok(());
    }
    if rollout_execution_receipt_status_transition_allowed(current_status, next_status) {
        return Ok(());
    }
    Err(format!(
        "runtime rollout {} cannot change status from {} to {} for the current execution",
        label, current_status, next_status
    ))
}

fn rollout_receipt_state_is_idempotent_replay(
    current_receipt_state: &OpsRuntimeRolloutReceiptState,
    next_receipt_state: &OpsRuntimeRolloutReceiptState,
) -> bool {
    current_receipt_state.rollout_request_id == next_receipt_state.rollout_request_id
        && current_receipt_state.execution_request_id == next_receipt_state.execution_request_id
        && current_receipt_state.status == next_receipt_state.status
        && current_receipt_state.stage == next_receipt_state.stage
        && current_receipt_state.phase == next_receipt_state.phase
        && current_receipt_state.target_profile == next_receipt_state.target_profile
        && current_receipt_state.actor == next_receipt_state.actor
        && rollout_optional_string_matches(&current_receipt_state.note, &next_receipt_state.note)
        && rollout_optional_string_matches(
            &current_receipt_state.external_ref,
            &next_receipt_state.external_ref,
        )
}

fn rollout_traffic_receipt_state_is_idempotent_replay(
    current_receipt_state: &OpsRuntimeRolloutTrafficReceiptState,
    next_receipt_state: &OpsRuntimeRolloutTrafficReceiptState,
) -> bool {
    current_receipt_state.rollout_request_id == next_receipt_state.rollout_request_id
        && current_receipt_state.execution_request_id == next_receipt_state.execution_request_id
        && current_receipt_state.status == next_receipt_state.status
        && current_receipt_state.stage == next_receipt_state.stage
        && current_receipt_state.phase == next_receipt_state.phase
        && current_receipt_state.target_profile == next_receipt_state.target_profile
        && current_receipt_state.actor == next_receipt_state.actor
        && rollout_optional_string_matches(&current_receipt_state.note, &next_receipt_state.note)
        && rollout_optional_string_matches(
            &current_receipt_state.external_ref,
            &next_receipt_state.external_ref,
        )
}

fn rollout_action_ack_state_to_json(
    ack_state: &OpsRuntimeRolloutActionAckState,
    current_fingerprint: Option<&str>,
    current_rollout_request_id: Option<&str>,
) -> serde_json::Value {
    let matches_current_rollout = current_rollout_request_id
        .map(|request_id| request_id == ack_state.rollout_request_id)
        .unwrap_or(false);
    let matches_current_action = current_fingerprint
        .map(|fingerprint| fingerprint == ack_state.fingerprint)
        .unwrap_or(matches_current_rollout)
        || matches_current_rollout;
    json!({
        "active": true,
        "ack_request_id": ack_state.ack_request_id,
        "adapter": ack_state.adapter,
        "rollout_request_id": ack_state.rollout_request_id,
        "fingerprint": ack_state.fingerprint,
        "status": ack_state.status,
        "actor": ack_state.actor,
        "note": ack_state.note,
        "external_ref": ack_state.external_ref,
        "updated_at_ms": ack_state.updated_at_ms,
        "matches_current_action": matches_current_action,
        "matches_current_rollout": matches_current_rollout,
    })
}

fn rollout_action_execution_state_to_json(
    execution_state: &OpsRuntimeRolloutActionExecutionState,
    current_fingerprint: Option<&str>,
    current_rollout_request_id: Option<&str>,
    timeout_ms: u64,
) -> serde_json::Value {
    let now_ms = now_ts_ms();
    let matches_current_rollout = current_rollout_request_id
        .map(|request_id| request_id == execution_state.rollout_request_id)
        .unwrap_or(false);
    let matches_current_action = current_fingerprint
        .map(|fingerprint| fingerprint == execution_state.fingerprint)
        .unwrap_or(matches_current_rollout)
        || matches_current_rollout;
    let pending_elapsed_ms = now_ms.saturating_sub(execution_state.updated_at_ms);
    let timed_out = timeout_ms > 0 && pending_elapsed_ms >= timeout_ms;
    json!({
        "active": true,
        "execution_request_id": execution_state.execution_request_id,
        "adapter": execution_state.adapter,
        "rollout_request_id": execution_state.rollout_request_id,
        "fingerprint": execution_state.fingerprint,
        "actor": execution_state.actor,
        "note": execution_state.note,
        "external_ref": execution_state.external_ref,
        "source": execution_state.source,
        "claimed_at_ms": execution_state.claimed_at_ms,
        "updated_at_ms": execution_state.updated_at_ms,
        "last_status": execution_state.last_status,
        "pending_elapsed_ms": pending_elapsed_ms,
        "pending_timeout_ms": timeout_ms,
        "timed_out": timed_out,
        "matches_current_action": matches_current_action,
        "matches_current_rollout": matches_current_rollout,
    })
}

fn rollout_action_redispatch_to_json(
    dispatch_state: &OpsAlertDispatchState,
    action_status: &OpsRuntimeRolloutActionStatusSnapshot,
) -> serde_json::Value {
    json!({
        "active": action_status.redispatch_attempts > 0,
        "attempts": action_status.redispatch_attempts,
        "max_attempts": action_status.redispatch_max_attempts,
        "remaining_attempts": action_status.redispatch_remaining_attempts,
        "eligible": action_status.redispatch_eligible,
        "exhausted": action_status.redispatch_exhausted,
        "backoff_active": action_status.redispatch_backoff_active,
        "next_eligible_at_ms": action_status.redispatch_next_eligible_at_ms,
        "remaining_backoff_ms": action_status.redispatch_remaining_backoff_ms,
        "last_request_id": dispatch_state.last_redispatch_request_id,
        "last_source": dispatch_state.last_redispatch_source,
        "last_reason": dispatch_state.last_redispatch_reason,
        "last_fingerprint": dispatch_state.last_redispatch_fingerprint,
        "last_redispatch_at_ms": dispatch_state.last_redispatch_at_ms,
    })
}

type HmacSha256 = Hmac<Sha256>;

#[derive(Debug, Clone)]
struct OutboundWebhookSecurity {
    request_id: String,
    idempotency_key: String,
    timestamp_ms: u64,
    bearer_token: Option<String>,
    signature: Option<String>,
}

fn build_webhook_signature(secret: &str, timestamp_ms: u64, body: &str) -> Result<String, String> {
    let mut mac =
        HmacSha256::new_from_slice(secret.as_bytes()).map_err(|error| error.to_string())?;
    mac.update(timestamp_ms.to_string().as_bytes());
    mac.update(b".");
    mac.update(body.as_bytes());
    Ok(format!(
        "sha256={}",
        hex::encode(mac.finalize().into_bytes())
    ))
}

fn build_runtime_rollout_action_callback_token(
    secret: &str,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    rollout_request_id: &str,
    fingerprint: &str,
) -> Result<String, String> {
    let mut mac =
        HmacSha256::new_from_slice(secret.as_bytes()).map_err(|error| error.to_string())?;
    mac.update(b"runtime_rollout_action_callback");
    mac.update(b".");
    mac.update(adapter.as_str().as_bytes());
    mac.update(b".");
    mac.update(rollout_request_id.as_bytes());
    mac.update(b".");
    mac.update(fingerprint.as_bytes());
    Ok(format!("v1.{}", hex::encode(mac.finalize().into_bytes())))
}

fn runtime_rollout_action_callback_token_for_feed(
    config: &DubheChannelConfig,
    feed: &OpsRuntimeRolloutActionFeed,
) -> Option<String> {
    feed.adapter
        .callback_token_secret(config)
        .and_then(|secret| {
            build_runtime_rollout_action_callback_token(
                secret,
                feed.adapter,
                feed.rollout_state.request_id.as_str(),
                feed.fingerprint.as_str(),
            )
            .ok()
        })
}

fn build_runtime_rollout_action_webhook_security(
    config: &DubheChannelConfig,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    feed: &OpsRuntimeRolloutActionFeed,
    body: &str,
) -> Result<OutboundWebhookSecurity, String> {
    let timestamp_ms = now_ts_ms();
    let request_id = format!(
        "runtime-rollout-{}-action-{}",
        adapter.as_str(),
        feed.rollout_state.request_id
    );
    let signature = match adapter.hmac_secret(config) {
        Some(secret) => Some(build_webhook_signature(secret, timestamp_ms, body)?),
        None => None,
    };
    Ok(OutboundWebhookSecurity {
        request_id,
        idempotency_key: feed.fingerprint.clone(),
        timestamp_ms,
        bearer_token: adapter.bearer_token(config).map(str::to_string),
        signature,
    })
}

fn build_runtime_rollout_action_retry_webhook_security(
    config: &DubheChannelConfig,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    fingerprint: &str,
    body: &str,
) -> Result<OutboundWebhookSecurity, String> {
    let timestamp_ms = now_ts_ms();
    let request_id = format!(
        "runtime-rollout-{}-action-retry-{}",
        adapter.as_str(),
        fingerprint
    );
    let signature = match adapter.hmac_secret(config) {
        Some(secret) => Some(build_webhook_signature(secret, timestamp_ms, body)?),
        None => None,
    };
    Ok(OutboundWebhookSecurity {
        request_id,
        idempotency_key: fingerprint.to_string(),
        timestamp_ms,
        bearer_token: adapter.bearer_token(config).map(str::to_string),
        signature,
    })
}

async fn send_ops_webhook(
    webhook_url: &str,
    timeout_ms: u64,
    payload: &serde_json::Value,
    security: Option<&OutboundWebhookSecurity>,
) -> Result<(), String> {
    let body = payload.to_string();
    let client = reqwest::Client::builder()
        .timeout(Duration::from_millis(timeout_ms.max(1)))
        .build()
        .map_err(|error| error.to_string())?;
    let mut request = client
        .post(webhook_url)
        .header(CONTENT_TYPE, "application/json")
        .body(body);
    if let Some(security) = security {
        request = request
            .header(REQUEST_ID_HEADER, &security.request_id)
            .header("x-obelisk-idempotency-key", &security.idempotency_key)
            .header(
                "x-obelisk-webhook-timestamp",
                security.timestamp_ms.to_string(),
            );
        if let Some(signature) = &security.signature {
            request = request
                .header("x-obelisk-webhook-signature", signature)
                .header("x-obelisk-webhook-signature-alg", "hmac-sha256");
        }
        if let Some(token) = &security.bearer_token {
            request = request.header("authorization", format!("Bearer {}", token));
        }
    }
    let response = request.send().await.map_err(|error| error.to_string())?;
    if !response.status().is_success() {
        let status = response.status();
        let body = response.text().await.unwrap_or_default();
        return Err(format!("webhook returned status={} body={}", status, body));
    }
    Ok(())
}

async fn process_ops_alert_delivery_once<DB>(state: &AppState<DB>) -> Result<bool, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let Some(webhook_url) = state.config.ops_alert_webhook_url.as_deref() else {
        return Ok(false);
    };
    let Some(mut pending) = current_ops_alert_delivery_pending(state).await? else {
        return Ok(false);
    };
    let now_ms = now_ts_ms();
    if pending.next_attempt_at_ms > now_ms {
        return Ok(true);
    }

    pending.last_attempt_at_ms = Some(now_ms);
    let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
    dispatch_state.last_attempt_at_ms = Some(now_ms);
    update_ops_alert_dispatch_state(state, dispatch_state).await?;
    match send_ops_webhook(
        webhook_url,
        state.config.ops_alert_webhook_timeout_ms,
        &pending.payload,
        None,
    )
    .await
    {
        Ok(()) => {
            update_ops_alert_delivery_pending(state, None).await?;
            let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
            dispatch_state.last_success_at_ms = Some(now_ms);
            dispatch_state.last_fingerprint = Some(pending.fingerprint.clone());
            dispatch_state.last_error = None;
            dispatch_state.consecutive_failures = 0;
            update_ops_alert_dispatch_state(state, dispatch_state).await?;
            state
                .metrics
                .ops_alert_dispatch_success_total
                .fetch_add(1, Ordering::Relaxed);
        }
        Err(error) => {
            pending.attempts = pending.attempts.saturating_add(1);
            pending.last_error = Some(error.clone());
            pending.next_attempt_at_ms = now_ms.saturating_add(ops_alert_delivery_backoff_ms(
                &state.config,
                pending.attempts,
            ));
            update_ops_alert_delivery_pending(state, Some(pending)).await?;
            let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
            dispatch_state.last_error = Some(error);
            dispatch_state.consecutive_failures =
                dispatch_state.consecutive_failures.saturating_add(1);
            update_ops_alert_dispatch_state(state, dispatch_state).await?;
            state
                .metrics
                .ops_alert_dispatch_failures_total
                .fetch_add(1, Ordering::Relaxed);
            state
                .metrics
                .ops_alert_delivery_retry_scheduled_total
                .fetch_add(1, Ordering::Relaxed);
        }
    }

    Ok(true)
}

async fn dispatch_ops_alert_feed<DB>(
    state: &AppState<DB>,
    force: bool,
) -> Result<(OpsAlertFeed, bool), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let webhook_url = state
        .config
        .ops_alert_webhook_url
        .clone()
        .ok_or_else(|| "ops alert webhook is not configured".to_string())?;
    let snapshot = build_dead_letter_ops_snapshot(state).await?;
    let ready_evaluation =
        evaluate_ready_state(state, snapshot.outbox_size, snapshot.dead_letter_size).await;
    update_ready_metrics(&state.metrics, &ready_evaluation);
    let ready_slo = observe_ready_slo_snapshot(state, ready_evaluation.ready).await;
    let feed = build_ops_alert_feed(state, ready_evaluation, &ready_slo, &snapshot);
    update_ops_alert_metrics(&state.metrics, feed.alerts.as_slice());
    let payload = build_ops_alert_delivery_payload(&feed);

    let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
    let pending_delivery = current_ops_alert_delivery_pending(state).await?;
    let now_ms = now_ts_ms();
    dispatch_state.last_attempt_at_ms = Some(now_ms);
    if !force
        && dispatch_state
            .last_fingerprint
            .as_deref()
            .map(|fingerprint| fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_alert_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_alert_dispatch_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, true));
    }
    if !force
        && pending_delivery
            .as_ref()
            .map(|pending| pending.fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_alert_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_alert_dispatch_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, true));
    }
    update_ops_alert_dispatch_state(state, dispatch_state.clone()).await?;

    if let Err(error) = send_ops_webhook(
        &webhook_url,
        state.config.ops_alert_webhook_timeout_ms,
        &payload,
        None,
    )
    .await
    {
        let attempts = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.attempts.saturating_add(1))
            .unwrap_or(1);
        let created_at_ms = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.created_at_ms)
            .unwrap_or(now_ms);
        update_ops_alert_delivery_pending(
            state,
            Some(OpsAlertDeliveryEntry {
                fingerprint: feed.fingerprint.clone(),
                payload,
                attempts,
                created_at_ms,
                last_attempt_at_ms: Some(now_ms),
                next_attempt_at_ms: now_ms
                    .saturating_add(ops_alert_delivery_backoff_ms(&state.config, attempts)),
                last_error: Some(error.clone()),
            }),
        )
        .await?;
        let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
        dispatch_state.last_error = Some(error.clone());
        dispatch_state.consecutive_failures = dispatch_state.consecutive_failures.saturating_add(1);
        update_ops_alert_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_alert_dispatch_failures_total
            .fetch_add(1, Ordering::Relaxed);
        state
            .metrics
            .ops_alert_delivery_enqueued_total
            .fetch_add(1, Ordering::Relaxed);
        state
            .metrics
            .ops_alert_delivery_retry_scheduled_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, false));
    }

    if pending_delivery.is_some() {
        update_ops_alert_delivery_pending(state, None).await?;
    }
    let mut dispatch_state = current_ops_alert_dispatch_state(state).await?;
    dispatch_state.last_success_at_ms = Some(now_ts_ms());
    dispatch_state.last_fingerprint = Some(feed.fingerprint.clone());
    dispatch_state.last_error = None;
    dispatch_state.consecutive_failures = 0;
    update_ops_alert_dispatch_state(state, dispatch_state).await?;
    state
        .metrics
        .ops_alert_dispatch_success_total
        .fetch_add(1, Ordering::Relaxed);
    Ok((feed, false))
}

