async fn process_ops_runtime_rollout_action_delivery_once<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> Result<bool, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let Some(webhook_url) = adapter.webhook_url(&state.config) else {
        return Ok(false);
    };
    let Some(mut pending) =
        current_ops_runtime_rollout_action_delivery_pending(state, adapter).await?
    else {
        return Ok(false);
    };
    let now_ms = now_ts_ms();
    if pending.next_attempt_at_ms > now_ms {
        return Ok(true);
    }

    pending.last_attempt_at_ms = Some(now_ms);
    let mut dispatch_state =
        current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
    dispatch_state.last_attempt_at_ms = Some(now_ms);
    update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
    let retry_security = build_runtime_rollout_action_retry_webhook_security(
        &state.config,
        adapter,
        &pending.fingerprint,
        &pending.payload.to_string(),
    )?;
    match send_ops_webhook(
        webhook_url,
        state.config.ops_runtime_rollout_webhook_timeout_ms,
        &pending.payload,
        Some(&retry_security),
    )
    .await
    {
        Ok(()) => {
            update_ops_runtime_rollout_action_delivery_pending(state, adapter, None).await?;
            let mut dispatch_state =
                current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
            dispatch_state.last_success_at_ms = Some(now_ms);
            dispatch_state.last_fingerprint = Some(pending.fingerprint.clone());
            dispatch_state.last_error = None;
            dispatch_state.consecutive_failures = 0;
            update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state)
                .await?;
            record_ops_runtime_rollout_action_dispatch_success(&state.metrics, adapter);
        }
        Err(error) => {
            pending.attempts = pending.attempts.saturating_add(1);
            pending.last_error = Some(error.clone());
            pending.next_attempt_at_ms = now_ms.saturating_add(
                ops_runtime_rollout_delivery_backoff_ms(&state.config, pending.attempts),
            );
            update_ops_runtime_rollout_action_delivery_pending(state, adapter, Some(pending))
                .await?;
            let mut dispatch_state =
                current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
            dispatch_state.last_error = Some(error);
            dispatch_state.consecutive_failures =
                dispatch_state.consecutive_failures.saturating_add(1);
            update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state)
                .await?;
            record_ops_runtime_rollout_action_dispatch_failure(&state.metrics, adapter);
            record_ops_runtime_rollout_action_delivery_retry_scheduled(&state.metrics, adapter);
        }
    }

    Ok(true)
}

async fn invoke_internal_ops_request<DB>(
    state: &AppState<DB>,
    request_id: &str,
    path: &str,
    payload: serde_json::Value,
) -> Result<(StatusCode, serde_json::Value, String), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let admin_token = state
        .config
        .ops_admin_token
        .clone()
        .ok_or_else(|| "ops admin token is required for rollout controller".to_string())?;
    let mut req = Request::builder()
        .method(hyper::Method::POST)
        .uri(path)
        .header(OPS_ADMIN_TOKEN_HEADER, admin_token)
        .header(REQUEST_ID_HEADER, request_id)
        .body(Body::from(payload.to_string()))
        .map_err(|error| error.to_string())?;
    req.extensions_mut().insert(RequestContext {
        request_id: request_id.to_string(),
    });

    let response = match path {
        OPS_RUNTIME_ROLLOUT_ADVANCE_PATH => {
            handle_ops_runtime_rollout_advance(req, (*state).clone()).await
        }
        OPS_RUNTIME_ROLLOUT_AUTO_ROLLBACK_PATH => {
            handle_ops_runtime_rollout_auto_rollback(req, (*state).clone()).await
        }
        _ => {
            return Err(format!(
                "unsupported internal ops request path for rollout controller: {}",
                path
            ));
        }
    };

    let status = response.status();
    let body = body::to_bytes(response.into_body())
        .await
        .map_err(|error| error.to_string())?;
    let raw_body = String::from_utf8_lossy(&body).to_string();
    let payload = serde_json::from_slice(&body).unwrap_or_else(|_| json!({}));
    Ok((status, payload, raw_body))
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum OpsRuntimeRolloutControllerActionTriggerMode {
    Dispatch,
    Redispatch,
}

impl OpsRuntimeRolloutControllerActionTriggerMode {
    fn as_str(&self) -> &'static str {
        match self {
            Self::Dispatch => "dispatch",
            Self::Redispatch => "redispatch",
        }
    }
}

fn rollout_controller_action_directive(
    recommended_action: &str,
) -> Option<(
    OpsRuntimeRolloutActionAdapterKind,
    OpsRuntimeRolloutControllerActionTriggerMode,
)> {
    match recommended_action {
        "redeliver_deploy_action" => Some((
            OpsRuntimeRolloutActionAdapterKind::Deploy,
            OpsRuntimeRolloutControllerActionTriggerMode::Dispatch,
        )),
        "redispatch_deploy_action" => Some((
            OpsRuntimeRolloutActionAdapterKind::Deploy,
            OpsRuntimeRolloutControllerActionTriggerMode::Redispatch,
        )),
        "redeliver_traffic_action" => Some((
            OpsRuntimeRolloutActionAdapterKind::Traffic,
            OpsRuntimeRolloutControllerActionTriggerMode::Dispatch,
        )),
        "redispatch_traffic_action" => Some((
            OpsRuntimeRolloutActionAdapterKind::Traffic,
            OpsRuntimeRolloutControllerActionTriggerMode::Redispatch,
        )),
        _ => None,
    }
}

fn rollout_controller_redispatch_reason(
    blocked_reasons: &[String],
    adapter: OpsRuntimeRolloutActionAdapterKind,
) -> &'static str {
    match adapter {
        OpsRuntimeRolloutActionAdapterKind::Deploy => {
            if blocked_reasons
                .iter()
                .any(|reason| reason == "deploy_action_execution_timeout")
            {
                "action_execution_timeout"
            } else {
                "action_ack_timeout"
            }
        }
        OpsRuntimeRolloutActionAdapterKind::Traffic => {
            if blocked_reasons
                .iter()
                .any(|reason| reason == "traffic_action_execution_timeout")
            {
                "action_execution_timeout"
            } else {
                "action_ack_timeout"
            }
        }
    }
}

async fn trigger_ops_runtime_rollout_controller_action<DB>(
    state: &AppState<DB>,
    source: &str,
    now_ms: u64,
    current_rollout_state: &OpsRuntimeRolloutState,
    next_phase: &str,
    ready_slo_severity: Option<String>,
    ready_slo_policy_action: String,
    recommended_action: String,
    blocked_reasons: Vec<String>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    trigger_mode: OpsRuntimeRolloutControllerActionTriggerMode,
) -> Result<OpsRuntimeRolloutControllerState, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let request_id = format!(
        "rollout-controller-{}-{}-{}-{}",
        source,
        adapter.as_str(),
        trigger_mode.as_str(),
        now_ms
    );
    let lease = match acquire_ops_runtime_rollout_controller_lease(state, &request_id).await {
        Ok(lease) => lease,
        Err(error) => {
            let controller_state = OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some("lease_conflict".to_string()),
                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                current_phase: Some(current_rollout_state.phase.clone()),
                next_phase: Some(next_phase.to_string()),
                recommended_action: Some("wait_for_controller_lease".to_string()),
                blocked_reasons: vec!["controller_lease_conflict".to_string()],
                ready_slo_severity,
                ready_slo_policy_action: Some(ready_slo_policy_action),
                last_error: Some(error),
                triggered: false,
            };
            update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
            state
                .metrics
                .ops_runtime_rollout_controller_lease_conflicts_total
                .fetch_add(1, Ordering::Relaxed);
            return Ok(controller_state);
        }
    };

    let latest_rollout_state = current_ops_runtime_rollout_state(state).await?;
    if latest_rollout_state.request_id != current_rollout_state.request_id
        || latest_rollout_state.phase != current_rollout_state.phase
    {
        drop(lease);
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: Some(request_id),
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("stale".to_string()),
            rollout_request_id: Some(latest_rollout_state.request_id.clone()),
            current_phase: Some(latest_rollout_state.phase.clone()),
            next_phase: Some(next_phase.to_string()),
            recommended_action: Some("reconcile_latest_state".to_string()),
            blocked_reasons: vec!["rollout_state_changed".to_string()],
            ready_slo_severity,
            ready_slo_policy_action: Some(ready_slo_policy_action),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    }

    let action_result = match trigger_mode {
        OpsRuntimeRolloutControllerActionTriggerMode::Dispatch => {
            dispatch_ops_runtime_rollout_action_feed(
                state,
                adapter,
                true,
                Some("controller_auto_dispatch"),
                None,
            )
            .await
            .map(|_| ())
        }
        OpsRuntimeRolloutControllerActionTriggerMode::Redispatch => {
            redispatch_ops_runtime_rollout_action_feed(
                state,
                adapter,
                &request_id,
                "controller_auto_redispatch",
                Some(rollout_controller_redispatch_reason(
                    &blocked_reasons,
                    adapter,
                )),
            )
            .await
            .map(|_| ())
        }
    };
    drop(lease);

    let controller_state = match action_result {
        Ok(()) => {
            let refreshed_rollout_state = current_ops_runtime_rollout_state(state).await?;
            let refreshed_checklist = Box::pin(evaluate_runtime_rollout_checklist(
                state,
                refreshed_rollout_state,
            ))
            .await?;
            state
                .metrics
                .ops_runtime_rollout_controller_triggered_total
                .fetch_add(1, Ordering::Relaxed);
            OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some(format!(
                    "{}_action_{}_triggered",
                    adapter.as_str(),
                    trigger_mode.as_str()
                )),
                rollout_request_id: Some(refreshed_checklist.rollout_state.request_id.clone()),
                current_phase: Some(refreshed_checklist.rollout_state.phase.clone()),
                next_phase: Some(next_phase.to_string()),
                recommended_action: Some(refreshed_checklist.recommended_action.clone()),
                blocked_reasons: refreshed_checklist.blocked_reasons.clone(),
                ready_slo_severity,
                ready_slo_policy_action: Some(ready_slo_policy_action),
                last_error: None,
                triggered: true,
            }
        }
        Err(error) => {
            state
                .metrics
                .ops_runtime_rollout_controller_blocked_total
                .fetch_add(1, Ordering::Relaxed);
            OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some(format!(
                    "{}_action_{}_blocked",
                    adapter.as_str(),
                    trigger_mode.as_str()
                )),
                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                current_phase: Some(current_rollout_state.phase.clone()),
                next_phase: Some(next_phase.to_string()),
                recommended_action: Some(recommended_action),
                blocked_reasons,
                ready_slo_severity,
                ready_slo_policy_action: Some(ready_slo_policy_action),
                last_error: Some(error),
                triggered: false,
            }
        }
    };

    update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
    Ok(controller_state)
}

async fn process_ops_runtime_rollout_controller_once<DB>(
    state: &AppState<DB>,
    source: &str,
) -> Result<OpsRuntimeRolloutControllerState, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .ops_runtime_rollout_controller_polls_total
        .fetch_add(1, Ordering::Relaxed);

    let current_rollout_state = current_ops_runtime_rollout_state(state).await?;
    let now_ms = now_ts_ms();

    if !current_rollout_state.active {
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: None,
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("idle".to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: None,
            recommended_action: Some("start_rollout".to_string()),
            blocked_reasons: Vec::new(),
            ready_slo_severity: None,
            ready_slo_policy_action: None,
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    }

    let latest_receipt_state = current_ops_runtime_rollout_receipt_state(state).await?;
    let latest_traffic_receipt_state =
        current_ops_runtime_rollout_traffic_receipt_state(state).await?;
    let ready_slo_severity = if matches!(
        current_rollout_state.phase.as_str(),
        "prepare" | "canary" | "promote"
    ) {
        let (_ready_evaluation, _ready_slo, severity) = current_ready_slo_severity(state).await?;
        severity.map(str::to_string)
    } else {
        None
    };
    let ready_slo_policy_action = ready_slo_rollout_policy_action(
        &state.config,
        &current_rollout_state.phase,
        ready_slo_severity.as_deref(),
    );
    let failed_receipt_signal = is_failed_receipt_for_current_rollout(
        latest_receipt_state.as_ref(),
        &current_rollout_state,
    );
    let timed_out_receipt_signal = is_timed_out_receipt_for_current_rollout(
        latest_receipt_state.as_ref(),
        &current_rollout_state,
        state.config.ops_runtime_rollout_receipt_pending_timeout_ms,
        now_ms,
    );
    let failed_traffic_receipt_signal = is_failed_traffic_receipt_for_current_rollout(
        latest_traffic_receipt_state.as_ref(),
        &current_rollout_state,
    );
    let timed_out_traffic_receipt_signal = is_timed_out_traffic_receipt_for_current_rollout(
        latest_traffic_receipt_state.as_ref(),
        &current_rollout_state,
        state
            .config
            .ops_runtime_rollout_traffic_receipt_pending_timeout_ms,
        now_ms,
    );
    let latest_deploy_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await?;
    let latest_deploy_action_ack = current_ops_runtime_rollout_action_ack_state(
        state,
        OpsRuntimeRolloutActionAdapterKind::Deploy,
    )
    .await?;
    let rejected_deploy_action_signal = latest_deploy_action_ack
        .as_ref()
        .map(|ack_state| {
            rollout_action_ack_matches_current_action(
                ack_state,
                OpsRuntimeRolloutActionAdapterKind::Deploy,
                latest_deploy_action_dispatch_state
                    .last_fingerprint
                    .as_deref(),
                Some(current_rollout_state.request_id.as_str()),
                latest_deploy_action_dispatch_state.last_success_at_ms,
            ) && ack_state.status == "rejected"
        })
        .unwrap_or(false);
    let latest_traffic_action_dispatch_state = current_ops_runtime_rollout_action_dispatch_state(
        state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
    )
    .await?;
    let latest_traffic_action_ack = current_ops_runtime_rollout_action_ack_state(
        state,
        OpsRuntimeRolloutActionAdapterKind::Traffic,
    )
    .await?;
    let rejected_traffic_action_signal = latest_traffic_action_ack
        .as_ref()
        .map(|ack_state| {
            rollout_action_ack_matches_current_action(
                ack_state,
                OpsRuntimeRolloutActionAdapterKind::Traffic,
                latest_traffic_action_dispatch_state
                    .last_fingerprint
                    .as_deref(),
                Some(current_rollout_state.request_id.as_str()),
                latest_traffic_action_dispatch_state.last_success_at_ms,
            ) && ack_state.status == "rejected"
        })
        .unwrap_or(false);
    let policy_decision = evaluate_runtime_rollout_policy_decision(
        failed_receipt_signal,
        timed_out_receipt_signal,
        failed_traffic_receipt_signal,
        timed_out_traffic_receipt_signal,
        rejected_deploy_action_signal,
        rejected_traffic_action_signal,
        ready_slo_severity.as_deref(),
        ready_slo_policy_action,
    );
    let rollback_ready_slo_signal = policy_decision.source == "ready_slo"
        && policy_decision.action == RuntimeRolloutPolicyAction::Rollback;
    let rollback_signal = if current_rollout_state.phase != "rollback"
        && policy_decision.action == RuntimeRolloutPolicyAction::Rollback
    {
        Some(match policy_decision.source.as_str() {
            "external_receipt" => (
                "failed receipt",
                "rollback_triggered",
                "rollback_blocked",
                "rollback_error",
                Vec::new(),
            ),
            "traffic_receipt" => (
                "failed traffic receipt",
                "rollback_triggered",
                "rollback_blocked",
                "rollback_error",
                vec!["failed_traffic_receipt".to_string()],
            ),
            "ready_slo" => (
                "ready slo burn rate",
                "slo_rollback_triggered",
                "slo_rollback_blocked",
                "slo_rollback_error",
                vec![policy_decision
                    .reason
                    .clone()
                    .unwrap_or_else(|| "ready_slo_burn_rate".to_string())],
            ),
            _ => (
                "policy decision",
                "rollback_triggered",
                "rollback_blocked",
                "rollback_error",
                Vec::new(),
            ),
        })
    } else {
        None
    };
    if let Some((
        rollback_reason,
        rollback_success_decision,
        rollback_blocked_decision,
        rollback_error_decision,
        rollback_signal_reasons,
    )) = rollback_signal
    {
        let request_id = format!("rollout-controller-rollback-{}-{}", source, now_ms);
        let lease = match acquire_ops_runtime_rollout_controller_lease(state, &request_id).await {
            Ok(lease) => lease,
            Err(error) => {
                let controller_state = OpsRuntimeRolloutControllerState {
                    last_request_id: Some(request_id),
                    last_decision_at_ms: Some(now_ms),
                    last_decision: Some("lease_conflict".to_string()),
                    rollout_request_id: Some(current_rollout_state.request_id.clone()),
                    current_phase: Some(current_rollout_state.phase.clone()),
                    next_phase: Some("rollback".to_string()),
                    recommended_action: Some("wait_for_controller_lease".to_string()),
                    blocked_reasons: vec!["controller_lease_conflict".to_string()],
                    ready_slo_severity: ready_slo_severity.clone(),
                    ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                    last_error: Some(error),
                    triggered: false,
                };
                update_ops_runtime_rollout_controller_state(state, controller_state.clone())
                    .await?;
                state
                    .metrics
                    .ops_runtime_rollout_controller_lease_conflicts_total
                    .fetch_add(1, Ordering::Relaxed);
                return Ok(controller_state);
            }
        };

        let latest_rollout_state = current_ops_runtime_rollout_state(state).await?;
        if latest_rollout_state.request_id != current_rollout_state.request_id
            || latest_rollout_state.phase != current_rollout_state.phase
        {
            drop(lease);
            let controller_state = OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some("stale".to_string()),
                rollout_request_id: Some(latest_rollout_state.request_id.clone()),
                current_phase: Some(latest_rollout_state.phase.clone()),
                next_phase: Some("rollback".to_string()),
                recommended_action: Some("reconcile_latest_state".to_string()),
                blocked_reasons: vec!["rollout_state_changed".to_string()],
                ready_slo_severity: ready_slo_severity.clone(),
                ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                last_error: None,
                triggered: false,
            };
            update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
            state
                .metrics
                .ops_runtime_rollout_controller_skips_total
                .fetch_add(1, Ordering::Relaxed);
            return Ok(controller_state);
        }

        let (status, payload, raw_body) = invoke_internal_ops_request(
            state,
            &request_id,
            OPS_RUNTIME_ROLLOUT_AUTO_ROLLBACK_PATH,
            json!({
                "operator": "system:rollout-controller",
                "ready_slo_critical": rollback_ready_slo_signal
                    && ready_slo_severity.as_deref() == Some("critical"),
                "reason": format!(
                    "automatic rollback after {} for rollout_request_id={} phase={}",
                    rollback_reason,
                    current_rollout_state.request_id,
                    current_rollout_state.phase
                ),
            }),
        )
        .await?;
        drop(lease);

        let controller_state = if status == StatusCode::OK {
            state
                .metrics
                .ops_runtime_rollout_controller_triggered_total
                .fetch_add(1, Ordering::Relaxed);
            OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some(rollback_success_decision.to_string()),
                rollout_request_id: payload["runtime_rollout"]["request_id"]
                    .as_str()
                    .map(str::to_string)
                    .or_else(|| Some(current_rollout_state.request_id.clone())),
                current_phase: payload["runtime_rollout"]["phase"]
                    .as_str()
                    .map(str::to_string)
                    .or_else(|| Some("rollback".to_string())),
                next_phase: Some("rollback".to_string()),
                recommended_action: Some("verify_rollback".to_string()),
                blocked_reasons: Vec::new(),
                ready_slo_severity: ready_slo_severity.clone(),
                ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                last_error: None,
                triggered: true,
            }
        } else if status == StatusCode::CONFLICT {
            state
                .metrics
                .ops_runtime_rollout_controller_blocked_total
                .fetch_add(1, Ordering::Relaxed);
            OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some(rollback_blocked_decision.to_string()),
                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                current_phase: Some(current_rollout_state.phase.clone()),
                next_phase: Some("rollback".to_string()),
                recommended_action: Some("manual_review".to_string()),
                blocked_reasons: {
                    let mut reasons = vec!["auto_rollback_blocked".to_string()];
                    reasons.extend(rollback_signal_reasons.clone());
                    reasons
                },
                ready_slo_severity: ready_slo_severity.clone(),
                ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                last_error: payload["error"].as_str().map(str::to_string),
                triggered: false,
            }
        } else {
            state
                .metrics
                .ops_runtime_rollout_controller_errors_total
                .fetch_add(1, Ordering::Relaxed);
            OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some(rollback_error_decision.to_string()),
                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                current_phase: Some(current_rollout_state.phase.clone()),
                next_phase: Some("rollback".to_string()),
                recommended_action: Some("investigate_controller_error".to_string()),
                blocked_reasons: rollback_signal_reasons.clone(),
                ready_slo_severity: ready_slo_severity.clone(),
                ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                last_error: Some(format!(
                    "auto_rollback returned status={} payload={}",
                    status, raw_body
                )),
                triggered: false,
            }
        };

        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        return Ok(controller_state);
    }

    let Some(next_phase_hint) = ops_runtime_rollout_next_phase_hint(&current_rollout_state.phase)
    else {
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: None,
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("terminal".to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: None,
            recommended_action: Some("manual_review".to_string()),
            blocked_reasons: Vec::new(),
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    };
    let next_phase = if next_phase_hint == "complete" {
        "idle".to_string()
    } else {
        next_phase_hint.to_string()
    };

    if policy_decision.action == RuntimeRolloutPolicyAction::Block {
        let (last_decision, recommended_action, blocked_reasons) =
            match policy_decision.source.as_str() {
                "ready_slo" => {
                    if let Some(severity) = ready_slo_severity.as_deref() {
                        (
                            "slo_blocked".to_string(),
                            "wait_for_ready_slo_recovery".to_string(),
                            vec![format!("{}_ready_slo_burn_rate", severity)],
                        )
                    } else {
                        (
                            "policy_blocked".to_string(),
                            "manual_review".to_string(),
                            policy_decision.reason.clone().into_iter().collect(),
                        )
                    }
                }
                "external_receipt_timeout" => (
                    "receipt_timeout_blocked".to_string(),
                    "investigate_receipt_timeout".to_string(),
                    vec!["latest_receipt_timeout".to_string()],
                ),
                "deploy_action_ack" => (
                    "deploy_action_rejection_blocked".to_string(),
                    "investigate_deploy_action_rejection".to_string(),
                    vec!["deploy_action_rejected".to_string()],
                ),
                "traffic_action_ack" => (
                    "traffic_action_rejection_blocked".to_string(),
                    "investigate_traffic_action_rejection".to_string(),
                    vec!["traffic_action_rejected".to_string()],
                ),
                "traffic_receipt_timeout" => (
                    "traffic_receipt_timeout_blocked".to_string(),
                    "investigate_traffic_receipt_timeout".to_string(),
                    vec!["latest_traffic_receipt_timeout".to_string()],
                ),
                _ => (
                    "policy_blocked".to_string(),
                    "manual_review".to_string(),
                    policy_decision.reason.clone().into_iter().collect(),
                ),
            };
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: None,
            last_decision_at_ms: Some(now_ms),
            last_decision: Some(last_decision),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: Some(next_phase.clone()),
            recommended_action: Some(recommended_action),
            blocked_reasons,
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    } else if policy_decision.source == "ready_slo"
        && policy_decision.action == RuntimeRolloutPolicyAction::Proceed
    {
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: None,
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("slo_observed".to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: Some(next_phase.clone()),
            recommended_action: Some("proceed".to_string()),
            blocked_reasons: Vec::new(),
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state).await?;
    }

    let rollout_checklist = Box::pin(evaluate_runtime_rollout_checklist(
        state,
        current_rollout_state.clone(),
    ))
    .await?;
    if let Some((adapter, trigger_mode)) =
        rollout_controller_action_directive(rollout_checklist.recommended_action.as_str())
    {
        return trigger_ops_runtime_rollout_controller_action(
            state,
            source,
            now_ms,
            &current_rollout_state,
            &next_phase,
            ready_slo_severity.clone(),
            ready_slo_policy_action.as_str().to_string(),
            rollout_checklist.recommended_action.clone(),
            rollout_checklist.blocked_reasons.clone(),
            adapter,
            trigger_mode,
        )
        .await;
    }

    let stage_completion =
        evaluate_runtime_rollout_stage_completion(state, &current_rollout_state, &next_phase)
            .await?;
    if !stage_completion.can_transition {
        let auto_redispatch_adapter = if stage_completion
            .blocked_reasons
            .iter()
            .any(|reason| reason == "deploy_action_ack_timeout")
        {
            Some(OpsRuntimeRolloutActionAdapterKind::Deploy)
        } else if stage_completion
            .blocked_reasons
            .iter()
            .any(|reason| reason == "traffic_action_ack_timeout")
        {
            Some(OpsRuntimeRolloutActionAdapterKind::Traffic)
        } else {
            None
        };
        if let Some(adapter) = auto_redispatch_adapter {
            let action_feed = build_ops_runtime_rollout_action_feed(
                state,
                adapter,
                Some("controller_auto_redispatch"),
                None,
            )
            .await
            .ok()
            .filter(|feed| validate_ops_runtime_rollout_action_feed(feed).is_ok());
            let action_status = build_ops_runtime_rollout_action_status_snapshot(
                state,
                adapter,
                action_feed.as_ref(),
            )
            .await?;
            if action_status.redispatch_eligible {
                let request_id = format!(
                    "rollout-controller-{}-redispatch-{}-{}",
                    source,
                    adapter.as_str(),
                    now_ms
                );
                let lease =
                    match acquire_ops_runtime_rollout_controller_lease(state, &request_id).await {
                        Ok(lease) => lease,
                        Err(error) => {
                            let controller_state = OpsRuntimeRolloutControllerState {
                                last_request_id: Some(request_id),
                                last_decision_at_ms: Some(now_ms),
                                last_decision: Some("lease_conflict".to_string()),
                                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                                current_phase: Some(current_rollout_state.phase.clone()),
                                next_phase: Some(next_phase.clone()),
                                recommended_action: Some("wait_for_controller_lease".to_string()),
                                blocked_reasons: vec!["controller_lease_conflict".to_string()],
                                ready_slo_severity: ready_slo_severity.clone(),
                                ready_slo_policy_action: Some(
                                    ready_slo_policy_action.as_str().to_string(),
                                ),
                                last_error: Some(error),
                                triggered: false,
                            };
                            update_ops_runtime_rollout_controller_state(
                                state,
                                controller_state.clone(),
                            )
                            .await?;
                            state
                                .metrics
                                .ops_runtime_rollout_controller_lease_conflicts_total
                                .fetch_add(1, Ordering::Relaxed);
                            return Ok(controller_state);
                        }
                    };
                let latest_rollout_state = current_ops_runtime_rollout_state(state).await?;
                if latest_rollout_state.request_id != current_rollout_state.request_id
                    || latest_rollout_state.phase != current_rollout_state.phase
                {
                    drop(lease);
                    let controller_state = OpsRuntimeRolloutControllerState {
                        last_request_id: Some(request_id),
                        last_decision_at_ms: Some(now_ms),
                        last_decision: Some("stale".to_string()),
                        rollout_request_id: Some(latest_rollout_state.request_id.clone()),
                        current_phase: Some(latest_rollout_state.phase.clone()),
                        next_phase: Some(next_phase.clone()),
                        recommended_action: Some("reconcile_latest_state".to_string()),
                        blocked_reasons: vec!["rollout_state_changed".to_string()],
                        ready_slo_severity: ready_slo_severity.clone(),
                        ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                        last_error: None,
                        triggered: false,
                    };
                    update_ops_runtime_rollout_controller_state(state, controller_state.clone())
                        .await?;
                    state
                        .metrics
                        .ops_runtime_rollout_controller_skips_total
                        .fetch_add(1, Ordering::Relaxed);
                    return Ok(controller_state);
                }

                let redispatch_result = redispatch_ops_runtime_rollout_action_feed(
                    state,
                    adapter,
                    &request_id,
                    "controller_auto_redispatch",
                    Some("action_ack_timeout"),
                )
                .await;
                drop(lease);

                match redispatch_result {
                    Ok((_feed, refreshed_action_status)) => {
                        state
                            .metrics
                            .ops_runtime_rollout_controller_triggered_total
                            .fetch_add(1, Ordering::Relaxed);
                        let controller_state = OpsRuntimeRolloutControllerState {
                            last_request_id: Some(request_id),
                            last_decision_at_ms: Some(now_ms),
                            last_decision: Some(format!(
                                "{}_action_redispatch_triggered",
                                adapter.as_str()
                            )),
                            rollout_request_id: Some(current_rollout_state.request_id.clone()),
                            current_phase: Some(current_rollout_state.phase.clone()),
                            next_phase: Some(next_phase.clone()),
                            recommended_action: Some(format!(
                                "wait_for_{}_action_ack",
                                adapter.as_str()
                            )),
                            blocked_reasons: vec![format!(
                                "{}_action_ack_redispatch_triggered",
                                adapter.as_str()
                            )],
                            ready_slo_severity: ready_slo_severity.clone(),
                            ready_slo_policy_action: Some(
                                ready_slo_policy_action.as_str().to_string(),
                            ),
                            last_error: if refreshed_action_status.redispatch_exhausted {
                                Some("redispatch attempts exhausted".to_string())
                            } else {
                                None
                            },
                            triggered: true,
                        };
                        update_ops_runtime_rollout_controller_state(
                            state,
                            controller_state.clone(),
                        )
                        .await?;
                        return Ok(controller_state);
                    }
                    Err(error) => {
                        state
                            .metrics
                            .ops_runtime_rollout_controller_blocked_total
                            .fetch_add(1, Ordering::Relaxed);
                        let controller_state = OpsRuntimeRolloutControllerState {
                            last_request_id: Some(request_id),
                            last_decision_at_ms: Some(now_ms),
                            last_decision: Some(format!(
                                "{}_action_redispatch_blocked",
                                adapter.as_str()
                            )),
                            rollout_request_id: Some(current_rollout_state.request_id.clone()),
                            current_phase: Some(current_rollout_state.phase.clone()),
                            next_phase: Some(next_phase.clone()),
                            recommended_action: Some(stage_completion.recommended_action.clone()),
                            blocked_reasons: stage_completion.blocked_reasons.clone(),
                            ready_slo_severity: ready_slo_severity.clone(),
                            ready_slo_policy_action: Some(
                                ready_slo_policy_action.as_str().to_string(),
                            ),
                            last_error: Some(error),
                            triggered: false,
                        };
                        update_ops_runtime_rollout_controller_state(
                            state,
                            controller_state.clone(),
                        )
                        .await?;
                        return Ok(controller_state);
                    }
                }
            }
        }
        let last_decision = if stage_completion
            .blocked_reasons
            .iter()
            .any(|reason| reason == "phase_min_dwell_not_elapsed")
        {
            "dwell_blocked"
        } else {
            "blocked"
        };
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: None,
            last_decision_at_ms: Some(now_ms),
            last_decision: Some(last_decision.to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: Some(next_phase),
            recommended_action: Some(stage_completion.recommended_action),
            blocked_reasons: stage_completion.blocked_reasons,
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    }

    let request_id = format!("rollout-controller-{}-{}", source, now_ms);
    let lease = match acquire_ops_runtime_rollout_controller_lease(state, &request_id).await {
        Ok(lease) => lease,
        Err(error) => {
            let controller_state = OpsRuntimeRolloutControllerState {
                last_request_id: Some(request_id),
                last_decision_at_ms: Some(now_ms),
                last_decision: Some("lease_conflict".to_string()),
                rollout_request_id: Some(current_rollout_state.request_id.clone()),
                current_phase: Some(current_rollout_state.phase.clone()),
                next_phase: Some(next_phase),
                recommended_action: Some("wait_for_controller_lease".to_string()),
                blocked_reasons: vec!["controller_lease_conflict".to_string()],
                ready_slo_severity: ready_slo_severity.clone(),
                ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
                last_error: Some(error),
                triggered: false,
            };
            update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
            state
                .metrics
                .ops_runtime_rollout_controller_lease_conflicts_total
                .fetch_add(1, Ordering::Relaxed);
            return Ok(controller_state);
        }
    };

    let latest_rollout_state = current_ops_runtime_rollout_state(state).await?;
    if latest_rollout_state.request_id != current_rollout_state.request_id
        || latest_rollout_state.phase != current_rollout_state.phase
    {
        drop(lease);
        let controller_state = OpsRuntimeRolloutControllerState {
            last_request_id: Some(request_id),
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("stale".to_string()),
            rollout_request_id: Some(latest_rollout_state.request_id.clone()),
            current_phase: Some(latest_rollout_state.phase.clone()),
            next_phase: Some(next_phase),
            recommended_action: Some("reconcile_latest_state".to_string()),
            blocked_reasons: vec!["rollout_state_changed".to_string()],
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: false,
        };
        update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
        state
            .metrics
            .ops_runtime_rollout_controller_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok(controller_state);
    }

    let (status, payload, raw_body) = invoke_internal_ops_request(
        state,
        &request_id,
        OPS_RUNTIME_ROLLOUT_ADVANCE_PATH,
        json!({
            "operator": "system:rollout-controller",
            "reason": format!(
                "automatic rollout progression from phase={} to next_phase={}",
                current_rollout_state.phase, next_phase
            ),
        }),
    )
    .await?;
    drop(lease);

    let controller_state = if status == StatusCode::OK {
        state
            .metrics
            .ops_runtime_rollout_controller_triggered_total
            .fetch_add(1, Ordering::Relaxed);
        OpsRuntimeRolloutControllerState {
            last_request_id: Some(request_id),
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("triggered".to_string()),
            rollout_request_id: payload["runtime_rollout"]["request_id"]
                .as_str()
                .map(str::to_string)
                .or_else(|| Some(current_rollout_state.request_id.clone())),
            current_phase: payload["runtime_rollout"]["phase"]
                .as_str()
                .map(str::to_string)
                .or_else(|| payload["advance"]["to_phase"].as_str().map(str::to_string)),
            next_phase: payload["advance"]["to_phase"]
                .as_str()
                .map(str::to_string)
                .or_else(|| Some(next_phase)),
            recommended_action: Some("proceed".to_string()),
            blocked_reasons: Vec::new(),
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: None,
            triggered: true,
        }
    } else if status == StatusCode::CONFLICT {
        state
            .metrics
            .ops_runtime_rollout_controller_blocked_total
            .fetch_add(1, Ordering::Relaxed);
        let blocked_reasons = payload
            .get("stage_completion")
            .and_then(|value| value.get("summary"))
            .and_then(|value| value.get("blocked_reasons"))
            .or_else(|| {
                payload
                    .get("rollout_checklist")
                    .and_then(|value| value.get("summary"))
                    .and_then(|value| value.get("blocked_reasons"))
            })
            .and_then(|value| value.as_array())
            .map(|values| {
                values
                    .iter()
                    .filter_map(|value| value.as_str().map(str::to_string))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let recommended_action = payload["stage_completion"]["summary"]["recommended_action"]
            .as_str()
            .or_else(|| payload["rollout_checklist"]["summary"]["recommended_action"].as_str())
            .map(str::to_string);
        if let Some((adapter, trigger_mode)) = recommended_action
            .as_deref()
            .and_then(rollout_controller_action_directive)
        {
            let latest_rollout_state = current_ops_runtime_rollout_state(state).await?;
            return trigger_ops_runtime_rollout_controller_action(
                state,
                source,
                now_ms,
                &latest_rollout_state,
                &next_phase,
                ready_slo_severity.clone(),
                ready_slo_policy_action.as_str().to_string(),
                recommended_action.unwrap_or_else(|| "manual_review".to_string()),
                blocked_reasons,
                adapter,
                trigger_mode,
            )
            .await;
        }
        OpsRuntimeRolloutControllerState {
            last_request_id: Some(request_id),
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("blocked".to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: Some(next_phase),
            recommended_action,
            blocked_reasons,
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: payload["error"].as_str().map(str::to_string),
            triggered: false,
        }
    } else {
        state
            .metrics
            .ops_runtime_rollout_controller_errors_total
            .fetch_add(1, Ordering::Relaxed);
        OpsRuntimeRolloutControllerState {
            last_request_id: Some(request_id),
            last_decision_at_ms: Some(now_ms),
            last_decision: Some("error".to_string()),
            rollout_request_id: Some(current_rollout_state.request_id.clone()),
            current_phase: Some(current_rollout_state.phase.clone()),
            next_phase: Some(next_phase),
            recommended_action: Some("investigate_controller_error".to_string()),
            blocked_reasons: Vec::new(),
            ready_slo_severity: ready_slo_severity.clone(),
            ready_slo_policy_action: Some(ready_slo_policy_action.as_str().to_string()),
            last_error: Some(format!(
                "advance returned status={} payload={}",
                status, raw_body
            )),
            triggered: false,
        }
    };

    update_ops_runtime_rollout_controller_state(state, controller_state.clone()).await?;
    Ok(controller_state)
}

async fn dispatch_ops_runtime_rollout_feed<DB>(
    state: &AppState<DB>,
    force: bool,
    source: Option<&str>,
    history_entry: Option<&OpsRuntimeRolloutHistoryEntry>,
) -> Result<(OpsRuntimeRolloutDeliveryFeed, bool), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let webhook_url = state
        .config
        .ops_runtime_rollout_webhook_url
        .clone()
        .ok_or_else(|| "ops runtime rollout webhook is not configured".to_string())?;
    let feed = build_ops_runtime_rollout_delivery_feed(state, source, history_entry).await?;
    let receipt_state = current_ops_runtime_rollout_receipt_state(state).await?;
    let payload = build_ops_runtime_rollout_delivery_payload(
        &feed,
        receipt_state.as_ref(),
        state.config.ops_runtime_rollout_history_limit,
        &state.config,
    );

    let mut dispatch_state = current_ops_runtime_rollout_dispatch_state(state).await?;
    let pending_delivery = current_ops_runtime_rollout_delivery_pending(state).await?;
    let now_ms = now_ts_ms();
    dispatch_state.last_attempt_at_ms = Some(now_ms);
    if !force
        && dispatch_state
            .last_fingerprint
            .as_deref()
            .map(|fingerprint| fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_runtime_rollout_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_runtime_rollout_dispatch_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, true));
    }
    if !force
        && pending_delivery
            .as_ref()
            .map(|pending| pending.fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_runtime_rollout_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_runtime_rollout_dispatch_skips_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, true));
    }
    update_ops_runtime_rollout_dispatch_state(state, dispatch_state.clone()).await?;

    if let Err(error) = send_ops_webhook(
        &webhook_url,
        state.config.ops_runtime_rollout_webhook_timeout_ms,
        &payload,
        None,
    )
    .await
    {
        let attempts = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.attempts.saturating_add(1))
            .unwrap_or(1);
        let created_at_ms = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.created_at_ms)
            .unwrap_or(now_ms);
        update_ops_runtime_rollout_delivery_pending(
            state,
            Some(OpsAlertDeliveryEntry {
                fingerprint: feed.fingerprint.clone(),
                payload,
                attempts,
                created_at_ms,
                last_attempt_at_ms: Some(now_ms),
                next_attempt_at_ms: now_ms.saturating_add(ops_runtime_rollout_delivery_backoff_ms(
                    &state.config,
                    attempts,
                )),
                last_error: Some(error.clone()),
            }),
        )
        .await?;
        let mut dispatch_state = current_ops_runtime_rollout_dispatch_state(state).await?;
        dispatch_state.last_error = Some(error.clone());
        dispatch_state.consecutive_failures = dispatch_state.consecutive_failures.saturating_add(1);
        update_ops_runtime_rollout_dispatch_state(state, dispatch_state).await?;
        state
            .metrics
            .ops_runtime_rollout_dispatch_failures_total
            .fetch_add(1, Ordering::Relaxed);
        state
            .metrics
            .ops_runtime_rollout_delivery_enqueued_total
            .fetch_add(1, Ordering::Relaxed);
        state
            .metrics
            .ops_runtime_rollout_delivery_retry_scheduled_total
            .fetch_add(1, Ordering::Relaxed);
        return Ok((feed, false));
    }

    if pending_delivery.is_some() {
        update_ops_runtime_rollout_delivery_pending(state, None).await?;
    }
    let mut dispatch_state = current_ops_runtime_rollout_dispatch_state(state).await?;
    dispatch_state.last_success_at_ms = Some(now_ts_ms());
    dispatch_state.last_fingerprint = Some(feed.fingerprint.clone());
    dispatch_state.last_error = None;
    dispatch_state.consecutive_failures = 0;
    update_ops_runtime_rollout_dispatch_state(state, dispatch_state).await?;
    state
        .metrics
        .ops_runtime_rollout_dispatch_success_total
        .fetch_add(1, Ordering::Relaxed);
    Ok((feed, false))
}

async fn dispatch_ops_runtime_rollout_action_feed<DB>(
    state: &AppState<DB>,
    adapter: OpsRuntimeRolloutActionAdapterKind,
    force: bool,
    source: Option<&str>,
    history_entry: Option<&OpsRuntimeRolloutHistoryEntry>,
) -> Result<(OpsRuntimeRolloutActionFeed, bool), String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let webhook_url = adapter.webhook_url(&state.config).ok_or_else(|| {
        format!(
            "ops runtime rollout {} action webhook is not configured",
            adapter.as_str()
        )
    })?;
    let feed = build_ops_runtime_rollout_action_feed(state, adapter, source, history_entry).await?;
    validate_ops_runtime_rollout_action_feed(&feed)?;
    let action_status =
        build_ops_runtime_rollout_action_status_snapshot(state, adapter, Some(&feed)).await?;
    let mut dispatch_state =
        current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
    let payload = build_ops_runtime_rollout_action_payload(
        &feed,
        state.config.ops_runtime_rollout_history_limit,
        &state.config,
        &dispatch_state,
        &action_status,
    );
    let pending_delivery =
        current_ops_runtime_rollout_action_delivery_pending(state, adapter).await?;
    let now_ms = now_ts_ms();
    dispatch_state.last_attempt_at_ms = Some(now_ms);
    if !force
        && dispatch_state
            .last_fingerprint
            .as_deref()
            .map(|fingerprint| fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
        record_ops_runtime_rollout_action_dispatch_skip(&state.metrics, adapter);
        return Ok((feed, true));
    }
    if !force
        && pending_delivery
            .as_ref()
            .map(|pending| pending.fingerprint == feed.fingerprint)
            .unwrap_or(false)
    {
        dispatch_state.last_skipped_at_ms = Some(now_ms);
        update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
        record_ops_runtime_rollout_action_dispatch_skip(&state.metrics, adapter);
        return Ok((feed, true));
    }
    update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state.clone())
        .await?;
    let action_security = build_runtime_rollout_action_webhook_security(
        &state.config,
        adapter,
        &feed,
        &payload.to_string(),
    )?;

    if let Err(error) = send_ops_webhook(
        webhook_url,
        state.config.ops_runtime_rollout_webhook_timeout_ms,
        &payload,
        Some(&action_security),
    )
    .await
    {
        let attempts = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.attempts.saturating_add(1))
            .unwrap_or(1);
        let created_at_ms = pending_delivery
            .as_ref()
            .filter(|pending| pending.fingerprint == feed.fingerprint)
            .map(|pending| pending.created_at_ms)
            .unwrap_or(now_ms);
        update_ops_runtime_rollout_action_delivery_pending(
            state,
            adapter,
            Some(OpsAlertDeliveryEntry {
                fingerprint: feed.fingerprint.clone(),
                payload,
                attempts,
                created_at_ms,
                last_attempt_at_ms: Some(now_ms),
                next_attempt_at_ms: now_ms.saturating_add(ops_runtime_rollout_delivery_backoff_ms(
                    &state.config,
                    attempts,
                )),
                last_error: Some(error.clone()),
            }),
        )
        .await?;
        let mut dispatch_state =
            current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
        dispatch_state.last_error = Some(error.clone());
        dispatch_state.consecutive_failures = dispatch_state.consecutive_failures.saturating_add(1);
        update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
        record_ops_runtime_rollout_action_dispatch_failure(&state.metrics, adapter);
        record_ops_runtime_rollout_action_delivery_enqueued(&state.metrics, adapter);
        record_ops_runtime_rollout_action_delivery_retry_scheduled(&state.metrics, adapter);
        return Ok((feed, false));
    }

    if pending_delivery.is_some() {
        update_ops_runtime_rollout_action_delivery_pending(state, adapter, None).await?;
    }
    let mut dispatch_state =
        current_ops_runtime_rollout_action_dispatch_state(state, adapter).await?;
    dispatch_state.last_success_at_ms = Some(now_ts_ms());
    dispatch_state.last_fingerprint = Some(feed.fingerprint.clone());
    dispatch_state.last_error = None;
    dispatch_state.consecutive_failures = 0;
    update_ops_runtime_rollout_action_dispatch_state(state, adapter, dispatch_state).await?;
    record_ops_runtime_rollout_action_dispatch_success(&state.metrics, adapter);
    Ok((feed, false))
}

fn query_param_usize(req: &Request<Body>, key: &str) -> Option<usize> {
    req.uri().query()?.split('&').find_map(|pair| {
        let mut parts = pair.splitn(2, '=');
        let name = parts.next()?;
        let value = parts.next().unwrap_or_default();
        if name == key {
            value.parse::<usize>().ok()
        } else {
            None
        }
    })
}

async fn record_dead_letter_replay_terminal_state<DB>(
    state: &AppState<DB>,
    request_id: &str,
    started_at_ms: u64,
    result: &str,
    source: DeadLetterReplaySource,
    replayed_entries: u64,
    max_entries: Option<u64>,
    operator: Option<String>,
    reason: Option<String>,
    forced: bool,
    error: Option<String>,
    error_class: Option<String>,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let finished_at_ms = now_ts_ms();
    let _ = update_dead_letter_replay_status(
        state,
        DeadLetterReplayStatus {
            last_request_id: Some(request_id.to_string()),
            last_started_at_ms: Some(started_at_ms),
            last_finished_at_ms: Some(finished_at_ms),
            last_result: Some(result.to_string()),
            last_source: Some(source.as_str().to_string()),
            last_replayed_entries: Some(replayed_entries),
            last_max_entries: max_entries,
            last_operator: operator.clone(),
            last_reason: reason.clone(),
            last_error: error.clone(),
            last_error_class: error_class.clone(),
        },
    )
    .await;
    let _ = record_dead_letter_replay_history(
        state,
        DeadLetterReplayHistoryEntry {
            request_id: request_id.to_string(),
            started_at_ms,
            finished_at_ms,
            result: result.to_string(),
            source: source.as_str().to_string(),
            replayed_entries,
            max_entries,
            operator,
            reason,
            forced,
            error,
            error_class,
        },
    )
    .await;
}

async fn execute_dead_letter_replay<DB>(
    state: &AppState<DB>,
    invocation: DeadLetterReplayInvocation,
) -> DeadLetterReplayExecutionOutcome
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .submit_materialization_dead_letter_replay_requests_total
        .fetch_add(1, Ordering::Relaxed);

    let previous_replay_status = match current_dead_letter_replay_status(state).await {
        Ok(status) => status,
        Err(error) => {
            return DeadLetterReplayExecutionOutcome::InternalError {
                class: DeadLetterReplayInternalErrorClass::ReplayStatusRead,
                error,
            };
        }
    };

    refresh_submit_materialization_outbox_size(state).await;
    refresh_submit_materialization_dead_letter_size(state).await;
    let replay_handoff = match current_dead_letter_replay_handoff(state).await {
        Ok(handoff) => handoff,
        Err(error) => {
            return DeadLetterReplayExecutionOutcome::InternalError {
                class: DeadLetterReplayInternalErrorClass::ReplayHandoffRead,
                error,
            };
        }
    };
    let replay_escalation_ack = match current_dead_letter_replay_escalation_ack(state).await {
        Ok(ack) => ack,
        Err(error) => {
            return DeadLetterReplayExecutionOutcome::InternalError {
                class: DeadLetterReplayInternalErrorClass::EscalationAckRead,
                error,
            };
        }
    };
    let replay_escalation_notification =
        match current_dead_letter_replay_escalation_notification(state).await {
            Ok(notification) => notification,
            Err(error) => {
                return DeadLetterReplayExecutionOutcome::InternalError {
                    class: DeadLetterReplayInternalErrorClass::EscalationNotificationRead,
                    error,
                };
            }
        };
    let runbook_history_limit = state
        .config
        .submit_materialization_dead_letter_replay_history_limit
        .min(DEAD_LETTER_RUNBOOK_HISTORY_SAMPLE_LIMIT)
        .max(1);
    let replay_history =
        match current_dead_letter_replay_history(state, runbook_history_limit).await {
            Ok(history) => history,
            Err(error) => {
                return DeadLetterReplayExecutionOutcome::InternalError {
                    class: DeadLetterReplayInternalErrorClass::ReplayHistoryRead,
                    error,
                };
            }
        };
    let now_ms = now_ts_ms();
    let outbox_size = state
        .metrics
        .submit_materialization_outbox_size
        .load(Ordering::Relaxed);
    let dead_letter_size = state
        .metrics
        .submit_materialization_dead_letter_size
        .load(Ordering::Relaxed);
    let dead_letter_error_summary =
        current_dead_letter_error_class_summary(state, dead_letter_size)
            .await
            .unwrap_or_default();
    let cooldown_until_ms =
        current_dead_letter_replay_cooldown_until(previous_replay_status.as_ref(), &state.config);
    let cooldown_active = cooldown_until_ms
        .map(|until_ms| now_ms < until_ms)
        .unwrap_or(false);
    let runbook_summary = build_dead_letter_runbook_summary(
        &state.config,
        now_ms,
        outbox_size,
        dead_letter_size,
        Some(&dead_letter_error_summary),
        false,
        cooldown_active,
        replay_handoff.as_ref(),
        previous_replay_status.as_ref(),
        replay_history.as_slice(),
    );
    let runbook_fingerprint = runbook_summary
        .get("fingerprint")
        .and_then(|value| value.as_str())
        .unwrap_or_default();
    let escalation_acknowledged = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
        && replay_escalation_ack
            .as_ref()
            .map(|ack| ack.runbook_fingerprint == runbook_fingerprint)
            .unwrap_or(false);
    let escalation_notified = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false)
        && replay_escalation_notification
            .as_ref()
            .map(|notification| notification.runbook_fingerprint == runbook_fingerprint)
            .unwrap_or(false);
    let replay_policy_block_reason = dead_letter_replay_policy_block_reason(
        &runbook_summary,
        escalation_acknowledged,
        escalation_notified,
    );
    if !invocation.force {
        if let Some(policy_block_reason) = replay_policy_block_reason {
            if invocation.record_policy_history {
                let _ = record_dead_letter_replay_history(
                    state,
                    DeadLetterReplayHistoryEntry {
                        request_id: invocation.request_id.clone(),
                        started_at_ms: now_ms,
                        finished_at_ms: now_ms,
                        result: "policy_blocked".to_string(),
                        source: invocation.source.as_str().to_string(),
                        replayed_entries: 0,
                        max_entries: Some(invocation.max_entries as u64),
                        operator: invocation.operator.clone(),
                        reason: invocation.reason.clone(),
                        forced: false,
                        error: Some(policy_block_reason.to_string()),
                        error_class: None,
                    },
                )
                .await;
            }
            return DeadLetterReplayExecutionOutcome::PolicyBlocked {
                policy_block_reason,
                runbook_summary,
            };
        }
    }

    if let Some(cooldown_until_ms) = cooldown_until_ms {
        if !invocation.force && now_ms < cooldown_until_ms {
            state
                .metrics
                .submit_materialization_dead_letter_replay_cooldown_blocks_total
                .fetch_add(1, Ordering::Relaxed);
            let remaining_ms = cooldown_until_ms.saturating_sub(now_ms);
            if invocation.record_cooldown_history {
                let _ = record_dead_letter_replay_history(
                    state,
                    DeadLetterReplayHistoryEntry {
                        request_id: invocation.request_id.clone(),
                        started_at_ms: now_ms,
                        finished_at_ms: now_ms,
                        result: "cooldown_blocked".to_string(),
                        source: invocation.source.as_str().to_string(),
                        replayed_entries: 0,
                        max_entries: Some(invocation.max_entries as u64),
                        operator: invocation.operator.clone(),
                        reason: invocation.reason.clone(),
                        forced: false,
                        error: Some(format!(
                            "replay cooldown active for {}ms more",
                            remaining_ms
                        )),
                        error_class: None,
                    },
                )
                .await;
            }
            return DeadLetterReplayExecutionOutcome::CooldownBlocked {
                cooldown_until_ms,
                remaining_ms,
            };
        }
    }

    let replay_lease = match acquire_dead_letter_replay_lease(state, &invocation.request_id).await {
        Ok(lease) => lease,
        Err(error) => {
            return DeadLetterReplayExecutionOutcome::LeaseConflict { error };
        }
    };
    let replay_started_at_ms = now_ts_ms();
    let _ = update_dead_letter_replay_status(
        state,
        DeadLetterReplayStatus {
            last_request_id: Some(invocation.request_id.clone()),
            last_started_at_ms: Some(replay_started_at_ms),
            last_finished_at_ms: None,
            last_result: Some("running".to_string()),
            last_source: Some(invocation.source.as_str().to_string()),
            last_replayed_entries: None,
            last_max_entries: Some(invocation.max_entries as u64),
            last_operator: invocation.operator.clone(),
            last_reason: invocation.reason.clone(),
            last_error: None,
            last_error_class: None,
        },
    )
    .await;
    let mut entries = drain_submit_materialization_dead_letter_entries(
        state,
        invocation.max_entries,
        &invocation.request_id,
    )
    .await;
    let replayed = entries.len();

    if replayed == 0 {
        println!(
            "submit.materialization.dead_letter_replay_empty request_id={} source={} max_entries={}",
            invocation.request_id,
            invocation.source.as_str(),
            invocation.max_entries
        );
        refresh_submit_materialization_outbox_size(state).await;
        refresh_submit_materialization_dead_letter_size(state).await;
        record_dead_letter_replay_terminal_state(
            state,
            &invocation.request_id,
            replay_started_at_ms,
            "empty",
            invocation.source,
            0,
            Some(invocation.max_entries as u64),
            invocation.operator.clone(),
            invocation.reason.clone(),
            invocation.force,
            None,
            None,
        )
        .await;
        clear_dead_letter_replay_lease_state(state).await;
        drop(replay_lease);
        return DeadLetterReplayExecutionOutcome::Completed {
            replayed: 0,
            outbox_size: state
                .metrics
                .submit_materialization_outbox_size
                .load(Ordering::Relaxed),
            dead_letter_size: state
                .metrics
                .submit_materialization_dead_letter_size
                .load(Ordering::Relaxed),
        };
    }

    state
        .metrics
        .submit_materialization_dead_letter_replay_entries_total
        .fetch_add(replayed as u64, Ordering::Relaxed);

    println!(
        "submit.materialization.dead_letter_replay_started request_id={} source={} replayed={} max_entries={} operator={} reason={}",
        invocation.request_id,
        invocation.source.as_str(),
        replayed,
        invocation.max_entries,
        invocation.operator.as_deref().unwrap_or("-"),
        invocation.reason.as_deref().unwrap_or("-"),
    );

    requeue_submit_materialization_outbox_entries(
        state,
        &mut entries,
        &invocation.request_id,
        "dead_letter_replay",
    )
    .await;
    refresh_submit_materialization_dead_letter_size(state).await;
    record_dead_letter_replay_terminal_state(
        state,
        &invocation.request_id,
        replay_started_at_ms,
        "requeued",
        invocation.source,
        replayed as u64,
        Some(invocation.max_entries as u64),
        invocation.operator.clone(),
        invocation.reason.clone(),
        invocation.force,
        None,
        None,
    )
    .await;
    clear_dead_letter_replay_lease_state(state).await;
    drop(replay_lease);
    DeadLetterReplayExecutionOutcome::Completed {
        replayed,
        outbox_size: state
            .metrics
            .submit_materialization_outbox_size
            .load(Ordering::Relaxed),
        dead_letter_size: state
            .metrics
            .submit_materialization_dead_letter_size
            .load(Ordering::Relaxed),
    }
}

fn auto_replay_backoff_base_ms(
    config: &DubheChannelConfig,
    class: DeadLetterAutoReplayBackoffClass,
    cooldown_remaining_ms: Option<u64>,
) -> u64 {
    let initial_backoff_ms =
        config.submit_materialization_dead_letter_auto_replay_backoff_initial_ms;
    let poll_interval_ms = config
        .submit_materialization_dead_letter_auto_replay_interval_ms
        .max(1);

    match class {
        DeadLetterAutoReplayBackoffClass::PolicyBlocked => {
            initial_backoff_ms.saturating_mul(4).max(poll_interval_ms)
        }
        DeadLetterAutoReplayBackoffClass::CooldownBlocked => initial_backoff_ms
            .saturating_mul(2)
            .max(cooldown_remaining_ms.unwrap_or(0))
            .max(poll_interval_ms),
        DeadLetterAutoReplayBackoffClass::LeaseConflict => poll_interval_ms.max(1_000),
        DeadLetterAutoReplayBackoffClass::Failed => initial_backoff_ms.max(poll_interval_ms),
    }
}

fn policy_block_backoff_base_ms(config: &DubheChannelConfig, reason: &str) -> u64 {
    let initial_backoff_ms =
        config.submit_materialization_dead_letter_auto_replay_backoff_initial_ms;
    let poll_interval_ms = config
        .submit_materialization_dead_letter_auto_replay_interval_ms
        .max(1);

    match reason {
        "handoff_claim_required" => initial_backoff_ms.saturating_mul(4),
        "escalation_ack_required" => initial_backoff_ms.saturating_mul(6),
        "escalation_notification_required" => initial_backoff_ms.saturating_mul(8),
        "investigation_ack_required" => initial_backoff_ms.saturating_mul(12),
        _ => initial_backoff_ms.saturating_mul(4),
    }
    .max(poll_interval_ms)
}

fn internal_error_backoff_base_ms(
    config: &DubheChannelConfig,
    class: DeadLetterReplayInternalErrorClass,
) -> u64 {
    let initial_backoff_ms =
        config.submit_materialization_dead_letter_auto_replay_backoff_initial_ms;
    let poll_interval_ms = config
        .submit_materialization_dead_letter_auto_replay_interval_ms
        .max(1);

    match class {
        DeadLetterReplayInternalErrorClass::ReplayStatusRead => {
            initial_backoff_ms.saturating_mul(2)
        }
        DeadLetterReplayInternalErrorClass::ReplayHistoryRead => {
            initial_backoff_ms.saturating_mul(2)
        }
        DeadLetterReplayInternalErrorClass::ReplayHandoffRead => {
            initial_backoff_ms.saturating_mul(3)
        }
        DeadLetterReplayInternalErrorClass::EscalationAckRead => {
            initial_backoff_ms.saturating_mul(4)
        }
        DeadLetterReplayInternalErrorClass::EscalationNotificationRead => {
            initial_backoff_ms.saturating_mul(5)
        }
    }
    .max(poll_interval_ms)
}

fn decision_scoped_auto_replay_backoff_ms(
    config: &DubheChannelConfig,
    previous_backoff_ms: u64,
    class: DeadLetterAutoReplayBackoffClass,
    cooldown_remaining_ms: Option<u64>,
) -> u64 {
    let base_ms = auto_replay_backoff_base_ms(config, class, cooldown_remaining_ms);
    decision_scoped_auto_replay_backoff_from_base_ms(config, previous_backoff_ms, base_ms)
}

fn decision_scoped_auto_replay_backoff_from_base_ms(
    config: &DubheChannelConfig,
    previous_backoff_ms: u64,
    base_ms: u64,
) -> u64 {
    let capped_max = config
        .submit_materialization_dead_letter_auto_replay_backoff_max_ms
        .max(base_ms);
    if previous_backoff_ms == 0 {
        base_ms.min(capped_max)
    } else {
        previous_backoff_ms
            .saturating_mul(2)
            .max(base_ms)
            .min(capped_max)
    }
}

async fn update_dead_letter_auto_replay_runtime_state<DB>(
    state: &AppState<DB>,
    request_id: Option<String>,
    decision: &str,
    next_attempt_at_ms: Option<u64>,
    current_backoff_ms: u64,
    current_backoff_class: Option<DeadLetterAutoReplayBackoffClass>,
    current_backoff_reason: Option<String>,
    consecutive_deferred_runs: u64,
    last_error: Option<String>,
    last_error_class: Option<String>,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let _ = update_dead_letter_auto_replay_state(
        state,
        DeadLetterAutoReplayState {
            last_request_id: request_id,
            last_decision_at_ms: Some(now_ts_ms()),
            last_decision: Some(decision.to_string()),
            next_attempt_at_ms,
            current_backoff_ms,
            current_backoff_class: current_backoff_class.map(|class| class.as_str().to_string()),
            current_backoff_reason,
            consecutive_deferred_runs,
            last_error,
            last_error_class,
        },
    )
    .await;
}

async fn process_submit_materialization_dead_letter_auto_replay_once<DB>(state: &AppState<DB>)
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state
        .config
        .submit_materialization_dead_letter_auto_replay_interval_ms
        == 0
    {
        return;
    }

    state
        .metrics
        .submit_materialization_dead_letter_auto_replay_polls_total
        .fetch_add(1, Ordering::Relaxed);

    let existing_auto_replay_state = match current_dead_letter_auto_replay_state(state).await {
        Ok(auto_replay_state) => auto_replay_state,
        Err(error) => {
            println!(
                "submit.materialization.dead_letter_auto_replay_state_read_failed error={}",
                error
            );
            None
        }
    };
    let now_ms = now_ts_ms();
    if let Some(auto_replay_state) = existing_auto_replay_state.as_ref() {
        if auto_replay_state
            .next_attempt_at_ms
            .map(|next_attempt_at_ms| now_ms < next_attempt_at_ms)
            .unwrap_or(false)
        {
            state
                .metrics
                .submit_materialization_dead_letter_auto_replay_backoff_skips_total
                .fetch_add(1, Ordering::Relaxed);
            println!(
                "submit.materialization.dead_letter_auto_replay_backoff request_id={} next_attempt_at_ms={} current_backoff_ms={}",
                auto_replay_state.last_request_id.as_deref().unwrap_or("-"),
                auto_replay_state.next_attempt_at_ms.unwrap_or(0),
                auto_replay_state.current_backoff_ms,
            );
            return;
        }
    }

    refresh_submit_materialization_dead_letter_size(state).await;
    if state
        .metrics
        .submit_materialization_dead_letter_size
        .load(Ordering::Relaxed)
        == 0
    {
        if existing_auto_replay_state
            .as_ref()
            .map(|auto_replay_state| {
                auto_replay_state.next_attempt_at_ms.is_some()
                    || auto_replay_state.current_backoff_ms > 0
            })
            .unwrap_or(false)
        {
            update_dead_letter_auto_replay_runtime_state(
                state,
                existing_auto_replay_state.and_then(|value| value.last_request_id),
                "idle",
                None,
                0,
                None,
                None,
                0,
                None,
                None,
            )
            .await;
        }
        return;
    }

    let request_id = format!("auto-dead-letter-replay-{:032x}", random::<u128>());
    let auto_replay_operator = Some(DeadLetterReplaySource::Auto.default_operator().to_string());
    let auto_replay_reason = Some(DeadLetterReplaySource::Auto.default_reason().to_string());
    let invocation = DeadLetterReplayInvocation {
        request_id: request_id.clone(),
        max_entries: state
            .config
            .submit_materialization_dead_letter_auto_replay_max_entries
            .clamp(1, 1024),
        operator: auto_replay_operator.clone(),
        reason: auto_replay_reason.clone(),
        force: false,
        source: DeadLetterReplaySource::Auto,
        record_policy_history: false,
        record_cooldown_history: false,
    };

    match execute_dead_letter_replay(state, invocation).await {
        DeadLetterReplayExecutionOutcome::Completed {
            replayed,
            outbox_size,
            dead_letter_size,
        } => {
            state
                .metrics
                .submit_materialization_dead_letter_auto_replay_runs_total
                .fetch_add(1, Ordering::Relaxed);
            update_dead_letter_auto_replay_runtime_state(
                state,
                Some(request_id.clone()),
                if replayed == 0 { "empty" } else { "requeued" },
                None,
                0,
                None,
                None,
                0,
                None,
                None,
            )
            .await;
            println!(
                "submit.materialization.dead_letter_auto_replay_completed request_id={} replayed={} outbox_size={} dead_letter_size={}",
                request_id, replayed, outbox_size, dead_letter_size
            );
        }
        DeadLetterReplayExecutionOutcome::PolicyBlocked {
            policy_block_reason,
            ..
        } => {
            state
                .metrics
                .submit_materialization_dead_letter_auto_replay_policy_blocks_total
                .fetch_add(1, Ordering::Relaxed);
            let backoff_ms = decision_scoped_auto_replay_backoff_from_base_ms(
                &state.config,
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.current_backoff_ms)
                    .unwrap_or(0),
                policy_block_backoff_base_ms(&state.config, policy_block_reason),
            );
            update_dead_letter_auto_replay_runtime_state(
                state,
                Some(request_id.clone()),
                "policy_blocked",
                Some(now_ms.saturating_add(backoff_ms)),
                backoff_ms,
                Some(DeadLetterAutoReplayBackoffClass::PolicyBlocked),
                Some(policy_block_reason.to_string()),
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.consecutive_deferred_runs)
                    .unwrap_or(0)
                    .saturating_add(1),
                Some(policy_block_reason.to_string()),
                None,
            )
            .await;
            println!(
                "submit.materialization.dead_letter_auto_replay_skipped request_id={} reason={}",
                request_id, policy_block_reason
            );
        }
        DeadLetterReplayExecutionOutcome::CooldownBlocked { remaining_ms, .. } => {
            state
                .metrics
                .submit_materialization_dead_letter_auto_replay_cooldown_blocks_total
                .fetch_add(1, Ordering::Relaxed);
            let backoff_ms = decision_scoped_auto_replay_backoff_ms(
                &state.config,
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.current_backoff_ms)
                    .unwrap_or(0),
                DeadLetterAutoReplayBackoffClass::CooldownBlocked,
                Some(remaining_ms),
            );
            update_dead_letter_auto_replay_runtime_state(
                state,
                Some(request_id.clone()),
                "cooldown_blocked",
                Some(now_ms.saturating_add(backoff_ms.max(remaining_ms))),
                backoff_ms,
                Some(DeadLetterAutoReplayBackoffClass::CooldownBlocked),
                Some("cooldown_window".to_string()),
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.consecutive_deferred_runs)
                    .unwrap_or(0)
                    .saturating_add(1),
                Some(format!("cooldown remaining {}ms", remaining_ms)),
                None,
            )
            .await;
            println!(
                "submit.materialization.dead_letter_auto_replay_cooldown request_id={} remaining_ms={}",
                request_id, remaining_ms
            );
        }
        DeadLetterReplayExecutionOutcome::LeaseConflict { error } => {
            state
                .metrics
                .submit_materialization_dead_letter_auto_replay_lease_conflicts_total
                .fetch_add(1, Ordering::Relaxed);
            let backoff_ms = decision_scoped_auto_replay_backoff_ms(
                &state.config,
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.current_backoff_ms)
                    .unwrap_or(0),
                DeadLetterAutoReplayBackoffClass::LeaseConflict,
                None,
            );
            update_dead_letter_auto_replay_runtime_state(
                state,
                Some(request_id.clone()),
                "lease_conflict",
                Some(now_ms.saturating_add(backoff_ms)),
                backoff_ms,
                Some(DeadLetterAutoReplayBackoffClass::LeaseConflict),
                Some("replay_lease_conflict".to_string()),
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.consecutive_deferred_runs)
                    .unwrap_or(0)
                    .saturating_add(1),
                Some(error.clone()),
                None,
            )
            .await;
            println!(
                "submit.materialization.dead_letter_auto_replay_lease_conflict request_id={} error={}",
                request_id, error
            );
        }
        DeadLetterReplayExecutionOutcome::InternalError { class, error } => {
            state
                .metrics
                .submit_materialization_dead_letter_replay_failures_total
                .fetch_add(1, Ordering::Relaxed);
            state
                .metrics
                .observe_dead_letter_replay_internal_error(DeadLetterReplaySource::Auto, class);
            record_dead_letter_replay_terminal_state(
                state,
                &request_id,
                now_ms,
                "failed",
                DeadLetterReplaySource::Auto,
                0,
                Some(
                    state
                        .config
                        .submit_materialization_dead_letter_auto_replay_max_entries
                        .clamp(1, 1024) as u64,
                ),
                auto_replay_operator,
                auto_replay_reason,
                false,
                Some(error.clone()),
                Some(class.as_str().to_string()),
            )
            .await;
            let backoff_ms = decision_scoped_auto_replay_backoff_from_base_ms(
                &state.config,
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.current_backoff_ms)
                    .unwrap_or(0),
                internal_error_backoff_base_ms(&state.config, class),
            );
            update_dead_letter_auto_replay_runtime_state(
                state,
                Some(request_id.clone()),
                "failed",
                Some(now_ms.saturating_add(backoff_ms)),
                backoff_ms,
                Some(DeadLetterAutoReplayBackoffClass::Failed),
                Some(class.as_str().to_string()),
                existing_auto_replay_state
                    .as_ref()
                    .map(|value| value.consecutive_deferred_runs)
                    .unwrap_or(0)
                    .saturating_add(1),
                Some(error.clone()),
                Some(class.as_str().to_string()),
            )
            .await;
            println!(
                "submit.materialization.dead_letter_auto_replay_failed request_id={} class={} error={}",
                request_id,
                class.as_str(),
                error
            );
        }
    }
}

async fn handle_replay_submit_materialization_dead_letter<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let request_id = request_id_for_logs(&req);
    let body_bytes = match body::to_bytes(req.into_body()).await {
        Ok(bytes) => bytes,
        Err(error) => {
            let replay_started_at_ms = now_ts_ms();
            state
                .metrics
                .submit_materialization_dead_letter_replay_failures_total
                .fetch_add(1, Ordering::Relaxed);
            record_dead_letter_replay_terminal_state(
                &state,
                &request_id,
                replay_started_at_ms,
                "failed",
                DeadLetterReplaySource::Manual,
                0,
                None,
                None,
                None,
                false,
                Some(format!("failed to read request body: {}", error)),
                None,
            )
            .await;
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("failed to read request body: {}", error) })
                        .to_string(),
                ))
                .unwrap();
        }
    };

    let replay_request = if body_bytes.is_empty() {
        DeadLetterReplayRequest::default()
    } else {
        match serde_json::from_slice::<DeadLetterReplayRequest>(&body_bytes) {
            Ok(payload) => payload,
            Err(error) => {
                let replay_started_at_ms = now_ts_ms();
                state
                    .metrics
                    .submit_materialization_dead_letter_replay_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                record_dead_letter_replay_terminal_state(
                    &state,
                    &request_id,
                    replay_started_at_ms,
                    "failed",
                    DeadLetterReplaySource::Manual,
                    0,
                    None,
                    None,
                    None,
                    false,
                    Some(format!("invalid replay request: {}", error)),
                    None,
                )
                .await;
                return Response::builder()
                    .status(StatusCode::BAD_REQUEST)
                    .header(CONTENT_TYPE, "application/json")
                    .header("Access-Control-Allow-Origin", "*")
                    .body(Body::from(
                        json!({ "error": format!("invalid replay request: {}", error) })
                            .to_string(),
                    ))
                    .unwrap();
            }
        }
    };

    let replay_operator = normalized_optional_string(replay_request.operator);
    let replay_reason = normalized_optional_string(replay_request.reason);
    let replay_force = replay_request.force.unwrap_or(false);
    let max_entries = replay_request.max_entries.unwrap_or(128).clamp(1, 1024);
    let replay_request_id = request_id.clone();
    match execute_dead_letter_replay(
        &state,
        DeadLetterReplayInvocation {
            request_id,
            max_entries,
            operator: replay_operator.clone(),
            reason: replay_reason.clone(),
            force: replay_force,
            source: DeadLetterReplaySource::Manual,
            record_policy_history: true,
            record_cooldown_history: true,
        },
    )
    .await
    {
        DeadLetterReplayExecutionOutcome::Completed {
            replayed,
            outbox_size,
            dead_letter_size,
        } => Response::builder()
            .status(StatusCode::OK)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "ok": true,
                    "replayed": replayed,
                    "outbox_size": outbox_size,
                    "dead_letter_size": dead_letter_size,
                })
                .to_string(),
            ))
            .unwrap(),
        DeadLetterReplayExecutionOutcome::PolicyBlocked {
            policy_block_reason,
            mut runbook_summary,
        } => {
            if let Some(runbook) = runbook_summary.as_object_mut() {
                runbook.insert("replay_blocked".to_string(), serde_json::Value::Bool(true));
                runbook.insert(
                    "replay_block_reason".to_string(),
                    serde_json::Value::String(policy_block_reason.to_string()),
                );
            }
            Response::builder()
                .status(StatusCode::CONFLICT)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": "dead-letter replay blocked by policy",
                        "policy_block": policy_block_reason,
                        "force_allowed": true,
                        "runbook": runbook_summary,
                    })
                    .to_string(),
                ))
                .unwrap()
        }
        DeadLetterReplayExecutionOutcome::CooldownBlocked {
            cooldown_until_ms,
            remaining_ms,
        } => Response::builder()
            .status(StatusCode::TOO_MANY_REQUESTS)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": "dead-letter replay cooldown active",
                    "cooldown_until_ms": cooldown_until_ms,
                    "remaining_ms": remaining_ms,
                    "force_allowed": true,
                })
                .to_string(),
            ))
            .unwrap(),
        DeadLetterReplayExecutionOutcome::LeaseConflict { error } => ops_conflict_response(error),
        DeadLetterReplayExecutionOutcome::InternalError { class, error } => {
            state
                .metrics
                .submit_materialization_dead_letter_replay_failures_total
                .fetch_add(1, Ordering::Relaxed);
            state
                .metrics
                .observe_dead_letter_replay_internal_error(DeadLetterReplaySource::Manual, class);
            record_dead_letter_replay_terminal_state(
                &state,
                &replay_request_id,
                now_ts_ms(),
                "failed",
                DeadLetterReplaySource::Manual,
                0,
                Some(max_entries as u64),
                replay_operator,
                replay_reason,
                replay_force,
                Some(error.clone()),
                Some(class.as_str().to_string()),
            )
            .await;
            Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": error, "error_class": class.as_str() }).to_string(),
                ))
                .unwrap()
        }
    }
}

async fn handle_ops_chain_commit_status<DB>(
    req: Request<Body>,
    state: AppState<DB>,
) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if state.config.ops_admin_token.is_none() {
        return ops_admin_not_found_response();
    }
    if !is_ops_admin_authorized(&req, &state) {
        return ops_admin_unauthorized_response();
    }

    let limit = query_param_usize(&req, "limit").unwrap_or(20).clamp(1, 100);
    let snapshot = collect_chain_commit_status_snapshot(&state).await;
    let dead_letter_entries = match current_chain_commit_dead_letter_entries(&state, limit).await {
        Ok(entries) => entries,
        Err(error) => {
            return Response::builder()
                .status(StatusCode::INTERNAL_SERVER_ERROR)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(json!({ "error": error }).to_string()))
                .unwrap();
        }
    };

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "enabled": snapshot.enabled,
                "retry_policy": {
                    "retry_interval_ms": state.config.submit_materialization_retry_interval_ms,
                    "max_attempts": state.config.submit_materialization_max_attempts,
                },
                "idempotency": {
                    "marker_ttl_secs": CHAIN_COMMIT_MARKER_TTL_SECS,
                    "marker_backend": if state.submit_coordinator.is_some() { "redis" } else { "in-memory" },
                },
                "outbox": {
                    "backend": snapshot.outbox_backend,
                    "batch_size": CHAIN_COMMIT_OUTBOX_BATCH_SIZE,
                    "size": snapshot.outbox_size,
                },
                "dead_letter": {
                    "backend": snapshot.dead_letter_backend,
                    "size": snapshot.dead_letter_size,
                    "limit": limit,
                    "count": dead_letter_entries.len(),
                    "has_more": snapshot.dead_letter_size > dead_letter_entries.len() as u64,
                    "entries": dead_letter_entries.into_iter().map(|entry| {
                        json!({
                            "commit_id": entry.commit_id,
                            "request_id": entry.request_id,
                            "tenant_namespace": entry.tenant_namespace,
                            "checkpoint_ts_ms": entry.checkpoint_ts_ms,
                            "cursor_opaque": entry.cursor_opaque,
                            "table_id": entry.store_set_record.table_id,
                            "attempts": entry.attempts,
                            "last_error": entry.last_error,
                        })
                    }).collect::<Vec<_>>(),
                },
                "writer_lease": {
                    "backend": snapshot.writer_lease_backend,
                    "active": snapshot.writer_lease_owner.is_some(),
                    "owner": snapshot.writer_lease_owner,
                    "ttl_ms": snapshot.writer_lease_ttl_ms,
                },
                "config": {
                    "dubhe_config_loaded": state.chain_commit_dubhe_config.is_some(),
                    "rpc_url": state.config.rpc_url,
                },
            })
            .to_string(),
        ))
        .unwrap()
}

