    let runbook_summary = build_dead_letter_runbook_summary(
        &state.config,
        now_ms,
        outbox_size,
        dead_letter_size,
        Some(&dead_letter_error_summary),
        replay_owner.is_some(),
        cooldown_active,
        replay_handoff.as_ref(),
        replay_status.as_ref(),
        replay_history.as_slice(),
    );
    let escalate = runbook_summary
        .get("escalate")
        .and_then(|value| value.as_bool())
        .unwrap_or(false);
    if !escalate {
        return Response::builder()
            .status(StatusCode::CONFLICT)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({
                    "error": "no active escalation to notify",
                    "runbook": runbook_summary,
                })
                .to_string(),
            ))
            .unwrap();
    }

    let notification = DeadLetterEscalationNotificationState {
        request_id,
        operator,
        channel,
        target,
        note,
        sent_at_ms: now_ms,
        runbook_fingerprint: runbook_summary
            .get("fingerprint")
            .and_then(|value| value.as_str())
            .unwrap_or_default()
            .to_string(),
        severity: runbook_summary
            .get("severity")
            .and_then(|value| value.as_str())
            .unwrap_or("none")
            .to_string(),
        recommended_action: runbook_summary
            .get("recommended_action")
            .and_then(|value| value.as_str())
            .unwrap_or("none")
            .to_string(),
    };

    if let Err(error) =
        update_dead_letter_replay_escalation_notification(&state, Some(notification.clone())).await
    {
        return Response::builder()
            .status(StatusCode::INTERNAL_SERVER_ERROR)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(json!({ "error": error }).to_string()))
            .unwrap();
    }

    Response::builder()
        .status(StatusCode::OK)
