fn v2_auth_context_for_tenant(tenant: Option<&ResolvedTenant>) -> AuthContext {
    let mut ctx = AuthContext::default();
    if let Some(namespace) = tenant.and_then(ResolvedTenant::namespace) {
        ctx.subject = Some(format!("deployment:{namespace}"));
        ctx.claims
            .insert(DEPLOYMENT_SCOPE_KEY.to_string(), namespace.to_string());
    }
    ctx
}

fn now_ts_ms() -> u64 {
    use std::time::{SystemTime, UNIX_EPOCH};

    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or(0)
}

fn submit_replay_ttl(config: &DubheChannelConfig) -> Duration {
    Duration::from_secs(config.submit_replay_ttl_secs)
}

fn submit_replay_key(req: &SubmitRequest) -> Option<SubmitReplayKey> {
    submit_replay_key_for_tenant(req, None)
}

fn submit_replay_key_for_tenant(
    req: &SubmitRequest,
    tenant: Option<&ResolvedTenant>,
) -> Option<SubmitReplayKey> {
    req.nonce.map(|nonce| SubmitReplayKey {
        tenant_namespace: tenant
            .and_then(ResolvedTenant::namespace)
            .map(str::to_string),
        chain: req.chain.clone(),
        sender: req.sender.clone(),
        nonce,
    })
}

fn scoped_submit_account_key(account_key: &str, tenant: Option<&ResolvedTenant>) -> String {
    match tenant.and_then(ResolvedTenant::namespace) {
        Some(namespace) => format!("{namespace}:{account_key}"),
        None => account_key.to_string(),
    }
}

fn normalize_optional_header_value(value: Option<&hyper::header::HeaderValue>) -> Option<String> {
    value
        .and_then(|value| value.to_str().ok())
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn parse_forwarded_ip(value: &str) -> Option<String> {
    value
        .split(',')
        .next()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .and_then(|value| value.parse::<IpAddr>().ok())
        .map(|ip| ip.to_string())
}

fn resolve_request_client(req: &Request<Body>) -> ResolvedClient {
    if let Some(forwarded_for) =
        normalize_optional_header_value(req.headers().get("x-forwarded-for"))
            .and_then(|value| parse_forwarded_ip(&value))
    {
        return ResolvedClient {
            client_id: forwarded_for,
            source: "x-forwarded-for",
        };
    }

    if let Some(real_ip) = normalize_optional_header_value(req.headers().get("x-real-ip"))
        .and_then(|value| value.parse::<IpAddr>().ok())
        .map(|ip| ip.to_string())
    {
        return ResolvedClient {
            client_id: real_ip,
            source: "x-real-ip",
        };
    }

    if let Some(remote_addr) = req.extensions().get::<SocketAddr>() {
        return ResolvedClient {
            client_id: remote_addr.ip().to_string(),
            source: "socket",
        };
    }

    ResolvedClient {
        client_id: "unknown".to_string(),
        source: "unknown",
    }
}

fn request_admission_kind_label(kind: RequestAdmissionKind) -> &'static str {
    match kind {
        RequestAdmissionKind::Submit => "submit",
        RequestAdmissionKind::Publish => "publish",
        RequestAdmissionKind::Subscribe => "subscribe",
    }
}

fn request_admission_limit(config: &DubheChannelConfig, kind: RequestAdmissionKind) -> u64 {
    match kind {
        RequestAdmissionKind::Submit => config.http_max_submit_inflight_per_client,
        RequestAdmissionKind::Publish => config.http_max_publish_inflight_per_client,
        RequestAdmissionKind::Subscribe => config.http_max_subscribe_inflight_per_client,
    }
}

fn observe_request_admission_rejection(metrics: &AppMetrics, kind: RequestAdmissionKind) {
    match kind {
        RequestAdmissionKind::Submit => {
            metrics
                .http_submit_inflight_admission_rejections_total
                .fetch_add(1, Ordering::Relaxed);
        }
        RequestAdmissionKind::Publish => {
            metrics
                .http_publish_inflight_admission_rejections_total
                .fetch_add(1, Ordering::Relaxed);
        }
        RequestAdmissionKind::Subscribe => {
            metrics
                .http_subscribe_inflight_admission_rejections_total
                .fetch_add(1, Ordering::Relaxed);
        }
    }
}

fn request_admission_rejection_response(
    config: &DubheChannelConfig,
    kind: RequestAdmissionKind,
    client: &ResolvedClient,
) -> Response<Body> {
    Response::builder()
        .status(StatusCode::TOO_MANY_REQUESTS)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "error": "client inflight admission limit exceeded",
                "admission": {
                    "kind": request_admission_kind_label(kind),
                    "client_id": client.client_id,
                    "client_source": client.source,
                    "limit": request_admission_limit(config, kind),
                }
            })
            .to_string(),
        ))
        .unwrap()
}

fn request_id_from_request(req: &Request<Body>) -> String {
    normalize_optional_header_value(req.headers().get(REQUEST_ID_HEADER))
        .unwrap_or_else(|| format!("{:032x}", random::<u128>()))
}

fn request_context(req: &Request<Body>) -> Option<&RequestContext> {
    req.extensions().get::<RequestContext>()
}

fn request_id_for_logs(req: &Request<Body>) -> String {
    request_context(req)
        .map(|ctx| ctx.request_id.clone())
        .unwrap_or_else(|| request_id_from_request(req))
}

fn attach_common_response_headers(
    mut response: Response<Body>,
    request_id: &str,
) -> Response<Body> {
    let headers = response.headers_mut();
    headers.insert(REQUEST_ID_HEADER, request_id.parse().unwrap());
    headers
        .entry("Access-Control-Allow-Origin")
        .or_insert_with(|| "*".parse().unwrap());
    headers
        .entry(ACCESS_CONTROL_EXPOSE_HEADERS)
        .or_insert_with(|| REQUEST_ID_HEADER.parse().unwrap());
    response
}

fn log_request_completed(
    request_id: &str,
    method: &hyper::Method,
    path: &str,
    status: StatusCode,
    duration_ms: u64,
    tenant: Option<&ResolvedTenant>,
    client: &ResolvedClient,
) {
    let tenant_namespace = tenant.and_then(ResolvedTenant::namespace).unwrap_or("-");
    let tenant_source = tenant.map(|tenant| tenant.source).unwrap_or("-");
    println!(
        "request.completed request_id={} method={} path={} status={} duration_ms={} tenant={} tenant_source={} client={} client_source={}",
        request_id,
        method,
        path,
        status.as_u16(),
        duration_ms,
        tenant_namespace,
        tenant_source,
        client.client_id,
        client.source,
    );
}

fn normalize_host_header(value: &str) -> String {
    value
        .trim()
        .split(':')
        .next()
        .unwrap_or_default()
        .trim()
        .trim_end_matches('.')
        .to_ascii_lowercase()
}

fn deployment_slug_from_host(host: &str, suffix: &str) -> Option<String> {
    let normalized_host = normalize_host_header(host);
    let normalized_suffix = normalize_host_header(suffix);
    if normalized_host == normalized_suffix {
        return None;
    }

    let needle = format!(".{normalized_suffix}");
    normalized_host
        .strip_suffix(&needle)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
}

fn resolve_request_tenant(
    req: &Request<Body>,
    config: &DubheChannelConfig,
) -> Result<ResolvedTenant, String> {
    if !config.hosted_mode {
        return Ok(ResolvedTenant::default());
    }

    let host = normalize_optional_header_value(req.headers().get(hyper::header::HOST));
    let host_slug = match (&host, &config.hosted_domain_suffix) {
        (Some(host), Some(suffix)) => deployment_slug_from_host(host, suffix),
        _ => None,
    };
    let header_deployment =
        normalize_optional_header_value(req.headers().get("x-obelisk-deployment"));
    let header_slug =
        normalize_optional_header_value(req.headers().get("x-obelisk-deployment-slug"));

    if config.allow_deployment_header_override
        && (header_deployment.is_some() || header_slug.is_some())
    {
        return Ok(ResolvedTenant {
            deployment_id: header_deployment,
            deployment_slug: header_slug,
            source: "header_override",
        });
    }

    if host_slug.is_some() {
        return Ok(ResolvedTenant {
            deployment_id: None,
            deployment_slug: host_slug,
            source: "host",
        });
    }

    if header_deployment.is_some() || header_slug.is_some() {
        return Ok(ResolvedTenant {
            deployment_id: header_deployment,
            deployment_slug: header_slug,
            source: "header",
        });
    }

    if let Some(default_deployment_id) = config.default_deployment_id.clone() {
        return Ok(ResolvedTenant {
            deployment_id: Some(default_deployment_id),
            deployment_slug: None,
            source: "default",
        });
    }

    Err("Hosted mode requires a deployment scope from subdomain, deployment header, or --default-deployment-id".to_string())
}

fn request_tenant(req: &Request<Body>) -> Option<&ResolvedTenant> {
    req.extensions().get::<ResolvedTenant>()
}

fn configured_sse_timer(timeout_secs: u64) -> Option<Pin<Box<Sleep>>> {
    (timeout_secs > 0).then(|| Box::pin(sleep(Duration::from_secs(timeout_secs))))
}

fn reset_sse_timer(timer: &mut Option<Pin<Box<Sleep>>>, timeout_secs: u64) {
    if timeout_secs == 0 {
        return;
    }

    if let Some(timer) = timer.as_mut() {
        timer
            .as_mut()
            .reset(TokioInstant::now() + Duration::from_secs(timeout_secs));
    }
}

async fn wait_optional_sse_timer(timer: &mut Option<Pin<Box<Sleep>>>) {
    match timer.as_mut() {
        Some(timer) => timer.as_mut().await,
        None => pending::<()>().await,
    }
}

fn sse_limit_rejection_response(error: &SseConnectionAdmissionError) -> Response<Body> {
    Response::builder()
        .status(StatusCode::TOO_MANY_REQUESTS)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!({
                "error": format!("SSE connection limit exceeded: {}", error.kind),
                "sse_governance": {
                    "kind": error.kind,
                    "scope": error.scope,
                    "global_connection_limit": error.global_limit,
                    "active_connections": error.active_connections,
                    "active_instances": error.active_instances,
                    "tenant_connection_limit": error.tenant_limit,
                    "tenant_active_connections": error.tenant_active_connections,
                    "client_connection_limit": error.client_limit,
                    "client_active_connections": error.client_active_connections,
                }
            })
            .to_string(),
        ))
        .unwrap()
}

fn scoped_data_key(data_key: &DataKey, tenant: Option<&ResolvedTenant>) -> ScopedDataKey {
    ScopedDataKey {
        tenant_namespace: tenant
            .and_then(ResolvedTenant::namespace)
            .map(str::to_string),
        data_key: data_key.clone(),
    }
}

fn scoped_account_key(
    account_key: &AccountKey,
    tenant: Option<&ResolvedTenant>,
) -> ScopedAccountKey {
    ScopedAccountKey {
        tenant_namespace: tenant
            .and_then(ResolvedTenant::namespace)
            .map(str::to_string),
        account_key: account_key.clone(),
    }
}

fn scoped_runtime_topic(topic: &str, tenant: Option<&ResolvedTenant>) -> String {
    match tenant.and_then(ResolvedTenant::namespace) {
        Some(namespace) => format!("{RUNTIME_TOPIC_SCOPE_PREFIX}.{namespace}.{topic}"),
        None => topic.to_string(),
    }
}

fn descoped_runtime_topic(topic: &str, tenant: Option<&ResolvedTenant>) -> String {
    match tenant.and_then(ResolvedTenant::namespace) {
        Some(namespace) => topic
            .strip_prefix(&format!("{RUNTIME_TOPIC_SCOPE_PREFIX}.{namespace}."))
            .unwrap_or(topic)
            .to_string(),
        None => topic.to_string(),
    }
}

fn ensure_deployment_scope_match(
    existing: Option<&str>,
    namespace: &str,
    field: &str,
) -> Result<(), String> {
    match existing {
        Some(existing) if existing != namespace => Err(format!(
            "{field} deployment scope {existing} does not match resolved tenant {namespace}"
        )),
        _ => Ok(()),
    }
}

fn validate_deployment_filter(filter: &FilterValue, namespace: &str) -> Result<(), String> {
    match filter {
        FilterValue::String(value) => {
            ensure_deployment_scope_match(Some(value.as_str()), namespace, "filter")
        }
        FilterValue::StringList(values) => {
            if values.len() == 1 && values.iter().any(|value| value == namespace) {
                Ok(())
            } else {
                Err(format!(
                    "filter deployment scope {:?} does not match resolved tenant {}",
                    values, namespace
                ))
            }
        }
    }
}

fn scope_snapshot_query(
    mut query: SnapshotQuery,
    tenant: Option<&ResolvedTenant>,
) -> Result<SnapshotQuery, String> {
    if let Some(namespace) = tenant.and_then(ResolvedTenant::namespace) {
        ensure_deployment_scope_match(
            query.scope.get(DEPLOYMENT_SCOPE_KEY).map(String::as_str),
            namespace,
            "query",
        )?;
        query
            .scope
            .insert(DEPLOYMENT_SCOPE_KEY.to_string(), namespace.to_string());
    }
    Ok(query)
}

fn scope_subscription_spec(
    mut spec: SubscriptionSpec,
    tenant: Option<&ResolvedTenant>,
) -> Result<SubscriptionSpec, String> {
    if let Some(namespace) = tenant.and_then(ResolvedTenant::namespace) {
        if let Some(existing) = spec.filters.get(DEPLOYMENT_SCOPE_KEY) {
            validate_deployment_filter(existing, namespace)?;
        }
        spec.filters.insert(
            DEPLOYMENT_SCOPE_KEY.to_string(),
            FilterValue::String(namespace.to_string()),
        );
        spec.topics = spec
            .topics
            .into_iter()
            .map(|topic| scoped_runtime_topic(&topic, tenant))
            .collect();
    }
    Ok(spec)
}

fn scope_event_envelope(
    mut event: EventEnvelope,
    tenant: Option<&ResolvedTenant>,
) -> Result<EventEnvelope, String> {
    if let Some(namespace) = tenant.and_then(ResolvedTenant::namespace) {
        ensure_deployment_scope_match(
            event.metadata.get(DEPLOYMENT_SCOPE_KEY).map(String::as_str),
            namespace,
            "event",
        )?;
        event
            .metadata
            .insert(DEPLOYMENT_SCOPE_KEY.to_string(), namespace.to_string());
        event.topic = scoped_runtime_topic(&event.topic, tenant);
    }
    Ok(event)
}

fn descope_event_envelope(
    mut event: EventEnvelope,
    tenant: Option<&ResolvedTenant>,
) -> EventEnvelope {
    event.topic = descoped_runtime_topic(&event.topic, tenant);
    event
}

