async fn enqueue_submit_materialization_outbox<DB>(
    app_state: &AppState<DB>,
    store_set_record: &StoreSetRecord,
    checkpoint_ts_ms: u64,
    cursor_opaque: &str,
    tenant: Option<&ResolvedTenant>,
    request_id: &str,
    error_class: SubmitMaterializationFailureClass,
    error: String,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let entry = SubmitMaterializationOutboxEntry {
        request_id: request_id.to_string(),
        tenant_namespace: tenant
            .and_then(ResolvedTenant::namespace)
            .map(str::to_string),
        checkpoint_ts_ms,
        cursor_opaque: cursor_opaque.to_string(),
        store_set_record: store_set_record.clone(),
        attempts: 0,
        last_error_class: error_class.clone(),
        last_error: error.clone(),
    };

    let mut persisted_to_redis = false;
    if let Some(coordinator) = &app_state.submit_coordinator {
        match coordinator.enqueue_materialization_entry(&entry).await {
            Ok(outbox_len) => {
                app_state
                    .metrics
                    .submit_materialization_redis_enqueue_total
                    .fetch_add(1, Ordering::Relaxed);
                set_submit_materialization_outbox_size(&app_state.metrics, outbox_len as usize);
                persisted_to_redis = true;
            }
            Err(redis_error) => {
                app_state
                    .metrics
                    .submit_materialization_redis_enqueue_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.materialization.enqueue_failed request_id={} tenant={} table_id={} backend=redis error={}",
                    request_id,
                    tenant.and_then(ResolvedTenant::namespace).unwrap_or("-"),
                    store_set_record.table_id,
                    redis_error,
                );
            }
        }
    }

    if !persisted_to_redis {
        let mut outbox = app_state.submit_materialization_outbox.write().await;
        outbox.push_back(entry);
        let outbox_len = outbox.len();
        drop(outbox);
        set_submit_materialization_outbox_size(&app_state.metrics, outbox_len);
    }

    app_state
        .metrics
        .submit_materialization_outbox_enqueued_total
        .fetch_add(1, Ordering::Relaxed);

    println!(
        "submit.materialization.enqueued request_id={} tenant={} table_id={} attempts=0 error_class={} error={}",
        request_id,
        tenant.and_then(ResolvedTenant::namespace).unwrap_or("-"),
        store_set_record.table_id,
        error_class.as_str(),
        error,
    );
}

async fn requeue_submit_materialization_outbox_entries<DB>(
    app_state: &AppState<DB>,
    entries: &mut Vec<SubmitMaterializationOutboxEntry>,
    request_id: &str,
    source: &'static str,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if entries.is_empty() {
        refresh_submit_materialization_outbox_size(app_state).await;
        return;
    }

    let mut persisted_to_redis = false;
    if let Some(coordinator) = &app_state.submit_coordinator {
        match coordinator.requeue_materialization_entries(entries).await {
            Ok(outbox_len) => {
                app_state
                    .metrics
                    .submit_materialization_redis_requeue_total
                    .fetch_add(1, Ordering::Relaxed);
                set_submit_materialization_outbox_size(&app_state.metrics, outbox_len as usize);
                persisted_to_redis = true;
            }
            Err(error) => {
                app_state
                    .metrics
                    .submit_materialization_redis_requeue_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.materialization.requeue_failed request_id={} source={} backend=redis error={}",
                    request_id, source, error
                );
            }
        }
    }

    if !persisted_to_redis {
        let mut outbox = app_state.submit_materialization_outbox.write().await;
        outbox.extend(entries.drain(..));
    }
    refresh_submit_materialization_outbox_size(app_state).await;
}

