async fn commit_chain_commit_outbox_entry<DB>(
    app_state: &AppState<DB>,
    entry: &SubmitChainCommitOutboxEntry,
) -> Result<(), anyhow::Error>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let Some(dubhe_config) = app_state.chain_commit_dubhe_config.as_ref() else {
        return Ok(());
    };
    let (table_id, key_tuple) = split_chain_commit_table_and_keys(&entry.store_set_record);
    if table_id.is_empty() {
        return Err(anyhow!(
            "missing table id in store_set_record key_tuple for commit_id={}",
            entry.commit_id
        ));
    }
    app_state
        .chain_commit_executor
        .commit(
            &app_state.config,
            dubhe_config.as_ref(),
            table_id,
            key_tuple,
            entry.store_set_record.value_tuple.clone(),
            entry.checkpoint_ts_ms.max(1),
        )
        .await
}

async fn process_submit_chain_commit_outbox_once<DB>(app_state: &AppState<DB>)
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    if app_state.chain_commit_dubhe_config.is_none() {
        return;
    }

    let request_id = format!("chain-commit-writer-{}", now_ts_ms());
    let lease = match acquire_chain_commit_writer_lease(app_state, &request_id).await {
        Ok(lease) => lease,
        Err(error) => {
            if !error.contains("already held") && !error.contains("timed out acquiring") {
                println!(
                    "submit.chain_commit.lease_acquire_failed request_id={} error={}",
                    request_id, error
                );
            }
            return;
        }
    };
    let local_writer_lease_acquired = matches!(&lease, ChainCommitWriterLeaseGuard::Local(_));
    if local_writer_lease_acquired {
        *app_state.submit_chain_commit_writer_owner.write().await = Some(ReplayLeaseOwnerInfo {
            request_id: request_id.clone(),
            holder: replay_lease_holder_identity(),
            acquired_at_ms: now_ts_ms(),
            backend: "in-memory".to_string(),
        });
    }

    let mut pending_entries = if let Some(coordinator) = &app_state.submit_coordinator {
        match coordinator
            .drain_chain_commit_entries(CHAIN_COMMIT_OUTBOX_BATCH_SIZE)
            .await
        {
            Ok(entries) => {
                if !entries.is_empty() {
                    app_state
                        .metrics
                        .submit_chain_commit_redis_drain_total
                        .fetch_add(1, Ordering::Relaxed);
                }
                entries
            }
            Err(error) => {
                app_state
                    .metrics
                    .submit_chain_commit_redis_drain_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.chain_commit.drain_failed request_id={} backend=redis error={}",
                    request_id, error
                );
                Vec::new()
            }
        }
    } else {
        Vec::new()
    };

    {
        let mut outbox = app_state.submit_chain_commit_outbox.write().await;
        pending_entries.extend(outbox.drain(..));
    }
    refresh_submit_chain_commit_outbox_size(app_state).await;

    if pending_entries.is_empty() {
        if local_writer_lease_acquired {
            *app_state.submit_chain_commit_writer_owner.write().await = None;
        }
        drop(lease);
        return;
    }

    let mut requeue = VecDeque::new();
    for mut entry in pending_entries {
        if let Some(coordinator) = &app_state.submit_coordinator {
            match coordinator
                .chain_commit_was_committed(&entry.commit_id)
                .await
            {
                Ok(true) => {
                    app_state
                        .metrics
                        .submit_chain_commit_marker_skipped_total
                        .fetch_add(1, Ordering::Relaxed);
                    println!(
                        "submit.chain_commit.skipped_already_committed request_id={} commit_id={}",
                        entry.request_id, entry.commit_id
                    );
                    continue;
                }
                Ok(false) => {}
                Err(error) => {
                    app_state
                        .metrics
                        .submit_chain_commit_marker_check_failures_total
                        .fetch_add(1, Ordering::Relaxed);
                    println!(
                        "submit.chain_commit.marker_check_failed request_id={} commit_id={} error={}",
                        entry.request_id, entry.commit_id, error
                    );
                }
            }
        }

        app_state
            .metrics
            .submit_chain_commit_outbox_retries_total
            .fetch_add(1, Ordering::Relaxed);
        match commit_chain_commit_outbox_entry(app_state, &entry).await {
            Ok(()) => {
                app_state
                    .metrics
                    .submit_chain_commit_outbox_recovered_total
                    .fetch_add(1, Ordering::Relaxed);
                if let Some(coordinator) = &app_state.submit_coordinator {
                    if let Err(error) = coordinator
                        .mark_chain_commit_committed(&entry.commit_id, CHAIN_COMMIT_MARKER_TTL_SECS)
                        .await
                    {
                        app_state
                            .metrics
                            .submit_chain_commit_marker_write_failures_total
                            .fetch_add(1, Ordering::Relaxed);
                        println!(
                            "submit.chain_commit.marker_write_failed request_id={} commit_id={} error={}",
                            entry.request_id, entry.commit_id, error
                        );
                    }
                }
                println!(
                    "submit.chain_commit.committed request_id={} tenant={} table_id={} commit_id={} attempts={}",
                    entry.request_id,
                    entry.tenant_namespace.as_deref().unwrap_or("-"),
                    entry.store_set_record.table_id,
                    entry.commit_id,
                    entry.attempts + 1
                );
            }
            Err(error) => {
                app_state
                    .metrics
                    .submit_chain_commit_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                entry.attempts += 1;
                entry.last_error = error.to_string();
                if entry.attempts >= app_state.config.submit_materialization_max_attempts {
                    app_state
                        .metrics
                        .submit_chain_commit_outbox_dropped_total
                        .fetch_add(1, Ordering::Relaxed);
                    enqueue_submit_chain_commit_dead_letter(app_state, entry).await;
                } else {
                    println!(
                        "submit.chain_commit.retry_scheduled request_id={} tenant={} table_id={} commit_id={} attempts={} error={}",
                        entry.request_id,
                        entry.tenant_namespace.as_deref().unwrap_or("-"),
                        entry.store_set_record.table_id,
                        entry.commit_id,
                        entry.attempts,
                        entry.last_error
                    );
                    requeue.push_back(entry);
                }
            }
        }
    }

    if !requeue.is_empty() {
        let mut requeue_vec = requeue.into_iter().collect::<Vec<_>>();
        requeue_submit_chain_commit_outbox_entries(
            app_state,
            &mut requeue_vec,
            "submit-chain-commit-worker",
            "chain_commit_outbox",
        )
        .await;
    }
    refresh_submit_chain_commit_dead_letter_size(app_state).await;
    if local_writer_lease_acquired {
        *app_state.submit_chain_commit_writer_owner.write().await = None;
    }
    drop(lease);
}

async fn drain_submit_materialization_dead_letter_entries<DB>(
    app_state: &AppState<DB>,
    max_entries: usize,
    request_id: &str,
) -> Vec<SubmitMaterializationOutboxEntry>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut drained = if let Some(coordinator) = &app_state.submit_coordinator {
        match coordinator
            .drain_materialization_dead_letter_entries(max_entries)
            .await
        {
            Ok(entries) => {
                if !entries.is_empty() {
                    app_state
                        .metrics
                        .submit_materialization_redis_drain_total
                        .fetch_add(1, Ordering::Relaxed);
                }
                entries
            }
            Err(error) => {
                app_state
                    .metrics
                    .submit_materialization_redis_drain_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.materialization.dead_letter_drain_failed request_id={} backend=redis error={}",
                    request_id, error
                );
                Vec::new()
            }
        }
    } else {
        Vec::new()
    };

    if drained.len() < max_entries {
        let mut dead_letter = app_state.submit_materialization_dead_letter.write().await;
        let remaining = max_entries - drained.len();
        for _ in 0..remaining {
            let Some(entry) = dead_letter.pop_front() else {
                break;
            };
            drained.push(entry);
        }
    }

    refresh_submit_materialization_dead_letter_size(app_state).await;
    drained
}

async fn materialize_store_set_record<DB>(
    app_state: &AppState<DB>,
    store_set_record: &StoreSetRecord,
    checkpoint_ts_ms: u64,
    cursor: Cursor,
    tenant: Option<&ResolvedTenant>,
    request_id: &str,
    source: &'static str,
    attempt: u64,
) -> Result<(), SubmitMaterializationFailure>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let data_key = data_key_from_store_set_record(store_set_record);
    let value = store_set_record.value_tuple.clone();

    let table_key = to_v2_table_key(&data_key);
    let snapshot_query = match scope_snapshot_query(table_key.to_snapshot_query(), tenant) {
        Ok(query) => query,
        Err(error) => {
            app_state
                .metrics
                .observe_submit_materialization_failure_class(
                    &SubmitMaterializationFailureClass::ScopeSnapshotQuery,
                );
            return Err(SubmitMaterializationFailure {
                class: SubmitMaterializationFailureClass::ScopeSnapshotQuery,
                error: format!("scope snapshot query failed: {}", error),
            });
        }
    };

    println!(
        "submit.materialization.runtime_started request_id={} tenant={} table_id={} source={} attempt={}",
        request_id,
        tenant.and_then(ResolvedTenant::namespace).unwrap_or("-"),
        store_set_record.table_id,
        source,
        attempt,
    );

    let snapshot_started_at = Instant::now();
    app_state
        .v2_runtime
        .upsert_snapshot(
            snapshot_query,
            v2_snapshot_result(value.clone(), Some(cursor)),
        )
        .await
        .map_err(|error| {
            app_state
                .metrics
                .submit_materialization_runtime_snapshot_failures_total
                .fetch_add(1, Ordering::Relaxed);
            SubmitMaterializationFailure {
                class: SubmitMaterializationFailureClass::RuntimeSnapshot,
                error: format!("upsert snapshot failed: {}", error),
            }
        })?;
    let snapshot_duration_ms = snapshot_started_at.elapsed().as_millis() as u64;
    app_state
        .metrics
        .observe_submit_materialization_runtime_snapshot(snapshot_duration_ms);
    println!(
        "submit.materialization.snapshot_succeeded request_id={} tenant={} table_id={} source={} attempt={} duration_ms={}",
        request_id,
        tenant.and_then(ResolvedTenant::namespace).unwrap_or("-"),
        store_set_record.table_id,
        source,
        attempt,
        snapshot_duration_ms,
    );

    let event = match scope_event_envelope(
        event_from_table(&table_key, value, checkpoint_ts_ms),
        tenant,
    ) {
        Ok(event) => event,
        Err(error) => {
            app_state
                .metrics
                .observe_submit_materialization_failure_class(
                    &SubmitMaterializationFailureClass::ScopeRuntimeEvent,
                );
            return Err(SubmitMaterializationFailure {
                class: SubmitMaterializationFailureClass::ScopeRuntimeEvent,
                error: format!("scope runtime event failed: {}", error),
            });
        }
    };
    let publish_started_at = Instant::now();
    app_state
        .v2_runtime
        .publish(&v2_auth_context_for_tenant(tenant), event)
        .await
        .map_err(|error| {
            app_state
                .metrics
                .submit_materialization_runtime_publish_failures_total
                .fetch_add(1, Ordering::Relaxed);
            SubmitMaterializationFailure {
                class: SubmitMaterializationFailureClass::RuntimePublish,
                error: format!("publish runtime event failed: {}", error),
            }
        })?;
    let publish_duration_ms = publish_started_at.elapsed().as_millis() as u64;
    app_state
        .metrics
        .observe_submit_materialization_runtime_publish(publish_duration_ms);
    println!(
        "submit.materialization.publish_succeeded request_id={} tenant={} table_id={} source={} attempt={} duration_ms={}",
        request_id,
        tenant.and_then(ResolvedTenant::namespace).unwrap_or("-"),
        store_set_record.table_id,
        source,
        attempt,
        publish_duration_ms,
    );

    Ok(())
}

async fn process_submit_materialization_outbox_once<DB>(app_state: &AppState<DB>)
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut pending_entries = if let Some(coordinator) = &app_state.submit_coordinator {
        match coordinator.drain_materialization_entries(256).await {
            Ok(entries) => {
                if !entries.is_empty() {
                    app_state
                        .metrics
                        .submit_materialization_redis_drain_total
                        .fetch_add(1, Ordering::Relaxed);
                }
                entries
            }
            Err(error) => {
                app_state
                    .metrics
                    .submit_materialization_redis_drain_failures_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.materialization.drain_failed backend=redis error={}",
                    error
                );
                Vec::new()
            }
        }
    } else {
        Vec::new()
    };

    {
        let mut outbox = app_state.submit_materialization_outbox.write().await;
        pending_entries.extend(outbox.drain(..));
    }
    refresh_submit_materialization_outbox_size(app_state).await;

    if pending_entries.is_empty() {
        app_state
            .metrics
            .submit_materialization_recovery_empty_polls_total
            .fetch_add(1, Ordering::Relaxed);
        return;
    }

    app_state
        .metrics
        .submit_materialization_recovery_batches_total
        .fetch_add(1, Ordering::Relaxed);
    app_state
        .metrics
        .submit_materialization_recovery_entries_total
        .fetch_add(pending_entries.len() as u64, Ordering::Relaxed);

    let mut requeue = VecDeque::new();
    for mut entry in pending_entries {
        app_state
            .metrics
            .submit_materialization_outbox_retries_total
            .fetch_add(1, Ordering::Relaxed);

        let tenant = outbox_tenant_from_namespace(entry.tenant_namespace.as_deref());
        let result = materialize_store_set_record(
            app_state,
            &entry.store_set_record,
            entry.checkpoint_ts_ms,
            Cursor {
                opaque: entry.cursor_opaque.clone(),
            },
            tenant.as_ref(),
            &entry.request_id,
            "recovery_outbox",
            entry.attempts + 1,
        )
        .await;

        match result {
            Ok(()) => {
                app_state
                    .metrics
                    .submit_materialization_outbox_recovered_total
                    .fetch_add(1, Ordering::Relaxed);
                println!(
                    "submit.materialization.recovered request_id={} tenant={} table_id={} attempts={}",
                    entry.request_id,
                    entry.tenant_namespace.as_deref().unwrap_or("-"),
                    entry.store_set_record.table_id,
                    entry.attempts + 1,
                );
            }
            Err(error) => {
                entry.attempts += 1;
                entry.last_error_class = error.class.clone();
                entry.last_error = error.error.clone();
                if entry.attempts >= app_state.config.submit_materialization_max_attempts {
                    app_state
                        .metrics
                        .submit_materialization_outbox_dropped_total
                        .fetch_add(1, Ordering::Relaxed);
                    enqueue_submit_materialization_dead_letter(app_state, entry).await;
                } else {
                    println!(
                        "submit.materialization.retry_scheduled request_id={} tenant={} table_id={} attempts={} error_class={} error={}",
                        entry.request_id,
                        entry.tenant_namespace.as_deref().unwrap_or("-"),
                        entry.store_set_record.table_id,
                        entry.attempts,
                        entry.last_error_class.as_str(),
                        entry.last_error,
                    );
                    requeue.push_back(entry);
                }
            }
        }
    }

    if !requeue.is_empty() {
        let mut requeue_vec = requeue.into_iter().collect::<Vec<_>>();
        requeue_submit_materialization_outbox_entries(
            app_state,
            &mut requeue_vec,
            "submit-materialization-worker",
            "recovery_outbox",
        )
        .await;
    }
}

async fn apply_store_set_record<DB>(
    app_state: &AppState<DB>,
    store_set_record: &StoreSetRecord,
    checkpoint_ts_ms: u64,
    cursor: Cursor,
    tenant: Option<&ResolvedTenant>,
    request_id: &str,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let data_key = data_key_from_store_set_record(store_set_record);
    let value = store_set_record.value_tuple.clone();

    cache_table_data(app_state, &data_key, tenant, value.clone()).await;
    println!(
        "✅ Inserted data into AppState.data {:?}, {:?}",
        data_key, value
    );

    let response = SubscribeTableResponse {
        data_key: data_key.clone(),
        value: value.clone(),
    };
    let _ = app_state
        .subscription_tx
        .send(ScopedSubscribeTableResponse {
            tenant_namespace: tenant
                .and_then(ResolvedTenant::namespace)
                .map(str::to_string),
            response,
        });

    if let Err(error) = materialize_store_set_record(
        app_state,
        store_set_record,
        checkpoint_ts_ms,
        cursor.clone(),
        tenant,
        request_id,
        "inline_submit",
        1,
    )
    .await
    {
        app_state
            .metrics
            .submit_materialization_failures_total
            .fetch_add(1, Ordering::Relaxed);
        enqueue_submit_materialization_outbox(
            app_state,
            store_set_record,
            checkpoint_ts_ms,
            &cursor.opaque,
            tenant,
            request_id,
            error.class,
            error.error,
        )
        .await;
    }

    enqueue_submit_chain_commit_outbox(
        app_state,
        store_set_record,
        checkpoint_ts_ms,
        &cursor.opaque,
        tenant,
        request_id,
    )
    .await;
}

async fn apply_submit_execution_outcome<DB>(
    app_state: &AppState<DB>,
    outcome: &SubmitExecutionOutcome,
    tenant: Option<&ResolvedTenant>,
    request_id: &str,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    for store_set_record in &outcome.store_set_records {
        apply_store_set_record(
            app_state,
            store_set_record,
            outcome.checkpoint_ts_ms,
            Cursor {
                opaque: outcome.cursor_opaque.clone(),
            },
            tenant,
            request_id,
        )
        .await;
    }
}

async fn persist_v2_table_snapshot<DB>(
    state: &AppState<DB>,
    data_key: &DataKey,
    value: Vec<Vec<u8>>,
    tenant: Option<&ResolvedTenant>,
) where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let query = match scope_snapshot_query(to_v2_table_key(data_key).to_snapshot_query(), tenant) {
        Ok(query) => query,
        Err(error) => {
            println!("❌ Failed to scope snapshot query: {}", error);
            return;
        }
    };
    if let Ok(existing) = state
        .v2_runtime
        .query(&v2_auth_context_for_tenant(tenant), query.clone())
        .await
    {
        if existing.found {
            return;
        }
    }
    let _ = state
        .v2_runtime
        .upsert_snapshot(
            query,
            v2_snapshot_result(
                value,
                Some(Cursor {
                    opaque: now_ts_ms().to_string(),
                }),
            ),
        )
        .await;
}

async fn read_table_data<DB>(
    state: &AppState<DB>,
    data_key: DataKey,
    tenant: Option<&ResolvedTenant>,
) -> Result<Vec<Vec<u8>>, String>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut table_data = cached_table_data(state, &data_key, tenant)
        .await
        .unwrap_or_default();

    if table_data.is_empty() {
        let client = SuiClientBuilder::default()
            .build(&state.config.rpc_url)
            .await
            .map_err(|e| e.to_string())?;
        let parent_object_id = ObjectID::from_hex_literal(
            "0x0b3baf7b3a0d822da137be8838bd729fce9ad411e590056d3f6d866ebcf049c3",
        )
        .map_err(|e| e.to_string())?;

        let account_key = AccountKey {
            dapp_key: data_key.dapp_key.clone(),
            account: data_key.account.clone(),
        };

        let scoped_account = scoped_account_key(&account_key, tenant);
        let dapp_data_key = state.dapp_data.read().await.get(&scoped_account).cloned();
        let parent_object_id = match dapp_data_key {
            Some(dapp_data_key) => dapp_data_key,
            None => {
                let name = DynamicFieldName {
                    type_: sui_types::TypeTag::from_str("0x8817b4976b6c607da01cea49d728f71d09274c82e9b163fa20c2382586f8aefc::dapp_service::AccountKey")
                        .map_err(|e| e.to_string())?,
                    value: json!({
                        "account": data_key.account,
                        "dapp_key": data_key.dapp_key,
                    }),
                };
                let dynamic_field_object = client
                    .read_api()
                    .get_dynamic_field_object(parent_object_id, name)
                    .await
                    .map_err(|e| e.to_string())?;
                let parent_object_id = dynamic_field_object
                    .clone()
                    .object_id()
                    .map_err(|e| e.to_string())?;
                state
                    .dapp_data
                    .write()
                    .await
                    .insert(scoped_account, parent_object_id);
                parent_object_id
            }
        };

        let mut value = vec![data_key.table.as_bytes().to_vec()];
        value.extend(data_key.key.clone());
        let name = DynamicFieldName {
            type_: sui_types::TypeTag::Vector(Box::new(sui_types::TypeTag::Vector(Box::new(
                sui_types::TypeTag::U8,
            )))),
            value: serde_json::Value::Array(
                value
                    .iter()
                    .map(|v| {
                        serde_json::Value::Array(
                            v.iter()
                                .map(|v| {
                                    serde_json::Value::Number(
                                        Number::from_u128(u128::from(*v)).unwrap(),
                                    )
                                })
                                .collect(),
                        )
                    })
                    .collect(),
            ),
        };

        let dynamic_field_object = client
            .read_api()
            .get_dynamic_field_object(parent_object_id, name)
            .await
            .map_err(|e| e.to_string())?;
        let parsed_move_object = dynamic_field_object
            .clone()
            .into_object()
            .map_err(|e| e.to_string())?
            .content
            .ok_or_else(|| "missing object content".to_string())?
            .try_into_move()
            .ok_or_else(|| "missing move object".to_string())?;
        let parsed_move_object_value = parsed_move_object
            .fields
            .field_value("value")
            .ok_or_else(|| "missing move field value".to_string())?;
        table_data = serde_json::from_str(
            parsed_move_object_value
                .to_json_value()
                .to_string()
                .as_str(),
        )
        .map_err(|e| e.to_string())?;
        cache_table_data(state, &data_key, tenant, table_data.clone()).await;
    }

    persist_v2_table_snapshot(state, &data_key, table_data.clone(), tenant).await;
    Ok(table_data)
}

fn table_key_from_spec(spec: &SubscriptionSpec) -> Option<V2TableKey> {
    let dapp_key = match spec.filters.get("dapp_key")? {
        FilterValue::String(value) => value.clone(),
        FilterValue::StringList(_) => return None,
    };
    let account = match spec.filters.get("account")? {
        FilterValue::String(value) => value.clone(),
        FilterValue::StringList(_) => return None,
    };
    let table = match spec.filters.get("table")? {
        FilterValue::String(value) => value.clone(),
        FilterValue::StringList(_) => return None,
    };
    let key = match spec.filters.get("key") {
        Some(FilterValue::String(value)) => serde_json::from_str(value).ok()?,
        Some(FilterValue::StringList(_)) => return None,
        None => vec![],
    };

    Some(V2TableKey {
        dapp_key,
        account,
        table,
        key,
    })
}

async fn handle_submit<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    println!(
        "submit.request_received request_id={} path=/submit tenant={}",
        request_id_for_logs(&req),
        request_tenant(&req)
            .and_then(ResolvedTenant::namespace)
            .unwrap_or("-"),
    );
    state
        .metrics
        .submit_requests_total
        .fetch_add(1, Ordering::Relaxed);
    if let Err(response) = ensure_write_gate_open(&state).await {
        return response;
    }
    let client = resolve_request_client(&req);
    let _admission_guard = match RequestAdmissionGuard::try_acquire(
        &state,
        RequestAdmissionKind::Submit,
        client.client_id.clone(),
    )
    .await
    {
        Ok(guard) => guard,
        Err(_) => {
            observe_request_admission_rejection(&state.metrics, RequestAdmissionKind::Submit);
            println!(
                    "request.admission_rejected request_id={} path=/submit client={} source={} kind=submit",
                    request_id_for_logs(&req),
                    client.client_id,
                    client.source,
                );
            return request_admission_rejection_response(
                &state.config,
                RequestAdmissionKind::Submit,
                &client,
            );
        }
    };
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let request_id = request_id_for_logs(&req);

    // Read body
    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "success": false,
                        "message": format!("Failed to read body: {}", e),
                        "data": null
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    };

    // Parse JSON
    let submit_request: Result<SubmitRequest, _> = serde_json::from_reader(whole_body.reader());

    match submit_request {
        Ok(req_data) => {
            let account_key = req_data.sender.clone();
            let _account_guard =
                match acquire_submit_account_guard_for_tenant(&state, &account_key, Some(&tenant))
                    .await
                {
                    Ok(guard) => guard,
                    Err(result) => return submit_route_response(result),
                };
            submit_route_response(
                process_submit_request_locked(&state, req_data, &tenant, &request_id).await,
            )
        }
        Err(e) => {
            println!(
                "submit.request_invalid_json request_id={} error={}",
                request_id, e
            );
            submit_route_response(submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Invalid JSON body: {}", e),
                None,
            ))
        }
    }
}

async fn process_submit_request_locked<DB>(
    state: &AppState<DB>,
    req_data: SubmitRequest,
    tenant: &ResolvedTenant,
    request_id: &str,
) -> SubmitRouteResult
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    println!(
        "submit.request_parsed request_id={} tenant={} chain={} backend={} sender={} nonce={} ptb_inputs={} ptb_commands={} signature_present={}",
        request_id,
        tenant.namespace().unwrap_or("-"),
        req_data.chain,
        state.execution_backend,
        req_data.sender,
        req_data.nonce.map(|nonce| nonce.to_string()).unwrap_or_else(|| "-".to_string()),
        req_data.ptb.inputs.len(),
        req_data.ptb.commands.len(),
        req_data.signature.is_some(),
    );

    let account_key = req_data.sender.clone();
    let request_fingerprint = match submit_request_fingerprint(&req_data) {
        Ok(fingerprint) => fingerprint,
        Err(e) => {
            println!(
                "submit.fingerprint_failed request_id={} sender={} error={}",
                request_id, req_data.sender, e
            );
            return submit_error_result(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("Failed to fingerprint request: {}", e),
                None,
            );
        }
    };

    let replay_key = submit_replay_key_for_tenant(&req_data, Some(tenant));
    if let Some(replay_key) = replay_key.clone() {
        let cached_response = match replay_cache_entry(state, &replay_key).await {
            Ok(cached_response) => cached_response,
            Err(result) => return result,
        };

        if let Some(cached_response) = cached_response {
            if cached_response.request_fingerprint == request_fingerprint {
                println!(
                    "submit.replayed request_id={} sender={} nonce={} tenant={}",
                    request_id,
                    replay_key.sender,
                    replay_key.nonce,
                    tenant.namespace().unwrap_or("-"),
                );
                return SubmitRouteResult {
                    status: StatusCode::OK,
                    body: cached_response.response_body,
                    replayed: true,
                };
            }
        }
    }

    let sender = match req_data.chain.as_str() {
        "sui" => match SuiAddress::from_str(&req_data.sender) {
            Ok(sender) => sender,
            Err(e) => {
                println!(
                    "submit.invalid_sender request_id={} chain=sui sender={} error={}",
                    request_id, req_data.sender, e
                );
                return submit_error_result(
                    StatusCode::BAD_REQUEST,
                    format!("Invalid sui sender: {}", e),
                    None,
                );
            }
        },
        "evm" => match evm_to_sui(&req_data.sender) {
            Ok(sender) => sender,
            Err(e) => {
                println!(
                    "submit.invalid_sender request_id={} chain=evm sender={} error={}",
                    request_id, req_data.sender, e
                );
                return submit_error_result(
                    StatusCode::BAD_REQUEST,
                    format!("Invalid evm sender: {}", e),
                    None,
                );
            }
        },
        "solana" => match solana_to_sui(&req_data.sender) {
            Ok(sender) => sender,
            Err(e) => {
                println!(
                    "submit.invalid_sender request_id={} chain=solana sender={} error={}",
                    request_id, req_data.sender, e
                );
                return submit_error_result(
                    StatusCode::BAD_REQUEST,
                    format!("Invalid solana sender: {}", e),
                    None,
                );
            }
        },
        _ => {
            println!(
                "submit.invalid_chain request_id={} chain={}",
                request_id, req_data.chain
            );
            return submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Invalid chain: {}", req_data.chain),
                None,
            );
        }
    };

    let current_nonce =
        match current_account_nonce_for_tenant(state, &account_key, Some(tenant)).await {
            Ok(current_nonce) => current_nonce,
            Err(result) => return result,
        };
    let expected_nonce = current_nonce + 1;

    match req_data.nonce {
        Some(submitted_nonce) => {
            if submitted_nonce != expected_nonce {
                println!(
                    "submit.invalid_nonce request_id={} sender={} expected={} got={}",
                    request_id, account_key, expected_nonce, submitted_nonce
                );
                return submit_error_result(
                    StatusCode::BAD_REQUEST,
                    format!(
                        "Invalid nonce: expected {}, got {}",
                        expected_nonce, submitted_nonce
                    ),
                    None,
                );
            }
        }
        None => {
            println!(
                "submit.missing_nonce request_id={} sender={} expected={}",
                request_id, account_key, expected_nonce
            );
            return submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Nonce is required: expected {}", expected_nonce),
                None,
            );
        }
    }

    let tx_digest = get_tx_digest_by_chain(req_data.chain.clone());
    let ptb = match convert_ptb_json_to_transaction(&req_data.ptb, &state.cache_db).await {
        Ok(ptb) => ptb,
        Err(e) => {
            println!(
                "submit.ptb_conversion_failed request_id={} sender={} error={}",
                request_id, req_data.sender, e
            );
            return submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Failed to convert PTB: {}", e),
                None,
            );
        }
    };

    println!(
        "submit.execution_started request_id={} sender={} tx_digest={:?}",
        request_id, req_data.sender, tx_digest
    );
    let execution = {
        let mut cache_db_guard = state.cache_db.write().await;
        state.submit_executor.execute(
            &state.config,
            &ptb,
            &mut *cache_db_guard,
            sender,
            tx_digest,
            &state.temp_storage_state,
        )
    };

    match execution {
        Ok(outcome) => {
            apply_submit_execution_outcome(state, &outcome, Some(tenant), request_id).await;

            let response_body = submit_response_body(
                true,
                "Submit request processed successfully",
                Some(json!({
                    "deployment": tenant.namespace(),
                    "chain": req_data.chain,
                    "sender": req_data.sender,
                    "nonce": req_data.nonce,
                    "tx_digest": format!("{:?}", tx_digest),
                    "sql_count": outcome.sqls.len(),
                })),
            );

            let replay_entry = SubmitReplayEntry {
                request_fingerprint: request_fingerprint.clone(),
                response_body: response_body.clone(),
                recorded_at: Instant::now(),
            };

            if let Err(result) = record_submit_success_for_tenant(
                state,
                &account_key,
                Some(tenant),
                expected_nonce,
                replay_key.as_ref(),
                replay_entry,
            )
            .await
            {
                return result;
            }

            println!(
                "submit.execution_succeeded request_id={} sender={} nonce={} sql_count={} materialized_records={}",
                request_id,
                account_key,
                expected_nonce,
                outcome.sqls.len(),
                outcome.store_set_records.len(),
            );

            SubmitRouteResult {
                status: StatusCode::OK,
                body: response_body,
                replayed: false,
            }
        }
        Err(e) => {
            println!(
                "submit.execution_failed request_id={} sender={} error={}",
                request_id, req_data.sender, e
            );
            submit_error_result(
                StatusCode::INTERNAL_SERVER_ERROR,
                format!("Failed to execute PTB: {}", e),
                None,
            )
        }
    }
}

async fn handle_submit_batch<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    println!(
        "submit_batch.request_received request_id={} tenant={}",
        request_id_for_logs(&req),
        request_tenant(&req)
            .and_then(ResolvedTenant::namespace)
            .unwrap_or("-"),
    );
    state
        .metrics
        .submit_requests_total
        .fetch_add(1, Ordering::Relaxed);
    if let Err(response) = ensure_write_gate_open(&state).await {
        return response;
    }
    let client = resolve_request_client(&req);
    let _admission_guard = match RequestAdmissionGuard::try_acquire(
        &state,
        RequestAdmissionKind::Submit,
        client.client_id.clone(),
    )
    .await
    {
        Ok(guard) => guard,
        Err(_) => {
            observe_request_admission_rejection(&state.metrics, RequestAdmissionKind::Submit);
            println!(
                    "request.admission_rejected request_id={} path=/submit_batch client={} source={} kind=submit",
                    request_id_for_logs(&req),
                    client.client_id,
                    client.source,
                );
            return request_admission_rejection_response(
                &state.config,
                RequestAdmissionKind::Submit,
                &client,
            );
        }
    };
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let request_id = request_id_for_logs(&req);

    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return submit_route_response(submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Failed to read body: {}", e),
                None,
            ));
        }
    };

    let submit_batch_request: Result<SubmitBatchRequest, _> =
        serde_json::from_reader(whole_body.reader());

    let req_data = match submit_batch_request {
        Ok(req_data) => req_data,
        Err(e) => {
            println!(
                "submit_batch.request_invalid_json request_id={} error={}",
                request_id, e
            );
            return submit_route_response(submit_error_result(
                StatusCode::BAD_REQUEST,
                format!("Invalid JSON body: {}", e),
                None,
            ));
        }
    };

    if req_data.requests.is_empty() {
        println!(
            "submit_batch.request_empty request_id={} tenant={}",
            request_id,
            tenant.namespace().unwrap_or("-"),
        );
        return submit_route_response(submit_error_result(
            StatusCode::BAD_REQUEST,
            "submit_batch requires at least one request",
            None,
        ));
    }

    let first_request = req_data.requests.first().unwrap();
    let sender = first_request.sender.clone();
    let chain = first_request.chain.clone();
    if req_data
        .requests
        .iter()
        .any(|request| request.sender != sender || request.chain != chain)
    {
        println!(
            "submit_batch.request_mixed_sender_or_chain request_id={} tenant={}",
            request_id,
            tenant.namespace().unwrap_or("-"),
        );
        return submit_route_response(submit_error_result(
            StatusCode::BAD_REQUEST,
            "submit_batch currently requires every request to use the same chain and sender",
            None,
        ));
    }

    let _account_guard =
        match acquire_submit_account_guard_for_tenant(&state, &sender, Some(&tenant)).await {
            Ok(guard) => guard,
            Err(result) => return submit_route_response(result),
        };

    let mut items = Vec::with_capacity(req_data.requests.len());
    let mut batch_success = true;
    let mut batch_message = "Submit batch processed successfully".to_string();
    println!(
        "submit_batch.request_parsed request_id={} tenant={} sender={} chain={} item_count={}",
        request_id,
        tenant.namespace().unwrap_or("-"),
        sender,
        chain,
        req_data.requests.len(),
    );

    for (index, submit_request) in req_data.requests.into_iter().enumerate() {
        let result =
            process_submit_request_locked(&state, submit_request, &tenant, &request_id).await;
        let item = submit_batch_item_from_result(index, &result);
        let item_failed = !item.success || !result.status.is_success();
        items.push(item);

        if item_failed {
            batch_success = false;
            batch_message = format!("Submit batch stopped at item {}", index);
            break;
        }
    }

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(
            json!(SubmitBatchResponse {
                success: batch_success,
                message: batch_message,
                data: items,
            })
            .to_string(),
        ))
        .unwrap()
}

async fn handle_get_table<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let request_id = request_id_for_logs(&req);
    println!(
        "query.table_request_received request_id={} tenant={}",
        request_id,
        request_tenant(&req)
            .and_then(ResolvedTenant::namespace)
            .unwrap_or("-"),
    );
    state
        .metrics
        .query_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();

    // Read body
    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "message": false,
                        "data": []
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    };

    // Parse JSON
    let req_data: Result<GetTableRequest, _> = serde_json::from_reader(whole_body.reader());

    match req_data {
        Ok(data) => {
            println!(
                "query.table_request_parsed request_id={} tenant={} dapp_key={} account={} table={} key_len={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                data.dapp_key,
                data.account,
                data.table,
                data.key.len(),
            );
            let data_key = DataKey {
                dapp_key: data.dapp_key,
                account: data.account,
                table: data.table,
                key: data.key,
            };
            let table_data = match read_table_data(&state, data_key, Some(&tenant)).await {
                Ok(table_data) => table_data,
                Err(error) => {
                    println!(
                        "query.table_read_failed request_id={} tenant={} error={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        error,
                    );
                    return Response::builder()
                        .status(StatusCode::INTERNAL_SERVER_ERROR)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(
                            json!({
                                "message": false,
                                "data": []
                            })
                            .to_string(),
                        ))
                        .unwrap();
                }
            };

            let mock_response = GetTableResponse {
                message: true,
                data: table_data,
            };

            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(serde_json::to_string(&mock_response).unwrap()))
                .unwrap()
        }
        Err(e) => {
            println!(
                "query.table_request_invalid_json request_id={} error={}",
                request_id, e
            );
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "message": false,
                        "data": []
                    })
                    .to_string(),
                ))
                .unwrap()
        }
    }
}

// Check if DataKey matches subscription criteria
fn matches_subscription(data_key: &DataKey, subscription: &SubscribeTableRequest) -> bool {
    // 1. Match only dapp_key
    if let Some(ref dapp_key) = subscription.dapp_key {
        if data_key.dapp_key != *dapp_key {
            return false;
        }
    } else {
        // If dapp_key is not specified, no match
        return false;
    }

    // 2. Match dapp_key and account
    if let Some(ref account) = subscription.account {
        if data_key.account != *account {
            return false;
        }
    }

    // 3. Match dapp_key, account and table
    if let Some(ref table) = subscription.table {
        if data_key.table != *table {
            return false;
        }
    }

    // 4. Match dapp_key, account, table and key
    if let Some(ref key) = subscription.key {
        if data_key.key != *key {
            return false;
        }
    }

    true
}

async fn handle_subscribe_table<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    println!("🔍 Processing /subscribe_table request");
    state
        .metrics
        .subscribe_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let client = resolve_request_client(&req);
    let request_id = request_id_for_logs(&req);
    let _admission_guard = match RequestAdmissionGuard::try_acquire(
        &state,
        RequestAdmissionKind::Subscribe,
        client.client_id.clone(),
    )
    .await
    {
        Ok(guard) => guard,
        Err(_) => {
            observe_request_admission_rejection(&state.metrics, RequestAdmissionKind::Subscribe);
            println!(
                    "request.admission_rejected request_id={} path=/subscribe_table client={} source={} kind=subscribe",
                    request_id,
                    client.client_id,
                    client.source,
                );
            return request_admission_rejection_response(
                &state.config,
                RequestAdmissionKind::Subscribe,
                &client,
            );
        }
    };

    // Read body
    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": format!("Failed to read body: {}", e)
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    };

    // Parse JSON
    let subscription: Result<SubscribeTableRequest, _> =
        serde_json::from_reader(whole_body.reader());

    match subscription {
        Ok(sub) => {
            println!("✅ Received subscribe_table request:");
            println!("  Dapp Key: {:?}", sub.dapp_key);
            println!("  Account: {:?}", sub.account);
            println!("  Table: {:?}", sub.table);
            println!("  Key: {:?}", sub.key);

            if let Err(response) = ensure_realtime_gate_open(&state).await {
                println!(
                    "sse.connection_rejected request_id={} path=/subscribe_table tenant={} client={} kind=realtime_gate",
                    request_id,
                    tenant.namespace().unwrap_or("-"),
                    client.client_id,
                );
                return response;
            }

            // Create subscription receiver
            let mut rx = state.subscription_tx.subscribe();
            let sse_guard = match SseConnectionGuard::try_open(
                &state,
                &request_id,
                tenant.namespace().map(str::to_string),
                Some(client.client_id.clone()),
            )
            .await
            {
                Ok(guard) => guard,
                Err(error) => {
                    state
                        .metrics
                        .sse_connection_rejections_total
                        .fetch_add(1, Ordering::Relaxed);
                    println!(
                        "sse.connection_rejected request_id={} path=/subscribe_table tenant={} client={} kind={} scope={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        client.client_id,
                        error.kind,
                        error.scope,
                    );
                    return sse_limit_rejection_response(&error);
                }
            };
            println!(
                "sse.connection_opened request_id={} path=/subscribe_table tenant={} client={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                client.client_id,
            );

            // Get currently matched data (initial data)
            let initial_data: Vec<SubscribeTableResponse> = {
                let data_map = state.data.read().await;
                let mut matched = Vec::new();
                for (data_key, value) in data_map.iter() {
                    if data_key.tenant_namespace == tenant.namespace().map(str::to_string)
                        && matches_subscription(&data_key.data_key, &sub)
                    {
                        matched.push(SubscribeTableResponse {
                            data_key: data_key.data_key.clone(),
                            value: value.clone(),
                        });
                    }
                }
                matched
            };

            // Create SSE stream: send initial data first, then continuously listen for new data
            let subscription_clone = sub.clone();
            let tenant_namespace = tenant.namespace().map(str::to_string);
            let sse_metrics = state.metrics.clone();
            let sse_topic_governance_state = state.topic_governance_state.clone();
            let sse_submit_coordinator = state.submit_coordinator.clone();
            let sse_realtime_gate_state = state.ops_realtime_gate_state.clone();
            let sse_topic_window_ms = state.config.ops_runtime_topic_window_ms;
            let sse_topic_publish_limit_per_window =
                state.config.ops_runtime_topic_publish_limit_per_window;
            let sse_max_lifetime_secs = state.config.sse_max_connection_lifetime_secs;
            let sse_idle_timeout_secs = state.config.sse_idle_timeout_secs;
            let sse_max_lagged_messages = state.config.sse_max_lagged_messages;
            let request_id = request_id.clone();
            let client_id = client.client_id.clone();
            let tenant_label = tenant.namespace().unwrap_or("-").to_string();
            let sse_stream = async_stream::stream! {
                let _sse_guard = sse_guard;
                let mut heartbeat = interval(Duration::from_secs(SSE_HEARTBEAT_INTERVAL_SECS));
                heartbeat.tick().await;
                let mut gate_poll = interval(Duration::from_millis(SSE_GATE_POLL_INTERVAL_MS));
                gate_poll.tick().await;
                let mut max_lifetime = configured_sse_timer(sse_max_lifetime_secs);
                let mut idle_timeout = configured_sse_timer(sse_idle_timeout_secs);
                let mut lagged_messages = 0u64;

                // First send initial data
                for item in initial_data {
                    let json = match serde_json::to_string(&item) {
                        Ok(json) => json,
                        Err(_) => continue,
                    };
                    observe_realtime_topic_delivery_shared(
                        &sse_topic_governance_state,
                        &sse_metrics,
                        sse_topic_window_ms,
                        sse_topic_publish_limit_per_window,
                        "table",
                        tenant_namespace.as_deref(),
                    ).await;
                    sse_metrics
                        .sse_events_total
                        .fetch_add(1, Ordering::Relaxed);
                    reset_sse_timer(&mut idle_timeout, sse_idle_timeout_secs);
                    yield Ok::<_, Infallible>(format!("data: {}\n\n", json));
                }

                // Then continuously listen for new data
                loop {
                    tokio::select! {
                        _ = wait_optional_sse_timer(&mut max_lifetime) => {
                            state
                                .metrics
                                .sse_connections_expired_total
                                .fetch_add(1, Ordering::Relaxed);
                            println!(
                                "sse.connection_closed request_id={} path=/subscribe_table tenant={} client={} reason=max_lifetime",
                                request_id,
                                tenant_label,
                                client_id,
                            );
                            break;
                        }
                        _ = wait_optional_sse_timer(&mut idle_timeout) => {
                            let disconnect_at_ms = now_ts_ms();
                            state
                                .metrics
                                .sse_idle_disconnects_total
                                .fetch_add(1, Ordering::Relaxed);
                            state
                                .metrics
                                .sse_last_idle_disconnect_at_ms
                                .store(disconnect_at_ms, Ordering::Relaxed);
                            println!(
                                "sse.connection_closed request_id={} path=/subscribe_table tenant={} client={} reason=idle_timeout",
                                request_id,
                                tenant_label,
                                client_id,
                            );
                            break;
                        }
                        _ = gate_poll.tick() => {
                            if let Some(gate_state) = realtime_gate_disconnect_state(
                                sse_submit_coordinator.as_ref(),
                                &sse_realtime_gate_state,
                                &sse_metrics,
                            )
                            .await
                            {
                                let disconnect_at_ms = now_ts_ms();
                                state
                                    .metrics
                                    .sse_gate_disconnects_total
                                    .fetch_add(1, Ordering::Relaxed);
                                state
                                    .metrics
                                    .sse_last_gate_disconnect_at_ms
                                    .store(disconnect_at_ms, Ordering::Relaxed);
                                println!(
                                    "sse.connection_closed request_id={} path=/subscribe_table tenant={} client={} reason=realtime_gate_disabled gate_request_id={} gate_operator={} gate_reason={}",
                                    request_id,
                                    tenant_label,
                                    client_id,
                                    gate_state.request_id,
                                    gate_state.operator,
                                    gate_state.reason.as_deref().unwrap_or("-"),
                                );
                                break;
                            }
                        }
                        _ = heartbeat.tick() => {
                            state
                                .metrics
                                .sse_heartbeats_total
                                .fetch_add(1, Ordering::Relaxed);
                            yield Ok::<_, Infallible>(": heartbeat\n\n".to_string());
                        }
                        recv = rx.recv() => match recv {
                            Ok(response) => {
                                if response.tenant_namespace != tenant_namespace {
                                    continue;
                                }
                            // Check if matches subscription criteria
                            if matches_subscription(&response.response.data_key, &subscription_clone) {
                                let json = match serde_json::to_string(&response.response) {
                                    Ok(json) => json,
                                    Err(_) => continue,
                                };
                                observe_realtime_topic_delivery_shared(
                                    &sse_topic_governance_state,
                                    &sse_metrics,
                                    sse_topic_window_ms,
                                    sse_topic_publish_limit_per_window,
                                    "table",
                                    tenant_namespace.as_deref(),
                                ).await;
                                sse_metrics
                                    .sse_events_total
                                    .fetch_add(1, Ordering::Relaxed);
                                reset_sse_timer(&mut idle_timeout, sse_idle_timeout_secs);
                                yield Ok(format!("data: {}\n\n", json));
                            }
                            },
                            Err(broadcast::error::RecvError::Closed) => {
                                println!(
                                    "sse.connection_closed request_id={} path=/subscribe_table tenant={} client={} reason=upstream_closed",
                                    request_id,
                                    tenant_label,
                                    client_id,
                                );
                                break;
                            },
                            Err(broadcast::error::RecvError::Lagged(skipped)) => {
                                let lagged_at_ms = now_ts_ms();
                                let skipped = skipped as u64;
                                lagged_messages = lagged_messages.saturating_add(skipped);
                                state
                                    .metrics
                                    .sse_lagged_messages_total
                                    .fetch_add(skipped, Ordering::Relaxed);
                                state
                                    .metrics
                                    .sse_last_lagged_message_at_ms
                                    .store(lagged_at_ms, Ordering::Relaxed);
                                if sse_max_lagged_messages > 0
                                    && lagged_messages >= sse_max_lagged_messages
                                {
                                    let disconnect_at_ms = now_ts_ms();
                                    state
                                        .metrics
                                        .sse_slow_consumer_disconnects_total
                                        .fetch_add(1, Ordering::Relaxed);
                                    state
                                        .metrics
                                        .sse_last_slow_consumer_disconnect_at_ms
                                        .store(disconnect_at_ms, Ordering::Relaxed);
                                    println!(
                                        "sse.connection_closed request_id={} path=/subscribe_table tenant={} client={} reason=slow_consumer lagged_messages={}",
                                        request_id,
                                        tenant_label,
                                        client_id,
                                        lagged_messages,
                                    );
                                    break;
                                }
                                continue;
                            }
                        }
                    }
                }
            };

            // Convert stream to hyper Body
            // hyper 0.14 uses Body::wrap_stream or directly uses Body::from()
            // If wrap_stream is not available, we need to use other methods
            use futures_util::StreamExt;
            let body_stream = sse_stream.map(|result| result.map(|s| bytes::Bytes::from(s)));
            let body = Body::wrap_stream(body_stream);

            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "text/event-stream")
                .header("Cache-Control", "no-cache")
                .header("Connection", "keep-alive")
                .header("Access-Control-Allow-Origin", "*")
                .header("Access-Control-Allow-Headers", "Cache-Control")
                .body(body)
                .unwrap()
        }
        Err(e) => {
            println!("❌ Failed to parse subscribe_table request: {}", e);
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": format!("Invalid JSON body: {}", e)
                    })
                    .to_string(),
                ))
                .unwrap()
        }
    }
}

async fn handle_v2_query<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .query_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let request_id = request_id_for_logs(&req);
    println!(
        "query.request_received request_id={} path=/v2/query tenant={}",
        request_id,
        tenant.namespace().unwrap_or("-"),
    );
    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Failed to read body: {}", e) }).to_string(),
                ))
                .unwrap();
        }
    };

    let request: Result<V2QueryRequest, _> = serde_json::from_reader(whole_body.reader());
    match request {
        Ok(request) => {
            println!(
                "query.request_parsed request_id={} tenant={} entity={} scope_keys={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                request.query.entity,
                request.query.scope.len(),
            );
            let scoped_query = match scope_snapshot_query(request.query.clone(), Some(&tenant)) {
                Ok(query) => query,
                Err(error) => {
                    println!(
                        "query.scope_failed request_id={} tenant={} error={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        error,
                    );
                    return Response::builder()
                        .status(StatusCode::BAD_REQUEST)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(json!({ "error": error }).to_string()))
                        .unwrap();
                }
            };
            let result = if request.query.entity == "table" {
                let table_key: V2TableKey = match serde_json::from_str(&request.query.key) {
                    Ok(table_key) => table_key,
                    Err(error) => {
                        println!(
                            "query.invalid_table_key request_id={} tenant={} error={}",
                            request_id,
                            tenant.namespace().unwrap_or("-"),
                            error,
                        );
                        return Response::builder()
                            .status(StatusCode::BAD_REQUEST)
                            .header(CONTENT_TYPE, "application/json")
                            .header("Access-Control-Allow-Origin", "*")
                            .body(Body::from(
                                json!({ "error": format!("Invalid table query key: {}", error) })
                                    .to_string(),
                            ))
                            .unwrap();
                    }
                };

                let data_key = DataKey {
                    dapp_key: table_key.dapp_key,
                    account: table_key.account,
                    table: table_key.table,
                    key: table_key.key,
                };

                match read_table_data(&state, data_key.clone(), Some(&tenant)).await {
                    Ok(data) => {
                        match state
                            .v2_runtime
                            .query(
                                &v2_auth_context_for_tenant(Some(&tenant)),
                                scoped_query.clone(),
                            )
                            .await
                        {
                            Ok(existing) if existing.found => existing,
                            _ => {
                                let result = v2_snapshot_result(
                                    data,
                                    Some(Cursor {
                                        opaque: now_ts_ms().to_string(),
                                    }),
                                );
                                let _ = state
                                    .v2_runtime
                                    .upsert_snapshot(scoped_query.clone(), result.clone())
                                    .await;
                                result
                            }
                        }
                    }
                    Err(error) => {
                        println!(
                            "query.table_read_failed request_id={} tenant={} error={}",
                            request_id,
                            tenant.namespace().unwrap_or("-"),
                            error,
                        );
                        return Response::builder()
                            .status(StatusCode::INTERNAL_SERVER_ERROR)
                            .header(CONTENT_TYPE, "application/json")
                            .header("Access-Control-Allow-Origin", "*")
                            .body(Body::from(json!({ "error": error }).to_string()))
                            .unwrap();
                    }
                }
            } else {
                match state
                    .v2_runtime
                    .query(&v2_auth_context_for_tenant(Some(&tenant)), scoped_query)
                    .await
                {
                    Ok(result) => result,
                    Err(error) => {
                        println!(
                            "query.runtime_failed request_id={} tenant={} error={}",
                            request_id,
                            tenant.namespace().unwrap_or("-"),
                            error,
                        );
                        return Response::builder()
                            .status(StatusCode::INTERNAL_SERVER_ERROR)
                            .header(CONTENT_TYPE, "application/json")
                            .header("Access-Control-Allow-Origin", "*")
                            .body(Body::from(
                                json!({ "error": error.to_string() }).to_string(),
                            ))
                            .unwrap();
                    }
                }
            };

            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(serde_json::to_string(&result).unwrap()))
                .unwrap()
        }
        Err(error) => {
            println!(
                "query.request_invalid_json request_id={} error={}",
                request_id, error
            );
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Invalid JSON body: {}", error) }).to_string(),
                ))
                .unwrap()
        }
    }
}

async fn handle_v2_subscribe<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .subscribe_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let client = resolve_request_client(&req);
    let request_id = request_id_for_logs(&req);
    let _admission_guard = match RequestAdmissionGuard::try_acquire(
        &state,
        RequestAdmissionKind::Subscribe,
        client.client_id.clone(),
    )
    .await
    {
        Ok(guard) => guard,
        Err(_) => {
            observe_request_admission_rejection(&state.metrics, RequestAdmissionKind::Subscribe);
            println!(
                    "request.admission_rejected request_id={} path=/v2/subscribe client={} source={} kind=subscribe",
                    request_id,
                    client.client_id,
                    client.source,
                );
            return request_admission_rejection_response(
                &state.config,
                RequestAdmissionKind::Subscribe,
                &client,
            );
        }
    };
    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Failed to read body: {}", e) }).to_string(),
                ))
                .unwrap();
        }
    };

    let request: Result<V2SubscribeRequest, _> = serde_json::from_reader(whole_body.reader());
    match request {
        Ok(request) => {
            let scoped_spec = match scope_subscription_spec(request.spec.clone(), Some(&tenant)) {
                Ok(spec) => spec,
                Err(error) => {
                    return Response::builder()
                        .status(StatusCode::BAD_REQUEST)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(json!({ "error": error }).to_string()))
                        .unwrap();
                }
            };

            if let Err(response) = ensure_realtime_gate_open(&state).await {
                println!(
                    "sse.connection_rejected request_id={} path=/v2/subscribe tenant={} client={} kind=realtime_gate",
                    request_id,
                    tenant.namespace().unwrap_or("-"),
                    client.client_id,
                );
                return response;
            }
            let initial_event = if let Some(table_key) = table_key_from_spec(&request.spec) {
                let data_key = DataKey {
                    dapp_key: table_key.dapp_key.clone(),
                    account: table_key.account.clone(),
                    table: table_key.table.clone(),
                    key: table_key.key.clone(),
                };
                match read_table_data(&state, data_key, Some(&tenant)).await {
                    Ok(data) => scope_event_envelope(
                        event_from_table(&table_key, data, now_ts_ms()),
                        Some(&tenant),
                    )
                    .ok()
                    .map(|event| descope_event_envelope(event, Some(&tenant))),
                    Err(_) => None,
                }
            } else {
                None
            };

            let stream = match state
                .v2_runtime
                .subscribe(&v2_auth_context_for_tenant(Some(&tenant)), scoped_spec)
                .await
            {
                Ok(stream) => stream,
                Err(error) => {
                    return Response::builder()
                        .status(StatusCode::INTERNAL_SERVER_ERROR)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(
                            json!({ "error": error.to_string() }).to_string(),
                        ))
                        .unwrap();
                }
            };

            let sse_guard = match SseConnectionGuard::try_open(
                &state,
                &request_id,
                tenant.namespace().map(str::to_string),
                Some(client.client_id.clone()),
            )
            .await
            {
                Ok(guard) => guard,
                Err(error) => {
                    state
                        .metrics
                        .sse_connection_rejections_total
                        .fetch_add(1, Ordering::Relaxed);
                    println!(
                        "sse.connection_rejected request_id={} path=/v2/subscribe tenant={} client={} kind={} scope={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        client.client_id,
                        error.kind,
                        error.scope,
                    );
                    return sse_limit_rejection_response(&error);
                }
            };
            println!(
                "sse.connection_opened request_id={} path=/v2/subscribe tenant={} client={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                client.client_id,
            );
            let sse_metrics = state.metrics.clone();
            let sse_topic_governance_state = state.topic_governance_state.clone();
            let sse_submit_coordinator = state.submit_coordinator.clone();
            let sse_realtime_gate_state = state.ops_realtime_gate_state.clone();
            let sse_topic_window_ms = state.config.ops_runtime_topic_window_ms;
            let sse_topic_publish_limit_per_window =
                state.config.ops_runtime_topic_publish_limit_per_window;
            let sse_max_lifetime_secs = state.config.sse_max_connection_lifetime_secs;
            let sse_idle_timeout_secs = state.config.sse_idle_timeout_secs;
            let sse_max_lagged_messages = state.config.sse_max_lagged_messages;
            let request_id = request_id.clone();
            let client_id = client.client_id.clone();
            let tenant_label = tenant.namespace().unwrap_or("-").to_string();
            let tenant_namespace = tenant.namespace().map(str::to_string);
            let sse_stream = async_stream::stream! {
                let _sse_guard = sse_guard;
                let mut heartbeat = interval(Duration::from_secs(SSE_HEARTBEAT_INTERVAL_SECS));
                heartbeat.tick().await;
                let mut gate_poll = interval(Duration::from_millis(SSE_GATE_POLL_INTERVAL_MS));
                gate_poll.tick().await;
                let mut max_lifetime = configured_sse_timer(sse_max_lifetime_secs);
                let mut idle_timeout = configured_sse_timer(sse_idle_timeout_secs);
                let mut lagged_messages = 0u64;

                if let Some(initial_event) = initial_event {
                    if let Ok(json) = serde_json::to_string(&initial_event) {
                        observe_realtime_topic_delivery_shared(
                            &sse_topic_governance_state,
                            &sse_metrics,
                            sse_topic_window_ms,
                            sse_topic_publish_limit_per_window,
                            &initial_event.topic,
                            tenant_namespace.as_deref(),
                        ).await;
                        sse_metrics
                            .sse_events_total
                            .fetch_add(1, Ordering::Relaxed);
                        reset_sse_timer(&mut idle_timeout, sse_idle_timeout_secs);
                        yield Ok::<_, Infallible>(format!("data: {}\n\n", json));
                    }
                }

                futures_util::pin_mut!(stream);
                loop {
                    tokio::select! {
                        _ = wait_optional_sse_timer(&mut max_lifetime) => {
                            state
                                .metrics
                                .sse_connections_expired_total
                                .fetch_add(1, Ordering::Relaxed);
                            println!(
                                "sse.connection_closed request_id={} path=/v2/subscribe tenant={} client={} reason=max_lifetime",
                                request_id,
                                tenant_label,
                                client_id,
                            );
                            break;
                        }
                        _ = wait_optional_sse_timer(&mut idle_timeout) => {
                            let disconnect_at_ms = now_ts_ms();
                            state
                                .metrics
                                .sse_idle_disconnects_total
                                .fetch_add(1, Ordering::Relaxed);
                            state
                                .metrics
                                .sse_last_idle_disconnect_at_ms
                                .store(disconnect_at_ms, Ordering::Relaxed);
                            println!(
                                "sse.connection_closed request_id={} path=/v2/subscribe tenant={} client={} reason=idle_timeout",
                                request_id,
                                tenant_label,
                                client_id,
                            );
                            break;
                        }
                        _ = gate_poll.tick() => {
                            if let Some(gate_state) = realtime_gate_disconnect_state(
                                sse_submit_coordinator.as_ref(),
                                &sse_realtime_gate_state,
                                &sse_metrics,
                            )
                            .await
                            {
                                let disconnect_at_ms = now_ts_ms();
                                state
                                    .metrics
                                    .sse_gate_disconnects_total
                                    .fetch_add(1, Ordering::Relaxed);
                                state
                                    .metrics
                                    .sse_last_gate_disconnect_at_ms
                                    .store(disconnect_at_ms, Ordering::Relaxed);
                                println!(
                                    "sse.connection_closed request_id={} path=/v2/subscribe tenant={} client={} reason=realtime_gate_disabled gate_request_id={} gate_operator={} gate_reason={}",
                                    request_id,
                                    tenant_label,
                                    client_id,
                                    gate_state.request_id,
                                    gate_state.operator,
                                    gate_state.reason.as_deref().unwrap_or("-"),
                                );
                                break;
                            }
                        }
                        _ = heartbeat.tick() => {
                            state
                                .metrics
                                .sse_heartbeats_total
                                .fetch_add(1, Ordering::Relaxed);
                            yield Ok::<_, Infallible>(": heartbeat\n\n".to_string());
                        }
                        event = stream.next() => {
                            match event {
                                Some(Ok(event)) => {
                                    let event = descope_event_envelope(event, Some(&tenant));
                                    if let Ok(json) = serde_json::to_string(&event) {
                                        observe_realtime_topic_delivery_shared(
                                            &sse_topic_governance_state,
                                            &sse_metrics,
                                            sse_topic_window_ms,
                                            sse_topic_publish_limit_per_window,
                                            &event.topic,
                                            tenant_namespace.as_deref(),
                                        ).await;
                                        sse_metrics
                                            .sse_events_total
                                            .fetch_add(1, Ordering::Relaxed);
                                        reset_sse_timer(&mut idle_timeout, sse_idle_timeout_secs);
                                        yield Ok(format!("data: {}\n\n", json));
                                    }
                                }
                                Some(Err(error)) => {
                                    if let Some(skipped) = lagged_messages_from_channel_error(&error) {
                                        let lagged_at_ms = now_ts_ms();
                                        lagged_messages = lagged_messages.saturating_add(skipped);
                                        state
                                            .metrics
                                            .sse_lagged_messages_total
                                            .fetch_add(skipped, Ordering::Relaxed);
                                        state
                                            .metrics
                                            .sse_last_lagged_message_at_ms
                                            .store(lagged_at_ms, Ordering::Relaxed);
                                        if sse_max_lagged_messages > 0
                                            && lagged_messages >= sse_max_lagged_messages
                                        {
                                            let disconnect_at_ms = now_ts_ms();
                                            state
                                                .metrics
                                                .sse_slow_consumer_disconnects_total
                                                .fetch_add(1, Ordering::Relaxed);
                                            state
                                                .metrics
                                                .sse_last_slow_consumer_disconnect_at_ms
                                                .store(disconnect_at_ms, Ordering::Relaxed);
                                            println!(
                                                "sse.connection_closed request_id={} path=/v2/subscribe tenant={} client={} reason=slow_consumer lagged_messages={}",
                                                request_id,
                                                tenant_label,
                                                client_id,
                                                lagged_messages,
                                            );
                                            break;
                                        }
                                        continue;
                                    }
                                    println!(
                                        "sse.connection_stream_error request_id={} path=/v2/subscribe tenant={} client={} code={} error={}",
                                        request_id,
                                        tenant_label,
                                        client_id,
                                        error.code,
                                        error.message,
                                    );
                                    continue;
                                }
                                None => {
                                    println!(
                                        "sse.connection_closed request_id={} path=/v2/subscribe tenant={} client={} reason=upstream_closed",
                                        request_id,
                                        tenant_label,
                                        client_id,
                                    );
                                    break;
                                }
                            }
                        }
                    }
                }
            };

            let body_stream = sse_stream.map(|result| result.map(bytes::Bytes::from));
            let body = Body::wrap_stream(body_stream);

            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "text/event-stream")
                .header("Cache-Control", "no-cache")
                .header("Connection", "keep-alive")
                .header("Access-Control-Allow-Origin", "*")
                .header("Access-Control-Allow-Headers", "Cache-Control")
                .body(body)
                .unwrap()
        }
        Err(error) => Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(
                json!({ "error": format!("Invalid JSON body: {}", error) }).to_string(),
            ))
            .unwrap(),
    }
}

async fn handle_v2_publish<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .publish_requests_total
        .fetch_add(1, Ordering::Relaxed);
    if let Err(response) = ensure_write_gate_open(&state).await {
        return response;
    }
    let client = resolve_request_client(&req);
    let _admission_guard = match RequestAdmissionGuard::try_acquire(
        &state,
        RequestAdmissionKind::Publish,
        client.client_id.clone(),
    )
    .await
    {
        Ok(guard) => guard,
        Err(_) => {
            observe_request_admission_rejection(&state.metrics, RequestAdmissionKind::Publish);
            println!(
                    "request.admission_rejected request_id={} path=/v2/publish client={} source={} kind=publish",
                    request_id_for_logs(&req),
                    client.client_id,
                    client.source,
                );
            return request_admission_rejection_response(
                &state.config,
                RequestAdmissionKind::Publish,
                &client,
            );
        }
    };
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let request_id = request_id_for_logs(&req);
    println!(
        "publish.request_received request_id={} tenant={}",
        request_id,
        tenant.namespace().unwrap_or("-"),
    );

    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Failed to read body: {}", e) }).to_string(),
                ))
                .unwrap();
        }
    };

    let request: Result<V2PublishRequest, _> = serde_json::from_reader(whole_body.reader());
    match request {
        Ok(request) => {
            let mut event = request.event;
            println!(
                "publish.request_parsed request_id={} tenant={} topic={} event_id_present={} metadata_keys={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                event.topic,
                !event.id.is_empty(),
                event.metadata.len(),
            );
            if event.id.is_empty() {
                event.id = format!("evt-{:016x}", random::<u64>());
            }
            if event.ts_ms == 0 {
                event.ts_ms = now_ts_ms();
            }
            let scoped_event = match scope_event_envelope(event.clone(), Some(&tenant)) {
                Ok(event) => event,
                Err(error) => {
                    println!(
                        "publish.scope_failed request_id={} tenant={} topic={} error={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        event.topic,
                        error,
                    );
                    return Response::builder()
                        .status(StatusCode::BAD_REQUEST)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(json!({ "error": error }).to_string()))
                        .unwrap();
                }
            };
            let topic_snapshot = match admit_realtime_topic_publish(
                &state,
                &event.topic,
                &scoped_event.topic,
                Some(&tenant),
                &request_id,
            )
            .await
            {
                Ok(snapshot) => snapshot,
                Err(admission) => {
                    let snapshot = &admission.local;
                    let scope = if admission.cluster.is_some() {
                        "cluster"
                    } else {
                        "local"
                    };
                    println!(
                        "publish.rejected request_id={} tenant={} topic={} reason=topic_publish_limit scope={} window_ms={} limit={} publish_count={} rejected_publishes={} cluster_publish_count={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        snapshot.scoped_topic,
                        scope,
                        state.config.ops_runtime_topic_window_ms,
                        state.config.ops_runtime_topic_publish_limit_per_window,
                        snapshot.publish_count,
                        snapshot.rejected_publishes,
                        admission
                            .cluster
                            .as_ref()
                            .map(|cluster| cluster.publish_count.to_string())
                            .unwrap_or_else(|| "-".to_string()),
                    );
                    return Response::builder()
                        .status(StatusCode::TOO_MANY_REQUESTS)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(
                            json!({
                                "error": "realtime topic publish limit exceeded",
                                "topic_governance": {
                                    "scope": scope,
                                    "tenant": snapshot.tenant_namespace,
                                    "topic": snapshot.public_topic,
                                    "scoped_topic": snapshot.scoped_topic,
                                    "window_ms": state.config.ops_runtime_topic_window_ms,
                                    "publish_limit_per_window": state.config.ops_runtime_topic_publish_limit_per_window,
                                    "window_started_at_ms": snapshot.window_started_at_ms,
                                    "remaining_window_ms": snapshot.remaining_window_ms,
                                    "publish_count": snapshot.publish_count,
                                    "delivery_count": snapshot.delivery_count,
                                    "rejected_publishes": snapshot.rejected_publishes,
                                    "hotspot_active": snapshot.hotspot_active,
                                    "cluster_window_started_at_ms": admission
                                        .cluster
                                        .as_ref()
                                        .map(|cluster| cluster.window_started_at_ms),
                                    "cluster_remaining_window_ms": admission
                                        .cluster
                                        .as_ref()
                                        .map(|cluster| cluster.remaining_window_ms),
                                    "cluster_publish_count": admission
                                        .cluster
                                        .as_ref()
                                        .map(|cluster| cluster.publish_count),
                                    "cluster_rejected_publishes": admission
                                        .cluster
                                        .as_ref()
                                        .map(|cluster| cluster.rejected_publishes),
                                }
                            })
                            .to_string(),
                        ))
                        .unwrap();
                }
            };
            println!(
                "publish.topic_admitted request_id={} tenant={} topic={} window_ms={} publish_count={} delivery_count={} hotspot_active={} cluster_publish_count={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                topic_snapshot.local.scoped_topic,
                state.config.ops_runtime_topic_window_ms,
                topic_snapshot.local.publish_count,
                topic_snapshot.local.delivery_count,
                topic_snapshot.local.hotspot_active,
                topic_snapshot
                    .cluster
                    .as_ref()
                    .map(|cluster| cluster.publish_count.to_string())
                    .unwrap_or_else(|| "-".to_string()),
            );

            match state
                .v2_runtime
                .publish(
                    &v2_auth_context_for_tenant(Some(&tenant)),
                    scoped_event.clone(),
                )
                .await
            {
                Ok(()) => {
                    println!(
                        "publish.succeeded request_id={} tenant={} topic={} event_id={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        scoped_event.topic,
                        scoped_event.id,
                    );
                    Response::builder()
                        .status(StatusCode::OK)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(
                            serde_json::to_string(&descope_event_envelope(
                                scoped_event,
                                Some(&tenant),
                            ))
                            .unwrap(),
                        ))
                        .unwrap()
                }
                Err(error) => {
                    println!(
                        "publish.failed request_id={} tenant={} topic={} error={}",
                        request_id,
                        tenant.namespace().unwrap_or("-"),
                        scoped_event.topic,
                        error,
                    );
                    Response::builder()
                        .status(StatusCode::INTERNAL_SERVER_ERROR)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(
                            json!({ "error": error.to_string() }).to_string(),
                        ))
                        .unwrap()
                }
            }
        }
        Err(error) => {
            println!(
                "publish.request_invalid_json request_id={} error={}",
                request_id, error
            );
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Invalid JSON body: {}", error) }).to_string(),
                ))
                .unwrap()
        }
    }
}

fn compile_sui_move_call_intent(sender: &str, intent: SuiMoveCallIntent) -> PtbJson {
    let move_call = MoveCallInner {
        package: intent.package,
        module: intent.module,
        function: intent.function,
        type_arguments: intent.type_arguments,
        arguments: intent.arguments,
    };

    PtbJson {
        version: 2,
        sender: Some(sender.to_string()),
        expiration: None,
        gas_data: Some(json!({
            "budget": null,
            "price": null,
            "owner": null,
            "payment": null
        })),
        inputs: intent.inputs,
        commands: vec![PtbCommand::MoveCall {
            data: MoveCallData { move_call },
        }],
    }
}

fn sha256_hex(bytes: &[u8]) -> String {
    hex::encode(Sha256::digest(bytes))
}

fn build_riscv_artifact_for_intent(
    sender: &str,
    intent: &SuiMoveCallIntent,
    ptb: &PtbJson,
) -> std::result::Result<RiscvProgramArtifact, IntentCompileError> {
    let mut instructions = Vec::new();
    for (input_index, input) in intent.inputs.iter().enumerate() {
        match input {
            PtbInput::UnresolvedObject { data } => {
                instructions.push(RiscvProgramInstruction::ResolveObject {
                    object_id: data.unresolved_object.object_id.clone(),
                });
            }
            PtbInput::Pure { data } => {
                let bytes =
                    general_purpose::STANDARD
                        .decode(&data.pure.bytes)
                        .map_err(|error| {
                            IntentCompileError::new(
                                "invalid_pure_input_encoding",
                                format!("Failed to decode pure input {}: {}", input_index, error),
                            )
                            .with_detail(json!({ "input_index": input_index }))
                        })?;
                instructions.push(RiscvProgramInstruction::PureInput {
                    input_index,
                    bytes_len: bytes.len(),
                    bytes_hash: sha256_hex(&bytes),
                });
            }
        }
    }
    instructions.push(RiscvProgramInstruction::MoveCall {
        package: intent.package.clone(),
        module: intent.module.clone(),
        function: intent.function.clone(),
        type_arguments: intent.type_arguments.clone(),
        arguments_len: intent.arguments.len(),
    });

    let program_material = serde_json::to_vec(&json!({
        "sender": sender,
        "package": intent.package,
        "module": intent.module,
        "function": intent.function,
        "type_arguments": intent.type_arguments,
        "arguments": intent.arguments,
        "inputs": intent.inputs,
        "instructions": instructions,
    }))
    .map_err(|error| {
        IntentCompileError::new(
            "riscv_program_serialize_failed",
            format!("Failed to serialize RISC-V program material: {}", error),
        )
    })?;
    let program_hash = sha256_hex(&program_material);
    let ptb_hash = serde_json::to_vec(ptb)
        .map(|encoded| sha256_hex(&encoded))
        .map_err(|error| {
            IntentCompileError::new(
                "ptb_hash_serialize_failed",
                format!("Failed to serialize PTB for hashing: {}", error),
            )
        })?;

    Ok(RiscvProgramArtifact {
        version: 1,
        entry: "sui_move_call".to_string(),
        artifact_id: format!("rva_{}", &program_hash[..16]),
        program_hash,
        ptb_hash,
        instructions,
        notes: vec![
            "deterministic_lowering_v1".to_string(),
            "intent_to_riscv_program_artifact".to_string(),
        ],
    })
}

fn compile_sui_move_call_intent_via_riscv(
    sender: &str,
    intent: SuiMoveCallIntent,
) -> std::result::Result<IntentCompileOutcome, IntentCompileError> {
    println!("intent.compile backend=riscv mode=lower_to_sui_ptb");
    for argument in &intent.arguments {
        let ArgumentJson::Input { index, .. } = argument;
        if (*index as usize) >= intent.inputs.len() {
            return Err(IntentCompileError::new(
                "invalid_argument_index",
                format!(
                    "Argument input index {} is out of bounds for {} inputs",
                    index,
                    intent.inputs.len()
                ),
            )
            .with_detail(json!({
                "input_index": index,
                "inputs_len": intent.inputs.len()
            })));
        }
    }

    let ptb = compile_sui_move_call_intent(sender, intent.clone());
    let artifact = build_riscv_artifact_for_intent(sender, &intent, &ptb)?;
    Ok(IntentCompileOutcome {
        ptb,
        artifact: Some(artifact),
    })
}

async fn handle_intent_compile<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    state
        .metrics
        .query_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();
    let request_id = request_id_for_logs(&req);
    println!(
        "intent.compile.request_received request_id={} tenant={}",
        request_id,
        tenant.namespace().unwrap_or("-"),
    );

    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Failed to read body: {}", e) }).to_string(),
                ))
                .unwrap();
        }
    };

    let request: Result<IntentCompileRequest, _> = serde_json::from_reader(whole_body.reader());
    let request = match request {
        Ok(request) => request,
        Err(error) => {
            println!(
                "intent.compile.request_invalid_json request_id={} error={}",
                request_id, error
            );
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({ "error": format!("Invalid JSON body: {}", error) }).to_string(),
                ))
                .unwrap();
        }
    };

    let chain = request.chain.unwrap_or_else(|| "sui".to_string());
    if chain != "sui" {
        let error = IntentCompileErrorInfo {
            code: "unsupported_intent_chain".to_string(),
            message: format!(
                "Unsupported intent chain '{}': currently only 'sui' is supported",
                chain
            ),
            detail: Some(json!({ "chain": chain })),
        };
        return Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(intent_compile_response_body(
                false,
                error.message.clone(),
                None,
                Some(error),
            )))
            .unwrap();
    }

    if let Err(error) = SuiAddress::from_str(&request.sender) {
        let error = IntentCompileErrorInfo {
            code: "invalid_sui_sender".to_string(),
            message: format!("Invalid sui sender: {}", error),
            detail: Some(json!({ "sender": request.sender })),
        };
        return Response::builder()
            .status(StatusCode::BAD_REQUEST)
            .header(CONTENT_TYPE, "application/json")
            .header("Access-Control-Allow-Origin", "*")
            .body(Body::from(intent_compile_response_body(
                false,
                error.message.clone(),
                None,
                Some(error),
            )))
            .unwrap();
    }

    let nonce = match request.nonce {
        Some(nonce) => nonce,
        None => {
            match current_account_nonce_for_tenant(&state, &request.sender, Some(&tenant)).await {
                Ok(current_nonce) => current_nonce + 1,
                Err(error_result) => {
                    let message = serde_json::from_str::<SubmitResponse>(&error_result.body)
                        .map(|payload| payload.message)
                        .unwrap_or_else(|_| "Failed to resolve nonce for sender".to_string());
                    return Response::builder()
                        .status(error_result.status)
                        .header(CONTENT_TYPE, "application/json")
                        .header("Access-Control-Allow-Origin", "*")
                        .body(Body::from(intent_compile_response_body(
                            false,
                            message,
                            None,
                            Some(IntentCompileErrorInfo {
                                code: "nonce_resolution_failed".to_string(),
                                message: "Failed to resolve nonce for sender".to_string(),
                                detail: Some(json!({ "sender": request.sender })),
                            }),
                        )))
                        .unwrap();
                }
            }
        }
    };

    let compile_outcome = match state
        .intent_compiler
        .compile(&request.sender, request.intent)
    {
        Ok(outcome) => outcome,
        Err(error) => {
            println!(
                "intent.compile.failed request_id={} backend={} error={}",
                request_id,
                state.intent_compiler.backend(),
                error
            );
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(intent_compile_response_body(
                    false,
                    format!("Failed to compile intent: {}", error),
                    None,
                    Some(error.to_response_error()),
                )))
                .unwrap();
        }
    };
    let ptb = compile_outcome.ptb;

    let submit = SubmitRequest {
        chain: chain.clone(),
        sender: request.sender.clone(),
        nonce: Some(nonce),
        ptb: ptb.clone(),
        signature: None,
    };

    let response = IntentCompileData {
        chain,
        backend: state.intent_compiler.backend().to_string(),
        sender: request.sender,
        nonce,
        ptb,
        submit,
        artifact: compile_outcome.artifact,
    };

    Response::builder()
        .status(StatusCode::OK)
        .header(CONTENT_TYPE, "application/json")
        .header("Access-Control-Allow-Origin", "*")
        .body(Body::from(intent_compile_response_body(
            true,
            format!(
                "Intent compiled to Sui PTB successfully via {} backend",
                state.intent_compiler.backend()
            ),
            Some(response),
            None,
        )))
        .unwrap()
}

async fn handle_get_nonce<DB>(req: Request<Body>, state: AppState<DB>) -> Response<Body>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let request_id = request_id_for_logs(&req);
    println!(
        "nonce.request_received request_id={} tenant={}",
        request_id,
        request_tenant(&req)
            .and_then(ResolvedTenant::namespace)
            .unwrap_or("-"),
    );
    state
        .metrics
        .nonce_requests_total
        .fetch_add(1, Ordering::Relaxed);
    let tenant = request_tenant(&req).cloned().unwrap_or_default();

    let whole_body = match body::aggregate(req.into_body()).await {
        Ok(body) => body,
        Err(e) => {
            return Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": format!("Failed to read body: {}", e)
                    })
                    .to_string(),
                ))
                .unwrap();
        }
    };

    let req_data: Result<GetNonceRequest, _> = serde_json::from_reader(whole_body.reader());

    match req_data {
        Ok(data) => {
            println!(
                "nonce.request_parsed request_id={} tenant={} sender={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                data.sender,
            );

            let nonce =
                match current_account_nonce_for_tenant(&state, &data.sender, Some(&tenant)).await {
                    Ok(current_nonce) => current_nonce + 1,
                    Err(result) => return submit_route_response(result),
                };

            let response = GetNonceResponse { nonce };
            println!(
                "nonce.succeeded request_id={} tenant={} sender={} next_nonce={}",
                request_id,
                tenant.namespace().unwrap_or("-"),
                data.sender,
                response.nonce,
            );

            Response::builder()
                .status(StatusCode::OK)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(serde_json::to_string(&response).unwrap()))
                .unwrap()
        }
        Err(e) => {
            println!(
                "nonce.request_invalid_json request_id={} error={}",
                request_id, e
            );
            Response::builder()
                .status(StatusCode::BAD_REQUEST)
                .header(CONTENT_TYPE, "application/json")
                .header("Access-Control-Allow-Origin", "*")
                .body(Body::from(
                    json!({
                        "error": format!("Invalid JSON body: {}", e)
                    })
                    .to_string(),
                ))
                .unwrap()
        }
    }
}

fn get_tx_digest_by_chain(chain: String) -> TransactionDigest {
    if chain == "evm" {
        let tx_digest = TransactionDigest::random();
        let mut tx_digest_inner = tx_digest.into_inner();
        tx_digest_inner[0] = 0xDB;
        tx_digest_inner[1] = 0xDB;
        tx_digest_inner[2] = 0x01;
        tx_digest_inner[3] = 0xE1;
        TransactionDigest::new(tx_digest_inner)
    } else if chain == "solana" {
        let tx_digest = TransactionDigest::random();
        let mut tx_digest_inner = tx_digest.into_inner();
        tx_digest_inner[0] = 0xDB;
        tx_digest_inner[1] = 0xDB;
        tx_digest_inner[2] = 0x01;
        tx_digest_inner[3] = 0xE2;
        TransactionDigest::new(tx_digest_inner)
    } else {
        // Default to SUI
        TransactionDigest::random()
    }
}

// ========== PTB Conversion Functions ==========

/// Convert PtbJson to ProgrammableTransaction
async fn convert_ptb_json_to_transaction<'a, DB>(
    ptb_json: &'a PtbJson,
    cache_db: &Arc<RwLock<CacheDB<DB>>>,
) -> Result<ProgrammableTransaction>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut inputs = Vec::new();

    // Process inputs
    for input in &ptb_json.inputs {
        match input {
            PtbInput::UnresolvedObject { data } => {
                let object_id = ObjectID::from_hex_literal(&data.unresolved_object.object_id)?;

                // Get object from cache_db
                let object = {
                    let mut cache_db_guard = cache_db.write().await;
                    DBTrait::object(&mut *cache_db_guard, object_id)?
                        .ok_or_else(|| anyhow!("Object not found: {}", object_id))?
                };

                // Determine object type and create corresponding CallArg
                let call_arg = if let Some(initial_shared_version) = object.owner.start_version() {
                    // SharedObject
                    CallArg::Object(ObjectArg::SharedObject {
                        id: object.id(),
                        initial_shared_version,
                        mutable: true,
                    })
                } else {
                    // ImmOrOwnedObject
                    CallArg::Object(ObjectArg::ImmOrOwnedObject(
                        object.compute_object_reference(),
                    ))
                };

                inputs.push(call_arg);
            }
            PtbInput::Pure { data } => {
                // Decode base64 bytes
                let bytes = general_purpose::STANDARD
                    .decode(&data.pure.bytes)
                    .map_err(|e| anyhow!("Failed to decode base64: {}", e))?;
                inputs.push(CallArg::Pure(bytes));
            }
        }
    }

    // Process commands
    let mut commands = Vec::new();
    for command in &ptb_json.commands {
        match command {
            PtbCommand::MoveCall { data } => {
                let move_call = &data.move_call;

                // Parse package ID
                let package = ObjectID::from_hex_literal(&move_call.package)?;

                // Parse module and function (directly use String)
                let module = move_call.module.clone();
                let function = move_call.function.clone();

                let type_arguments: Vec<TypeInput> = move_call
                    .type_arguments
                    .iter()
                    .map(|tag| {
                        TypeTag::from_str(tag)
                            .map(TypeInput::from)
                            .map_err(|e| anyhow!("Failed to parse type argument '{}': {}", tag, e))
                    })
                    .collect::<Result<Vec<_>>>()?;

                // Parse arguments
                let arguments: Vec<Argument> = move_call
                    .arguments
                    .iter()
                    .map(|arg| match arg {
                        ArgumentJson::Input { index, .. } => Argument::Input(*index),
                    })
                    .collect();

                commands.push(Command::MoveCall(Box::new(ProgrammableMoveCall {
                    package,
                    module,
                    function,
                    type_arguments,
                    arguments,
                })));
            }
        }
    }

    Ok(ProgrammableTransaction { inputs, commands })
}

// ========== Address Conversion Functions ==========

/// Convert hex string to bytes
/// Supports both "0x..." and raw hex formats
fn hex_string_to_bytes(hex_str: &str) -> Result<Vec<u8>> {
    let hex_str = hex_str.trim();
    let hex_str = if hex_str.starts_with("0x") || hex_str.starts_with("0X") {
        &hex_str[2..]
    } else {
        hex_str
    };

    hex::decode(hex_str).map_err(|e| anyhow!("Invalid hex string: {}", e))
}

/// Convert EVM address to SUI address
/// EVM address is 20 bytes, SUI address is 32 bytes
/// Format: [12 zero bytes][20 bytes EVM address]
pub fn evm_to_sui(evm_address_str: &str) -> Result<SuiAddress> {
    let evm_bytes = hex_string_to_bytes(evm_address_str)?;

    if evm_bytes.len() != 20 {
        return Err(anyhow!(
            "Invalid EVM address length: expected 20 bytes, got {}",
            evm_bytes.len()
        ));
    }

    // Create 32-byte array: 12 zero bytes + 20 EVM address bytes
    let mut sui_bytes = vec![0u8; 12];
    sui_bytes.extend_from_slice(&evm_bytes);

    // Convert to SuiAddress
    SuiAddress::from_bytes(&sui_bytes).map_err(|e| anyhow!("Failed to create SuiAddress: {}", e))
}

/// Convert Solana address to SUI address
/// Solana address is Base58 encoded 32 bytes
/// Direct use of 32 bytes from Base58 decode
pub fn solana_to_sui(solana_address_str: &str) -> Result<SuiAddress> {
    // Decode Base58 string
    let solana_bytes = bs58::decode(solana_address_str)
        .into_vec()
        .map_err(|e| anyhow!("Invalid Solana Base58 address: {}", e))?;

    if solana_bytes.len() != 32 {
        return Err(anyhow!(
            "Invalid Solana address length: expected 32 bytes, got {}",
            solana_bytes.len()
        ));
    }

    // Convert to SuiAddress
    SuiAddress::from_bytes(&solana_bytes).map_err(|e| anyhow!("Failed to create SuiAddress: {}", e))
}

#[derive(Debug)]
struct RiscvKernelPreflightStats {
    resolved_objects: usize,
    pure_inputs: usize,
    move_calls: usize,
}

fn riscv_artifact_from_programmable_transaction(
    ptb: &ProgrammableTransaction,
) -> Result<RiscvProgramArtifact, anyhow::Error> {
    let mut instructions = Vec::new();

    for (input_index, input) in ptb.inputs.iter().enumerate() {
        match input {
            CallArg::Object(object_arg) => {
                let object_id = match object_arg {
                    ObjectArg::ImmOrOwnedObject((id, _, _)) => *id,
                    ObjectArg::SharedObject { id, .. } => *id,
                    ObjectArg::Receiving((id, _, _)) => *id,
                };
                instructions.push(RiscvProgramInstruction::ResolveObject {
                    object_id: object_id.to_string(),
                });
            }
            CallArg::Pure(bytes) => {
                instructions.push(RiscvProgramInstruction::PureInput {
                    input_index,
                    bytes_len: bytes.len(),
                    bytes_hash: sha256_hex(bytes),
                });
            }
            CallArg::FundsWithdrawal(_) => {
                return Err(anyhow!(
                    "riscv kernel does not support funds_withdrawal call args yet"
                ));
            }
        }
    }

    for command in &ptb.commands {
        match command {
            Command::MoveCall(move_call) => {
                instructions.push(RiscvProgramInstruction::MoveCall {
                    package: move_call.package.to_string(),
                    module: move_call.module.to_string(),
                    function: move_call.function.to_string(),
                    type_arguments: move_call
                        .type_arguments
                        .iter()
                        .map(|tag| tag.to_string())
                        .collect(),
                    arguments_len: move_call.arguments.len(),
                });
            }
            unsupported => {
                return Err(anyhow!(
                    "riscv kernel only supports move_call commands currently; found {:?}",
                    unsupported
                ));
            }
        }
    }

    let artifact_material = serde_json::to_vec(&json!({
        "entry": "submit_ptb",
        "instructions": instructions,
    }))?;
    let program_hash = sha256_hex(&artifact_material);
    let ptb_hash = sha256_hex(&bcs::to_bytes(ptb)?);
    Ok(RiscvProgramArtifact {
        version: 1,
        entry: "submit_ptb".to_string(),
        artifact_id: format!("rva_exec_{}", &program_hash[..16]),
        program_hash,
        ptb_hash,
        instructions,
        notes: vec![
            "submit_preflight_kernel_v1".to_string(),
            "deterministic_object_resolution".to_string(),
        ],
    })
}

fn run_riscv_preflight<DB>(
    cache_db: &mut CacheDB<DB>,
    artifact: &RiscvProgramArtifact,
) -> Result<RiscvKernelPreflightStats, anyhow::Error>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let mut stats = RiscvKernelPreflightStats {
        resolved_objects: 0,
        pure_inputs: 0,
        move_calls: 0,
    };

    for instruction in &artifact.instructions {
        match instruction {
            RiscvProgramInstruction::ResolveObject { object_id } => {
                let object = ObjectID::from_hex_literal(object_id).map_err(|error| {
                    anyhow!(
                        "riscv preflight failed to parse object id '{}': {}",
                        object_id,
                        error
                    )
                })?;
                let found = DBTrait::object(cache_db, object)?;
                if found.is_none() {
                    return Err(anyhow!(
                        "riscv preflight object resolution failed: {} not found",
                        object_id
                    ));
                }
                stats.resolved_objects += 1;
            }
            RiscvProgramInstruction::PureInput { bytes_len, .. } => {
                if *bytes_len > 8 * 1024 {
                    return Err(anyhow!(
                        "riscv preflight pure input rejected: {} bytes exceeds 8192",
                        bytes_len
                    ));
                }
                stats.pure_inputs += 1;
            }
            RiscvProgramInstruction::MoveCall {
                module, function, ..
            } => {
                if module.is_empty() || function.is_empty() {
                    return Err(anyhow!(
                        "riscv preflight move_call rejected: module/function cannot be empty"
                    ));
                }
                stats.move_calls += 1;
            }
        }
    }

    if stats.move_calls == 0 {
        return Err(anyhow!(
            "riscv preflight rejected PTB: at least one move_call is required"
        ));
    }

    Ok(stats)
}

fn execute_submit_ptb_via_riscv_kernel<DB>(
    config: &Arc<DubheChannelConfig>,
    ptb: &ProgrammableTransaction,
    cache_db: &mut CacheDB<DB>,
    sender: SuiAddress,
    tx_digest: TransactionDigest,
    temp_storage_state: &Arc<RwLock<StorageState>>,
) -> Result<SubmitExecutionOutcome, anyhow::Error>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    let artifact = riscv_artifact_from_programmable_transaction(ptb)?;
    let stats = run_riscv_preflight(cache_db, &artifact)?;
    println!(
        "submit.backend=riscv mode=kernel_preflight_and_commit artifact_id={} ptb_hash={} resolved_objects={} pure_inputs={} move_calls={}",
        artifact.artifact_id,
        artifact.ptb_hash,
        stats.resolved_objects,
        stats.pure_inputs,
        stats.move_calls,
    );

    execute_submit_ptb(config, ptb, cache_db, sender, tx_digest, temp_storage_state)
}

fn execute_submit_ptb<DB>(
    _config: &Arc<DubheChannelConfig>,
    ptb: &ProgrammableTransaction,
    cache_db: &mut CacheDB<DB>,
    sender: SuiAddress,
    tx_digest: TransactionDigest,
    temp_storage_state: &Arc<RwLock<StorageState>>,
) -> Result<SubmitExecutionOutcome, anyhow::Error>
where
    DB: dubhe_db::interface::DatabaseRef + 'static,
    <DB as dubhe_db::interface::DatabaseRef>::Error: Send + Sync + 'static,
{
    println!("🔄 Starting PTB execution...");
    println!("📝 Executing PTB transaction...");
    let (store_set_records, current_checkpoint_timestamp_ms, _current_digest) =
        dubhe_vm::execute_single_ptb_with_store_set_record(ptb, cache_db, sender, tx_digest)?;
    println!("store_set_records: {:?}", store_set_records);
    let mut sql_list = Vec::new();

    let mut applied_records = Vec::new();

    for event in store_set_records {
        if let Event::StoreSetRecord(store_set_record) = event {
            println!("store_set_record: {:?}", store_set_record);
            applied_records.push(store_set_record);

            // if dubhe_config
            //                     .can_convert_event_to_sql(&store_set_record)
            //                     .is_ok() {
            //     // Get table name
            //     let table_name = store_set_record.table_id().to_string();

            //     if table_name != "dapp_fee_state" {
            //         temp_storage_state.write().await.push(
            //             store_set_record.key_tuple().clone(),
            //             store_set_record.value_tuple().clone()
            //         );
            //     }
            // }
        }
    }
    let _ = temp_storage_state;
    Ok(SubmitExecutionOutcome {
        sqls: std::mem::take(&mut sql_list),
        store_set_records: applied_records,
        checkpoint_ts_ms: current_checkpoint_timestamp_ms,
        cursor_opaque: current_checkpoint_timestamp_ms.to_string(),
    })
}

async fn set_storage(
    config: &Arc<DubheChannelConfig>,
    table_id: String,
    key_tuple: Vec<Vec<u8>>,
    value_tuple: Vec<Vec<u8>>,
    dubhe_config: &DubheConfig,
    count: u64,
) -> Result<(), anyhow::Error> {
    let sui_client = SuiClientBuilder::default().build(&config.rpc_url).await?;

    let private_key = dotenvy::var(CHAIN_COMMIT_PRIVATE_KEY_ENV).map_err(|_| {
        anyhow!(
            "{} must be set when chain commit writer is enabled",
            CHAIN_COMMIT_PRIVATE_KEY_ENV
        )
    })?;
    let keypair = SuiKeyPair::decode(&private_key).map_err(|e| anyhow!(e))?;

    let mut keystore = InMemKeystore::default();
    InMemKeystore::import(&mut keystore, Some("hello".to_string()), keypair).await?;
    let sender = *keystore
        .addresses()
        .first()
        .ok_or(anyhow!("No sender found"))?;

    // we need to find the coin we will use as gas
    let coins = sui_client
        .coin_read_api()
        .get_coins(sender, None, None, None)
        .await?;
    let coin = coins
        .data
        .into_iter()
        .next()
        .ok_or(anyhow!("No coins found"))?;

    let object_id =
        ObjectID::from_hex_literal(&dubhe_config.dubhe_object_id).map_err(|e| anyhow!(e))?;
    let obj = sui_client
        .read_api()
        .get_object_with_options(object_id, SuiObjectDataOptions::bcs_lossless())
        .await?;
    let object: Object = obj.into_object()?.try_into()?;

    let object_inner = object.clone().into_inner();

    let input_object = CallArg::Object(ObjectArg::SharedObject {
        id: object.id(),
        initial_shared_version: object_inner
            .owner
            .start_version()
            .ok_or(anyhow!("Failed to get start version"))?,
        mutable: true,
    });

    let input_keys = CallArg::Pure(bcs::to_bytes(&key_tuple).unwrap());

    let input_values = CallArg::Pure(bcs::to_bytes(&value_tuple).unwrap());

    let input_count = CallArg::Pure(bcs::to_bytes(&U256::from(count)).unwrap());

    let input_table_id = CallArg::Pure(bcs::to_bytes(&table_id).unwrap());
    let mut ptb = ProgrammableTransactionBuilder::new();
    ptb.input(input_object)?;
    ptb.input(input_table_id)?;
    ptb.input(input_keys)?;
    ptb.input(input_values)?;
    ptb.input(input_count)?;

    let package = ObjectID::from_hex_literal(&dubhe_config.original_dubhe_package_id)
        .map_err(|e| anyhow!(e))?;
    let module = Identifier::new("dapp_system").map_err(|e| anyhow!(e))?;
    let function = Identifier::new("set_storage").map_err(|e| anyhow!(e))?;
    let move_call = Command::move_call(
        package,
        module,
        function,
        vec![TypeTag::from_str(&format!(
            "{}::dapp_key::DappKey",
            dubhe_config.original_package_id
        ))?],
        vec![
            Argument::Input(0),
            Argument::Input(1),
            Argument::Input(2),
            Argument::Input(3),
            Argument::Input(4),
        ],
    );
    ptb.command(move_call);

    // build the transaction block by calling finish on the ptb
    let builder = ptb.finish();

    let gas_budget = 1_000_000_000;
    let gas_price = sui_client.read_api().get_reference_gas_price().await?;
    // create the transaction data that will be sent to the network
    let tx_data = TransactionData::new_programmable(
        sender,
        vec![coin.object_ref()],
        builder,
        gas_budget,
        gas_price,
    );

    let signature = keystore
        .sign_secure(&sender, &tx_data, Intent::sui_transaction())
        .await?;

    // 5) execute the transaction
    print!("Executing the transaction...");
    let transaction_response = sui_client
        .quorum_driver_api()
        .execute_transaction_block(
            Transaction::from_data(tx_data, vec![signature]),
            SuiTransactionBlockResponseOptions::full_content(),
            Some(ExecuteTransactionRequestType::WaitForEffectsCert),
        )
        .await?;
    println!(
        "Successfully executed transaction: {}",
        transaction_response.digest
    );

    Ok(())
}

