    fn local_test_redis_url() -> String {
        env::var("DUBHE_TEST_REDIS_URL").unwrap_or_else(|_| "redis://127.0.0.1:16379/".to_string())
    }

    fn unique_test_prefix(label: &str) -> String {
        let now = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("system clock before unix epoch")
            .as_nanos();
        format!("dubhe:test:{}:{}", label, now)
    }

    async fn clear_test_redis_namespace(redis_url: &str, key_prefix: &str) -> Result<()> {
        let client = redis::Client::open(redis_url)?;
        let mut connection = client.get_multiplexed_async_connection().await?;
        let pattern = format!("{}*", key_prefix);
        let keys: Vec<String> = redis::cmd("KEYS")
            .arg(pattern)
            .query_async(&mut connection)
            .await?;

        if !keys.is_empty() {
            let _: () = redis::cmd("DEL")
                .arg(keys)
                .query_async(&mut connection)
                .await?;
        }

        Ok(())
    }

    async fn spawn_test_webhook_server(
        status: StatusCode,
    ) -> (
        String,
        Arc<AtomicUsize>,
        oneshot::Sender<()>,
        tokio::task::JoinHandle<()>,
    ) {
        let requests = Arc::new(AtomicUsize::new(0));
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let request_counter = requests.clone();
        let service = make_service_fn(move |_| {
            let request_counter = request_counter.clone();
            async move {
                Ok::<_, Infallible>(service_fn(move |req: Request<Body>| {
                    let request_counter = request_counter.clone();
                    async move {
                        let _ = to_bytes(req.into_body()).await.unwrap();
                        request_counter.fetch_add(1, Ordering::SeqCst);
                        Ok::<_, Infallible>(
                            Response::builder()
                                .status(status)
                                .header(CONTENT_TYPE, "application/json")
                                .body(Body::from("{}"))
                                .unwrap(),
                        )
                    }
                }))
            }
        });
        let server = Server::from_tcp(listener).unwrap().serve(service);
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            let server = server.with_graceful_shutdown(async move {
                let _ = shutdown_rx.await;
            });
            let _ = server.await;
        });
        (format!("http://{}", address), requests, shutdown_tx, handle)
    }

    async fn spawn_recording_webhook_server(
        status: StatusCode,
    ) -> (
        String,
        Arc<tokio::sync::Mutex<Vec<serde_json::Value>>>,
        oneshot::Sender<()>,
        tokio::task::JoinHandle<()>,
    ) {
        let payloads = Arc::new(tokio::sync::Mutex::new(Vec::new()));
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let captured_payloads = payloads.clone();
        let service = make_service_fn(move |_| {
            let captured_payloads = captured_payloads.clone();
            async move {
                Ok::<_, Infallible>(service_fn(move |req: Request<Body>| {
                    let captured_payloads = captured_payloads.clone();
                    async move {
                        let body = to_bytes(req.into_body()).await.unwrap();
                        let payload = serde_json::from_slice::<serde_json::Value>(&body).unwrap();
                        captured_payloads.lock().await.push(payload);
                        Ok::<_, Infallible>(
                            Response::builder()
                                .status(status)
                                .header(CONTENT_TYPE, "application/json")
                                .body(Body::from("{}"))
                                .unwrap(),
                        )
                    }
                }))
            }
        });
        let server = Server::from_tcp(listener).unwrap().serve(service);
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            let server = server.with_graceful_shutdown(async move {
                let _ = shutdown_rx.await;
            });
            let _ = server.await;
        });
        (format!("http://{}", address), payloads, shutdown_tx, handle)
    }

    async fn spawn_recording_webhook_server_with_headers(
        status: StatusCode,
    ) -> (
        String,
        Arc<tokio::sync::Mutex<Vec<(serde_json::Value, BTreeMap<String, String>)>>>,
        oneshot::Sender<()>,
        tokio::task::JoinHandle<()>,
    ) {
        let requests = Arc::new(tokio::sync::Mutex::new(Vec::new()));
        let listener = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        listener.set_nonblocking(true).unwrap();
        let address = listener.local_addr().unwrap();
        let captured_requests = requests.clone();
        let service = make_service_fn(move |_| {
            let captured_requests = captured_requests.clone();
            async move {
                Ok::<_, Infallible>(service_fn(move |req: Request<Body>| {
                    let captured_requests = captured_requests.clone();
                    async move {
                        let headers = req
                            .headers()
                            .iter()
                            .filter_map(|(name, value)| {
                                value
                                    .to_str()
                                    .ok()
                                    .map(|value| (name.as_str().to_string(), value.to_string()))
                            })
                            .collect::<BTreeMap<_, _>>();
                        let body = to_bytes(req.into_body()).await.unwrap();
                        let payload = serde_json::from_slice::<serde_json::Value>(&body).unwrap();
                        captured_requests.lock().await.push((payload, headers));
                        Ok::<_, Infallible>(
                            Response::builder()
                                .status(status)
                                .header(CONTENT_TYPE, "application/json")
                                .body(Body::from("{}"))
                                .unwrap(),
                        )
                    }
                }))
            }
        });
        let server = Server::from_tcp(listener).unwrap().serve(service);
        let (shutdown_tx, shutdown_rx) = oneshot::channel::<()>();
        let handle = tokio::spawn(async move {
            let server = server.with_graceful_shutdown(async move {
                let _ = shutdown_rx.await;
            });
            let _ = server.await;
        });
        (format!("http://{}", address), requests, shutdown_tx, handle)
    }

