    #[test]
    fn test_compute_ready_slo_window_tracks_degraded_intervals() {
        let history = VecDeque::from(vec![
            ReadyObservation {
                at_ms: 1_000,
                ready: true,
            },
            ReadyObservation {
                at_ms: 2_000,
                ready: false,
            },
            ReadyObservation {
                at_ms: 4_000,
                ready: true,
            },
        ]);

        let snapshot = compute_ready_slo_window(&history, 5_000, 10_000, READY_SLO_TARGET_BPS);
        assert_eq!(snapshot.observed_ms, 4_000);
        assert_eq!(snapshot.degraded_ms, 2_000);
        assert_eq!(snapshot.availability_bps, 5_000);
        assert_eq!(snapshot.burn_rate_milli, 50_000);
    }

