    #[tokio::test]
    async fn test_submit_nonce_is_scoped_by_tenant() {
        let state = test_state();
        let tenant_one = ResolvedTenant {
            deployment_id: Some("deployment-a".to_string()),
            deployment_slug: None,
            source: "test",
        };
        let tenant_two = ResolvedTenant {
            deployment_id: Some("deployment-b".to_string()),
            deployment_slug: None,
            source: "test",
        };

        record_submit_success_for_tenant(
            &state,
            "0xplayer",
            Some(&tenant_one),
            1,
            None,
            test_replay_entry("tenant-a"),
        )
        .await
        .unwrap();

        let tenant_one_nonce =
            current_account_nonce_for_tenant(&state, "0xplayer", Some(&tenant_one))
                .await
                .unwrap();
        let tenant_two_nonce =
            current_account_nonce_for_tenant(&state, "0xplayer", Some(&tenant_two))
                .await
                .unwrap();
        let unscoped_nonce = current_account_nonce(&state, "0xplayer").await.unwrap();

        assert_eq!(tenant_one_nonce, 1);
        assert_eq!(tenant_two_nonce, 0);
        assert_eq!(unscoped_nonce, 0);
    }

    #[tokio::test]
