    #[test]
    fn test_riscv_artifact_is_deterministic_for_same_intent() {
        let sender = "0x15fde77101778fafe8382743171294dfd8e7900a547711ee375379c27a85fd31";
        let request = test_intent_compile_request(sender, Some(1));
        let intent = match request.intent {
            IntentPayload::SuiMoveCall(intent) => intent,
        };

        let first = compile_sui_move_call_intent_via_riscv(sender, intent.clone()).unwrap();
        let second = compile_sui_move_call_intent_via_riscv(sender, intent).unwrap();

        let first_artifact = first.artifact.expect("first artifact");
        let second_artifact = second.artifact.expect("second artifact");
        assert_eq!(first_artifact.program_hash, second_artifact.program_hash);
        assert_eq!(first_artifact.ptb_hash, second_artifact.ptb_hash);
        assert_eq!(
            first_artifact.instructions.len(),
            second_artifact.instructions.len()
        );
    }

    #[test]
    fn test_riscv_preflight_rejects_large_pure_input() {
        let artifact = RiscvProgramArtifact {
            version: 1,
            entry: "submit_ptb".to_string(),
            artifact_id: "rva_exec_test".to_string(),
            program_hash: "00".to_string(),
            ptb_hash: "11".to_string(),
            instructions: vec![
                RiscvProgramInstruction::PureInput {
                    input_index: 0,
                    bytes_len: 8193,
                    bytes_hash: "22".to_string(),
                },
                RiscvProgramInstruction::MoveCall {
                    package: "0x2".to_string(),
                    module: "clock".to_string(),
                    function: "timestamp_ms".to_string(),
                    type_arguments: vec![],
                    arguments_len: 1,
                },
            ],
            notes: vec![],
        };

        let mut cache_db = CacheDB::new(EmptyDB::default());
        let error = run_riscv_preflight(&mut cache_db, &artifact).unwrap_err();
        assert!(error.to_string().contains("exceeds 8192"));
    }

    #[test]
    fn test_evm_to_sui() {
        // Test EVM address conversion
        let evm_address = "0x9168765EE952de7C6f8fC6FaD5Ec209B960b7622";
        let result = evm_to_sui(evm_address);
        assert!(result.is_ok());

        let sui_address = result.unwrap();
        let sui_address_str = format!("{:?}", sui_address);
        println!("EVM {} -> SUI {}", evm_address, sui_address_str);

        // Verify it's 32 bytes (64 hex chars after 0x)
        assert!(sui_address_str.starts_with("0x"));
    }

