    #[tokio::test]
    async fn test_ops_realtime_gate_live_enforcement_reports_draining_then_drained() {
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            state.config = Arc::new(config);
        }
        let request = V2SubscribeRequest {
            spec: SubscriptionSpec {
                topics: vec!["movement_intent".to_string()],
                filters: BTreeMap::new(),
                cursor: None,
                semantics: dubhe_channel_core::DeliverySemantics::Ephemeral,
            },
        };
        let response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(CONTENT_TYPE, "application/json")
                .header("Accept", "text/event-stream")
                .body(Body::from(serde_json::to_vec(&request).unwrap()))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(response.status(), StatusCode::OK);

        let gate_disable_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_REALTIME_GATE_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "ops-realtime-gate-draining")
                .body(Body::from(
                    r#"{"enabled":false,"operator":"ops","reason":"drain live subscribers"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(gate_disable_response.status(), StatusCode::OK);
        let gate_disable_body = to_bytes(gate_disable_response.into_body()).await.unwrap();
        let gate_disable_payload: serde_json::Value =
            serde_json::from_slice(&gate_disable_body).unwrap();
        assert_eq!(
            gate_disable_payload["live_enforcement"]["drain_state"],
            "draining"
        );
        assert_eq!(
            gate_disable_payload["live_enforcement"]["local_active_connections"],
            1
        );
        assert_eq!(
            gate_disable_payload["live_enforcement"]["drain_complete"],
            false
        );

        let mut body = response.into_body();
        let next_chunk = timeout(Duration::from_secs(3), body.data()).await.unwrap();
        assert!(next_chunk.is_none());
        tokio::time::sleep(Duration::from_millis(50)).await;

        let gate_status_response = handle_request(
            Request::builder()
                .method(hyper::Method::GET)
                .uri(OPS_REALTIME_GATE_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .body(Body::empty())
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(gate_status_response.status(), StatusCode::OK);
        let gate_status_body = to_bytes(gate_status_response.into_body()).await.unwrap();
        let gate_status_payload: serde_json::Value =
            serde_json::from_slice(&gate_status_body).unwrap();
        assert_eq!(
            gate_status_payload["live_enforcement"]["drain_state"],
            "drained"
        );
        assert_eq!(
            gate_status_payload["live_enforcement"]["local_active_connections"],
            0
        );
        assert_eq!(
            gate_status_payload["live_enforcement"]["drain_complete"],
            true
        );
        assert!(
            gate_status_payload["live_enforcement"]["gate_disconnects_total"]
                .as_u64()
                .unwrap_or_default()
                >= 1
        );
    }

    #[test]
    fn test_realtime_connection_presence_aggregate_excludes_stale_instances() {
        let now_ms = 50_000;
        let stale_after_ms = realtime_connection_presence_stale_after_ms();
        let local_entry = RealtimeConnectionPresenceEntry {
            instance_id: "instance-local".to_string(),
            updated_at_ms: now_ms,
            total_active: 2,
            tenant_slots: 1,
            client_slots: 2,
            connections_by_tenant: HashMap::from([(String::from("tenant-alpha"), 2)]),
            connections_by_client: HashMap::from([
                (String::from("client-a"), 1),
                (String::from("client-b"), 1),
            ]),
            idle_disconnects_total: 1,
            gate_disconnects_total: 2,
            lagged_messages_total: 3,
            slow_consumer_disconnects_total: 1,
            last_idle_disconnect_at_ms: 49_700,
            last_gate_disconnect_at_ms: 49_710,
            last_lagged_message_at_ms: 49_720,
            last_slow_consumer_disconnect_at_ms: 49_730,
        };
        let aggregate = aggregate_realtime_connection_presence_entries(
            vec![
                RealtimeConnectionPresenceEntry {
                    instance_id: "instance-active".to_string(),
                    updated_at_ms: now_ms.saturating_sub(100),
                    total_active: 3,
                    tenant_slots: 2,
                    client_slots: 3,
                    connections_by_tenant: HashMap::from([
                        (String::from("tenant-alpha"), 1),
                        (String::from("tenant-beta"), 2),
                    ]),
                    connections_by_client: HashMap::from([
                        (String::from("client-a"), 2),
                        (String::from("client-c"), 1),
                    ]),
                    idle_disconnects_total: 4,
                    gate_disconnects_total: 5,
                    lagged_messages_total: 6,
                    slow_consumer_disconnects_total: 2,
                    last_idle_disconnect_at_ms: 49_800,
                    last_gate_disconnect_at_ms: 49_810,
                    last_lagged_message_at_ms: 49_820,
                    last_slow_consumer_disconnect_at_ms: 49_830,
                },
                RealtimeConnectionPresenceEntry {
                    instance_id: "instance-stale".to_string(),
                    updated_at_ms: now_ms.saturating_sub(stale_after_ms.saturating_add(1)),
                    total_active: 9,
                    tenant_slots: 9,
                    client_slots: 9,
                    connections_by_tenant: HashMap::from([(String::from("tenant-stale"), 9)]),
                    connections_by_client: HashMap::from([(String::from("client-stale"), 9)]),
                    idle_disconnects_total: 99,
                    gate_disconnects_total: 99,
                    lagged_messages_total: 99,
                    slow_consumer_disconnects_total: 99,
                    last_idle_disconnect_at_ms: 1,
                    last_gate_disconnect_at_ms: 1,
                    last_lagged_message_at_ms: 1,
                    last_slow_consumer_disconnect_at_ms: 1,
                },
            ],
            local_entry,
            now_ms,
        );
        assert_eq!(aggregate.instances.len(), 2);
        assert_eq!(aggregate.stale_instances.len(), 1);
        assert_eq!(aggregate.aggregate_active_connections, 5);
        assert_eq!(aggregate.aggregate_tenant_slots, 3);
        assert_eq!(aggregate.aggregate_client_slots, 5);
        assert_eq!(
            aggregate
                .aggregate_connections_by_tenant
                .get("tenant-alpha")
                .copied(),
            Some(3)
        );
        assert_eq!(
            aggregate
                .aggregate_connections_by_tenant
                .get("tenant-beta")
                .copied(),
            Some(2)
        );
        assert_eq!(
            aggregate
                .aggregate_connections_by_client
                .get("client-a")
                .copied(),
            Some(3)
        );
        assert_eq!(
            aggregate
                .aggregate_connections_by_client
                .get("client-b")
                .copied(),
            Some(1)
        );
        assert_eq!(aggregate.aggregate_idle_disconnects_total, 5);
        assert_eq!(aggregate.aggregate_gate_disconnects_total, 7);
        assert_eq!(aggregate.aggregate_lagged_messages_total, 9);
        assert_eq!(aggregate.aggregate_slow_consumer_disconnects_total, 3);

        let payload = realtime_gate_cluster_enforcement_json(
            false,
            &aggregate,
            10,
            3,
            3,
            &Arc::new(AppMetrics::default()),
        );
        assert_eq!(payload["drain_state"], "draining");
        assert_eq!(payload["active_instances"], 2);
        assert_eq!(payload["stale_instances"], 1);
        assert_eq!(payload["aggregate_active_connections"], 5);
        assert_eq!(payload["admission_scope"], "cluster");
        assert_eq!(payload["global_connection_limit"], 10);
        assert_eq!(payload["remaining_global_connections"], 5);
        assert_eq!(payload["global_limit_reached"], false);
        assert_eq!(payload["per_tenant_connection_limit"], 3);
        assert_eq!(payload["tenants_at_limit"], 1);
        assert_eq!(payload["tenant_connections"][0]["tenant"], "tenant-alpha");
        assert_eq!(payload["tenant_connections"][0]["active_connections"], 3);
        assert_eq!(payload["tenant_connections"][0]["remaining_connections"], 0);
        assert_eq!(payload["tenant_connections"][0]["limit_reached"], true);
        assert_eq!(payload["per_client_connection_limit"], 3);
        assert_eq!(payload["clients_at_limit"], 1);
        assert_eq!(payload["client_connections"][0]["client"], "client-a");
        assert_eq!(payload["client_connections"][0]["active_connections"], 3);
        assert_eq!(payload["client_connections"][0]["remaining_connections"], 0);
        assert_eq!(payload["client_connections"][0]["limit_reached"], true);
        assert_eq!(payload["idle_disconnects_total"], 5);
        assert_eq!(payload["gate_disconnects_total"], 7);
        assert_eq!(payload["lagged_messages_total"], 9);
        assert_eq!(payload["slow_consumer_disconnects_total"], 3);
        assert_eq!(payload["last_lagged_message_at_ms"], 49820);
        assert_eq!(payload["last_slow_consumer_disconnect_at_ms"], 49830);
        assert_eq!(payload["instances"][0]["gate_disconnects_total"], 5);
        assert_eq!(payload["drain_complete"], false);
    }

