    #[tokio::test]
    async fn test_ops_runtime_profile_endpoint_applies_effective_states() {
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            state.config = Arc::new(config);
        }

        let cases = [
            ("readonly", false, true, false, "none", "medium"),
            ("drain", false, false, false, "none", "high"),
            ("maintenance", false, false, true, "ready_degraded", "high"),
            ("normal", true, true, false, "none", "none"),
        ];

        for (profile, write_enabled, realtime_enabled, drill_enabled, drill_kind, severity) in cases
        {
            let response = handle_request(
                Request::builder()
                    .method(hyper::Method::POST)
                    .uri(OPS_RUNTIME_PROFILE_PATH)
                    .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                    .header(REQUEST_ID_HEADER, format!("profile-{}", profile))
                    .body(Body::from(format!(
                        r#"{{"profile":"{}","operator":"ops","reason":"preset {}"}}"#,
                        profile, profile
                    )))
                    .unwrap(),
                state.clone(),
            )
            .await
            .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
            let body = to_bytes(response.into_body()).await.unwrap();
            let payload: serde_json::Value = serde_json::from_slice(&body).unwrap();
            assert_eq!(payload["runtime_profile"]["profile"], profile);
            assert_eq!(payload["runtime_profile"]["active"], profile != "normal");
            assert_eq!(payload["runtime_profile"]["severity"], severity);
            assert_eq!(payload["runtime_profile"]["matches_effective"], true);
            assert_eq!(
                payload["runtime_profile"]["effective"]["write_gate_enabled"],
                write_enabled
            );
            assert_eq!(
                payload["runtime_profile"]["effective"]["realtime_gate_enabled"],
                realtime_enabled
            );
            assert_eq!(
                payload["runtime_profile"]["effective"]["runtime_drill_enabled"],
                drill_enabled
            );
            assert_eq!(
                payload["runtime_profile"]["effective"]["runtime_drill_kind"],
                drill_kind
            );

            let inspect_response = handle_request(
                Request::builder()
                    .method(hyper::Method::GET)
                    .uri(OPS_RUNTIME_PROFILE_PATH)
                    .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                    .body(Body::empty())
                    .unwrap(),
                state.clone(),
            )
            .await
            .unwrap();
            assert_eq!(inspect_response.status(), StatusCode::OK);
            let inspect_body = to_bytes(inspect_response.into_body()).await.unwrap();
            let inspect_payload: serde_json::Value = serde_json::from_slice(&inspect_body).unwrap();
            assert_eq!(inspect_payload["runtime_profile"]["profile"], profile);
            assert_eq!(
                inspect_payload["runtime_profile"]["matches_effective"],
                true
            );
            assert_eq!(
                inspect_payload["runtime_profile"]["effective"]["write_gate_enabled"],
                write_enabled
            );
            assert_eq!(
                inspect_payload["runtime_profile"]["effective"]["realtime_gate_enabled"],
                realtime_enabled
            );
            assert_eq!(
                inspect_payload["runtime_profile"]["effective"]["runtime_drill_enabled"],
                drill_enabled
            );
            assert_eq!(
                inspect_payload["runtime_profile"]["effective"]["runtime_drill_kind"],
                drill_kind
            );
        }

        assert_eq!(
            state
                .metrics
                .ops_runtime_profile_active
                .load(Ordering::Relaxed),
            0
        );
        assert_eq!(
            state
                .metrics
                .ops_runtime_profile_transitions_total
                .load(Ordering::Relaxed),
            4
        );
    }

