    #[tokio::test]
    async fn test_ops_runtime_rollout_history_endpoint_returns_recent_entries() {
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            config.ops_runtime_rollout_history_limit = 3;
            state.config = Arc::new(config);
        }

        for (phase, profile) in [
            ("canary", "readonly"),
            ("promote", "drain"),
            ("hold", "maintenance"),
        ] {
            let force_fragment = if phase == "promote" {
                r#","force":true"#
            } else {
                ""
            };
            let response = handle_request(
                Request::builder()
                    .method(hyper::Method::POST)
                    .uri(OPS_RUNTIME_ROLLOUT_PATH)
                    .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                    .header(REQUEST_ID_HEADER, format!("rollout-history-{}", phase))
                    .body(Body::from(format!(
                        r#"{{"active":true,"phase":"{}","target_profile":"{}"{},"operator":"ops","reason":"history {}"}}"#,
                        phase, profile, force_fragment, phase
                    )))
                    .unwrap(),
                state.clone(),
            )
            .await
            .unwrap();
            assert_eq!(response.status(), StatusCode::OK);
        }

        let history_response = handle_request(
            Request::builder()
                .method(hyper::Method::GET)
                .uri(format!("{}?limit=2", OPS_RUNTIME_ROLLOUT_HISTORY_PATH))
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .body(Body::empty())
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(history_response.status(), StatusCode::OK);
        let history_body = to_bytes(history_response.into_body()).await.unwrap();
        let history_payload: serde_json::Value = serde_json::from_slice(&history_body).unwrap();
        assert_eq!(history_payload["limit"], 2);
        assert_eq!(history_payload["count"], 2);
        assert_eq!(history_payload["history_limit"], 3);
        assert_eq!(history_payload["history"][0]["phase"], "hold");
        assert_eq!(history_payload["history"][0]["previous_phase"], "promote");
        assert_eq!(
            history_payload["history"][0]["target_profile"],
            "maintenance"
        );
        assert_eq!(history_payload["history"][0]["source"], "manual");
        assert_eq!(history_payload["history"][1]["phase"], "promote");
        assert_eq!(history_payload["history"][1]["previous_phase"], "canary");
        assert_eq!(history_payload["history"][1]["target_profile"], "drain");
    }

