    #[tokio::test]
    async fn test_ops_runtime_rollout_dispatch_endpoint_delivers_webhook_payload() {
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            state.config = Arc::new(config);
        }

        let seed_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-dispatch-seed")
                .body(Body::from(
                    r#"{"active":true,"phase":"canary","target_profile":"normal","apply_target_profile":true,"operator":"ops","reason":"seed canary"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(seed_response.status(), StatusCode::OK);

        let traffic_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_TRAFFIC_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-dispatch-traffic")
                .body(Body::from(
                    r#"{"stage":"canary","canary_percent":10,"stable_percent":90,"actor":"proxy-bot","dispatch_webhook":false}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(traffic_response.status(), StatusCode::OK);

        let (webhook_url, payloads, shutdown_tx, handle) =
            spawn_recording_webhook_server(StatusCode::OK).await;
        {
            let mut config = (*state.config).clone();
            config.ops_runtime_rollout_webhook_url = Some(webhook_url);
            config.ops_runtime_rollout_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }

        let dispatch_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_DISPATCH_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-dispatch-success")
                .body(Body::from(r#"{"force":true,"source":"manual_dispatch"}"#))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(dispatch_response.status(), StatusCode::OK);
        let dispatch_body = to_bytes(dispatch_response.into_body()).await.unwrap();
        let dispatch_payload: serde_json::Value = serde_json::from_slice(&dispatch_body).unwrap();
        assert_eq!(dispatch_payload["ok"], true);
        assert_eq!(dispatch_payload["skipped"], false);
        assert_eq!(dispatch_payload["source"], "manual_dispatch");
        assert_eq!(dispatch_payload["summary"]["phase"], "canary");
        assert_eq!(dispatch_payload["delivery"]["pending"]["active"], false);

        let recorded_payloads = payloads.lock().await;
        assert_eq!(recorded_payloads.len(), 1);
        assert_eq!(recorded_payloads[0]["event_type"], "runtime_rollout");
        assert_eq!(recorded_payloads[0]["source"], "manual_dispatch");
        assert_eq!(recorded_payloads[0]["runtime_rollout"]["phase"], "canary");
        assert_eq!(
            recorded_payloads[0]["rollout_checklist"]["summary"]["recommended_action"],
            "proceed"
        );
        drop(recorded_payloads);

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

