    #[tokio::test]
    async fn test_ops_runtime_rollout_deploy_action_redispatch_endpoint_redelivers_after_ack_timeout(
    ) {
        let mut state = test_state();
        let (webhook_url, payloads, shutdown_tx, handle) =
            spawn_recording_webhook_server(StatusCode::OK).await;
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            config.ops_runtime_rollout_deploy_action_webhook_url = Some(webhook_url);
            config.ops_runtime_rollout_action_ack_timeout_ms = 1;
            config.ops_runtime_rollout_action_ack_redispatch_max_attempts = 1;
            config.ops_runtime_rollout_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }

        let rollout_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(
                    REQUEST_ID_HEADER,
                    "runtime-rollout-deploy-action-redispatch-seed",
                )
                .body(Body::from(
                    r#"{"active":true,"phase":"canary","target_profile":"normal","apply_target_profile":true,"operator":"ops","reason":"seed deploy action redispatch"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(rollout_response.status(), StatusCode::OK);

        tokio::time::sleep(Duration::from_millis(5)).await;

        let redispatch_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_REDISPATCH_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(
                    REQUEST_ID_HEADER,
                    "runtime-rollout-deploy-action-redispatch",
                )
                .body(Body::from(
                    r#"{"source":"manual_redispatch","reason":"ack timeout replay"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(redispatch_response.status(), StatusCode::OK);
        let redispatch_body = to_bytes(redispatch_response.into_body()).await.unwrap();
        let redispatch_payload: serde_json::Value =
            serde_json::from_slice(&redispatch_body).unwrap();
        assert_eq!(redispatch_payload["redispatch"]["attempts"], 1);
        assert_eq!(redispatch_payload["redispatch"]["remaining_attempts"], 0);
        assert_eq!(redispatch_payload["redispatch"]["eligible"], false);

        let recorded_payloads = payloads.lock().await;
        assert_eq!(recorded_payloads.len(), 2);
        drop(recorded_payloads);

        let action_response = handle_request(
            Request::builder()
                .method(hyper::Method::GET)
                .uri(OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .body(Body::empty())
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(action_response.status(), StatusCode::OK);
        let action_body = to_bytes(action_response.into_body()).await.unwrap();
        let action_payload: serde_json::Value = serde_json::from_slice(&action_body).unwrap();
        assert_eq!(action_payload["redispatch"]["attempts"], 1);
        assert_eq!(action_payload["redispatch"]["backoff_active"], false);
        assert_eq!(action_payload["redispatch"]["exhausted"], true);

        tokio::time::sleep(Duration::from_millis(5)).await;
        let blocked_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_REDISPATCH_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(
                    REQUEST_ID_HEADER,
                    "runtime-rollout-deploy-action-redispatch-blocked",
                )
                .body(Body::from(r#"{"reason":"second retry should block"}"#))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(blocked_response.status(), StatusCode::CONFLICT);
        let blocked_body = to_bytes(blocked_response.into_body()).await.unwrap();
        let blocked_payload: serde_json::Value = serde_json::from_slice(&blocked_body).unwrap();
        assert!(blocked_payload["error"]
            .as_str()
            .unwrap_or_default()
            .contains("attempts exhausted"));
        assert_eq!(
            state
                .metrics
                .ops_runtime_rollout_deploy_action_redispatch_blocked_total
                .load(Ordering::Relaxed),
            1
        );

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

