    #[tokio::test]
    async fn test_ops_runtime_rollout_receipt_rejects_stale_execution_owner_after_takeover() {
        let mut state = test_state();
        let (webhook_url, _payloads, shutdown_tx, handle) =
            spawn_recording_webhook_server(StatusCode::OK).await;
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            config.ops_runtime_rollout_deploy_action_webhook_url = Some(webhook_url);
            config.ops_runtime_rollout_receipt_pending_timeout_ms = 60_000;
            config.ops_runtime_rollout_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }

        let rollout_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(
                    REQUEST_ID_HEADER,
                    "runtime-rollout-receipt-stale-execution-seed",
                )
                .body(Body::from(
                    r#"{"active":true,"phase":"canary","target_profile":"normal","apply_target_profile":true,"operator":"ops","reason":"seed deploy execution takeover"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(rollout_response.status(), StatusCode::OK);

        let first_ack_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_ACK_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-receipt-stale-ack-1")
                .body(Body::from(
                    r#"{"status":"accepted","actor":"deploy-bot-1","external_ref":"deploy-job-1"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(first_ack_response.status(), StatusCode::OK);
        let first_ack_body = to_bytes(first_ack_response.into_body()).await.unwrap();
        let first_ack_payload: serde_json::Value = serde_json::from_slice(&first_ack_body).unwrap();
        let first_execution_request_id = first_ack_payload["execution"]["execution_request_id"]
            .as_str()
            .unwrap()
            .to_string();

        {
            let mut execution_state = state
                .ops_runtime_rollout_deploy_action_execution_state
                .write()
                .await;
            let execution_state = execution_state.as_mut().unwrap();
            execution_state.updated_at_ms = execution_state.updated_at_ms.saturating_sub(120_000);
        }

        let second_ack_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_DEPLOY_ACTION_ACK_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-receipt-stale-ack-2")
                .body(Body::from(
                    r#"{"status":"accepted","actor":"deploy-bot-2","external_ref":"deploy-job-2"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(second_ack_response.status(), StatusCode::OK);
        let second_ack_body = to_bytes(second_ack_response.into_body()).await.unwrap();
        let second_ack_payload: serde_json::Value =
            serde_json::from_slice(&second_ack_body).unwrap();
        let second_execution_request_id = second_ack_payload["execution"]["execution_request_id"]
            .as_str()
            .unwrap()
            .to_string();
        assert_ne!(first_execution_request_id, second_execution_request_id);

        let stale_receipt_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_RECEIPT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(
                    REQUEST_ID_HEADER,
                    "runtime-rollout-receipt-stale-execution-receipt",
                )
                .body(Body::from(format!(
                    r#"{{"status":"in_progress","actor":"deploy-bot-1","execution_request_id":"{}","dispatch_webhook":false}}"#,
                    first_execution_request_id
                )))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(stale_receipt_response.status(), StatusCode::CONFLICT);
        let stale_receipt_body = to_bytes(stale_receipt_response.into_body()).await.unwrap();
        let stale_receipt_payload: serde_json::Value =
            serde_json::from_slice(&stale_receipt_body).unwrap();
        assert!(stale_receipt_payload["error"]
            .as_str()
            .unwrap()
            .contains("stale execution_request_id"));

        let receipt_get_response = handle_request(
            Request::builder()
                .method(hyper::Method::GET)
                .uri(OPS_RUNTIME_ROLLOUT_RECEIPT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .body(Body::empty())
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(receipt_get_response.status(), StatusCode::OK);
        let receipt_get_body = to_bytes(receipt_get_response.into_body()).await.unwrap();
        let receipt_get_payload: serde_json::Value =
            serde_json::from_slice(&receipt_get_body).unwrap();
        assert_eq!(receipt_get_payload["receipt"]["active"], false);
        assert_eq!(
            receipt_get_payload["execution"]["execution_request_id"],
            second_execution_request_id
        );
        assert_eq!(receipt_get_payload["execution"]["actor"], "deploy-bot-2");

        assert_eq!(
            state
                .metrics
                .ops_runtime_rollout_deploy_action_execution_conflicts_total
                .load(Ordering::Relaxed),
            1
        );

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

