    #[tokio::test]
    async fn test_ops_runtime_rollout_receipt_endpoint_dispatches_webhook_with_receipt_state() {
        let mut state = test_state();
        let (webhook_url, payloads, shutdown_tx, handle) =
            spawn_recording_webhook_server(StatusCode::OK).await;
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            config.ops_runtime_rollout_webhook_url = Some(webhook_url);
            config.ops_runtime_rollout_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }

        let seed_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-receipt-dispatch-seed")
                .body(Body::from(
                    r#"{"active":true,"phase":"prepare","target_profile":"readonly","operator":"ops","reason":"seed prepare"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(seed_response.status(), StatusCode::OK);

        let receipt_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_RECEIPT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-receipt-dispatch")
                .body(Body::from(
                    r#"{"status":"failed","actor":"deploy-bot","note":"canary apply failed","external_ref":"deploy-456"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(receipt_response.status(), StatusCode::OK);
        let receipt_body = to_bytes(receipt_response.into_body()).await.unwrap();
        let receipt_payload: serde_json::Value = serde_json::from_slice(&receipt_body).unwrap();
        assert_eq!(receipt_payload["dispatch"]["attempted"], true);
        assert_eq!(receipt_payload["dispatch"]["source"], "receipt");
        assert_eq!(receipt_payload["receipt"]["status"], "failed");

        let recorded_payloads = payloads.lock().await;
        assert_eq!(recorded_payloads.len(), 2);
        let latest_payload = recorded_payloads.last().unwrap();
        assert_eq!(latest_payload["event_type"], "runtime_rollout");
        assert_eq!(latest_payload["source"], "receipt");
        assert_eq!(latest_payload["receipt"]["active"], true);
        assert_eq!(latest_payload["receipt"]["status"], "failed");
        assert_eq!(latest_payload["receipt"]["actor"], "deploy-bot");
        assert_eq!(latest_payload["receipt"]["phase"], "prepare");
        drop(recorded_payloads);

        assert_eq!(
            state
                .metrics
                .ops_runtime_rollout_receipt_failed_total
                .load(Ordering::Relaxed),
            1
        );
        assert_eq!(
            state
                .metrics
                .ops_runtime_rollout_receipt_failed_active
                .load(Ordering::Relaxed),
            1
        );

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

