    #[tokio::test]
    async fn test_ops_runtime_rollout_approval_endpoint_dispatches_webhook_with_approval_state() {
        let mut state = test_state();
        let (webhook_url, payloads, shutdown_tx, handle) =
            spawn_recording_webhook_server(StatusCode::OK).await;
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            config.ops_runtime_rollout_webhook_url = Some(webhook_url);
            config.ops_runtime_rollout_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }

        let seed_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-approval-dispatch-seed")
                .body(Body::from(
                    r#"{"active":true,"phase":"canary","target_profile":"normal","apply_target_profile":true,"operator":"ops","reason":"seed canary"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(seed_response.status(), StatusCode::OK);

        let approval_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri(OPS_RUNTIME_ROLLOUT_APPROVAL_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .header(REQUEST_ID_HEADER, "runtime-rollout-approval-dispatch")
                .body(Body::from(
                    r#"{"status":"approved","actor":"release-bot","note":"approved for promote"}"#,
                ))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(approval_response.status(), StatusCode::OK);
        let approval_body = to_bytes(approval_response.into_body()).await.unwrap();
        let approval_payload: serde_json::Value = serde_json::from_slice(&approval_body).unwrap();
        assert_eq!(approval_payload["dispatch"]["attempted"], true);
        assert_eq!(approval_payload["dispatch"]["source"], "approval");

        let recorded_payloads = payloads.lock().await;
        assert_eq!(recorded_payloads.len(), 2);
        let latest_payload = recorded_payloads.last().unwrap();
        assert_eq!(latest_payload["event_type"], "runtime_rollout");
        assert_eq!(latest_payload["source"], "approval");
        assert_eq!(latest_payload["approval"]["active"], true);
        assert_eq!(latest_payload["approval"]["status"], "approved");
        assert_eq!(latest_payload["approval"]["actor"], "release-bot");
        drop(recorded_payloads);

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

