    #[tokio::test]
    async fn test_process_ops_alert_delivery_once_clears_pending_on_success() {
        let (webhook_url, requests, shutdown_tx, handle) =
            spawn_test_webhook_server(StatusCode::OK).await;
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_alert_webhook_url = Some(webhook_url);
            config.ops_alert_webhook_timeout_ms = 500;
            state.config = Arc::new(config);
        }
        update_ops_alert_delivery_pending(
            &state,
            Some(OpsAlertDeliveryEntry {
                fingerprint: "pending-success".to_string(),
                payload: json!({"hello":"world"}),
                attempts: 1,
                created_at_ms: 10,
                last_attempt_at_ms: None,
                next_attempt_at_ms: now_ts_ms().saturating_sub(1),
                last_error: Some("synthetic failure".to_string()),
            }),
        )
        .await
        .unwrap();

        let processed = process_ops_alert_delivery_once(&state).await.unwrap();
        assert!(processed);
        assert!(current_ops_alert_delivery_pending(&state)
            .await
            .unwrap()
            .is_none());
        assert_eq!(requests.load(Ordering::SeqCst), 1);
        assert_eq!(
            state
                .metrics
                .ops_alert_dispatch_success_total
                .load(Ordering::Relaxed),
            1
        );
        assert_eq!(
            state
                .metrics
                .ops_alert_delivery_pending_active
                .load(Ordering::Relaxed),
            0
        );

        let _ = shutdown_tx.send(());
        let _ = handle.await;
    }

    #[tokio::test]
    async fn test_ops_alerts_endpoint_reports_dominant_runtime_publish_failure() {
        let mut state = test_state();
        {
            let mut config = (*state.config).clone();
            config.ops_admin_token = Some("ops-secret".to_string());
            state.config = Arc::new(config);
        }
        state
            .submit_materialization_dead_letter
            .write()
            .await
            .push_back(SubmitMaterializationOutboxEntry {
                request_id: "ops-alert-runtime-publish".to_string(),
                tenant_namespace: None,
                checkpoint_ts_ms: 1,
                cursor_opaque: "cursor".to_string(),
                store_set_record: StoreSetRecord {
                    dapp_key: "demo::dapp_key::DappKey".to_string(),
                    table_id: "0xops-alert-runtime-publish".to_string(),
                    key_tuple: vec![b"position".to_vec(), vec![6]],
                    value_tuple: vec![vec![6, 6]],
                },
                attempts: 2,
                last_error_class: SubmitMaterializationFailureClass::RuntimePublish,
                last_error: "publish path unavailable".to_string(),
            });

        let response = handle_request(
            Request::builder()
                .method(hyper::Method::GET)
                .uri(OPS_ALERTS_PATH)
                .header(OPS_ADMIN_TOKEN_HEADER, "ops-secret")
                .body(Body::empty())
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(response.status(), StatusCode::OK);
        let body = to_bytes(response.into_body()).await.unwrap();
        let payload: serde_json::Value = serde_json::from_slice(&body).unwrap();
        assert_eq!(payload["ready"], false);
        assert_eq!(payload["summary"]["active_alerts"], 1);
        assert_eq!(payload["summary"]["critical_alerts"], 0);
        assert_eq!(payload["summary"]["highest_severity"], "high");
        assert!(payload["objectives"]
            .as_array()
            .unwrap()
            .iter()
            .any(
                |objective| objective["key"] == "submit_materialization_recovery"
                    && objective["status"] == "degraded"
            ));
        assert!(payload["alerts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|alert| alert["key"]
                == "submit_materialization_dead_letter_dominant_error_class"
                && alert["annotations"]["investigation_hint"] == "check_runtime_publish_path"));
        assert_eq!(
            state
                .metrics
                .ops_active_alerts_total
                .load(Ordering::Relaxed),
            1
        );
        assert_eq!(
            state
                .metrics
                .ops_critical_alerts_total
                .load(Ordering::Relaxed),
            0
        );
    }

