    #[tokio::test]
    async fn test_hosted_v2_publish_is_isolated_per_tenant() {
        let state = test_hosted_state();
        let subscribe_request = V2SubscribeRequest {
            spec: SubscriptionSpec {
                topics: vec!["movement_intent".to_string()],
                filters: {
                    let mut filters = BTreeMap::new();
                    filters.insert(
                        "dapp_key".to_string(),
                        FilterValue::String("demo::dapp_key::DappKey".to_string()),
                    );
                    filters
                },
                cursor: None,
                semantics: dubhe_channel_core::DeliverySemantics::Ephemeral,
            },
        };

        let alpha_subscribe = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(hyper::header::HOST, "alpha.channel.obelisk.build")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(serde_json::to_vec(&subscribe_request).unwrap()))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(alpha_subscribe.status(), StatusCode::OK);
        let beta_subscribe = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(hyper::header::HOST, "beta.channel.obelisk.build")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(serde_json::to_vec(&subscribe_request).unwrap()))
                .unwrap(),
            state.clone(),
        )
        .await
        .unwrap();
        assert_eq!(beta_subscribe.status(), StatusCode::OK);

        let mut alpha_body = alpha_subscribe.into_body();
        let mut beta_body = beta_subscribe.into_body();

        let publish_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/publish")
                .header(hyper::header::HOST, "alpha.channel.obelisk.build")
                .header(CONTENT_TYPE, "application/json")
                .body(Body::from(
                    serde_json::to_vec(&V2PublishRequest {
                        event: EventEnvelope {
                            id: String::new(),
                            topic: "movement_intent".to_string(),
                            partition_key: "player-alpha".to_string(),
                            kind: "move".to_string(),
                            ts_ms: 0,
                            payload: json!({ "direction": "UP" }),
                            metadata: {
                                let mut metadata = BTreeMap::new();
                                metadata.insert(
                                    "dapp_key".to_string(),
                                    "demo::dapp_key::DappKey".to_string(),
                                );
                                metadata
                            },
                        },
                    })
                    .unwrap(),
                ))
                .unwrap(),
            state,
        )
        .await
        .unwrap();
        assert_eq!(publish_response.status(), StatusCode::OK);
        let publish_body = to_bytes(publish_response.into_body()).await.unwrap();
        let publish_payload: EventEnvelope = serde_json::from_slice(&publish_body).unwrap();
        assert_eq!(publish_payload.topic, "movement_intent");

        let alpha_chunk = timeout(Duration::from_secs(1), alpha_body.data())
            .await
            .unwrap()
            .unwrap()
            .unwrap();
        let alpha_text = String::from_utf8(alpha_chunk.to_vec()).unwrap();
        assert!(alpha_text.contains(r#""topic":"movement_intent""#));
        assert!(alpha_text.contains(r#""direction":"UP""#));

        if let Ok(Some(Ok(beta_chunk))) =
            timeout(Duration::from_millis(200), beta_body.data()).await
        {
            let beta_text = String::from_utf8(beta_chunk.to_vec()).unwrap();
            assert!(!beta_text.contains(r#""direction":"UP""#));
            assert!(!beta_text.contains(r#""topic":"movement_intent""#));
        }
    }

