    #[tokio::test]
    #[ignore = "requires local Redis at 127.0.0.1:16379"]
    async fn test_v2_subscribe_rejects_when_shared_cluster_global_limit_exceeded() {
        let redis_url = local_test_redis_url();
        let key_prefix = unique_test_prefix("sse-cluster-global-limit");
        clear_test_redis_namespace(&redis_url, &key_prefix)
            .await
            .unwrap();

        let mut state_one = test_state_with_redis_executor(&key_prefix, Arc::new(VmSubmitExecutor))
            .await
            .unwrap();
        let mut state_two = test_state_with_redis_executor(&key_prefix, Arc::new(VmSubmitExecutor))
            .await
            .unwrap();
        for state in [&mut state_one, &mut state_two] {
            let mut config = (*state.config).clone();
            config.sse_max_connections_global = 2;
            state.config = Arc::new(config);
        }

        let request = V2SubscribeRequest {
            spec: SubscriptionSpec {
                topics: vec!["movement_intent".to_string()],
                filters: BTreeMap::new(),
                cursor: None,
                semantics: dubhe_channel_core::DeliverySemantics::Ephemeral,
            },
        };

        let first_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(CONTENT_TYPE, "application/json")
                .header("Accept", "text/event-stream")
                .header("x-forwarded-for", "203.0.113.31")
                .body(Body::from(serde_json::to_vec(&request).unwrap()))
                .unwrap(),
            state_one.clone(),
        )
        .await
        .unwrap();
        assert_eq!(first_response.status(), StatusCode::OK);

        let second_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(CONTENT_TYPE, "application/json")
                .header("Accept", "text/event-stream")
                .header("x-forwarded-for", "203.0.113.32")
                .body(Body::from(serde_json::to_vec(&request).unwrap()))
                .unwrap(),
            state_two.clone(),
        )
        .await
        .unwrap();
        assert_eq!(second_response.status(), StatusCode::OK);

        let third_response = handle_request(
            Request::builder()
                .method(hyper::Method::POST)
                .uri("/v2/subscribe")
                .header(CONTENT_TYPE, "application/json")
                .header("Accept", "text/event-stream")
                .header("x-forwarded-for", "203.0.113.33")
                .body(Body::from(serde_json::to_vec(&request).unwrap()))
                .unwrap(),
            state_one.clone(),
        )
        .await
        .unwrap();
        assert_eq!(third_response.status(), StatusCode::TOO_MANY_REQUESTS);
        let third_body = to_bytes(third_response.into_body()).await.unwrap();
        let third_payload: serde_json::Value = serde_json::from_slice(&third_body).unwrap();
        assert_eq!(
            third_payload["error"],
            "SSE connection limit exceeded: global"
        );
        assert_eq!(third_payload["sse_governance"]["scope"], "cluster");
        assert_eq!(third_payload["sse_governance"]["kind"], "global");
        assert_eq!(
            third_payload["sse_governance"]["global_connection_limit"],
            2
        );
        assert_eq!(third_payload["sse_governance"]["active_connections"], 2);
        assert_eq!(third_payload["sse_governance"]["active_instances"], 2);
        assert_eq!(
            third_payload["sse_governance"]["tenant_connection_limit"],
            serde_json::Value::Null
        );
        assert_eq!(
            third_payload["sse_governance"]["tenant_active_connections"],
            serde_json::Value::Null
        );
        assert_eq!(
            third_payload["sse_governance"]["client_connection_limit"],
            serde_json::Value::Null
        );
        assert_eq!(
            third_payload["sse_governance"]["client_active_connections"],
            serde_json::Value::Null
        );

        drop(first_response);
        drop(second_response);
        tokio::time::sleep(Duration::from_millis(50)).await;

        clear_test_redis_namespace(&redis_url, &key_prefix)
            .await
            .unwrap();
    }

