    #[test]
    fn test_decision_scoped_auto_replay_backoff_uses_tiered_bases() {
        let mut config = (*test_state().config).clone();
        config.submit_materialization_dead_letter_auto_replay_interval_ms = 1_000;
        config.submit_materialization_dead_letter_auto_replay_backoff_initial_ms = 5_000;
        config.submit_materialization_dead_letter_auto_replay_backoff_max_ms = 60_000;

        assert_eq!(
            decision_scoped_auto_replay_backoff_ms(
                &config,
                0,
                DeadLetterAutoReplayBackoffClass::PolicyBlocked,
                None,
            ),
            20_000
        );
        assert_eq!(
            decision_scoped_auto_replay_backoff_ms(
                &config,
                0,
                DeadLetterAutoReplayBackoffClass::CooldownBlocked,
                Some(42_000),
            ),
            42_000
        );
        assert_eq!(
            decision_scoped_auto_replay_backoff_ms(
                &config,
                0,
                DeadLetterAutoReplayBackoffClass::LeaseConflict,
                None,
            ),
            1_000
        );
        assert_eq!(
            decision_scoped_auto_replay_backoff_ms(
                &config,
                0,
                DeadLetterAutoReplayBackoffClass::Failed,
                None,
            ),
            5_000
        );
        assert_eq!(
            policy_block_backoff_base_ms(&config, "handoff_claim_required"),
            20_000
        );
        assert_eq!(
            policy_block_backoff_base_ms(&config, "escalation_notification_required"),
            40_000
        );
        assert_eq!(
            policy_block_backoff_base_ms(&config, "investigation_ack_required"),
            60_000
        );
        assert_eq!(
            internal_error_backoff_base_ms(
                &config,
                DeadLetterReplayInternalErrorClass::ReplayStatusRead
            ),
            10_000
        );
        assert_eq!(
            internal_error_backoff_base_ms(
                &config,
                DeadLetterReplayInternalErrorClass::EscalationNotificationRead
            ),
            25_000
        );
    }

